-- weather (80 entries)
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES
  ('nalssi', '날씨', 'nalssi', 'noun', 'weather', 'beginner', 'common', '["weather", "daily-life", "beginner-essential", "conversation"]', '{"ko": {"word": "날씨", "explanation": "대기의 상태를 나타내는 말로, 한국에서는 인사 다음으로 가장 흔한 대화 주제입니다. ''날씨가 좋다/나쁘다''로 기본 표현하며, 처음 만난 사람과의 스몰톡에서도 자주 쓰입니다.", "examples": {"beginner": "오늘 날씨가 좋아요.", "intermediate": "요즘 날씨가 많이 추워졌어요.", "advanced": "날씨가 풀리면 벚꽃 구경 가자.", "master": "이상 기후로 인해 날씨 변동폭이 점점 커지고 있다."}, "variations": {"formal": ["날씨가 좋습니다.", "오늘 날씨가 어떻습니까?"], "casual": ["날씨 좋다.", "날씨 어때?"], "short": ["날씨"]}, "dialogue": {"context": "엘리베이터에서 이웃을 만나며", "dialogue": [{"speaker": "A", "text": "오늘 날씨 좋죠?", "romanization": "oneul nalssi jojyo?", "translation": "Nice weather today, isn''t it?"}, {"speaker": "B", "text": "네, 나들이하기 딱 좋은 날이에요.", "romanization": "ne, nadeuri-hagi ttak joeun narieyo.", "translation": "Yes, it''s a perfect day for an outing."}]}}, "en": {"word": "weather", "explanation": "Refers to the state of the atmosphere. In Korea, weather is the most common small talk topic after greetings. Koreans are very attentive to seasonal changes and often comment on weather as a conversation starter, even with strangers.", "examples": {"beginner": "The weather is nice today.", "intermediate": "The weather has gotten much colder these days.", "advanced": "Let''s go see the cherry blossoms when the weather warms up.", "master": "Due to climate anomalies, weather fluctuations are becoming increasingly extreme."}, "variations": {"formal": ["The weather is nice.", "How is the weather today?"], "casual": ["Nice weather.", "How''s the weather?"], "short": ["weather"]}, "dialogue": {"context": "Meeting a neighbor in the elevator", "dialogue": [{"speaker": "A", "text": "Nice weather today, isn''t it?", "romanization": "", "translation": "오늘 날씨 좋죠?"}, {"speaker": "B", "text": "Yes, it''s a perfect day for an outing.", "romanization": "", "translation": "네, 나들이하기 딱 좋은 날이에요."}]}}}'),
  ('bi', '비', 'bi', 'noun', 'weather', 'beginner', 'common', '["weather", "nature", "daily-life", "seasonal"]', '{"ko": {"word": "비", "explanation": "하늘에서 물방울이 떨어지는 기상 현상입니다. 한국에는 장마철(6~7월)에 비가 많이 옵니다.", "examples": {"beginner": "오늘 비가 와요.", "intermediate": "장마철에는 비가 자주 내려요.", "advanced": "가을비가 추적추적 내리고 있다.", "master": "비가 오다가 갑자기 개었다."}, "variations": {"formal": ["비가 내리고 있습니다.", "비가 오고 있습니다."], "casual": ["비 온다.", "비 와."], "short": ["비"]}, "dialogue": {"context": "아침에 외출 준비를 하면서", "dialogue": [{"speaker": "A", "text": "밖에 비 와?", "romanization": "bakke bi wa?", "translation": "Is it raining outside?"}, {"speaker": "B", "text": "응, 우산 챙겨.", "romanization": "eung, usan chaenggyeo.", "translation": "Yeah, bring an umbrella."}]}}, "en": {"word": "rain", "explanation": "Rain, a weather phenomenon where water droplets fall from clouds. Korea has a monsoon season (jangma) from June to July with heavy rainfall.", "examples": {"beginner": "It''s raining today.", "intermediate": "It rains often during the monsoon season.", "advanced": "The autumn rain is drizzling softly.", "master": "It was raining and then suddenly cleared up."}, "variations": {"formal": ["It is raining.", "Rain is falling."], "casual": ["It''s raining.", "Rain''s coming down."], "short": ["rain"]}, "dialogue": {"context": "Getting ready to go out in the morning", "dialogue": [{"speaker": "A", "text": "Is it raining outside?", "romanization": "", "translation": "밖에 비 와?"}, {"speaker": "B", "text": "Yeah, bring an umbrella.", "romanization": "", "translation": "응, 우산 챙겨."}]}}}'),
  ('nun', '눈', 'nun', 'noun', 'weather', 'beginner', 'common', '["weather", "nature", "seasonal", "winter"]', '{"ko": {"word": "눈", "explanation": "하늘에서 얼음 결정이 내리는 기상 현상입니다. ''눈''은 동음이의어로 신체 부위(eye)도 뜻합니다. 문맥으로 구분합니다.", "examples": {"beginner": "눈이 와요!", "intermediate": "첫눈이 내렸어요.", "advanced": "함박눈이 펑펑 쏟아지고 있다.", "master": "눈이 녹아서 길이 미끄럽다."}, "variations": {"formal": ["눈이 내리고 있습니다.", "눈이 오고 있습니다."], "casual": ["눈 온다!", "눈이야!"], "short": ["눈"]}, "dialogue": {"context": "창밖을 보며", "dialogue": [{"speaker": "A", "text": "와, 눈이다!", "romanization": "wa, nunida!", "translation": "Wow, it''s snowing!"}, {"speaker": "B", "text": "첫눈이네! 소원 빌어.", "romanization": "cheonnunine! sowon bireo.", "translation": "It''s the first snow! Make a wish."}]}}, "en": {"word": "snow", "explanation": "Snow, frozen precipitation in the form of ice crystals. The word ''눈'' is a homonym that also means ''eye'' in Korean — context determines the meaning. In Korean culture, the first snow (첫눈) is considered romantic.", "examples": {"beginner": "It''s snowing!", "intermediate": "The first snow has fallen.", "advanced": "Big fluffy snowflakes are pouring down.", "master": "The snow has melted and the roads are slippery."}, "variations": {"formal": ["It is snowing.", "Snow is falling."], "casual": ["It''s snowing!", "Snow!"], "short": ["snow"]}, "dialogue": {"context": "Looking out the window", "dialogue": [{"speaker": "A", "text": "Wow, it''s snowing!", "romanization": "", "translation": "와, 눈이다!"}, {"speaker": "B", "text": "It''s the first snow! Make a wish.", "romanization": "", "translation": "첫눈이네! 소원 빌어."}]}}}'),
  ('baram', '바람', 'baram', 'noun', 'weather', 'beginner', 'common', '["weather", "nature", "daily-life"]', '{"ko": {"word": "바람", "explanation": "공기가 움직이는 현상입니다. 비유적으로 ''바람을 피우다''(have an affair), ''바람이 불다''(a trend emerges) 등 다양한 관용 표현에 쓰입니다.", "examples": {"beginner": "바람이 불어요.", "intermediate": "오늘은 바람이 많이 불어서 추워요.", "advanced": "찬바람이 불기 시작하면 겨울이 온 거다.", "master": "산들바람이 불어와 나뭇잎이 살랑살랑 흔들렸다."}, "variations": {"formal": ["바람이 불고 있습니다.", "강풍이 예상됩니다."], "casual": ["바람 분다.", "바람 엄청 세다."], "short": ["바람"]}, "dialogue": {"context": "산책하면서", "dialogue": [{"speaker": "A", "text": "바람이 시원하다.", "romanization": "barami siwonhada.", "translation": "The wind feels refreshing."}, {"speaker": "B", "text": "그러게, 산책하기 딱 좋은 날씨야.", "romanization": "geureoge, sanchaekhagi ttak joeun nalssiya.", "translation": "Right, it''s perfect weather for a walk."}]}}, "en": {"word": "wind", "explanation": "The movement of air. In Korean, ''바람'' is also used idiomatically: ''바람을 피우다'' means ''to have an affair,'' and ''바람이 불다'' can mean ''a trend is emerging.''", "examples": {"beginner": "The wind is blowing.", "intermediate": "It''s cold today because the wind is blowing a lot.", "advanced": "When cold winds start blowing, winter has arrived.", "master": "A gentle breeze blew and the leaves swayed softly."}, "variations": {"formal": ["The wind is blowing.", "Strong winds are expected."], "casual": ["It''s windy.", "Wind''s really strong."], "short": ["wind"]}, "dialogue": {"context": "While taking a walk", "dialogue": [{"speaker": "A", "text": "The wind feels refreshing.", "romanization": "", "translation": "바람이 시원하다."}, {"speaker": "B", "text": "Right, it''s perfect weather for a walk.", "romanization": "", "translation": "그러게, 산책하기 딱 좋은 날씨야."}]}}}'),
  ('gureum', '구름', 'gureum', 'noun', 'weather', 'beginner', 'common', '["weather", "nature", "sky"]', '{"ko": {"word": "구름", "explanation": "수증기가 응결하여 하늘에 떠 있는 것입니다. 한국어에서는 ''구름 위를 걷는 기분''(walking on clouds)이라는 표현으로 매우 행복한 상태를 나타냅니다. ''뭉게구름'', ''비구름'' 등 종류별 합성어가 많습니다.", "examples": {"beginner": "하늘에 구름이 있어요.", "intermediate": "구름이 많이 끼어서 해가 안 보여요.", "advanced": "뭉게구름이 하늘 가득 피어올랐다.", "master": "먹구름이 몰려오더니 금세 소나기가 쏟아졌다."}, "variations": {"formal": ["구름이 끼어 있습니다.", "구름이 많습니다."], "casual": ["구름 많다.", "구름 낀다."], "short": ["구름"]}, "dialogue": {"context": "소풍을 가려고 하늘을 보며", "dialogue": [{"speaker": "A", "text": "구름이 좀 끼었네.", "romanization": "gureumi jom kkieonne.", "translation": "It''s a bit cloudy."}, {"speaker": "B", "text": "괜찮아, 곧 걷힐 거야.", "romanization": "gwaenchana, got geothil geoya.", "translation": "It''s fine, it''ll clear up soon."}]}}, "en": {"word": "cloud", "explanation": "Visible masses of water vapor floating in the sky. Korean has many compound words for cloud types: ''뭉게구름'' (cumulus/fluffy clouds), ''비구름'' (rain clouds), ''먹구름'' (dark storm clouds). The expression ''walking on clouds'' (구름 위를 걷다) means feeling extremely happy.", "examples": {"beginner": "There are clouds in the sky.", "intermediate": "I can''t see the sun because there are too many clouds.", "advanced": "Fluffy cumulus clouds bloomed across the sky.", "master": "Dark clouds rolled in and a sudden shower poured down."}, "variations": {"formal": ["It is cloudy.", "There are many clouds."], "casual": ["Lots of clouds.", "Getting cloudy."], "short": ["cloud"]}, "dialogue": {"context": "Looking at the sky before a picnic", "dialogue": [{"speaker": "A", "text": "It''s a bit cloudy.", "romanization": "", "translation": "구름이 좀 끼었네."}, {"speaker": "B", "text": "It''s fine, it''ll clear up soon.", "romanization": "", "translation": "괜찮아, 곧 걷힐 거야."}]}}}'),
  ('taepung', '태풍', 'taepung', 'noun', 'weather', 'intermediate', 'common', '["weather", "nature", "disaster", "seasonal"]', '{"ko": {"word": "태풍", "explanation": "열대 해상에서 발생하는 강한 폭풍입니다. 한국에는 주로 여름~가을(7~9월)에 영향을 줍니다. 한자어 ''颱風''에서 유래했습니다.", "examples": {"beginner": "태풍이 오고 있어요.", "intermediate": "태풍 때문에 비행기가 취소되었어요.", "advanced": "이번 태풍은 강풍을 동반하여 피해가 컸다.", "master": "태풍의 눈이 한반도를 관통할 것으로 예상된다."}, "variations": {"formal": ["태풍이 접근하고 있습니다.", "태풍 경보가 발령되었습니다."], "casual": ["태풍 온대.", "태풍 무섭다."], "short": ["태풍"]}, "dialogue": {"context": "뉴스를 보면서", "dialogue": [{"speaker": "A", "text": "이번 주에 태풍 온대.", "romanization": "ibeon jue taepung ondae.", "translation": "They say a typhoon is coming this week."}, {"speaker": "B", "text": "진짜? 비상식량 사 놓자.", "romanization": "jinjja? bisangsignyang sa noja.", "translation": "Really? Let''s stock up on emergency food."}]}}, "en": {"word": "typhoon", "explanation": "A powerful tropical storm that forms over the Pacific Ocean. Typhoons typically affect Korea during summer and early autumn (July–September). The word comes from the Chinese characters ''颱風''.", "examples": {"beginner": "A typhoon is coming.", "intermediate": "The flight was canceled because of the typhoon.", "advanced": "This typhoon brought strong winds and caused significant damage.", "master": "The eye of the typhoon is expected to pass through the Korean Peninsula."}, "variations": {"formal": ["A typhoon is approaching.", "A typhoon warning has been issued."], "casual": ["Typhoon''s coming.", "Typhoon''s scary."], "short": ["typhoon"]}, "dialogue": {"context": "Watching the news", "dialogue": [{"speaker": "A", "text": "They say a typhoon is coming this week.", "romanization": "", "translation": "이번 주에 태풍 온대."}, {"speaker": "B", "text": "Really? Let''s stock up on emergency food.", "romanization": "", "translation": "진짜? 비상식량 사 놓자."}]}}}'),
  ('cheondung', '천둥', 'cheondung', 'noun', 'weather', 'intermediate', 'common', '["weather", "nature", "sound"]', '{"ko": {"word": "천둥", "explanation": "번개가 칠 때 나는 큰 소리입니다. 한국에서는 ''천둥벌거숭이''라는 표현이 있는데, 옷을 제대로 안 입은 사람을 놀릴 때 씁니다. ''천둥·번개''는 항상 함께 언급되는 경우가 많습니다.", "examples": {"beginner": "천둥 소리가 나요.", "intermediate": "천둥이 치면 무서워요.", "advanced": "천둥이 요란하게 울리더니 곧 폭우가 쏟아졌다.", "master": "마른하늘에 날벼락이라더니, 갑자기 천둥이 쳤다."}, "variations": {"formal": ["천둥이 치고 있습니다.", "천둥 소리가 들립니다."], "casual": ["천둥 친다!", "우르르 쾅쾅!"], "short": ["천둥"]}, "dialogue": {"context": "밤에 천둥소리에 놀라서", "dialogue": [{"speaker": "A", "text": "으악, 천둥이야!", "romanization": "euak, cheondungiya!", "translation": "Ahh, it''s thunder!"}, {"speaker": "B", "text": "괜찮아, 금방 지나갈 거야.", "romanization": "gwaenchana, geumbang jinagal geoya.", "translation": "It''s okay, it''ll pass soon."}]}}, "en": {"word": "thunder", "explanation": "The loud sound produced when lightning strikes. In Korean, ''천둥벌거숭이'' (thunder-naked person) is a playful expression used to tease someone who isn''t dressed properly. Thunder and lightning (천둥·번개) are almost always mentioned together.", "examples": {"beginner": "I hear thunder.", "intermediate": "I''m scared when there''s thunder.", "advanced": "Thunder roared loudly and heavy rain poured down soon after.", "master": "Like a bolt from the blue — thunder struck out of nowhere."}, "variations": {"formal": ["There is thunder.", "Thunder can be heard."], "casual": ["Thunder!", "Boom crash!"], "short": ["thunder"]}, "dialogue": {"context": "Startled by thunder at night", "dialogue": [{"speaker": "A", "text": "Ahh, it''s thunder!", "romanization": "", "translation": "으악, 천둥이야!"}, {"speaker": "B", "text": "It''s okay, it''ll pass soon.", "romanization": "", "translation": "괜찮아, 금방 지나갈 거야."}]}}}'),
  ('beongae', '번개', 'beongae', 'noun', 'weather', 'intermediate', 'common', '["weather", "nature", "sky"]', '{"ko": {"word": "번개", "explanation": "구름과 구름 사이, 또는 구름과 지면 사이에서 발생하는 전기 방전 현상입니다. ''번개같이 빠르다''는 매우 빠른 것을 비유하는 관용 표현입니다. 인터넷 용어로 ''번개''는 갑작스러운 모임(flash gathering)을 뜻하기도 합니다.", "examples": {"beginner": "번개가 쳤어요.", "intermediate": "번개가 치면 나무 밑에 서지 마세요.", "advanced": "번개가 하늘을 가르며 순간적으로 밝혔다.", "master": "낙뢰가 송전탑을 강타하여 일대가 정전되었다."}, "variations": {"formal": ["번개가 치고 있습니다.", "낙뢰 주의보가 발령되었습니다."], "casual": ["번개 친다!", "번개 무서워."], "short": ["번개"]}, "dialogue": {"context": "비가 오는 밤에 창밖을 보며", "dialogue": [{"speaker": "A", "text": "번개 봤어? 완전 밝았어.", "romanization": "beongae bwasseo? wanjeon balgasseo.", "translation": "Did you see the lightning? It was so bright."}, {"speaker": "B", "text": "응, 무섭다. 창문 닫자.", "romanization": "eung, museopda. changmun datja.", "translation": "Yeah, it''s scary. Let''s close the window."}]}}, "en": {"word": "lightning", "explanation": "An electrical discharge between clouds or between a cloud and the ground. The expression ''번개같이 빠르다'' (fast as lightning) is a common idiom. In Korean internet culture, ''번개'' also means a flash gathering — a spontaneous meetup organized on short notice.", "examples": {"beginner": "There was lightning.", "intermediate": "Don''t stand under a tree when there''s lightning.", "advanced": "Lightning split the sky and lit it up for a moment.", "master": "A lightning strike hit the transmission tower and caused a blackout in the area."}, "variations": {"formal": ["There is lightning.", "A lightning advisory has been issued."], "casual": ["Lightning!", "Lightning''s scary."], "short": ["lightning"]}, "dialogue": {"context": "Looking outside on a rainy night", "dialogue": [{"speaker": "A", "text": "Did you see the lightning? It was so bright.", "romanization": "", "translation": "번개 봤어? 완전 밝았어."}, {"speaker": "B", "text": "Yeah, it''s scary. Let''s close the window.", "romanization": "", "translation": "응, 무섭다. 창문 닫자."}]}}}'),
  ('makda', '맑다', 'makda', 'adjective', 'weather', 'beginner', 'common', '["weather", "adjective", "sky", "daily-life"]', '{"ko": {"word": "맑다", "explanation": "하늘에 구름이 없고 날씨가 좋은 상태를 뜻합니다. ''맑은 하늘'', ''맑은 물''처럼 투명하고 깨끗한 것에도 씁니다.", "examples": {"beginner": "오늘 날씨가 맑아요.", "intermediate": "맑은 날에 산책하고 싶어요.", "advanced": "비가 그치고 하늘이 맑게 개었다.", "master": "가을 하늘은 높고 맑아서 천고마비의 계절이라고 한다."}, "variations": {"formal": ["날씨가 맑습니다.", "하늘이 맑습니다."], "casual": ["날씨 맑다.", "하늘 진짜 맑다."], "short": ["맑음"]}, "dialogue": {"context": "날씨 예보를 보며", "dialogue": [{"speaker": "A", "text": "내일 날씨 어때?", "romanization": "naeil nalssi eottae?", "translation": "How''s the weather tomorrow?"}, {"speaker": "B", "text": "맑대! 소풍 가자.", "romanization": "maktae! sopung gaja.", "translation": "It''ll be clear! Let''s go on a picnic."}]}}, "en": {"word": "clear (weather)", "explanation": "Describes clear, cloudless weather. Also used to describe anything transparent or pure, such as clear water or a clear voice.", "examples": {"beginner": "The weather is clear today.", "intermediate": "I want to take a walk on a clear day.", "advanced": "The rain stopped and the sky cleared up.", "master": "Autumn skies are high and clear — that''s why it''s called the season of high skies."}, "variations": {"formal": ["The weather is clear.", "The sky is clear."], "casual": ["It''s clear out.", "Nice and clear."], "short": ["clear"]}, "dialogue": {"context": "Checking the weather forecast", "dialogue": [{"speaker": "A", "text": "How''s the weather tomorrow?", "romanization": "", "translation": "내일 날씨 어때?"}, {"speaker": "B", "text": "It''ll be clear! Let''s go on a picnic.", "romanization": "", "translation": "맑대! 소풍 가자."}]}}}'),
  ('heurida', '흐리다', 'heurida', 'adjective', 'weather', 'beginner', 'common', '["weather", "adjective", "sky", "daily-life"]', '{"ko": {"word": "흐리다", "explanation": "구름이 많이 끼어 하늘이 어두운 상태를 뜻합니다. 시야가 흐린 경우(안경이 흐리다)에도 씁니다.", "examples": {"beginner": "오늘 날씨가 흐려요.", "intermediate": "흐린 날에는 기분이 가라앉아요.", "advanced": "아침부터 잔뜩 흐려서 비가 올 것 같다.", "master": "구름이 잔뜩 끼어 흐린 하늘이 종일 계속되었다."}, "variations": {"formal": ["날씨가 흐립니다.", "하늘이 흐립니다."], "casual": ["날씨 흐리다.", "흐리네."], "short": ["흐림"]}, "dialogue": {"context": "아침에 창밖을 보며", "dialogue": [{"speaker": "A", "text": "오늘 날씨 흐리네.", "romanization": "oneul nalssi heurine.", "translation": "The weather is cloudy today."}, {"speaker": "B", "text": "비 올 수도 있겠다.", "romanization": "bi ol sudo itgetda.", "translation": "It might rain."}]}}, "en": {"word": "cloudy", "explanation": "Describes overcast or cloudy weather where clouds cover the sky. Can also describe blurry or unclear vision (e.g., foggy glasses).", "examples": {"beginner": "The weather is cloudy today.", "intermediate": "I feel down on cloudy days.", "advanced": "It''s been heavily overcast since morning, so it looks like rain.", "master": "The cloud-covered sky remained overcast all day long."}, "variations": {"formal": ["The weather is overcast.", "The sky is cloudy."], "casual": ["It''s cloudy.", "Looks gloomy."], "short": ["cloudy"]}, "dialogue": {"context": "Looking outside in the morning", "dialogue": [{"speaker": "A", "text": "The weather is cloudy today.", "romanization": "", "translation": "오늘 날씨 흐리네."}, {"speaker": "B", "text": "It might rain.", "romanization": "", "translation": "비 올 수도 있겠다."}]}}}'),
  ('deopda', '덥다', 'deopda', 'adjective', 'weather', 'beginner', 'common', '["weather", "adjective", "temperature", "summer", "daily-life"]', '{"ko": {"word": "덥다", "explanation": "기온이 높아 몸이 더운 느낌을 뜻합니다. ''ㅂ'' 불규칙 활용으로 ''더워요'', ''더운'' 등으로 변합니다.", "examples": {"beginner": "오늘 너무 더워요.", "intermediate": "여름에는 정말 더워서 에어컨이 필요해요.", "advanced": "찜통더위에 숨이 막힐 것 같다.", "master": "체감 온도가 40도를 넘어 폭염 경보가 내려졌다."}, "variations": {"formal": ["날씨가 덥습니다.", "기온이 높습니다."], "casual": ["더워.", "너무 덥다."], "short": ["덥다"]}, "dialogue": {"context": "한여름 더운 날", "dialogue": [{"speaker": "A", "text": "아, 너무 더워.", "romanization": "a, neomu deowo.", "translation": "Ah, it''s so hot."}, {"speaker": "B", "text": "아이스크림 먹으러 가자.", "romanization": "aiseukeulim meogeureo gaja.", "translation": "Let''s go get ice cream."}]}}, "en": {"word": "hot (weather)", "explanation": "Describes hot weather or feeling warm due to high temperature. This adjective follows the ''ㅂ'' irregular conjugation: 덥다 → 더워요 (present), 더운 (modifier).", "examples": {"beginner": "It''s very hot today.", "intermediate": "In summer it''s really hot, so you need air conditioning.", "advanced": "It feels suffocating in the sweltering heat.", "master": "The perceived temperature exceeded 40°C and a heat wave warning was issued."}, "variations": {"formal": ["The weather is hot.", "The temperature is high."], "casual": ["It''s hot.", "So hot."], "short": ["hot"]}, "dialogue": {"context": "On a hot midsummer day", "dialogue": [{"speaker": "A", "text": "Ah, it''s so hot.", "romanization": "", "translation": "아, 너무 더워."}, {"speaker": "B", "text": "Let''s go get ice cream.", "romanization": "", "translation": "아이스크림 먹으러 가자."}]}}}'),
  ('chupda', '춥다', 'chupda', 'adjective', 'weather', 'beginner', 'common', '["weather", "adjective", "temperature", "winter", "daily-life"]', '{"ko": {"word": "춥다", "explanation": "기온이 낮아 몸이 추운 느낌을 뜻합니다. ''ㅂ'' 불규칙 활용으로 ''추워요'', ''추운'' 등으로 변합니다.", "examples": {"beginner": "오늘 너무 추워요.", "intermediate": "겨울에는 많이 추워서 따뜻하게 입어야 해요.", "advanced": "뼛속까지 추운 한파가 몰려왔다.", "master": "영하 20도의 혹한에 수도관이 얼었다."}, "variations": {"formal": ["날씨가 춥습니다.", "기온이 낮습니다."], "casual": ["추워.", "너무 춥다."], "short": ["춥다"]}, "dialogue": {"context": "겨울 아침 출근길에", "dialogue": [{"speaker": "A", "text": "오늘 진짜 춥다.", "romanization": "oneul jinjja chupda.", "translation": "It''s really cold today."}, {"speaker": "B", "text": "그러니까, 목도리 하고 나올 걸.", "romanization": "geureonikka, mokdori hago naol geol.", "translation": "I know, I should''ve worn a scarf."}]}}, "en": {"word": "cold (weather)", "explanation": "Describes cold weather or feeling cold due to low temperature. This adjective follows the ''ㅂ'' irregular conjugation: 춥다 → 추워요 (present), 추운 (modifier).", "examples": {"beginner": "It''s very cold today.", "intermediate": "In winter it''s very cold, so you need to dress warmly.", "advanced": "A bone-chilling cold wave has arrived.", "master": "At minus 20°C, the water pipes froze in the extreme cold."}, "variations": {"formal": ["The weather is cold.", "The temperature is low."], "casual": ["It''s cold.", "So cold."], "short": ["cold"]}, "dialogue": {"context": "On a winter morning commute", "dialogue": [{"speaker": "A", "text": "It''s really cold today.", "romanization": "", "translation": "오늘 진짜 춥다."}, {"speaker": "B", "text": "I know, I should''ve worn a scarf.", "romanization": "", "translation": "그러니까, 목도리 하고 나올 걸."}]}}}'),
  ('ttatteuthada', '따뜻하다', 'ttatteuthada', 'adjective', 'weather', 'beginner', 'common', '["weather", "adjective", "temperature", "spring"]', '{"ko": {"word": "따뜻하다", "explanation": "적당히 온도가 높아 기분 좋은 상태를 뜻합니다. 날씨뿐 아니라 사람의 성격(''따뜻한 사람''), 음식(''따뜻한 국''), 감정(''마음이 따뜻해지다'') 등 폭넓게 쓰입니다. 겹받침 ''ㄸ''으로 시작하는 된소리 단어입니다.", "examples": {"beginner": "오늘 날씨가 따뜻해요.", "intermediate": "봄이 되니까 날씨가 따뜻해졌어요.", "advanced": "포근하고 따뜻한 봄 햇살이 기분 좋다.", "master": "겨울이 지나고 따뜻한 봄바람이 불어오면 마음까지 녹는다."}, "variations": {"formal": ["날씨가 따뜻합니다.", "기온이 포근합니다."], "casual": ["따뜻하다.", "따뜻해."], "short": ["따뜻"]}, "dialogue": {"context": "봄 날씨를 느끼며", "dialogue": [{"speaker": "A", "text": "오늘 되게 따뜻하다.", "romanization": "oneul doege ttatteuthada.", "translation": "It''s really warm today."}, {"speaker": "B", "text": "드디어 봄이 온 것 같아.", "romanization": "deudieo bomi on geot gata.", "translation": "I think spring is finally here."}]}}, "en": {"word": "warm", "explanation": "Describes a pleasantly warm temperature. Used broadly beyond weather — for personality (''따뜻한 사람'', a warm person), food (''따뜻한 국'', warm soup), and emotions (''마음이 따뜻해지다'', to feel warmth in one''s heart). A key word for describing spring in Korea.", "examples": {"beginner": "The weather is warm today.", "intermediate": "The weather has gotten warmer since spring came.", "advanced": "The cozy, warm spring sunlight feels wonderful.", "master": "When winter passes and warm spring breezes blow, even the heart melts."}, "variations": {"formal": ["The weather is warm.", "The temperature is mild."], "casual": ["It''s warm.", "So warm."], "short": ["warm"]}, "dialogue": {"context": "Feeling the spring weather", "dialogue": [{"speaker": "A", "text": "It''s really warm today.", "romanization": "", "translation": "오늘 되게 따뜻하다."}, {"speaker": "B", "text": "I think spring is finally here.", "romanization": "", "translation": "드디어 봄이 온 것 같아."}]}}}'),
  ('siwonhada', '시원하다', 'siwonhada', 'adjective', 'weather', 'beginner', 'common', '["weather", "adjective", "temperature", "autumn"]', '{"ko": {"word": "시원하다", "explanation": "적당히 서늘하여 상쾌한 느낌을 뜻합니다. 한국어 특유의 다의어로, 국물이 ''시원하다''(soup tastes refreshing), 대답이 ''시원하다''(answer is satisfying), 속이 ''시원하다''(feel relieved) 등 다양한 의미로 쓰입니다. 외국인이 가장 혼란스러워하는 한국어 단어 중 하나입니다.", "examples": {"beginner": "바람이 시원해요.", "intermediate": "가을 날씨가 시원해서 좋아요.", "advanced": "에어컨 바람이 시원하게 불어온다.", "master": "열대야가 끝나고 시원한 가을바람이 불어오니 살 것 같다."}, "variations": {"formal": ["날씨가 시원합니다.", "바람이 시원합니다."], "casual": ["시원하다.", "시원해!"], "short": ["시원"]}, "dialogue": {"context": "더운 여름날 에어컨을 켠 후", "dialogue": [{"speaker": "A", "text": "아, 시원하다!", "romanization": "a, siwonhada!", "translation": "Ah, that''s refreshing!"}, {"speaker": "B", "text": "에어컨 최고야.", "romanization": "eeokon choegoya.", "translation": "Air conditioning is the best."}]}}, "en": {"word": "cool / refreshing", "explanation": "Describes a pleasantly cool and refreshing sensation. This is one of the most uniquely Korean words — it extends far beyond temperature: soup can be ''시원하다'' (refreshingly savory), an answer can be ''시원하다'' (satisfyingly clear), and your stomach can feel ''시원하다'' (relieved). Often confuses Korean learners due to its broad usage.", "examples": {"beginner": "The wind is cool.", "intermediate": "I like autumn weather because it''s cool.", "advanced": "The air conditioning is blowing refreshingly cool air.", "master": "After the tropical nights ended, the cool autumn breeze made life bearable again."}, "variations": {"formal": ["The weather is cool.", "The breeze is refreshing."], "casual": ["So refreshing.", "Feels cool!"], "short": ["cool"]}, "dialogue": {"context": "After turning on the AC on a hot summer day", "dialogue": [{"speaker": "A", "text": "Ah, that''s refreshing!", "romanization": "", "translation": "아, 시원하다!"}, {"speaker": "B", "text": "Air conditioning is the best.", "romanization": "", "translation": "에어컨 최고야."}]}}}'),
  ('seupada', '습하다', 'seupada', 'adjective', 'weather', 'intermediate', 'common', '["weather", "adjective", "summer", "uncomfortable"]', '{"ko": {"word": "습하다", "explanation": "공기 중에 수분이 많아 축축한 상태를 뜻합니다. 한국의 여름(특히 장마철)은 고온다습하여 ''습하다''가 자주 쓰입니다. 한자어 ''濕''에서 유래했으며, ''습기'', ''습도'' 등 관련어가 많습니다.", "examples": {"beginner": "오늘 너무 습해요.", "intermediate": "장마철에는 공기가 습해서 불쾌해요.", "advanced": "습한 날씨에는 빨래가 잘 안 마른다.", "master": "고온다습한 날씨가 계속되면서 곰팡이 피해가 속출하고 있다."}, "variations": {"formal": ["습도가 높습니다.", "공기가 습합니다."], "casual": ["습하다.", "축축해."], "short": ["습함"]}, "dialogue": {"context": "장마철 습한 날씨에", "dialogue": [{"speaker": "A", "text": "오늘 진짜 습하다.", "romanization": "oneul jinjja seupada.", "translation": "It''s really humid today."}, {"speaker": "B", "text": "제습기 켜야겠다.", "romanization": "jeseupgi kyeoyagetda.", "translation": "I need to turn on the dehumidifier."}]}}, "en": {"word": "humid", "explanation": "Describes air with high moisture content. Korean summers (especially the monsoon season, 장마철) are notoriously hot and humid, making this a frequently used word from June through August. Related words include ''습기'' (moisture) and ''습도'' (humidity level).", "examples": {"beginner": "It''s very humid today.", "intermediate": "The air is humid during monsoon season, which is unpleasant.", "advanced": "Laundry doesn''t dry well in humid weather.", "master": "As the hot and humid weather continued, mold damage reports poured in."}, "variations": {"formal": ["The humidity is high.", "The air is humid."], "casual": ["It''s humid.", "So muggy."], "short": ["humid"]}, "dialogue": {"context": "During the humid monsoon season", "dialogue": [{"speaker": "A", "text": "It''s really humid today.", "romanization": "", "translation": "오늘 진짜 습하다."}, {"speaker": "B", "text": "I need to turn on the dehumidifier.", "romanization": "", "translation": "제습기 켜야겠다."}]}}}'),
  ('geonjohada', '건조하다', 'geonjohada', 'adjective', 'weather', 'intermediate', 'common', '["weather", "adjective", "winter", "health"]', '{"ko": {"word": "건조하다", "explanation": "공기 중에 수분이 적어 마른 상태를 뜻합니다. 한국의 겨울은 매우 건조하여 피부 관리와 화재 예방이 중요합니다. 한자어 ''乾燥''에서 유래했으며, 건조한 겨울철에는 ''건조주의보''가 자주 발령됩니다.", "examples": {"beginner": "겨울에는 공기가 건조해요.", "intermediate": "건조한 날씨에 피부가 갈라져요.", "advanced": "건조주의보가 발령되어 화재에 주의해야 한다.", "master": "대기가 극도로 건조해지면서 산불 위험이 크게 높아졌다."}, "variations": {"formal": ["공기가 건조합니다.", "건조주의보가 발령되었습니다."], "casual": ["건조하다.", "공기 완전 건조해."], "short": ["건조"]}, "dialogue": {"context": "겨울철 피부 관리에 대해 이야기하며", "dialogue": [{"speaker": "A", "text": "요즘 피부가 너무 건조해.", "romanization": "yojeum pibuga neomu geonjohe.", "translation": "My skin is so dry these days."}, {"speaker": "B", "text": "가습기 틀어. 겨울이라 건조하잖아.", "romanization": "gaseugi teureo. gyeourira geonjohajana.", "translation": "Turn on the humidifier. It''s dry because it''s winter."}]}}, "en": {"word": "dry", "explanation": "Describes air or weather with low moisture content. Korean winters are notoriously dry, making skin care and fire prevention important concerns. A ''건조주의보'' (dry weather advisory) is frequently issued during winter months. The word comes from the Chinese characters ''乾燥''.", "examples": {"beginner": "The air is dry in winter.", "intermediate": "My skin cracks in dry weather.", "advanced": "A dry weather advisory was issued, so be careful of fires.", "master": "As the atmosphere became extremely dry, wildfire risk increased significantly."}, "variations": {"formal": ["The air is dry.", "A dry weather advisory has been issued."], "casual": ["It''s dry.", "Air''s super dry."], "short": ["dry"]}, "dialogue": {"context": "Talking about winter skin care", "dialogue": [{"speaker": "A", "text": "My skin is so dry these days.", "romanization": "", "translation": "요즘 피부가 너무 건조해."}, {"speaker": "B", "text": "Turn on the humidifier. It''s dry because it''s winter.", "romanization": "", "translation": "가습기 틀어. 겨울이라 건조하잖아."}]}}}'),
  ('angae', '안개', 'angae', 'noun', 'weather', 'intermediate', 'common', '["weather", "nature", "driving", "morning"]', '{"ko": {"word": "안개", "explanation": "수증기가 지표면 가까이에서 응결하여 시야를 흐리게 하는 현상입니다. 한국에서는 가을~겨울 아침에 안개가 자주 끼며, 고속도로 안개 사고가 빈번하여 ''짙은 안개 주의보''가 중요합니다. 비유적으로 ''안개 속''은 불확실한 상황을 뜻합니다.", "examples": {"beginner": "안개가 끼었어요.", "intermediate": "안개 때문에 앞이 잘 안 보여요.", "advanced": "짙은 안개로 고속도로에서 연쇄 추돌 사고가 났다.", "master": "새벽 물안개가 호수 위를 신비롭게 덮고 있었다."}, "variations": {"formal": ["안개가 끼어 있습니다.", "짙은 안개 주의보가 발령되었습니다."], "casual": ["안개 꼈다.", "안개 엄청 짙다."], "short": ["안개"]}, "dialogue": {"context": "아침에 운전하려고 나가며", "dialogue": [{"speaker": "A", "text": "안개가 엄청 짙다. 조심해서 운전해.", "romanization": "angaega eomcheong jitda. josimhaeseo unjeonhae.", "translation": "The fog is really thick. Drive carefully."}, {"speaker": "B", "text": "알겠어, 천천히 갈게.", "romanization": "algesseo, cheoncheonhi galge.", "translation": "Got it, I''ll go slowly."}]}}, "en": {"word": "fog", "explanation": "Water vapor condensed near the ground that reduces visibility. Fog is common during autumn and winter mornings in Korea, and highway fog-related pileups are a significant concern, making ''짙은 안개 주의보'' (dense fog advisory) an important weather alert. Figuratively, ''안개 속'' (in the fog) means an uncertain situation.", "examples": {"beginner": "It''s foggy.", "intermediate": "I can''t see well because of the fog.", "advanced": "A chain-reaction accident occurred on the highway due to dense fog.", "master": "A mystical morning mist hovered over the lake at dawn."}, "variations": {"formal": ["There is fog.", "A dense fog advisory has been issued."], "casual": ["It''s foggy.", "Fog''s super thick."], "short": ["fog"]}, "dialogue": {"context": "Heading out to drive in the morning", "dialogue": [{"speaker": "A", "text": "The fog is really thick. Drive carefully.", "romanization": "", "translation": "안개가 엄청 짙다. 조심해서 운전해."}, {"speaker": "B", "text": "Got it, I''ll go slowly.", "romanization": "", "translation": "알겠어, 천천히 갈게."}]}}}'),
  ('seori', '서리', 'seori', 'noun', 'weather', 'intermediate', 'uncommon', '["weather", "nature", "winter", "morning"]', '{"ko": {"word": "서리", "explanation": "기온이 영하로 내려갈 때 공기 중 수증기가 물체 표면에 얼어붙는 현상입니다. 24절기 중 ''상강(霜降)''은 서리가 내리는 시기를 뜻합니다. 농업에서 서리 피해는 큰 관심사이며, ''첫서리''와 ''늦서리''가 농작물에 영향을 줍니다.", "examples": {"beginner": "서리가 내렸어요.", "intermediate": "아침에 차에 서리가 끼었어요.", "advanced": "첫서리가 내리면 가을이 끝나간다는 뜻이다.", "master": "늦서리 피해로 과수원 농가들의 시름이 깊어졌다."}, "variations": {"formal": ["서리가 내렸습니다.", "서리 주의보가 발령되었습니다."], "casual": ["서리 왔다.", "서리 끼었어."], "short": ["서리"]}, "dialogue": {"context": "가을 아침 차에 서리가 내린 것을 보고", "dialogue": [{"speaker": "A", "text": "차에 서리 끼었어. 좀 녹여야겠다.", "romanization": "chae seori kkieosseo. jom nogyeoyagetda.", "translation": "There''s frost on the car. I need to defrost it."}, {"speaker": "B", "text": "벌써 이렇게 추워졌네.", "romanization": "beolsseo ireoke chuwojyeonne.", "translation": "It''s gotten cold already."}]}}, "en": {"word": "frost", "explanation": "Ice crystals that form on surfaces when air temperature drops below freezing. In the Korean 24 seasonal divisions, ''상강'' (Sanggang, Frost Descent) marks the period when frost begins. Frost damage is a major concern in agriculture — both ''first frost'' (첫서리) and ''late frost'' (늦서리) significantly affect crops.", "examples": {"beginner": "There is frost.", "intermediate": "There was frost on the car this morning.", "advanced": "When the first frost comes, it means autumn is ending.", "master": "Late frost damage deepened the worries of orchard farmers."}, "variations": {"formal": ["Frost has formed.", "A frost advisory has been issued."], "casual": ["Frost is here.", "Car''s frosted over."], "short": ["frost"]}, "dialogue": {"context": "Seeing frost on the car on an autumn morning", "dialogue": [{"speaker": "A", "text": "There''s frost on the car. I need to defrost it.", "romanization": "", "translation": "차에 서리 끼었어. 좀 녹여야겠다."}, {"speaker": "B", "text": "It''s gotten cold already.", "romanization": "", "translation": "벌써 이렇게 추워졌네."}]}}}'),
  ('iseul', '이슬', 'iseul', 'noun', 'weather', 'intermediate', 'uncommon', '["weather", "nature", "morning", "poetic"]', '{"ko": {"word": "이슬", "explanation": "밤사이 기온이 내려가면서 풀이나 나뭇잎 위에 맺히는 작은 물방울입니다. 한국 문학과 시에서 이슬은 순수함, 덧없음의 상징으로 자주 쓰입니다. 24절기 중 ''백로(白露)''는 이슬이 많아지는 시기를 뜻합니다.", "examples": {"beginner": "풀에 이슬이 맺혔어요.", "intermediate": "아침 이슬을 밟으며 산책했어요.", "advanced": "이슬방울이 햇살에 반짝이고 있다.", "master": "아침 이슬처럼 덧없는 인생이라 하지만, 그래서 더 아름답다."}, "variations": {"formal": ["이슬이 맺혀 있습니다.", "아침 이슬이 내렸습니다."], "casual": ["이슬 맺혔다.", "풀에 이슬이야."], "short": ["이슬"]}, "dialogue": {"context": "이른 아침 정원을 산책하며", "dialogue": [{"speaker": "A", "text": "이슬이 반짝반짝 예쁘다.", "romanization": "iseuri banjjakbanjjak yeppeuda.", "translation": "The dew is sparkling beautifully."}, {"speaker": "B", "text": "아침 공기도 상쾌하고 좋다.", "romanization": "achim gonggido sangkwaehago jota.", "translation": "The morning air is fresh and nice too."}]}}, "en": {"word": "dew", "explanation": "Small water droplets that form on grass and leaves when temperature drops overnight. In Korean literature and poetry, dew symbolizes purity and transience. The 24 seasonal divisions include ''백로'' (Baengno, White Dew), marking the period when dew becomes abundant.", "examples": {"beginner": "There is dew on the grass.", "intermediate": "I walked stepping on the morning dew.", "advanced": "Dewdrops are sparkling in the sunlight.", "master": "Life is said to be as fleeting as morning dew, but that''s what makes it beautiful."}, "variations": {"formal": ["Dew has formed.", "Morning dew has settled."], "casual": ["There''s dew.", "Dew on the grass."], "short": ["dew"]}, "dialogue": {"context": "Walking in the garden early in the morning", "dialogue": [{"speaker": "A", "text": "The dew is sparkling beautifully.", "romanization": "", "translation": "이슬이 반짝반짝 예쁘다."}, {"speaker": "B", "text": "The morning air is fresh and nice too.", "romanization": "", "translation": "아침 공기도 상쾌하고 좋다."}]}}}'),
  ('mujigae', '무지개', 'mujigae', 'noun', 'weather', 'beginner', 'common', '["weather", "nature", "sky", "beautiful"]', '{"ko": {"word": "무지개", "explanation": "비가 온 뒤 햇빛이 물방울에 굴절되어 하늘에 나타나는 일곱 색깔의 호(弧)입니다. 한국에서 무지개는 희망과 행운의 상징으로 여겨집니다. ''무지갯빛''은 형형색색 아름다운 것을 표현할 때 쓰입니다.", "examples": {"beginner": "무지개가 떴어요!", "intermediate": "비 온 뒤에 무지개가 나타났어요.", "advanced": "쌍무지개가 하늘에 선명하게 걸려 있다.", "master": "비가 그치고 석양 무렵 하늘에 걸린 무지개는 자연이 주는 최고의 선물이다."}, "variations": {"formal": ["무지개가 나타났습니다.", "하늘에 무지개가 떴습니다."], "casual": ["무지개다!", "무지개 떴다!"], "short": ["무지개"]}, "dialogue": {"context": "비가 그친 후 하늘을 보며", "dialogue": [{"speaker": "A", "text": "와, 무지개 떴다! 봐봐!", "romanization": "wa, mujigae tteotda! bwabwa!", "translation": "Wow, there''s a rainbow! Look!"}, {"speaker": "B", "text": "진짜 예쁘다. 사진 찍자.", "romanization": "jinjja yeppeuda. sajin jjikja.", "translation": "It''s really beautiful. Let''s take a photo."}]}}, "en": {"word": "rainbow", "explanation": "An arc of seven colors appearing in the sky when sunlight refracts through water droplets after rain. In Korean culture, rainbows symbolize hope and good fortune. The word ''무지갯빛'' (rainbow-colored) describes anything colorfully beautiful.", "examples": {"beginner": "There''s a rainbow!", "intermediate": "A rainbow appeared after the rain.", "advanced": "A vivid double rainbow hung in the sky.", "master": "The rainbow hanging in the sky at sunset after the rain is nature''s greatest gift."}, "variations": {"formal": ["A rainbow has appeared.", "There is a rainbow in the sky."], "casual": ["Rainbow!", "A rainbow''s out!"], "short": ["rainbow"]}, "dialogue": {"context": "Looking at the sky after the rain stopped", "dialogue": [{"speaker": "A", "text": "Wow, there''s a rainbow! Look!", "romanization": "", "translation": "와, 무지개 떴다! 봐봐!"}, {"speaker": "B", "text": "It''s really beautiful. Let''s take a photo.", "romanization": "", "translation": "진짜 예쁘다. 사진 찍자."}]}}}'),
  ('ubak', '우박', 'ubak', 'noun', 'weather', 'intermediate', 'rare', '["weather", "nature", "disaster", "rare"]', '{"ko": {"word": "우박", "explanation": "구름 속에서 얼음 덩어리가 되어 떨어지는 기상 현상입니다. 한국에서는 봄~여름에 갑자기 내리기도 하며, 농작물 피해를 주는 자연재해로 분류됩니다. 크기가 골프공만 한 우박이 내리면 뉴스에 보도됩니다.", "examples": {"beginner": "우박이 내려요.", "intermediate": "갑자기 우박이 쏟아졌어요.", "advanced": "우박으로 인해 농작물 피해가 컸다.", "master": "골프공만 한 우박이 쏟아져 차량 수십 대가 파손됐다."}, "variations": {"formal": ["우박이 내리고 있습니다.", "우박이 떨어지고 있습니다."], "casual": ["우박 온다!", "우박이야!"], "short": ["우박"]}, "dialogue": {"context": "갑자기 우박이 내리기 시작해서", "dialogue": [{"speaker": "A", "text": "어, 우박이다! 차 괜찮아?", "romanization": "eo, ubagida! cha gwaenchana?", "translation": "Oh, it''s hailing! Is the car okay?"}, {"speaker": "B", "text": "빨리 지하 주차장으로 옮기자.", "romanization": "ppalli jiha juchajang-euro olmgija.", "translation": "Let''s quickly move it to the underground parking lot."}]}}, "en": {"word": "hail", "explanation": "Hail, frozen precipitation that falls as balls or lumps of ice from cumulonimbus clouds. In Korea, hail occasionally falls during spring and summer, and is classified as a natural disaster when it damages crops or vehicles.", "examples": {"beginner": "It''s hailing.", "intermediate": "It suddenly started hailing.", "advanced": "The hail caused significant crop damage.", "master": "Golf ball-sized hail poured down, damaging dozens of vehicles."}, "variations": {"formal": ["It is hailing.", "Hail is falling."], "casual": ["It''s hailing!", "Hail!"], "short": ["hail"]}, "dialogue": {"context": "When it suddenly starts hailing", "dialogue": [{"speaker": "A", "text": "Oh, it''s hailing! Is the car okay?", "romanization": "", "translation": "어, 우박이다! 차 괜찮아?"}, {"speaker": "B", "text": "Let''s quickly move it to the underground parking lot.", "romanization": "", "translation": "빨리 지하 주차장으로 옮기자."}]}}}'),
  ('sonagi', '소나기', 'sonagi', 'noun', 'weather', 'beginner', 'common', '["weather", "rain", "summer", "korean-culture"]', '{"ko": {"word": "소나기", "explanation": "갑자기 세차게 내리다가 곧 그치는 비입니다. 한국 문학에서 매우 중요한 소재로, 황순원의 단편소설 ''소나기''는 한국인이라면 누구나 아는 작품입니다. 여름철에 자주 내리며, 로맨틱한 분위기를 연출하는 문학적 상징이기도 합니다.", "examples": {"beginner": "소나기가 와요.", "intermediate": "여름에는 소나기가 자주 내려요.", "advanced": "오후에 갑자기 소나기가 쏟아졌다.", "master": "소나기가 한바탕 지나간 뒤 무지개가 떴다."}, "variations": {"formal": ["소나기가 내리고 있습니다.", "소나기가 오고 있습니다."], "casual": ["소나기 온다!", "소나기야!"], "short": ["소나기"]}, "dialogue": {"context": "밖에서 갑자기 비가 쏟아져서", "dialogue": [{"speaker": "A", "text": "소나기다! 어디서 비 피하자.", "romanization": "sonagida! eodiseo bi pihaja.", "translation": "It''s a sudden shower! Let''s find shelter."}, {"speaker": "B", "text": "저기 편의점으로 가자. 금방 그칠 거야.", "romanization": "jeogi pyeonuijeom-euro gaja. geumbang geuchil geoya.", "translation": "Let''s go to that convenience store. It''ll stop soon."}]}}, "en": {"word": "sudden shower", "explanation": "A sudden, heavy downpour that stops quickly. This word holds deep cultural significance in Korea — Hwang Sun-won''s short story ''Sonagi'' is one of the most beloved works in Korean literature, known by virtually every Korean. Summer showers are also a romantic literary symbol.", "examples": {"beginner": "A sudden shower is coming.", "intermediate": "Sudden showers are common in summer.", "advanced": "A sudden shower poured down in the afternoon.", "master": "After the sudden shower passed, a rainbow appeared."}, "variations": {"formal": ["A sudden shower is falling.", "There is a sudden downpour."], "casual": ["It''s pouring!", "Sudden rain!"], "short": ["shower"]}, "dialogue": {"context": "When it suddenly starts pouring outside", "dialogue": [{"speaker": "A", "text": "It''s a sudden shower! Let''s find shelter.", "romanization": "", "translation": "소나기다! 어디서 비 피하자."}, {"speaker": "B", "text": "Let''s go to that convenience store. It''ll stop soon.", "romanization": "", "translation": "저기 편의점으로 가자. 금방 그칠 거야."}]}}}'),
  ('jangma', '장마', 'jangma', 'noun', 'weather', 'beginner', 'common', '["weather", "seasonal", "summer", "korean-culture"]', '{"ko": {"word": "장마", "explanation": "6월 말~7월 말에 지속적으로 비가 내리는 기간입니다. 동아시아 몬순 기후의 영향으로 한국, 중국, 일본에서 공통적으로 나타납니다. 한국에서 ''장마철''은 습도가 매우 높아 곰팡이 관리가 중요하고, 제습기 사용이 일반적입니다.", "examples": {"beginner": "장마가 시작됐어요.", "intermediate": "올해 장마는 6월 말에 시작해요.", "advanced": "장마철이라 빨래가 안 마른다.", "master": "올해 장마가 예년보다 일주일 늦게 시작돼 가뭄 우려가 커지고 있다."}, "variations": {"formal": ["장마가 시작되었습니다.", "장마철에 접어들었습니다."], "casual": ["장마 시작이야.", "장마철이네."], "short": ["장마"]}, "dialogue": {"context": "뉴스에서 장마 소식을 듣고", "dialogue": [{"speaker": "A", "text": "내일부터 장마래. 우산 꼭 챙겨.", "romanization": "naeilbuteo jangmarae. usan kkok chaenggyeo.", "translation": "They say the rainy season starts tomorrow. Make sure to bring an umbrella."}, {"speaker": "B", "text": "제습기도 꺼내야겠다.", "romanization": "jeseupgido kkeonaeyagetda.", "translation": "I should bring out the dehumidifier too."}]}}, "en": {"word": "monsoon / rainy season", "explanation": "The East Asian monsoon season, typically from late June to late July in Korea. During this period, continuous rainfall brings high humidity. Koreans commonly use dehumidifiers and take extra care against mold during jangma season. It is a shared weather phenomenon across Korea, China, and Japan.", "examples": {"beginner": "The rainy season has started.", "intermediate": "This year''s monsoon starts in late June.", "advanced": "The laundry won''t dry because of the rainy season.", "master": "This year''s monsoon started a week later than usual, raising drought concerns."}, "variations": {"formal": ["The monsoon season has begun.", "We have entered the rainy season."], "casual": ["The rainy season''s here.", "It''s monsoon time."], "short": ["monsoon"]}, "dialogue": {"context": "After hearing monsoon news on TV", "dialogue": [{"speaker": "A", "text": "They say the rainy season starts tomorrow. Bring an umbrella.", "romanization": "", "translation": "내일부터 장마래. 우산 꼭 챙겨."}, {"speaker": "B", "text": "I should bring out the dehumidifier too.", "romanization": "", "translation": "제습기도 꺼내야겠다."}]}}}'),
  ('gamum', '가뭄', 'gamum', 'noun', 'weather', 'intermediate', 'uncommon', '["weather", "disaster", "agriculture", "nature"]', '{"ko": {"word": "가뭄", "explanation": "오랫동안 비가 오지 않아 땅이 마르는 현상입니다. 한국에서 가뭄은 특히 농업에 큰 피해를 주며, 봄 가뭄은 모내기 시기와 겹쳐 쌀 생산에 직접적인 영향을 미칩니다. ''가뭄에 콩 나듯''이라는 속담은 매우 드물다는 뜻입니다.", "examples": {"beginner": "가뭄이 심해요.", "intermediate": "올봄에 가뭄이 계속되고 있어요.", "advanced": "가뭄으로 인해 저수지 수위가 크게 낮아졌다.", "master": "기록적인 가뭄에 제한 급수가 시행되고 있다."}, "variations": {"formal": ["가뭄이 지속되고 있습니다.", "가뭄 피해가 확산되고 있습니다."], "casual": ["가뭄이 심하다.", "비가 안 와서 큰일이야."], "short": ["가뭄"]}, "dialogue": {"context": "농촌 뉴스를 보면서", "dialogue": [{"speaker": "A", "text": "올해 가뭄이 심하대. 농민들이 걱정이다.", "romanization": "olhae gamumi simhadae. nongmindeuri geokjjeongida.", "translation": "They say the drought is severe this year. I''m worried about the farmers."}, {"speaker": "B", "text": "비가 좀 와야 할 텐데.", "romanization": "biga jom waya hal tende.", "translation": "We really need some rain."}]}}, "en": {"word": "drought", "explanation": "A prolonged period without rainfall causing dry conditions. In Korea, drought particularly affects agriculture — spring droughts coincide with rice planting season, directly impacting rice production. The Korean proverb ''가뭄에 콩 나듯'' (like beans sprouting in a drought) means something extremely rare.", "examples": {"beginner": "The drought is severe.", "intermediate": "The drought has been continuing this spring.", "advanced": "The reservoir water level dropped significantly due to the drought.", "master": "Water rationing has been implemented due to the record drought."}, "variations": {"formal": ["The drought is persisting.", "Drought damage is spreading."], "casual": ["The drought''s bad.", "It really needs to rain."], "short": ["drought"]}, "dialogue": {"context": "Watching rural news", "dialogue": [{"speaker": "A", "text": "They say the drought is severe this year. I''m worried about the farmers.", "romanization": "", "translation": "올해 가뭄이 심하대. 농민들이 걱정이다."}, {"speaker": "B", "text": "We really need some rain.", "romanization": "", "translation": "비가 좀 와야 할 텐데."}]}}}'),
  ('hongsu', '홍수', 'hongsu', 'noun', 'weather', 'intermediate', 'uncommon', '["weather", "disaster", "nature", "news"]', '{"ko": {"word": "홍수", "explanation": "비가 많이 와서 강물이 넘치는 재해입니다. 한국에서는 장마철과 태풍 시기에 홍수가 자주 발생하며, 특히 반지하 주택(반지하방)이 침수 피해를 입는 경우가 뉴스에 자주 보도됩니다.", "examples": {"beginner": "홍수가 났어요.", "intermediate": "집중호우로 홍수가 발생했어요.", "advanced": "홍수로 인해 도로가 침수되었다.", "master": "기록적인 폭우에 하천이 범람하여 수백 세대가 대피했다."}, "variations": {"formal": ["홍수가 발생했습니다.", "홍수 피해가 우려됩니다."], "casual": ["홍수 났어!", "물이 넘쳤어."], "short": ["홍수"]}, "dialogue": {"context": "폭우 뉴스를 보면서", "dialogue": [{"speaker": "A", "text": "비가 너무 많이 와서 홍수 났대.", "romanization": "biga neomu mani waseo hongsu natdae.", "translation": "They say there''s been a flood because of all the rain."}, {"speaker": "B", "text": "저지대 주민들은 대피했대?", "romanization": "jeojidae jumindeureun daepiheatdae?", "translation": "Have the residents in low-lying areas evacuated?"}]}}, "en": {"word": "flood", "explanation": "A flood caused by excessive rainfall overflowing rivers and waterways. In Korea, floods commonly occur during the monsoon season and typhoon period. News coverage frequently reports flooding damage to semi-basement apartments (banjiha), a common housing type in Korean cities.", "examples": {"beginner": "There was a flood.", "intermediate": "Heavy rain caused a flood.", "advanced": "Roads were submerged due to the flood.", "master": "Rivers overflowed from record rainfall, forcing hundreds of households to evacuate."}, "variations": {"formal": ["A flood has occurred.", "Flood damage is a concern."], "casual": ["There''s a flood!", "The water overflowed."], "short": ["flood"]}, "dialogue": {"context": "Watching heavy rain news", "dialogue": [{"speaker": "A", "text": "They say there''s been a flood because of all the rain.", "romanization": "", "translation": "비가 너무 많이 와서 홍수 났대."}, {"speaker": "B", "text": "Have the residents in low-lying areas evacuated?", "romanization": "", "translation": "저지대 주민들은 대피했대?"}]}}}'),
  ('pokseol', '폭설', 'pokseol', 'noun', 'weather', 'intermediate', 'uncommon', '["weather", "winter", "disaster", "news"]', '{"ko": {"word": "폭설", "explanation": "갑자기 많은 양의 눈이 내리는 기상 현상입니다. 한국에서 폭설은 교통 마비, 비닐하우스 붕괴 등 큰 피해를 주며, 대설주의보(5cm 이상)와 대설경보(20cm 이상)로 구분합니다. 폭설이 오면 학교가 휴교하기도 합니다.", "examples": {"beginner": "폭설이 내렸어요.", "intermediate": "폭설로 학교가 쉬었어요.", "advanced": "폭설로 인해 고속도로가 전면 통제되었다.", "master": "기습 폭설에 귀경길 차량이 꼼짝없이 갇혔다."}, "variations": {"formal": ["폭설이 내리고 있습니다.", "대설경보가 발령되었습니다."], "casual": ["눈 엄청 온다!", "폭설이야!"], "short": ["폭설"]}, "dialogue": {"context": "아침에 창밖을 보며", "dialogue": [{"speaker": "A", "text": "밤새 폭설이 내렸나 봐. 차가 묻혔어.", "romanization": "bamsae pokseori naeryeonna bwa. chaga muthyeosseo.", "translation": "Looks like there was heavy snow overnight. The car is buried."}, {"speaker": "B", "text": "오늘 대중교통으로 출근하자.", "romanization": "oneul daejunggyotongeuro chulgeunhaja.", "translation": "Let''s take public transit to work today."}]}}, "en": {"word": "heavy snow", "explanation": "A sudden heavy snowfall event. In Korea, heavy snow can paralyze transportation and collapse greenhouse structures. Weather alerts are issued at two levels: heavy snow advisory (5cm+) and heavy snow warning (20cm+). Schools may close during severe snowfall.", "examples": {"beginner": "There was heavy snow.", "intermediate": "School was canceled due to heavy snow.", "advanced": "The highway was completely shut down due to heavy snow.", "master": "Vehicles heading home were stranded by the surprise blizzard."}, "variations": {"formal": ["Heavy snow is falling.", "A heavy snow warning has been issued."], "casual": ["It''s snowing like crazy!", "Heavy snow!"], "short": ["heavy snow"]}, "dialogue": {"context": "Looking out the window in the morning", "dialogue": [{"speaker": "A", "text": "Looks like there was heavy snow overnight. The car is buried.", "romanization": "", "translation": "밤새 폭설이 내렸나 봐. 차가 묻혔어."}, {"speaker": "B", "text": "Let''s take public transit to work today.", "romanization": "", "translation": "오늘 대중교통으로 출근하자."}]}}}'),
  ('pogyeom', '폭염', 'pogyeom', 'noun', 'weather', 'intermediate', 'common', '["weather", "summer", "health", "news"]', '{"ko": {"word": "폭염", "explanation": "기온이 매우 높은 극심한 더위입니다. 한국 기상청 기준으로 일 최고기온 33도 이상이면 폭염주의보, 35도 이상이면 폭염경보가 발령됩니다. 최근 기후변화로 한국의 폭염 일수가 증가하고 있으며, 온열질환(열사병 등) 예방이 중요한 사회적 이슈입니다.", "examples": {"beginner": "폭염이 계속돼요.", "intermediate": "이번 여름 폭염이 심해요.", "advanced": "폭염경보가 발령되어 야외 활동을 자제해야 한다.", "master": "연일 체감온도 40도를 넘는 폭염에 온열질환자가 급증하고 있다."}, "variations": {"formal": ["폭염이 지속되고 있습니다.", "폭염주의보가 발령되었습니다."], "casual": ["너무 더워!", "폭염이야."], "short": ["폭염"]}, "dialogue": {"context": "한여름 더위에 대해 이야기하며", "dialogue": [{"speaker": "A", "text": "오늘도 폭염이래. 밖에 나가지 마.", "romanization": "oneuldo pogyeomirae. bakke nagaji ma.", "translation": "They say it''s a heatwave again today. Don''t go outside."}, {"speaker": "B", "text": "물 많이 마시고 에어컨 틀어.", "romanization": "mul mani masigo eeokon teureo.", "translation": "Drink lots of water and turn on the AC."}]}}, "en": {"word": "heatwave", "explanation": "An extreme heat event with very high temperatures. Korea''s meteorological agency issues heat advisories at 33°C (91°F) and heat warnings at 35°C (95°F). Due to climate change, heatwave days in Korea have been increasing, making heat-related illness prevention a major public health concern.", "examples": {"beginner": "The heatwave continues.", "intermediate": "The heatwave is severe this summer.", "advanced": "A heat warning was issued, so outdoor activities should be avoided.", "master": "Heat-related illness patients are surging as the perceived temperature exceeds 40°C daily."}, "variations": {"formal": ["The heatwave is persisting.", "A heat advisory has been issued."], "casual": ["It''s so hot!", "Heatwave!"], "short": ["heatwave"]}, "dialogue": {"context": "Talking about midsummer heat", "dialogue": [{"speaker": "A", "text": "They say it''s a heatwave again today. Don''t go outside.", "romanization": "", "translation": "오늘도 폭염이래. 밖에 나가지 마."}, {"speaker": "B", "text": "Drink lots of water and turn on the AC.", "romanization": "", "translation": "물 많이 마시고 에어컨 틀어."}]}}}'),
  ('hanpa', '한파', 'hanpa', 'noun', 'weather', 'intermediate', 'common', '["weather", "winter", "health", "news"]', '{"ko": {"word": "한파", "explanation": "급격하게 기온이 낮아지는 추운 날씨입니다. 한국 기상청은 아침 최저기온이 -12도 이하이면 한파주의보, -15도 이하이면 한파경보를 발령합니다. 한파가 오면 수도관 동파 방지와 동상 예방이 중요하며, 한국에서는 ''내복 챙겨 입어''가 겨울 인사처럼 쓰입니다.", "examples": {"beginner": "한파가 왔어요.", "intermediate": "이번 주 한파가 올 거래요.", "advanced": "한파로 인해 수도관이 얼어붙었다.", "master": "시베리아 한파의 영향으로 체감온도가 영하 25도까지 떨어졌다."}, "variations": {"formal": ["한파가 몰려오고 있습니다.", "한파주의보가 발령되었습니다."], "casual": ["완전 추워!", "한파야."], "short": ["한파"]}, "dialogue": {"context": "겨울에 외출 준비를 하면서", "dialogue": [{"speaker": "A", "text": "오늘 한파래. 내복 입었어?", "romanization": "oneul hanparae. naebok ibeosseo?", "translation": "They say there''s a cold wave today. Are you wearing thermals?"}, {"speaker": "B", "text": "당연하지. 핫팩도 챙겼어.", "romanization": "dangyeonhaji. hatpaekdo chaenggyeosseo.", "translation": "Of course. I brought hand warmers too."}]}}, "en": {"word": "cold wave", "explanation": "A sudden severe drop in temperature. Korea issues cold wave advisories at -12°C (10°F) and warnings at -15°C (5°F). During cold waves, preventing frozen pipes and frostbite are key concerns. In Korean culture, telling someone to ''wear your thermals'' (내복 챙겨 입어) is a common winter greeting showing care.", "examples": {"beginner": "A cold wave has arrived.", "intermediate": "They say a cold wave is coming this week.", "advanced": "Water pipes froze due to the cold wave.", "master": "The wind chill dropped to -25°C under the influence of a Siberian cold wave."}, "variations": {"formal": ["A cold wave is approaching.", "A cold wave advisory has been issued."], "casual": ["It''s freezing!", "Cold wave!"], "short": ["cold wave"]}, "dialogue": {"context": "Getting ready to go out in winter", "dialogue": [{"speaker": "A", "text": "They say there''s a cold wave today. Are you wearing thermals?", "romanization": "", "translation": "오늘 한파래. 내복 입었어?"}, {"speaker": "B", "text": "Of course. I brought hand warmers too.", "romanization": "", "translation": "당연하지. 핫팩도 챙겼어."}]}}}'),
  ('misemeonji', '미세먼지', 'misemeonji', 'noun', 'weather', 'beginner', 'common', '["weather", "health", "environment", "korean-culture", "daily-life"]', '{"ko": {"word": "미세먼지", "explanation": "공기 중에 떠다니는 매우 작은 먼지 입자(PM10, PM2.5)입니다. 한국에서 미세먼지는 일상생활에 큰 영향을 미치는 환경 문제로, 매일 아침 미세먼지 수치를 확인하는 것이 습관화되어 있습니다. 마스크(KF94) 착용이 일반적이며, ''미세먼지 나쁨''이면 야외 활동을 자제합니다.", "examples": {"beginner": "오늘 미세먼지가 나빠요.", "intermediate": "미세먼지 때문에 마스크를 써요.", "advanced": "초미세먼지 농도가 ''매우 나쁨'' 수준이다.", "master": "미세먼지 비상저감조치가 발령되어 차량 2부제가 시행되고 있다."}, "variations": {"formal": ["미세먼지 농도가 높습니다.", "미세먼지 주의보가 발령되었습니다."], "casual": ["미세먼지 심하다.", "오늘 공기 안 좋아."], "short": ["미세먼지"]}, "dialogue": {"context": "아침에 핸드폰으로 날씨를 확인하며", "dialogue": [{"speaker": "A", "text": "오늘 미세먼지 ''나쁨''이야. 마스크 꼭 써.", "romanization": "oneul misemeonji ''nappeum''iya. masekeu kkok sseo.", "translation": "Fine dust is ''bad'' today. Make sure to wear a mask."}, {"speaker": "B", "text": "공기청정기도 켜 놔야겠다.", "romanization": "gonggicheongjeong-gido kyeo nwayagetda.", "translation": "I should leave the air purifier on too."}]}}, "en": {"word": "fine dust / PM2.5", "explanation": "Microscopic particulate matter (PM10, PM2.5) suspended in the air. Fine dust is a major daily concern in Korea — checking dust levels every morning is a common habit. Wearing KF94 masks is standard practice, and outdoor activities are discouraged when levels are rated ''bad''. This issue has significantly shaped Korean daily life and culture.", "examples": {"beginner": "The fine dust is bad today.", "intermediate": "I wear a mask because of fine dust.", "advanced": "Ultra-fine dust concentration is at ''very bad'' level.", "master": "Emergency fine dust reduction measures are in effect with odd-even vehicle restrictions."}, "variations": {"formal": ["Fine dust concentration is high.", "A fine dust advisory has been issued."], "casual": ["The dust is bad.", "Air quality is poor today."], "short": ["fine dust"]}, "dialogue": {"context": "Checking the weather on phone in the morning", "dialogue": [{"speaker": "A", "text": "Fine dust is ''bad'' today. Make sure to wear a mask.", "romanization": "", "translation": "오늘 미세먼지 ''나쁨''이야. 마스크 꼭 써."}, {"speaker": "B", "text": "I should leave the air purifier on too.", "romanization": "", "translation": "공기청정기도 켜 놔야겠다."}]}}}'),
  ('hwangsa', '황사', 'hwangsa', 'noun', 'weather', 'intermediate', 'uncommon', '["weather", "spring", "health", "environment", "korean-culture"]', '{"ko": {"word": "황사", "explanation": "중국 내몽골·고비 사막에서 발생한 모래먼지가 바람을 타고 한반도로 날아오는 현상입니다. 주로 봄철(3~5월)에 발생하며, 하늘이 노랗게 변하고 시야가 뿌옇게 됩니다. 황사는 한국에서 오래전부터 있었던 현상으로, 조선왕조실록에도 기록이 있습니다.", "examples": {"beginner": "황사가 심해요.", "intermediate": "봄에 황사가 자주 와요.", "advanced": "황사로 인해 시야가 크게 떨어졌다.", "master": "황사와 미세먼지가 겹치면서 대기질이 최악의 수준을 기록했다."}, "variations": {"formal": ["황사가 발생했습니다.", "황사경보가 발령되었습니다."], "casual": ["황사 온다.", "하늘이 노래."], "short": ["황사"]}, "dialogue": {"context": "봄에 하늘이 뿌옇게 보여서", "dialogue": [{"speaker": "A", "text": "하늘이 왜 이렇게 노래? 황사야?", "romanization": "haneuri wae ireoke norae? hwangsaya?", "translation": "Why is the sky so yellow? Is it yellow dust?"}, {"speaker": "B", "text": "응, 황사 왔대. 창문 닫아.", "romanization": "eung, hwangsa watdae. changmun dada.", "translation": "Yeah, yellow dust is here. Close the windows."}]}}, "en": {"word": "yellow dust", "explanation": "Sand and dust particles blown from the Gobi Desert and Inner Mongolia in China to the Korean Peninsula by wind. It primarily occurs in spring (March-May), turning the sky yellow and reducing visibility. Yellow dust has been a phenomenon in Korea for centuries, even documented in the Joseon Dynasty records (Annals of the Joseon Dynasty).", "examples": {"beginner": "The yellow dust is bad.", "intermediate": "Yellow dust often comes in spring.", "advanced": "Visibility dropped significantly due to yellow dust.", "master": "Air quality hit its worst level as yellow dust combined with fine dust."}, "variations": {"formal": ["Yellow dust has arrived.", "A yellow dust warning has been issued."], "casual": ["Yellow dust is here.", "The sky is yellow."], "short": ["yellow dust"]}, "dialogue": {"context": "When the sky looks hazy in spring", "dialogue": [{"speaker": "A", "text": "Why is the sky so yellow? Is it yellow dust?", "romanization": "", "translation": "하늘이 왜 이렇게 노래? 황사야?"}, {"speaker": "B", "text": "Yeah, yellow dust is here. Close the windows.", "romanization": "", "translation": "응, 황사 왔대. 창문 닫아."}]}}}'),
  ('gion', '기온', 'gion', 'noun', 'weather', 'beginner', 'common', '["weather", "measurement", "daily-life", "news"]', '{"ko": {"word": "기온", "explanation": "대기의 온도를 나타내는 말입니다. 한국은 섭씨(°C)를 사용하며, 일기예보에서 ''낮 최고기온''과 ''아침 최저기온''을 매일 알려줍니다. 한국의 기온은 사계절 변화가 뚜렷하여 여름 35도, 겨울 -15도까지 큰 차이를 보입니다.", "examples": {"beginner": "오늘 기온이 높아요.", "intermediate": "낮 최고 기온이 30도래요.", "advanced": "기온이 영하로 떨어지면서 도로가 얼었다.", "master": "기온 역전 현상으로 인해 대기오염이 심화되고 있다."}, "variations": {"formal": ["기온이 상승하고 있습니다.", "현재 기온은 25도입니다."], "casual": ["기온 몇 도야?", "온도가 높다."], "short": ["기온"]}, "dialogue": {"context": "외출 전 날씨를 확인하며", "dialogue": [{"speaker": "A", "text": "오늘 기온 몇 도야?", "romanization": "oneul gion myeot doya?", "translation": "What''s the temperature today?"}, {"speaker": "B", "text": "낮에 28도래. 반팔 입어.", "romanization": "naje 28dorae. banpal ibeo.", "translation": "They say 28 degrees during the day. Wear short sleeves."}]}}, "en": {"word": "temperature", "explanation": "The degree of heat in the atmosphere. Korea uses Celsius (°C), and weather forecasts daily report the daytime high and morning low temperatures. Korea has four distinct seasons with temperatures ranging widely from 35°C in summer to -15°C in winter.", "examples": {"beginner": "The temperature is high today.", "intermediate": "The daytime high will be 30 degrees.", "advanced": "Roads froze as the temperature dropped below zero.", "master": "Air pollution worsened due to a temperature inversion phenomenon."}, "variations": {"formal": ["The temperature is rising.", "The current temperature is 25 degrees."], "casual": ["What''s the temp?", "It''s hot out."], "short": ["temperature"]}, "dialogue": {"context": "Checking weather before going out", "dialogue": [{"speaker": "A", "text": "What''s the temperature today?", "romanization": "", "translation": "오늘 기온 몇 도야?"}, {"speaker": "B", "text": "They say 28 degrees during the day. Wear short sleeves.", "romanization": "", "translation": "낮에 28도래. 반팔 입어."}]}}}'),
  ('seupdo', '습도', 'seupdo', 'noun', 'weather', 'intermediate', 'common', '["weather", "measurement", "comfort", "health"]', '{"ko": {"word": "습도", "explanation": "공기 중에 포함된 수증기의 양을 나타내는 지표입니다. 한국의 여름(장마철)은 습도가 80~90%까지 올라가 매우 불쾌하며, 겨울에는 20~30%로 매우 건조합니다. 실내 쾌적 습도는 40~60%이며, 한국 가정에서는 여름에 제습기, 겨울에 가습기를 사용합니다.", "examples": {"beginner": "습도가 높아요.", "intermediate": "장마철에는 습도가 매우 높아요.", "advanced": "습도가 높아서 불쾌지수가 올라갔다.", "master": "상대습도 90%를 넘기면서 체감온도가 실제 기온보다 5도 이상 높게 느껴진다."}, "variations": {"formal": ["습도가 높습니다.", "현재 습도는 85%입니다."], "casual": ["습하다.", "눅눅해."], "short": ["습도"]}, "dialogue": {"context": "여름에 덥고 습한 날", "dialogue": [{"speaker": "A", "text": "너무 눅눅해. 습도가 몇이야?", "romanization": "neomu nuknukhae. seupdoga myeochiya?", "translation": "It''s so muggy. What''s the humidity?"}, {"speaker": "B", "text": "85%래. 제습기 켜자.", "romanization": "85%rae. jeseupgi kyeoja.", "translation": "They say 85%. Let''s turn on the dehumidifier."}]}}, "en": {"word": "humidity", "explanation": "A measure of water vapor in the air. Korean summers (monsoon season) see humidity levels of 80-90%, making it very uncomfortable, while winters drop to 20-30%, extremely dry. The ideal indoor humidity is 40-60%. Korean homes typically use dehumidifiers in summer and humidifiers in winter.", "examples": {"beginner": "The humidity is high.", "intermediate": "Humidity is very high during the monsoon season.", "advanced": "The discomfort index rose because of high humidity.", "master": "With relative humidity exceeding 90%, the perceived temperature feels over 5 degrees higher than actual."}, "variations": {"formal": ["The humidity is high.", "The current humidity is 85%."], "casual": ["It''s humid.", "It''s muggy."], "short": ["humidity"]}, "dialogue": {"context": "On a hot and humid summer day", "dialogue": [{"speaker": "A", "text": "It''s so muggy. What''s the humidity?", "romanization": "", "translation": "너무 눅눅해. 습도가 몇이야?"}, {"speaker": "B", "text": "They say 85%. Let''s turn on the dehumidifier.", "romanization": "", "translation": "85%래. 제습기 켜자."}]}}}'),
  ('gangsuryang', '강수량', 'gangsuryang', 'noun', 'weather', 'advanced', 'uncommon', '["weather", "measurement", "news", "academic"]', '{"ko": {"word": "강수량", "explanation": "일정 기간 동안 내린 비나 눈의 양을 밀리미터(mm) 단위로 나타낸 것입니다. 한국의 연평균 강수량은 약 1,300mm이며, 그중 50~60%가 장마철(6~8월)에 집중됩니다. 뉴스에서 ''시간당 강수량 50mm 이상''은 매우 강한 비를 의미합니다.", "examples": {"beginner": "강수량이 많아요.", "intermediate": "올해 강수량이 평년보다 적어요.", "advanced": "시간당 강수량이 30mm를 넘었다.", "master": "누적 강수량이 500mm를 초과하면서 산사태 위험이 높아지고 있다."}, "variations": {"formal": ["강수량이 증가하고 있습니다.", "예상 강수량은 100mm입니다."], "casual": ["비가 많이 왔어.", "비 엄청 왔다."], "short": ["강수량"]}, "dialogue": {"context": "뉴스에서 기상 정보를 보며", "dialogue": [{"speaker": "A", "text": "시간당 강수량이 50mm래. 역대급이야.", "romanization": "sigandang gangsuryangi 50mmrae. yeokdaegeu-giya.", "translation": "They say the hourly precipitation is 50mm. That''s record-breaking."}, {"speaker": "B", "text": "저지대 침수 조심해야겠다.", "romanization": "jeojidae chimsu josimhaeyagetda.", "translation": "We need to watch out for flooding in low-lying areas."}]}}, "en": {"word": "precipitation", "explanation": "The amount of rain or snow measured in millimeters (mm) over a given period. Korea''s average annual precipitation is about 1,300mm, with 50-60% concentrated during the monsoon season (June-August). When news reports ''hourly precipitation over 50mm,'' it indicates extremely heavy rainfall.", "examples": {"beginner": "The precipitation is high.", "intermediate": "This year''s precipitation is less than average.", "advanced": "Hourly precipitation exceeded 30mm.", "master": "Landslide risk is increasing as cumulative precipitation exceeds 500mm."}, "variations": {"formal": ["Precipitation is increasing.", "Expected precipitation is 100mm."], "casual": ["It rained a lot.", "So much rain."], "short": ["precipitation"]}, "dialogue": {"context": "Watching weather news", "dialogue": [{"speaker": "A", "text": "They say hourly precipitation is 50mm. That''s record-breaking.", "romanization": "", "translation": "시간당 강수량이 50mm래. 역대급이야."}, {"speaker": "B", "text": "We need to watch out for flooding in low-lying areas.", "romanization": "", "translation": "저지대 침수 조심해야겠다."}]}}}'),
  ('pungsok', '풍속', 'pungsok', 'noun', 'weather', 'advanced', 'uncommon', '["weather", "measurement", "news", "academic"]', '{"ko": {"word": "풍속", "explanation": "바람이 부는 속도를 나타내는 기상 용어입니다. 한국에서는 초속(m/s) 단위를 사용하며, 풍속 14m/s 이상이면 강풍주의보, 21m/s 이상이면 강풍경보가 발령됩니다. 태풍 시 풍속은 뉴스의 핵심 정보입니다.", "examples": {"beginner": "풍속이 강해요.", "intermediate": "오늘 풍속이 10m/s예요.", "advanced": "풍속이 20m/s를 넘어 강풍경보가 발령됐다.", "master": "순간 최대 풍속 45m/s의 초강력 태풍이 접근하고 있다."}, "variations": {"formal": ["풍속이 강합니다.", "풍속 14m/s 이상이 예상됩니다."], "casual": ["바람 세다.", "바람 엄청 불어."], "short": ["풍속"]}, "dialogue": {"context": "태풍 소식을 듣고", "dialogue": [{"speaker": "A", "text": "태풍 풍속이 40m/s래. 위험하다.", "romanization": "taepung pungsogi 40m/srae. wiheomhada.", "translation": "They say the typhoon wind speed is 40m/s. It''s dangerous."}, {"speaker": "B", "text": "창문 다 닫고 테이프 붙여야겠다.", "romanization": "changmun da datgo teipeu butyeoyagetda.", "translation": "We should close all windows and tape them up."}]}}, "en": {"word": "wind speed", "explanation": "A meteorological measurement of how fast wind is blowing, measured in meters per second (m/s) in Korea. A strong wind advisory is issued at 14m/s and a warning at 21m/s. During typhoons, wind speed is the most critical piece of information in news broadcasts.", "examples": {"beginner": "The wind speed is strong.", "intermediate": "Today''s wind speed is 10m/s.", "advanced": "A strong wind warning was issued as wind speed exceeded 20m/s.", "master": "A super typhoon with maximum instantaneous wind speed of 45m/s is approaching."}, "variations": {"formal": ["Wind speed is strong.", "Wind speeds above 14m/s are expected."], "casual": ["The wind is strong.", "It''s super windy."], "short": ["wind speed"]}, "dialogue": {"context": "Hearing typhoon news", "dialogue": [{"speaker": "A", "text": "They say the typhoon wind speed is 40m/s. It''s dangerous.", "romanization": "", "translation": "태풍 풍속이 40m/s래. 위험하다."}, {"speaker": "B", "text": "We should close all windows and tape them up.", "romanization": "", "translation": "창문 다 닫고 테이프 붙여야겠다."}]}}}'),
  ('ilgyocha', '일교차', 'ilgyocha', 'noun', 'weather', 'intermediate', 'common', '["weather", "health", "spring", "autumn", "korean-culture"]', '{"ko": {"word": "일교차", "explanation": "하루 중 최고 기온과 최저 기온의 차이입니다. 한국의 봄과 가을에는 일교차가 15~20도까지 벌어지는데, 이때 감기에 걸리기 쉽습니다. 한국에서는 ''일교차가 크니까 겉옷 챙겨''가 봄·가을 단골 인사입니다. 환절기 건강 관리의 핵심 지표입니다.", "examples": {"beginner": "일교차가 커요.", "intermediate": "봄에는 일교차가 크니까 감기 조심하세요.", "advanced": "일교차가 15도 이상 벌어져 건강 관리에 주의해야 한다.", "master": "큰 일교차로 인한 혈관 수축이 심혈관 질환 위험을 높인다."}, "variations": {"formal": ["일교차가 크겠습니다.", "일교차에 유의하시기 바랍니다."], "casual": ["일교차 심하다.", "낮이랑 밤이랑 온도 차이 크다."], "short": ["일교차"]}, "dialogue": {"context": "봄 아침에 외출 준비를 하면서", "dialogue": [{"speaker": "A", "text": "오늘 일교차가 15도래. 겉옷 챙겨.", "romanization": "oneul ilgyochaga 15dorae. geodot chaenggyeo.", "translation": "The temperature range is 15 degrees today. Bring a jacket."}, {"speaker": "B", "text": "환절기라 감기 조심해야지.", "romanization": "hwanjeolgi-ra gamgi josimhaeyaji.", "translation": "It''s the changing season, so I need to be careful not to catch a cold."}]}}, "en": {"word": "daily temperature range", "explanation": "The difference between the highest and lowest temperatures in a single day. In Korean spring and autumn, this range can reach 15-20 degrees, making people susceptible to colds. Saying ''the temperature range is big, bring a jacket'' (일교차가 크니까 겉옷 챙겨) is a common seasonal greeting in Korea, reflecting the culture of caring about others'' health.", "examples": {"beginner": "The temperature range is big.", "intermediate": "Be careful of colds since the temperature range is large in spring.", "advanced": "Health precautions are needed as the daily range exceeds 15 degrees.", "master": "Blood vessel constriction from large temperature swings increases cardiovascular disease risk."}, "variations": {"formal": ["The daily temperature range will be large.", "Please be mindful of the temperature range."], "casual": ["Big temp swings.", "Huge difference between day and night."], "short": ["temp range"]}, "dialogue": {"context": "Getting ready to go out on a spring morning", "dialogue": [{"speaker": "A", "text": "The temperature range is 15 degrees today. Bring a jacket.", "romanization": "", "translation": "오늘 일교차가 15도래. 겉옷 챙겨."}, {"speaker": "B", "text": "It''s the changing season, so I need to be careful not to catch a cold.", "romanization": "", "translation": "환절기라 감기 조심해야지."}]}}}'),
  ('chegamondo', '체감온도', 'chegamondo', 'noun', 'weather', 'intermediate', 'common', '["weather", "measurement", "winter", "daily-life"]', '{"ko": {"word": "체감온도", "explanation": "바람이나 습도를 고려하여 사람이 실제로 느끼는 온도입니다. 겨울에 바람이 강하면 실제 기온보다 훨씬 춥게 느껴지고, 여름에 습도가 높으면 더 덥게 느껴집니다. 한국 기상청에서는 겨울에 체감온도를 함께 발표하며, 체감온도가 -20도 이하면 외출 시 각별한 주의가 필요합니다.", "examples": {"beginner": "체감온도가 낮아요.", "intermediate": "바람 때문에 체감온도가 더 낮아요.", "advanced": "실제 기온은 -5도지만 체감온도는 -15도다.", "master": "강풍에 의한 체감온도 급강하로 동상 위험이 높아지고 있다."}, "variations": {"formal": ["체감온도가 매우 낮겠습니다.", "체감온도는 영하 20도입니다."], "casual": ["체감온도 완전 낮아.", "바람 불면 더 추워."], "short": ["체감온도"]}, "dialogue": {"context": "겨울에 바람이 세게 부는 날", "dialogue": [{"speaker": "A", "text": "기온은 -3도인데 체감온도는 -12도래.", "romanization": "gion-eun -3doinde chegamondoneun -12dorae.", "translation": "The actual temp is -3, but wind chill is -12."}, {"speaker": "B", "text": "목도리랑 장갑 꼭 해.", "romanization": "mokdorirang janggap kkok hae.", "translation": "Make sure to wear a scarf and gloves."}]}}, "en": {"word": "wind chill / feels like temperature", "explanation": "The temperature as perceived by the human body, accounting for wind and humidity. Strong winter wind makes it feel much colder than the actual temperature, while high summer humidity makes it feel hotter. Korea''s meteorological agency reports wind chill alongside actual temperature in winter. Extra caution is advised when wind chill drops below -20°C.", "examples": {"beginner": "The wind chill is low.", "intermediate": "Wind chill is even lower because of the wind.", "advanced": "The actual temperature is -5, but the wind chill is -15.", "master": "Frostbite risk is increasing due to a sharp wind chill drop from strong winds."}, "variations": {"formal": ["The wind chill will be very low.", "The wind chill is -20 degrees."], "casual": ["Wind chill is crazy low.", "Way colder with the wind."], "short": ["wind chill"]}, "dialogue": {"context": "On a windy winter day", "dialogue": [{"speaker": "A", "text": "The actual temp is -3, but wind chill is -12.", "romanization": "", "translation": "기온은 -3도인데 체감온도는 -12도래."}, {"speaker": "B", "text": "Make sure to wear a scarf and gloves.", "romanization": "", "translation": "목도리랑 장갑 꼭 해."}]}}}'),
  ('jawiseon', '자외선', 'jawiseon', 'noun', 'weather', 'intermediate', 'common', '["weather", "health", "summer", "beauty"]', '{"ko": {"word": "자외선", "explanation": "태양에서 나오는 보이지 않는 빛으로, 피부 노화와 화상을 유발합니다. 한국에서는 자외선 차단이 스킨케어의 핵심으로, 날씨에 상관없이 자외선 차단제(선크림)를 바르는 것이 일반적입니다. 자외선 지수는 0~11+ 단계로 표시되며, ''매우 높음'' 이상이면 야외 활동 시 주의가 필요합니다.", "examples": {"beginner": "자외선이 강해요.", "intermediate": "자외선 차단제를 꼭 바르세요.", "advanced": "자외선 지수가 ''매우 높음''이라 야외 활동을 자제해야 한다.", "master": "장시간 자외선 노출은 광노화를 촉진하고 피부암 위험을 높인다."}, "variations": {"formal": ["자외선이 강하겠습니다.", "자외선 지수가 높습니다."], "casual": ["자외선 쩔어.", "선크림 발라."], "short": ["자외선"]}, "dialogue": {"context": "여름에 외출 전", "dialogue": [{"speaker": "A", "text": "오늘 자외선 지수 높대. 선크림 발랐어?", "romanization": "oneul jawiseon jisu noptdae. seonkeurim ballasseo?", "translation": "The UV index is high today. Did you put on sunscreen?"}, {"speaker": "B", "text": "응, 모자도 쓸 거야.", "romanization": "eung, mojado sseul geoya.", "translation": "Yeah, I''m going to wear a hat too."}]}}, "en": {"word": "UV rays / ultraviolet", "explanation": "Invisible light from the sun that causes skin aging and burns. In Korea, UV protection is a cornerstone of skincare — applying sunscreen (선크림) daily regardless of weather is standard practice. The UV index is rated on a scale of 0-11+, and outdoor precautions are advised when the level is ''very high'' or above.", "examples": {"beginner": "The UV rays are strong.", "intermediate": "Make sure to apply sunscreen.", "advanced": "The UV index is ''very high,'' so outdoor activities should be limited.", "master": "Prolonged UV exposure accelerates photoaging and increases skin cancer risk."}, "variations": {"formal": ["UV rays will be strong.", "The UV index is high."], "casual": ["The UV is intense.", "Put on sunscreen."], "short": ["UV"]}, "dialogue": {"context": "Before going out in summer", "dialogue": [{"speaker": "A", "text": "The UV index is high today. Did you put on sunscreen?", "romanization": "", "translation": "오늘 자외선 지수 높대. 선크림 발랐어?"}, {"speaker": "B", "text": "Yeah, I''m going to wear a hat too.", "romanization": "", "translation": "응, 모자도 쓸 거야."}]}}}'),
  ('yeoldaeya', '열대야', 'yeoldaeya', 'noun', 'weather', 'intermediate', 'common', '["weather", "summer", "health", "sleep"]', '{"ko": {"word": "열대야", "explanation": "밤 최저기온이 25도 이상인 무더운 밤을 말합니다. 한국의 여름에 열대야가 지속되면 잠을 이루기 어려워 수면 부족과 건강 문제가 발생합니다. 에어컨 없이는 잠들기 힘들어 전기료가 급증하며, ''열대야 꿀팁''(시원하게 자는 방법)이 매년 여름 인기 검색어입니다.", "examples": {"beginner": "열대야라서 더워요.", "intermediate": "열대야 때문에 잠을 못 잤어요.", "advanced": "열대야가 일주일째 계속되면서 온열질환자가 늘고 있다.", "master": "도시 열섬 효과로 서울의 열대야 일수가 매년 증가하는 추세다."}, "variations": {"formal": ["열대야 현상이 지속되고 있습니다.", "열대야가 예상됩니다."], "casual": ["열대야야.", "밤에도 너무 더워."], "short": ["열대야"]}, "dialogue": {"context": "무더운 여름 밤에", "dialogue": [{"speaker": "A", "text": "또 열대야야. 잠을 못 자겠어.", "romanization": "tto yeoldaeyaya. jameul mot jagesseo.", "translation": "Another tropical night. I can''t sleep."}, {"speaker": "B", "text": "에어컨 타이머 맞춰 놓고 자.", "romanization": "eeokon taimeo matchwo noko ja.", "translation": "Set the AC timer and go to sleep."}]}}, "en": {"word": "tropical night", "explanation": "A night when the minimum temperature stays above 25°C (77°F). During Korean summers, consecutive tropical nights cause sleep deprivation and health issues. Air conditioning becomes essential, causing electricity bills to surge. ''Tropical night tips'' (how to sleep cool) is a popular search term every summer in Korea.", "examples": {"beginner": "It''s hot because of the tropical night.", "intermediate": "I couldn''t sleep because of the tropical night.", "advanced": "Heat-related illness patients are increasing as tropical nights continue for a week.", "master": "Seoul''s tropical night count increases annually due to the urban heat island effect."}, "variations": {"formal": ["The tropical night phenomenon continues.", "A tropical night is expected."], "casual": ["It''s a tropical night.", "It''s so hot even at night."], "short": ["tropical night"]}, "dialogue": {"context": "On a sweltering summer night", "dialogue": [{"speaker": "A", "text": "Another tropical night. I can''t sleep.", "romanization": "", "translation": "또 열대야야. 잠을 못 자겠어."}, {"speaker": "B", "text": "Set the AC timer and go to sleep.", "romanization": "", "translation": "에어컨 타이머 맞춰 놓고 자."}]}}}'),
  ('kkotsaemchuwi', '꽃샘추위', 'kkotsaemchuwi', 'noun', 'weather', 'advanced', 'uncommon', '["weather", "spring", "korean-culture", "seasonal"]', '{"ko": {"word": "꽃샘추위", "explanation": "봄에 꽃이 피기 직전 다시 찾아오는 추위입니다. ''꽃샘''은 ''꽃을 시샘하다''(꽃이 피는 것을 질투하다)라는 뜻으로, 겨울이 봄꽃의 등장을 시기해서 다시 추위를 보낸다는 한국 고유의 아름다운 표현입니다. 3~4월에 주로 나타나며, 벚꽃 개화 시기와 겹치는 경우가 많습니다.", "examples": {"beginner": "꽃샘추위가 왔어요.", "intermediate": "3월인데 꽃샘추위로 다시 추워졌어요.", "advanced": "꽃샘추위에 벚꽃 개화가 늦어지고 있다.", "master": "기상학적으로 꽃샘추위는 북쪽 찬 기단의 일시적 남하로 설명된다."}, "variations": {"formal": ["꽃샘추위가 찾아왔습니다.", "꽃샘추위가 예상됩니다."], "casual": ["꽃샘추위야.", "봄인데 왜 이렇게 추워?"], "short": ["꽃샘추위"]}, "dialogue": {"context": "봄인데 갑자기 추워져서", "dialogue": [{"speaker": "A", "text": "3월인데 왜 이렇게 추워? 꽃샘추위인가?", "romanization": "samwolinde wae ireoke chuwo? kkotsaemchuwi-inga?", "translation": "It''s March but why is it so cold? Is it a late spring cold snap?"}, {"speaker": "B", "text": "응, 겨울 옷 다시 꺼내야겠다.", "romanization": "eung, gyeoul ot dasi kkeonaeyagetda.", "translation": "Yeah, I need to bring out winter clothes again."}]}}, "en": {"word": "late spring cold snap", "explanation": "A return of cold weather just before spring flowers bloom. The Korean word literally means ''flower-jealousy cold'' — the poetic idea that winter is jealous of the flowers about to bloom and sends cold weather back. This uniquely Korean expression reflects the culture''s deep connection to nature and seasons. It typically occurs in March-April, often coinciding with cherry blossom season.", "examples": {"beginner": "The late spring cold snap is here.", "intermediate": "It''s March but it got cold again with the spring cold snap.", "advanced": "Cherry blossom blooming is delayed due to the spring cold snap.", "master": "Meteorologically, the late spring cold snap is explained by a temporary southward shift of northern cold air masses."}, "variations": {"formal": ["A late spring cold snap has arrived.", "A spring cold snap is expected."], "casual": ["It''s a spring cold snap.", "Why is it cold when it''s spring?"], "short": ["spring cold"]}, "dialogue": {"context": "When it suddenly gets cold in spring", "dialogue": [{"speaker": "A", "text": "It''s March but why is it so cold? Late spring cold snap?", "romanization": "", "translation": "3월인데 왜 이렇게 추워? 꽃샘추위인가?"}, {"speaker": "B", "text": "Yeah, I need to bring out winter clothes again.", "romanization": "", "translation": "응, 겨울 옷 다시 꺼내야겠다."}]}}}'),
  ('samhansaon', '삼한사온', 'samhansaon', 'noun', 'weather', 'advanced', 'uncommon', '["weather", "winter", "korean-culture", "idiom"]', '{"ko": {"word": "삼한사온", "explanation": "겨울에 3일은 춥고 4일은 따뜻한 날씨가 반복되는 현상입니다. 한자어로 三寒四溫(삼한사온)이며, 시베리아 고기압의 영향으로 한반도에 나타나는 기후 패턴입니다. 전통적으로 한국 겨울의 대표적 특징이었으나, 최근에는 기후변화로 이 패턴이 뚜렷하지 않다는 지적도 있습니다. 일상 대화에서 겨울 날씨를 설명할 때 자주 쓰입니다.", "examples": {"beginner": "삼한사온이에요.", "intermediate": "삼한사온이라 이번 주는 따뜻할 거예요.", "advanced": "올겨울은 삼한사온 패턴이 뚜렷하지 않다.", "master": "기후변화로 삼한사온의 주기가 불규칙해지면서 전통적 기후 패턴이 무너지고 있다."}, "variations": {"formal": ["삼한사온 현상이 나타나고 있습니다.", "삼한사온 패턴이 예상됩니다."], "casual": ["삼한사온이야.", "3일 춥고 4일 따뜻해."], "short": ["삼한사온"]}, "dialogue": {"context": "겨울에 갑자기 따뜻해져서", "dialogue": [{"speaker": "A", "text": "어제까지 추웠는데 오늘 왜 이렇게 따뜻해?", "romanization": "eojekkaji chuwonneunde oneul wae ireoke ttatteuthae?", "translation": "It was cold until yesterday, why is it so warm today?"}, {"speaker": "B", "text": "삼한사온이잖아. 내일 모레부터 다시 추울 거야.", "romanization": "samhansaon-ijana. naeil moributeo dasi chuwul geoya.", "translation": "It''s the 3 cold 4 warm pattern. It''ll be cold again the day after tomorrow."}]}}, "en": {"word": "3 cold 4 warm days pattern", "explanation": "A traditional Korean winter weather pattern where 3 cold days are followed by 4 warm days in a repeating cycle. Written as 三寒四溫 in Chinese characters, this pattern is caused by the Siberian high-pressure system''s influence on the Korean Peninsula. While it was traditionally a hallmark of Korean winters, climate change has made this pattern less predictable in recent years. It remains a commonly used expression in everyday winter conversation.", "examples": {"beginner": "It''s the 3 cold 4 warm pattern.", "intermediate": "It''ll be warm this week because of the 3 cold 4 warm pattern.", "advanced": "The samhansaon pattern isn''t as distinct this winter.", "master": "Climate change is disrupting the traditional samhansaon cycle, making it increasingly irregular."}, "variations": {"formal": ["The samhansaon pattern is appearing.", "A samhansaon pattern is expected."], "casual": ["It''s samhansaon.", "3 days cold, 4 days warm."], "short": ["samhansaon"]}, "dialogue": {"context": "When it suddenly gets warm in winter", "dialogue": [{"speaker": "A", "text": "It was cold until yesterday, why is it so warm today?", "romanization": "", "translation": "어제까지 추웠는데 오늘 왜 이렇게 따뜻해?"}, {"speaker": "B", "text": "It''s the 3 cold 4 warm pattern. It''ll be cold again the day after tomorrow.", "romanization": "", "translation": "삼한사온이잖아. 내일 모레부터 다시 추울 거야."}]}}}'),
  ('mudeowi', '무더위', 'mudeowi', 'noun', 'weather', 'intermediate', 'common', '["weather", "summer", "daily-life", "uncomfortable"]', '{"ko": {"word": "무더위", "explanation": "여름철에 기온과 습도가 매우 높아 견디기 힘든 더위를 말합니다. 한국의 7~8월에 자주 발생하며, ''폭염''보다 일상적인 표현입니다.", "examples": {"beginner": "무더위가 심해요.", "intermediate": "올해 무더위가 예년보다 일찍 시작됐어요.", "advanced": "연일 계속되는 무더위에 전력 소비가 급증하고 있다.", "master": "무더위가 기승을 부리면서 온열 질환자가 속출하고 있다."}, "variations": {"formal": ["무더위가 계속되고 있습니다.", "무더위에 주의하시기 바랍니다."], "casual": ["무더위 진짜 심하다.", "더워 죽겠다."], "short": ["무더위"]}, "dialogue": {"context": "한여름 점심시간에 동료와 대화하면서", "dialogue": [{"speaker": "A", "text": "오늘 무더위 진짜 장난 아니다.", "romanization": "oneul mudeowi jinjja jangnan anida.", "translation": "The sweltering heat today is no joke."}, {"speaker": "B", "text": "그러게, 밖에 나가기 싫어.", "romanization": "geureoge, bakke nagagi sireo.", "translation": "I know, I don''t want to go outside."}]}}, "en": {"word": "sweltering heat", "explanation": "Intense summer heat with high humidity that is difficult to endure. Common during July and August in Korea, it is a more colloquial term than ''polgyeom'' (heatwave).", "examples": {"beginner": "The sweltering heat is severe.", "intermediate": "This year''s sweltering heat started earlier than usual.", "advanced": "Electricity consumption is surging due to the ongoing sweltering heat.", "master": "As the sweltering heat rages on, heat-related illness cases are surging."}, "variations": {"formal": ["The sweltering heat continues.", "Please be cautious of the extreme heat."], "casual": ["The heat is killer.", "It''s so hot I could die."], "short": ["sweltering heat"]}, "dialogue": {"context": "Chatting with a coworker during lunch on a midsummer day", "dialogue": [{"speaker": "A", "text": "The sweltering heat today is no joke.", "romanization": "", "translation": "오늘 무더위 진짜 장난 아니다."}, {"speaker": "B", "text": "I know, I don''t want to go outside.", "romanization": "", "translation": "그러게, 밖에 나가기 싫어."}]}}}'),
  ('jjimtongdeowi', '찜통더위', 'jjimtongdeowi', 'noun', 'weather', 'advanced', 'common', '["weather", "summer", "slang", "daily-life"]', '{"ko": {"word": "찜통더위", "explanation": "찜통(steamer) 안에 들어간 것처럼 습하고 무더운 날씨를 비유적으로 표현한 말입니다. 한국 여름의 높은 습도를 강조하는 표현입니다.", "examples": {"beginner": "오늘 찜통더위예요.", "intermediate": "찜통더위에 에어컨 없이는 못 살아요.", "advanced": "장마가 끝나자마자 찜통더위가 시작됐다.", "master": "찜통더위 속에서도 건설 노동자들은 묵묵히 작업을 이어갔다."}, "variations": {"formal": ["찜통더위가 계속되고 있습니다.", "찜통 같은 더위입니다."], "casual": ["완전 찜통이야.", "찜통더위 미쳤다."], "short": ["찜통더위"]}, "dialogue": {"context": "퇴근 후 집에 돌아와서 가족과 대화하면서", "dialogue": [{"speaker": "A", "text": "오늘 밖에 완전 찜통이었어.", "romanization": "oneul bakke wanjeon jjimtong-ieosseo.", "translation": "It was like a steamer outside today."}, {"speaker": "B", "text": "에어컨 틀어놨으니까 시원할 거야.", "romanization": "eeokon teureonwasseunikka siwonhal geoya.", "translation": "I turned on the AC so it''ll be cool."}]}}, "en": {"word": "steamy heat", "explanation": "A figurative expression comparing the weather to being inside a steamer (jjimtong). It emphasizes the high humidity characteristic of Korean summers.", "examples": {"beginner": "It''s steamy hot today.", "intermediate": "I can''t live without AC in this steamy heat.", "advanced": "The steamy heat started as soon as the monsoon ended.", "master": "Even in the steamy heat, construction workers quietly continued their work."}, "variations": {"formal": ["The steamy heat continues.", "It feels like a steamer."], "casual": ["It''s totally like a steamer.", "This steamy heat is insane."], "short": ["steamy heat"]}, "dialogue": {"context": "Talking to family after coming home from work", "dialogue": [{"speaker": "A", "text": "It was like a steamer outside today.", "romanization": "", "translation": "오늘 밖에 완전 찜통이었어."}, {"speaker": "B", "text": "I turned on the AC so it''ll be cool.", "romanization": "", "translation": "에어컨 틀어놨으니까 시원할 거야."}]}}}'),
  ('yeongha', '영하', 'yeongha', 'noun', 'weather', 'intermediate', 'common', '["weather", "temperature", "winter", "measurement"]', '{"ko": {"word": "영하", "explanation": "섭씨 0도 이하의 온도를 나타내는 말입니다. ''영하 10도''는 -10°C를 뜻합니다. 한국 겨울에 자주 사용되는 표현입니다.", "examples": {"beginner": "오늘 영하예요.", "intermediate": "내일 아침 기온이 영하 5도래요.", "advanced": "영하의 날씨에도 불구하고 마라톤 대회가 열렸다.", "master": "영하 20도를 밑도는 혹한에 수도관이 동파됐다."}, "variations": {"formal": ["기온이 영하로 내려갔습니다.", "영하의 날씨가 이어지고 있습니다."], "casual": ["영하야.", "영하로 떨어졌대."], "short": ["영하"]}, "dialogue": {"context": "아침에 일기예보를 보면서", "dialogue": [{"speaker": "A", "text": "내일 영하 10도래.", "romanization": "naeil yeongha sipdo rae.", "translation": "They say it''ll be minus 10 degrees tomorrow."}, {"speaker": "B", "text": "옷 따뜻하게 입어야겠다.", "romanization": "ot ttatteuthage ibeoyagetda.", "translation": "I''d better dress warmly."}]}}, "en": {"word": "below zero", "explanation": "A term indicating temperatures below 0°C (Celsius). ''Yeongha 10do'' means -10°C. Frequently used during Korean winters.", "examples": {"beginner": "It''s below zero today.", "intermediate": "Tomorrow morning''s temperature will be minus 5 degrees.", "advanced": "The marathon was held despite the below-zero weather.", "master": "Water pipes burst in the bitter cold of minus 20 degrees."}, "variations": {"formal": ["The temperature has dropped below zero.", "Below-zero weather continues."], "casual": ["It''s below zero.", "It dropped below zero."], "short": ["below zero"]}, "dialogue": {"context": "Watching the weather forecast in the morning", "dialogue": [{"speaker": "A", "text": "They say it''ll be minus 10 tomorrow.", "romanization": "", "translation": "내일 영하 10도래."}, {"speaker": "B", "text": "I''d better dress warmly.", "romanization": "", "translation": "옷 따뜻하게 입어야겠다."}]}}}'),
  ('yeongsang', '영상', 'yeongsang', 'noun', 'weather', 'intermediate', 'common', '["weather", "temperature", "measurement"]', '{"ko": {"word": "영상", "explanation": "섭씨 0도 이상의 온도를 나타내는 말입니다. ''영상 5도''는 +5°C를 뜻합니다. ''영하''의 반대말로, 기상 예보에서 자주 사용됩니다. 참고: ''영상''은 ''동영상(video)''이라는 뜻도 있습니다.", "examples": {"beginner": "오늘 영상 3도예요.", "intermediate": "낮에는 영상으로 올라간대요.", "advanced": "이번 주말부터 기온이 영상으로 회복될 전망이다.", "master": "영상과 영하를 오가는 일교차에 건강 관리에 유의해야 한다."}, "variations": {"formal": ["기온이 영상으로 올라갔습니다.", "영상의 기온이 유지되고 있습니다."], "casual": ["영상이래.", "드디어 영상이다."], "short": ["영상"]}, "dialogue": {"context": "겨울이 끝나갈 무렵 친구와 대화하면서", "dialogue": [{"speaker": "A", "text": "드디어 내일부터 영상이래!", "romanization": "deudieo naeilbuteo yeongsang-irae!", "translation": "Finally, it''ll be above zero starting tomorrow!"}, {"speaker": "B", "text": "겨울이 끝나가는구나.", "romanization": "gyeouri kkeunnaganeuguna.", "translation": "Winter is coming to an end."}]}}, "en": {"word": "above zero", "explanation": "A term indicating temperatures above 0°C (Celsius). ''Yeongsang 5do'' means +5°C. The opposite of ''yeongha'' (below zero), frequently used in weather forecasts. Note: ''yeongsang'' also means ''video'' in a different context.", "examples": {"beginner": "It''s 3 degrees above zero today.", "intermediate": "They say it''ll rise above zero during the day.", "advanced": "Temperatures are expected to recover to above zero from this weekend.", "master": "We must take care of our health with the daily temperature swings between above and below zero."}, "variations": {"formal": ["The temperature has risen above zero.", "Above-zero temperatures are being maintained."], "casual": ["It''s above zero.", "Finally above zero."], "short": ["above zero"]}, "dialogue": {"context": "Chatting with a friend as winter nears its end", "dialogue": [{"speaker": "A", "text": "Finally, it''ll be above zero starting tomorrow!", "romanization": "", "translation": "드디어 내일부터 영상이래!"}, {"speaker": "B", "text": "Winter is coming to an end.", "romanization": "", "translation": "겨울이 끝나가는구나."}]}}}'),
  ('ssalssalhada', '쌀쌀하다', 'ssalssalhada', 'adjective', 'weather', 'intermediate', 'common', '["weather", "adjective", "autumn", "daily-life"]', '{"ko": {"word": "쌀쌀하다", "explanation": "날씨가 약간 춥고 서늘한 느낌을 표현하는 형용사입니다. ''춥다''보다 정도가 약하며, 가을이나 초겨울에 자주 사용됩니다.", "examples": {"beginner": "날씨가 쌀쌀해요.", "intermediate": "아침저녁으로 쌀쌀해졌어요.", "advanced": "가을이 깊어지면서 공기가 한층 쌀쌀해졌다.", "master": "쌀쌀한 바람이 옷깃을 여미게 하는 계절이 돌아왔다."}, "variations": {"formal": ["날씨가 쌀쌀합니다.", "쌀쌀한 날씨가 이어지고 있습니다."], "casual": ["쌀쌀하다.", "좀 쌀쌀하네."], "short": ["쌀쌀"]}, "dialogue": {"context": "가을에 퇴근하면서 동료와 이야기하면서", "dialogue": [{"speaker": "A", "text": "밖에 나오니까 꽤 쌀쌀하네.", "romanization": "bakke naonikka kkwae ssalssalhane.", "translation": "It''s quite chilly now that we''re outside."}, {"speaker": "B", "text": "이제 가을이 제대로 왔나 봐.", "romanization": "ije gaeuri jedaero wanna bwa.", "translation": "Looks like autumn has really arrived."}]}}, "en": {"word": "chilly", "explanation": "An adjective describing weather that is slightly cold and cool. It is milder than ''chupda'' (cold) and often used in autumn or early winter.", "examples": {"beginner": "The weather is chilly.", "intermediate": "It''s gotten chilly in the mornings and evenings.", "advanced": "The air has become much chillier as autumn deepens.", "master": "The season that makes you pull your collar tight against the chilly wind has returned."}, "variations": {"formal": ["The weather is chilly.", "The chilly weather continues."], "casual": ["It''s chilly.", "A bit chilly, huh."], "short": ["chilly"]}, "dialogue": {"context": "Talking with a coworker while leaving work in autumn", "dialogue": [{"speaker": "A", "text": "It''s quite chilly now that we''re outside.", "romanization": "", "translation": "밖에 나오니까 꽤 쌀쌀하네."}, {"speaker": "B", "text": "Looks like autumn has really arrived.", "romanization": "", "translation": "이제 가을이 제대로 왔나 봐."}]}}}'),
  ('pogeunhada', '포근하다', 'pogeunhada', 'adjective', 'weather', 'intermediate', 'common', '["weather", "adjective", "spring", "comfortable"]', '{"ko": {"word": "포근하다", "explanation": "날씨가 따뜻하고 부드러운 느낌을 표현하는 형용사입니다. 봄날의 따뜻한 기운이나 이불 속 같은 아늑함을 나타냅니다.", "examples": {"beginner": "오늘 날씨가 포근해요.", "intermediate": "봄바람이 포근하게 불어요.", "advanced": "삼월 초순의 포근한 날씨가 벚꽃 개화를 앞당겼다.", "master": "어머니의 품처럼 포근한 봄 햇살이 온 세상을 감싸안았다."}, "variations": {"formal": ["포근한 날씨입니다.", "날씨가 포근합니다."], "casual": ["포근하다.", "날씨 포근하네."], "short": ["포근"]}, "dialogue": {"context": "봄날 공원을 산책하면서", "dialogue": [{"speaker": "A", "text": "오늘 날씨 정말 포근하다.", "romanization": "oneul nalssi jeongmal pogeunhada.", "translation": "The weather is really cozy today."}, {"speaker": "B", "text": "산책하기 딱 좋은 날이야.", "romanization": "sanchaekagi ttak joeun nariya.", "translation": "It''s a perfect day for a walk."}]}}, "en": {"word": "cozy/mild", "explanation": "An adjective describing warm, soft, and comfortable weather. It conveys the gentle warmth of a spring day or the snugness of being under a blanket.", "examples": {"beginner": "The weather is cozy today.", "intermediate": "The spring breeze blows gently and warmly.", "advanced": "The mild weather in early March accelerated the cherry blossom bloom.", "master": "The cozy spring sunshine, like a mother''s embrace, wrapped the whole world."}, "variations": {"formal": ["The weather is mild.", "It is cozy weather."], "casual": ["It''s cozy.", "Weather''s nice and mild."], "short": ["cozy"]}, "dialogue": {"context": "Taking a walk in the park on a spring day", "dialogue": [{"speaker": "A", "text": "The weather is really cozy today.", "romanization": "", "translation": "오늘 날씨 정말 포근하다."}, {"speaker": "B", "text": "It''s a perfect day for a walk.", "romanization": "", "translation": "산책하기 딱 좋은 날이야."}]}}}'),
  ('hwachanghada', '화창하다', 'hwachanghada', 'adjective', 'weather', 'intermediate', 'common', '["weather", "adjective", "spring", "pleasant"]', '{"ko": {"word": "화창하다", "explanation": "날씨가 맑고 밝으며 따뜻한 상태를 나타내는 형용사입니다. 주로 봄이나 가을의 맑은 날에 사용되며, 긍정적인 느낌을 줍니다.", "examples": {"beginner": "오늘 날씨가 화창해요.", "intermediate": "화창한 날씨에 소풍을 갔어요.", "advanced": "며칠간 이어진 화창한 날씨에 나들이객이 크게 늘었다.", "master": "화창한 봄 날씨가 코로나로 움츠러든 시민들의 발걸음을 밖으로 이끌었다."}, "variations": {"formal": ["화창한 날씨입니다.", "날씨가 화창합니다."], "casual": ["날씨 화창하다.", "완전 화창하네."], "short": ["화창"]}, "dialogue": {"context": "주말 아침에 가족과 계획을 세우면서", "dialogue": [{"speaker": "A", "text": "날씨가 화창하니까 어디 나갈까?", "romanization": "nalssiga hwachanghanikka eodi nagalkka?", "translation": "It''s bright and clear, shall we go somewhere?"}, {"speaker": "B", "text": "좋아! 공원에 가자.", "romanization": "joa! gongwone gaja.", "translation": "Sure! Let''s go to the park."}]}}, "en": {"word": "bright and clear", "explanation": "An adjective describing weather that is sunny, bright, and warm. Mainly used for clear spring or autumn days, it carries a positive connotation.", "examples": {"beginner": "The weather is bright and clear today.", "intermediate": "We went on a picnic on a bright, clear day.", "advanced": "The number of day-trippers surged thanks to the continued bright weather.", "master": "The bright spring weather drew citizens, who had been cooped up due to COVID, back outdoors."}, "variations": {"formal": ["The weather is bright and clear.", "It is a beautiful day."], "casual": ["It''s gorgeous out.", "Totally clear and sunny."], "short": ["bright and clear"]}, "dialogue": {"context": "Making weekend plans with family on a morning", "dialogue": [{"speaker": "A", "text": "It''s bright and clear, shall we go somewhere?", "romanization": "", "translation": "날씨가 화창하니까 어디 나갈까?"}, {"speaker": "B", "text": "Sure! Let''s go to the park.", "romanization": "", "translation": "좋아! 공원에 가자."}]}}}'),
  ('eulssineonseureobda', '을씨년스럽다', 'eulssineonseureobda', 'adjective', 'weather', 'advanced', 'uncommon', '["weather", "adjective", "autumn", "literary"]', '{"ko": {"word": "을씨년스럽다", "explanation": "날씨가 흐리고 춥고 스산하여 기분이 우울해지는 느낌을 표현하는 형용사입니다. 늦가을이나 초겨울의 쓸쓸한 분위기를 묘사할 때 자주 사용됩니다.", "examples": {"beginner": "날씨가 을씨년스러워요.", "intermediate": "을씨년스러운 날씨에 기분이 가라앉았어요.", "advanced": "잎이 다 진 가로수길이 을씨년스러운 분위기를 자아내고 있다.", "master": "을씨년스러운 늦가을 풍경 속에서 홀로 걷는 사내의 뒷모습이 쓸쓸하기 그지없었다."}, "variations": {"formal": ["을씨년스러운 날씨입니다.", "날씨가 을씨년스럽습니다."], "casual": ["완전 을씨년스럽다.", "날씨가 을씨년스럽네."], "short": ["을씨년스럽다"]}, "dialogue": {"context": "흐리고 추운 가을날 창밖을 보면서", "dialogue": [{"speaker": "A", "text": "날씨가 너무 을씨년스럽다.", "romanization": "nalssiga neomu eulssineonseureobda.", "translation": "The weather is so gloomy and dreary."}, {"speaker": "B", "text": "따뜻한 차라도 한 잔 하자.", "romanization": "ttatteutan charado han jan haja.", "translation": "Let''s at least have a cup of warm tea."}]}}, "en": {"word": "gloomy/dreary", "explanation": "An adjective describing weather that is overcast, cold, and desolate, making one feel melancholic. Often used to describe the bleak atmosphere of late autumn or early winter.", "examples": {"beginner": "The weather is gloomy.", "intermediate": "My mood sank with the dreary weather.", "advanced": "The barren tree-lined streets create a gloomy atmosphere.", "master": "The lonely back of a man walking alone through the dreary late autumn landscape was utterly desolate."}, "variations": {"formal": ["The weather is dreary.", "It is gloomy weather."], "casual": ["So dreary out.", "The weather''s really gloomy."], "short": ["gloomy"]}, "dialogue": {"context": "Looking out the window on a cloudy, cold autumn day", "dialogue": [{"speaker": "A", "text": "The weather is so gloomy and dreary.", "romanization": "", "translation": "날씨가 너무 을씨년스럽다."}, {"speaker": "B", "text": "Let''s at least have a cup of warm tea.", "romanization": "", "translation": "따뜻한 차라도 한 잔 하자."}]}}}'),
  ('boseulbi', '보슬비', 'boseulbi', 'noun', 'weather', 'advanced', 'uncommon', '["weather", "rain", "poetic", "gentle"]', '{"ko": {"word": "보슬비", "explanation": "아주 가늘고 부드럽게 내리는 비를 뜻합니다. ''이슬비''보다 조금 더 굵고, ''가랑비''와 비슷한 정도입니다. 시적이고 감성적인 표현으로 자주 사용됩니다.", "examples": {"beginner": "보슬비가 내려요.", "intermediate": "보슬비가 내리는 날에는 산책이 좋아요.", "advanced": "보슬비가 내리는 골목길을 우산 없이 걸었다.", "master": "보슬비에 젖은 벚꽃잎이 보도블록 위에 수채화를 그려놓았다."}, "variations": {"formal": ["보슬비가 내리고 있습니다.", "보슬비가 오고 있습니다."], "casual": ["보슬비 온다.", "보슬비 내리네."], "short": ["보슬비"]}, "dialogue": {"context": "창밖에 가벼운 비가 내리는 카페에서", "dialogue": [{"speaker": "A", "text": "보슬비 내리는 날 카페가 분위기 좋다.", "romanization": "boseulbi naerineun nal kape-ga bunwigi jota.", "translation": "The café has a nice vibe on a drizzly day."}, {"speaker": "B", "text": "그러게, 커피 마시기 딱 좋은 날이야.", "romanization": "geureoge, keopi masigi ttak joeun nariya.", "translation": "Right, it''s a perfect day for coffee."}]}}, "en": {"word": "drizzle", "explanation": "A very fine, gentle rain. Slightly heavier than ''iseulbi'' (mist-like rain) and similar to ''garangbi'' (light rain). Often used as a poetic and sentimental expression.", "examples": {"beginner": "A drizzle is falling.", "intermediate": "A walk is nice on a drizzly day.", "advanced": "I walked through the drizzly alley without an umbrella.", "master": "Cherry blossom petals soaked in the drizzle painted a watercolor on the sidewalk."}, "variations": {"formal": ["A drizzle is falling.", "It is drizzling."], "casual": ["It''s drizzling.", "Light drizzle out."], "short": ["drizzle"]}, "dialogue": {"context": "At a café while light rain falls outside", "dialogue": [{"speaker": "A", "text": "The café has a nice vibe on a drizzly day.", "romanization": "", "translation": "보슬비 내리는 날 카페가 분위기 좋다."}, {"speaker": "B", "text": "Right, it''s a perfect day for coffee.", "romanization": "", "translation": "그러게, 커피 마시기 딱 좋은 날이야."}]}}}'),
  ('pogu', '폭우', 'pogu', 'noun', 'weather', 'intermediate', 'common', '["weather", "rain", "disaster", "summer"]', '{"ko": {"word": "폭우", "explanation": "갑자기 많은 양의 비가 쏟아지는 현상입니다. 한국의 장마철이나 여름에 자주 발생하며, 홍수나 산사태 등 피해를 유발할 수 있습니다.", "examples": {"beginner": "폭우가 내려요.", "intermediate": "폭우 때문에 길이 막혔어요.", "advanced": "갑작스런 폭우로 저지대에 침수 피해가 발생했다.", "master": "기록적인 폭우가 수도권을 강타하며 도시 기능이 마비됐다."}, "variations": {"formal": ["폭우가 쏟아지고 있습니다.", "폭우 주의보가 발령됐습니다."], "casual": ["폭우 온다.", "비 엄청 쏟아진다."], "short": ["폭우"]}, "dialogue": {"context": "갑자기 비가 세차게 내리기 시작하면서", "dialogue": [{"speaker": "A", "text": "갑자기 폭우가 쏟아지네!", "romanization": "gapjagi pogu-ga ssodajine!", "translation": "A sudden downpour is pouring!"}, {"speaker": "B", "text": "일단 이 건물 안에서 기다리자.", "romanization": "ildan i geonmul aneseo gidarija.", "translation": "Let''s wait inside this building for now."}]}}, "en": {"word": "downpour", "explanation": "A sudden heavy rainfall. Frequent during Korea''s monsoon season and summer, it can cause damage such as flooding and landslides.", "examples": {"beginner": "A downpour is falling.", "intermediate": "The roads were blocked because of the downpour.", "advanced": "A sudden downpour caused flooding in low-lying areas.", "master": "A record-breaking downpour struck the capital region, paralyzing city functions."}, "variations": {"formal": ["A downpour is pouring.", "A heavy rain warning has been issued."], "casual": ["Downpour coming.", "It''s pouring like crazy."], "short": ["downpour"]}, "dialogue": {"context": "As rain suddenly starts pouring heavily", "dialogue": [{"speaker": "A", "text": "A sudden downpour is pouring!", "romanization": "", "translation": "갑자기 폭우가 쏟아지네!"}, {"speaker": "B", "text": "Let''s wait inside this building for now.", "romanization": "", "translation": "일단 이 건물 안에서 기다리자."}]}}}'),
  ('hambagnun', '함박눈', 'hambagnun', 'noun', 'weather', 'intermediate', 'common', '["weather", "snow", "winter", "poetic"]', '{"ko": {"word": "함박눈", "explanation": "눈송이가 크고 풍성하게 내리는 눈을 뜻합니다. ''함박''은 ''큰 그릇''이라는 뜻으로, 그릇처럼 크고 탐스러운 눈을 비유합니다. 아름답고 낭만적인 이미지를 가진 표현입니다.", "examples": {"beginner": "함박눈이 와요!", "intermediate": "함박눈이 펑펑 내리고 있어요.", "advanced": "함박눈이 소복소복 쌓여 세상이 하얗게 변했다.", "master": "함박눈이 내리는 크리스마스이브에 연인들의 발걸음이 거리를 수놓았다."}, "variations": {"formal": ["함박눈이 내리고 있습니다.", "함박눈이 쏟아지고 있습니다."], "casual": ["함박눈이다!", "함박눈 펑펑 온다."], "short": ["함박눈"]}, "dialogue": {"context": "겨울날 창밖을 보다가", "dialogue": [{"speaker": "A", "text": "와, 함박눈이다!", "romanization": "wa, hambagnun-ida!", "translation": "Wow, it''s big fluffy snow!"}, {"speaker": "B", "text": "진짜 예쁘다. 눈사람 만들까?", "romanization": "jinjja yeppeuda. nunsaram mandeulkka?", "translation": "So pretty. Shall we make a snowman?"}]}}, "en": {"word": "big fluffy snow", "explanation": "Large, abundant snowflakes falling. ''Hambak'' means ''large bowl,'' metaphorically describing snow as big and plump as a bowl. It carries a beautiful and romantic image.", "examples": {"beginner": "Big fluffy snow is falling!", "intermediate": "Big fluffy snowflakes are pouring down.", "advanced": "The big fluffy snow piled up softly, turning the world white.", "master": "Couples'' footsteps adorned the streets on a Christmas Eve with big fluffy snow falling."}, "variations": {"formal": ["Big fluffy snow is falling.", "Heavy snowflakes are pouring."], "casual": ["It''s big fluffy snow!", "Huge snowflakes are coming down."], "short": ["big fluffy snow"]}, "dialogue": {"context": "Looking out the window on a winter day", "dialogue": [{"speaker": "A", "text": "Wow, it''s big fluffy snow!", "romanization": "", "translation": "와, 함박눈이다!"}, {"speaker": "B", "text": "So pretty. Shall we make a snowman?", "romanization": "", "translation": "진짜 예쁘다. 눈사람 만들까?"}]}}}'),
  ('jinnunkkaebi', '진눈깨비', 'jinnunkkaebi', 'noun', 'weather', 'advanced', 'uncommon', '["weather", "winter", "rain", "snow"]', '{"ko": {"word": "진눈깨비", "explanation": "비와 눈이 섞여 내리는 기상 현상입니다. 기온이 0도 근처일 때 발생하며, 초겨울이나 늦겨울에 자주 볼 수 있습니다.", "examples": {"beginner": "진눈깨비가 와요.", "intermediate": "아침에 진눈깨비가 내렸어요.", "advanced": "진눈깨비가 내려 도로가 질척거렸다.", "master": "진눈깨비로 시작된 초겨울의 비가 어느덧 함박눈으로 변했다."}, "variations": {"formal": ["진눈깨비가 내리고 있습니다.", "진눈깨비가 예상됩니다."], "casual": ["진눈깨비 온다.", "비인지 눈인지 모르겠다."], "short": ["진눈깨비"]}, "dialogue": {"context": "초겨울 아침에 출근 준비를 하면서", "dialogue": [{"speaker": "A", "text": "밖에 진눈깨비 내리고 있어.", "romanization": "bakke jinnunkkaebi naerigo isseo.", "translation": "It''s sleeting outside."}, {"speaker": "B", "text": "미끄러우니까 조심해서 가.", "romanization": "mikkeureunikka josimhaeseo ga.", "translation": "Be careful since it''ll be slippery."}]}}, "en": {"word": "sleet", "explanation": "A weather phenomenon where rain and snow fall together. It occurs when the temperature is around 0°C and is common in early or late winter.", "examples": {"beginner": "It''s sleeting.", "intermediate": "It sleeted this morning.", "advanced": "The roads became muddy from the sleet.", "master": "The early winter rain that started as sleet had turned into big fluffy snow before long."}, "variations": {"formal": ["Sleet is falling.", "Sleet is expected."], "casual": ["It''s sleeting.", "Can''t tell if it''s rain or snow."], "short": ["sleet"]}, "dialogue": {"context": "Getting ready for work on an early winter morning", "dialogue": [{"speaker": "A", "text": "It''s sleeting outside.", "romanization": "", "translation": "밖에 진눈깨비 내리고 있어."}, {"speaker": "B", "text": "Be careful since it''ll be slippery.", "romanization": "", "translation": "미끄러우니까 조심해서 가."}]}}}'),
  ('dolpung', '돌풍', 'dolpung', 'noun', 'weather', 'intermediate', 'common', '["weather", "wind", "sudden", "danger"]', '{"ko": {"word": "돌풍", "explanation": "갑자기 세차게 부는 바람을 뜻합니다. 예측하기 어렵고 순간적으로 발생하여 피해를 줄 수 있습니다. 비유적으로 ''갑작스러운 변화''를 뜻하기도 합니다.", "examples": {"beginner": "돌풍이 불었어요.", "intermediate": "돌풍에 우산이 뒤집혔어요.", "advanced": "갑작스런 돌풍으로 공사 현장 가림막이 쓰러졌다.", "master": "신인 감독의 데뷔작이 영화계에 돌풍을 일으켰다."}, "variations": {"formal": ["돌풍이 불고 있습니다.", "돌풍 주의보가 발령됐습니다."], "casual": ["돌풍 분다.", "바람 갑자기 세지네."], "short": ["돌풍"]}, "dialogue": {"context": "바깥에서 갑자기 강한 바람이 불면서", "dialogue": [{"speaker": "A", "text": "갑자기 돌풍이 불어서 모자가 날아갔어!", "romanization": "gapjagi dolpung-i bureoseo mojaga naragasseo!", "translation": "A sudden gust blew my hat away!"}, {"speaker": "B", "text": "저기! 내가 잡아올게.", "romanization": "jeogi! naega jabaolge.", "translation": "Over there! I''ll grab it."}]}}, "en": {"word": "gust", "explanation": "A sudden, strong burst of wind. It is unpredictable and can cause damage. Figuratively, it can also mean ''a sudden change'' or ''sensation.''", "examples": {"beginner": "A gust blew.", "intermediate": "My umbrella flipped inside out from the gust.", "advanced": "A sudden gust toppled construction barriers at the site.", "master": "A rookie director''s debut film caused a sensation in the film industry."}, "variations": {"formal": ["A gust is blowing.", "A wind advisory has been issued."], "casual": ["A gust is blowing.", "Wind got strong all of a sudden."], "short": ["gust"]}, "dialogue": {"context": "A strong wind suddenly blows while outside", "dialogue": [{"speaker": "A", "text": "A sudden gust blew my hat away!", "romanization": "", "translation": "갑자기 돌풍이 불어서 모자가 날아갔어!"}, {"speaker": "B", "text": "Over there! I''ll grab it.", "romanization": "", "translation": "저기! 내가 잡아올게."}]}}}'),
  ('sandeulbaram', '산들바람', 'sandeulbaram', 'noun', 'weather', 'intermediate', 'common', '["weather", "wind", "pleasant", "poetic"]', '{"ko": {"word": "산들바람", "explanation": "부드럽고 기분 좋게 살랑살랑 부는 바람을 뜻합니다. 봄이나 가을의 쾌적한 바람을 묘사할 때 많이 사용됩니다. 시적이고 서정적인 표현입니다.", "examples": {"beginner": "산들바람이 불어요.", "intermediate": "산들바람이 기분 좋게 불어와요.", "advanced": "산들바람에 나뭇잎이 사르르 흔들리고 있다.", "master": "산들바람이 벚꽃잎을 실어 나르는 봄날의 풍경이 한 폭의 그림 같았다."}, "variations": {"formal": ["산들바람이 불고 있습니다.", "상쾌한 산들바람이 불어옵니다."], "casual": ["산들바람 분다.", "바람 시원하다."], "short": ["산들바람"]}, "dialogue": {"context": "봄날 야외에서 앉아 쉬면서", "dialogue": [{"speaker": "A", "text": "산들바람이 너무 시원하다.", "romanization": "sandeulbaram-i neomu siwonhada.", "translation": "The gentle breeze feels so refreshing."}, {"speaker": "B", "text": "이런 날씨가 일 년 내내면 좋겠다.", "romanization": "ireon nalssiga il nyeon naenae-myeon joketda.", "translation": "I wish the weather was like this all year."}]}}, "en": {"word": "gentle breeze", "explanation": "A soft, pleasant wind that blows lightly. Often used to describe the comfortable breeze of spring or autumn. A poetic and lyrical expression.", "examples": {"beginner": "A gentle breeze is blowing.", "intermediate": "A pleasant gentle breeze is blowing.", "advanced": "The leaves rustle softly in the gentle breeze.", "master": "The spring scene of cherry blossom petals carried by the gentle breeze looked like a painting."}, "variations": {"formal": ["A gentle breeze is blowing.", "A refreshing breeze is blowing."], "casual": ["Nice breeze.", "The wind feels great."], "short": ["gentle breeze"]}, "dialogue": {"context": "Sitting outdoors and resting on a spring day", "dialogue": [{"speaker": "A", "text": "The gentle breeze feels so refreshing.", "romanization": "", "translation": "산들바람이 너무 시원하다."}, {"speaker": "B", "text": "I wish the weather was like this all year.", "romanization": "", "translation": "이런 날씨가 일 년 내내면 좋겠다."}]}}}'),
  ('ilgiyebo', '일기예보', 'ilgiyebo', 'noun', 'weather', 'beginner', 'common', '["weather", "news", "daily-life", "media"]', '{"ko": {"word": "일기예보", "explanation": "기상 관측 데이터를 바탕으로 앞으로의 날씨를 미리 알려주는 것입니다. TV, 라디오, 앱 등에서 매일 제공되며, 한국인의 일상에서 매우 중요한 정보입니다.", "examples": {"beginner": "일기예보를 봐요.", "intermediate": "일기예보에서 내일 비 온다고 했어요.", "advanced": "일기예보가 빗나가서 우산을 안 가져왔다.", "master": "최근 AI 기반 일기예보의 정확도가 기존 수치 모델을 앞지르기 시작했다."}, "variations": {"formal": ["일기예보를 확인하시기 바랍니다.", "일기예보에 따르면"], "casual": ["일기예보 봤어?", "날씨 뭐래?"], "short": ["예보"]}, "dialogue": {"context": "아침에 출근 준비를 하면서", "dialogue": [{"speaker": "A", "text": "일기예보 봤어? 오늘 비 온대?", "romanization": "ilgiyebo bwasseo? oneul bi ondae?", "translation": "Did you check the forecast? Will it rain today?"}, {"speaker": "B", "text": "오후에 올 수도 있대. 우산 챙겨.", "romanization": "ohue ol sudo itdae. usan chaenggyeo.", "translation": "It might rain in the afternoon. Bring an umbrella."}]}}, "en": {"word": "weather forecast", "explanation": "A prediction of future weather based on meteorological observation data. Provided daily via TV, radio, and apps, it is essential information in Korean daily life.", "examples": {"beginner": "I watch the weather forecast.", "intermediate": "The weather forecast said it will rain tomorrow.", "advanced": "I didn''t bring an umbrella because the forecast was wrong.", "master": "AI-based weather forecasting has recently begun to surpass traditional numerical models in accuracy."}, "variations": {"formal": ["Please check the weather forecast.", "According to the weather forecast"], "casual": ["Did you check the forecast?", "What''s the weather say?"], "short": ["forecast"]}, "dialogue": {"context": "Getting ready for work in the morning", "dialogue": [{"speaker": "A", "text": "Did you check the forecast? Will it rain today?", "romanization": "", "translation": "일기예보 봤어? 오늘 비 온대?"}, {"speaker": "B", "text": "It might rain in the afternoon. Bring an umbrella.", "romanization": "", "translation": "오후에 올 수도 있대. 우산 챙겨."}]}}}'),
  ('gisangcheong', '기상청', 'gisangcheong', 'noun', 'weather', 'intermediate', 'common', '["weather", "government", "news", "korean-culture"]', '{"ko": {"word": "기상청", "explanation": "대한민국의 기상 업무를 담당하는 정부 기관입니다. 날씨 예보, 지진 감시, 기후 변화 분석 등을 수행합니다. 공식 명칭은 ''기상청(Korea Meteorological Administration)''입니다.", "examples": {"beginner": "기상청에서 알려줘요.", "intermediate": "기상청에서 폭염 주의보를 발령했어요.", "advanced": "기상청의 예보와 실제 날씨가 달라 시민들의 불만이 쏟아졌다.", "master": "기상청이 슈퍼컴퓨터를 도입하면서 중기 예보의 정확도가 크게 향상됐다."}, "variations": {"formal": ["기상청에 따르면", "기상청에서 발표한 바에 의하면"], "casual": ["기상청이 뭐래?", "기상청 예보 맞아?"], "short": ["기상청"]}, "dialogue": {"context": "태풍 소식을 듣고 걱정하면서", "dialogue": [{"speaker": "A", "text": "기상청에서 태풍 온다고 했어.", "romanization": "gisangcheong-eseo taepung ondago haesseo.", "translation": "The meteorological agency said a typhoon is coming."}, {"speaker": "B", "text": "언제 온대? 대비해야 하는 거 아니야?", "romanization": "eonje ondae? daebihaeya haneun geo aniya?", "translation": "When? Don''t we need to prepare?"}]}}, "en": {"word": "meteorological agency", "explanation": "The government agency responsible for meteorological services in South Korea. It handles weather forecasting, earthquake monitoring, and climate change analysis. Official name: Korea Meteorological Administration (KMA).", "examples": {"beginner": "The meteorological agency tells us.", "intermediate": "The meteorological agency issued a heatwave advisory.", "advanced": "Citizens complained when the KMA''s forecast differed from the actual weather.", "master": "The KMA''s adoption of a supercomputer significantly improved the accuracy of medium-range forecasts."}, "variations": {"formal": ["According to the meteorological agency", "As announced by the KMA"], "casual": ["What did the weather agency say?", "Is the KMA forecast right?"], "short": ["KMA"]}, "dialogue": {"context": "Worrying after hearing about a typhoon", "dialogue": [{"speaker": "A", "text": "The meteorological agency said a typhoon is coming.", "romanization": "", "translation": "기상청에서 태풍 온다고 했어."}, {"speaker": "B", "text": "When? Don''t we need to prepare?", "romanization": "", "translation": "언제 온대? 대비해야 하는 거 아니야?"}]}}}'),
  ('usan', '우산', 'usan', 'noun', 'weather', 'beginner', 'common', '["weather", "rain", "daily-life", "item"]', '{"ko": {"word": "우산", "explanation": "비를 막기 위해 머리 위에 펼쳐 드는 도구입니다. 한국에서는 편의점에서 투명 비닐우산을 쉽게 살 수 있습니다. ''양산''은 햇빛을 막는 우산입니다.", "examples": {"beginner": "우산 있어요?", "intermediate": "우산을 안 가져와서 비를 맞았어요.", "advanced": "접이식 우산을 항상 가방에 넣어 다닌다.", "master": "편의점 투명 우산이 한국의 비 오는 날 풍경을 대표하는 아이템이 되었다."}, "variations": {"formal": ["우산을 준비하시기 바랍니다.", "우산이 필요합니다."], "casual": ["우산 챙겨.", "우산 있어?"], "short": ["우산"]}, "dialogue": {"context": "퇴근 시간에 갑자기 비가 오면서", "dialogue": [{"speaker": "A", "text": "비 오는데 우산 있어?", "romanization": "bi oneunde usan isseo?", "translation": "It''s raining, do you have an umbrella?"}, {"speaker": "B", "text": "아니, 편의점에서 하나 사야겠다.", "romanization": "ani, pyeonuijeomeseo hana sayagetda.", "translation": "No, I''ll have to buy one at the convenience store."}]}}, "en": {"word": "umbrella", "explanation": "A tool held above the head to block rain. In Korea, transparent vinyl umbrellas are easily available at convenience stores. ''Yangsan'' is a parasol for blocking sunlight.", "examples": {"beginner": "Do you have an umbrella?", "intermediate": "I got soaked because I didn''t bring my umbrella.", "advanced": "I always carry a folding umbrella in my bag.", "master": "The transparent convenience store umbrella has become an iconic item of Korea''s rainy-day landscape."}, "variations": {"formal": ["Please prepare an umbrella.", "An umbrella is needed."], "casual": ["Bring an umbrella.", "Got an umbrella?"], "short": ["umbrella"]}, "dialogue": {"context": "It suddenly starts raining at quitting time", "dialogue": [{"speaker": "A", "text": "It''s raining, do you have an umbrella?", "romanization": "", "translation": "비 오는데 우산 있어?"}, {"speaker": "B", "text": "No, I''ll have to buy one at the convenience store.", "romanization": "", "translation": "아니, 편의점에서 하나 사야겠다."}]}}}'),
  ('janghwa', '장화', 'janghwa', 'noun', 'weather', 'beginner', 'common', '["weather", "rain", "clothing", "item"]', '{"ko": {"word": "장화", "explanation": "비나 진흙으로부터 발을 보호하기 위해 신는 방수 신발입니다. 보통 고무로 만들어져 ''고무장화''라고도 합니다. 장마철이나 비 오는 날 필수 아이템입니다.", "examples": {"beginner": "장화를 신어요.", "intermediate": "비 오는 날에는 장화를 신는 게 좋아요.", "advanced": "어렸을 때 장화 신고 웅덩이에서 노는 게 너무 좋았다.", "master": "요즘은 패션 장화가 유행해서 비 오는 날도 스타일리시하게 외출할 수 있다."}, "variations": {"formal": ["장화를 착용하시기 바랍니다.", "장화가 필요합니다."], "casual": ["장화 신어.", "장화 신고 나가."], "short": ["장화"]}, "dialogue": {"context": "비 오는 아침에 아이에게 준비시키면서", "dialogue": [{"speaker": "A", "text": "밖에 비 오니까 장화 신어.", "romanization": "bakke bi onikka janghwa sineo.", "translation": "It''s raining outside, so wear your rain boots."}, {"speaker": "B", "text": "노란 장화 신을래!", "romanization": "noran janghwa sineullae!", "translation": "I want to wear the yellow rain boots!"}]}}, "en": {"word": "rain boots", "explanation": "Waterproof boots worn to protect feet from rain and mud. Usually made of rubber, they are also called ''gomu janghwa'' (rubber boots). An essential item during the monsoon season.", "examples": {"beginner": "I wear rain boots.", "intermediate": "It''s better to wear rain boots on rainy days.", "advanced": "I loved playing in puddles wearing rain boots as a kid.", "master": "Fashion rain boots are trendy these days, making it possible to go out stylishly even on rainy days."}, "variations": {"formal": ["Please wear rain boots.", "Rain boots are needed."], "casual": ["Put on rain boots.", "Wear your rain boots."], "short": ["rain boots"]}, "dialogue": {"context": "Getting a child ready on a rainy morning", "dialogue": [{"speaker": "A", "text": "It''s raining outside, so wear your rain boots.", "romanization": "", "translation": "밖에 비 오니까 장화 신어."}, {"speaker": "B", "text": "I want to wear the yellow rain boots!", "romanization": "", "translation": "노란 장화 신을래!"}]}}}'),
  ('seonkeurim', '선크림', 'seonkeurim', 'noun', 'weather', 'beginner', 'common', '["weather", "summer", "beauty", "health", "loanword"]', '{"ko": {"word": "선크림", "explanation": "자외선으로부터 피부를 보호하기 위해 바르는 화장품입니다. 영어 ''sunscreen''에서 유래한 콩글리시 표현입니다. 한국에서는 남녀노소 필수 뷰티 아이템으로, K-뷰티의 핵심 제품입니다.", "examples": {"beginner": "선크림을 발라요.", "intermediate": "외출하기 전에 선크림을 꼭 발라야 해요.", "advanced": "겨울에도 자외선 차단을 위해 선크림을 바르는 것이 좋다.", "master": "한국의 선크림 기술은 세계적으로 인정받아 K-뷰티를 대표하는 제품군이 되었다."}, "variations": {"formal": ["선크림을 바르시기 바랍니다.", "자외선 차단제를 사용하세요."], "casual": ["선크림 발라.", "선크림 챙겨."], "short": ["선크림"]}, "dialogue": {"context": "여름에 바다에 가기 전에", "dialogue": [{"speaker": "A", "text": "선크림 발랐어? 오늘 자외선 엄청 강하대.", "romanization": "seonkeurim ballasseo? oneul jawoeseong eomcheong ganghade.", "translation": "Did you put on sunscreen? UV rays are really strong today."}, {"speaker": "B", "text": "아, 맞다! 가방에 있으니까 바를게.", "romanization": "a, matda! gabange isseunikka bareulge.", "translation": "Oh, right! It''s in my bag, I''ll apply it."}]}}, "en": {"word": "sunscreen", "explanation": "A cosmetic product applied to protect skin from UV rays. A Konglish term derived from English ''sunscreen.'' In Korea, it is an essential beauty item for everyone and a flagship K-beauty product.", "examples": {"beginner": "I apply sunscreen.", "intermediate": "You should always apply sunscreen before going out.", "advanced": "It''s good to apply sunscreen for UV protection even in winter.", "master": "Korean sunscreen technology is globally recognized and has become a representative product category of K-beauty."}, "variations": {"formal": ["Please apply sunscreen.", "Please use sun protection."], "casual": ["Put on sunscreen.", "Don''t forget sunscreen."], "short": ["sunscreen"]}, "dialogue": {"context": "Before going to the beach in summer", "dialogue": [{"speaker": "A", "text": "Did you put on sunscreen? UV rays are really strong today.", "romanization": "", "translation": "선크림 발랐어? 오늘 자외선 엄청 강하대."}, {"speaker": "B", "text": "Oh, right! It''s in my bag, I''ll apply it.", "romanization": "", "translation": "아, 맞다! 가방에 있으니까 바를게."}]}}}'),
  ('eeokon', '에어컨', 'eeokon', 'noun', 'weather', 'beginner', 'common', '["weather", "summer", "appliance", "loanword", "daily-life"]', '{"ko": {"word": "에어컨", "explanation": "실내 공기의 온도와 습도를 조절하는 전자 제품입니다. 영어 ''air conditioner''를 줄인 콩글리시 표현입니다. 한국의 무더운 여름에 필수 가전으로, ''에어컨 전쟁''이라는 말이 있을 정도입니다.", "examples": {"beginner": "에어컨을 켜요.", "intermediate": "에어컨 온도를 너무 낮추면 감기 걸려요.", "advanced": "에어컨 실외기 소음 때문에 이웃 간 분쟁이 발생하기도 한다.", "master": "에너지 효율 등급이 높은 에어컨으로 교체하면 전기료를 크게 절감할 수 있다."}, "variations": {"formal": ["에어컨을 가동하겠습니다.", "냉방 장치를 켜겠습니다."], "casual": ["에어컨 켜.", "에어컨 좀 틀어줘."], "short": ["에어컨"]}, "dialogue": {"context": "더운 여름날 집에 돌아와서", "dialogue": [{"speaker": "A", "text": "너무 더워! 에어컨 좀 틀어줘.", "romanization": "neomu deowo! eeokon jom teureojwo.", "translation": "It''s so hot! Please turn on the AC."}, {"speaker": "B", "text": "이미 켜놨어. 조금만 기다려.", "romanization": "imi kyeonwasseo. jogeumman gidaryeo.", "translation": "I already turned it on. Just wait a bit."}]}}, "en": {"word": "air conditioner", "explanation": "An electronic appliance that controls indoor temperature and humidity. A Konglish abbreviation of ''air conditioner.'' An essential home appliance during Korea''s sweltering summers — there''s even a phrase ''AC war'' about disputes over its use.", "examples": {"beginner": "I turn on the air conditioner.", "intermediate": "You''ll catch a cold if you set the AC temperature too low.", "advanced": "Disputes between neighbors sometimes arise due to outdoor AC unit noise.", "master": "Replacing with a high energy-efficiency rated AC can significantly reduce electricity bills."}, "variations": {"formal": ["I will turn on the air conditioning.", "The cooling system will be activated."], "casual": ["Turn on the AC.", "Put the AC on."], "short": ["AC"]}, "dialogue": {"context": "Coming home on a hot summer day", "dialogue": [{"speaker": "A", "text": "It''s so hot! Please turn on the AC.", "romanization": "", "translation": "너무 더워! 에어컨 좀 틀어줘."}, {"speaker": "B", "text": "I already turned it on. Just wait a bit.", "romanization": "", "translation": "이미 켜놨어. 조금만 기다려."}]}}}'),
  ('hiteo', '히터', 'hiteo', 'noun', 'weather', 'beginner', 'common', '["weather", "winter", "appliance", "loanword"]', '{"ko": {"word": "히터", "explanation": "전기나 가스로 실내를 따뜻하게 해주는 난방 기기입니다. 영어 ''heater''에서 온 외래어로, 한국에서는 겨울철에 널리 사용됩니다.", "examples": {"beginner": "히터를 켜 주세요.", "intermediate": "히터를 틀어도 방이 안 따뜻해요.", "advanced": "전기 히터는 전기세가 많이 나와서 가스 히터를 쓰고 있어요.", "master": "히터를 장시간 가동하면 실내 공기가 건조해지니 환기가 필요하다."}, "variations": {"formal": ["히터를 켜겠습니다.", "난방기를 작동하겠습니다."], "casual": ["히터 켜.", "히터 좀 틀어."], "short": ["히터"]}, "dialogue": {"context": "겨울철 사무실에서", "dialogue": [{"speaker": "A", "text": "너무 추운데 히터 켜도 될까요?", "romanization": "neomu chuwonde hiteo kyeodo doelkkayo?", "translation": "It''s so cold, can I turn on the heater?"}, {"speaker": "B", "text": "네, 저도 춥네요. 켜세요.", "romanization": "ne, jeodo chupneyo. kyeoseyo.", "translation": "Yes, I''m cold too. Go ahead."}]}}, "en": {"word": "heater", "explanation": "A heating appliance that warms indoor spaces using electricity or gas. It is a loanword from English commonly used in Korean during winter months.", "examples": {"beginner": "Please turn on the heater.", "intermediate": "Even with the heater on, the room isn''t warm.", "advanced": "Electric heaters cost a lot in electricity, so I use a gas heater.", "master": "Running the heater for long periods dries out the indoor air, so ventilation is necessary."}, "variations": {"formal": ["I will turn on the heater.", "I will activate the heating unit."], "casual": ["Turn the heater on.", "Hit the heater."], "short": ["heater"]}, "dialogue": {"context": "In the office during winter", "dialogue": [{"speaker": "A", "text": "It''s so cold, can I turn on the heater?", "romanization": "", "translation": "너무 추운데 히터 켜도 될까요?"}, {"speaker": "B", "text": "Yes, I''m cold too. Go ahead.", "romanization": "", "translation": "네, 저도 춥네요. 켜세요."}]}}}'),
  ('jeseupgi', '제습기', 'jeseupgi', 'noun', 'weather', 'intermediate', 'common', '["weather", "summer", "appliance", "comfort"]', '{"ko": {"word": "제습기", "explanation": "공기 중의 습기를 제거하는 가전제품입니다. 한국의 장마철(6~7월)에 습도가 매우 높아져 제습기가 필수입니다.", "examples": {"beginner": "제습기를 켰어요.", "intermediate": "장마철에는 제습기가 필수예요.", "advanced": "제습기를 돌리니까 빨래가 빨리 마르더라고요.", "master": "올여름 습도가 심해서 제습기를 24시간 가동하고 있다."}, "variations": {"formal": ["제습기를 가동하겠습니다.", "제습기를 작동시키겠습니다."], "casual": ["제습기 켜.", "제습기 돌려."], "short": ["제습기"]}, "dialogue": {"context": "장마철 집에서", "dialogue": [{"speaker": "A", "text": "집이 너무 눅눅해.", "romanization": "jibi neomu nuknukae.", "translation": "The house is so damp."}, {"speaker": "B", "text": "제습기 켜 놓으면 금방 나아져.", "romanization": "jeseupgi kyeo noheumyeon geumbang naajyeo.", "translation": "If you leave the dehumidifier on, it''ll get better quickly."}]}}, "en": {"word": "dehumidifier", "explanation": "An appliance that removes moisture from the air. Essential during Korea''s monsoon season (June-July) when humidity becomes extremely high.", "examples": {"beginner": "I turned on the dehumidifier.", "intermediate": "A dehumidifier is essential during the monsoon season.", "advanced": "Running the dehumidifier helps laundry dry faster.", "master": "The humidity this summer is so severe that I''ve been running the dehumidifier 24 hours a day."}, "variations": {"formal": ["I will operate the dehumidifier.", "I will activate the dehumidifier."], "casual": ["Turn on the dehumidifier.", "Run the dehumidifier."], "short": ["dehumidifier"]}, "dialogue": {"context": "At home during monsoon season", "dialogue": [{"speaker": "A", "text": "The house is so damp.", "romanization": "", "translation": "집이 너무 눅눅해."}, {"speaker": "B", "text": "If you leave the dehumidifier on, it''ll get better quickly.", "romanization": "", "translation": "제습기 켜 놓으면 금방 나아져."}]}}}'),
  ('gaseupgi', '가습기', 'gaseupgi', 'noun', 'weather', 'intermediate', 'common', '["weather", "winter", "appliance", "health"]', '{"ko": {"word": "가습기", "explanation": "건조한 실내 공기에 수분을 공급하는 가전제품입니다. 한국의 겨울은 매우 건조하여 가습기를 많이 사용합니다.", "examples": {"beginner": "가습기를 켜 주세요.", "intermediate": "겨울에는 가습기가 꼭 필요해요.", "advanced": "가습기 물을 자주 갈아 주지 않으면 세균이 번식할 수 있어요.", "master": "초음파식 가습기보다 자연 기화식이 위생적이라고 하더라."}, "variations": {"formal": ["가습기를 켜겠습니다.", "가습기를 작동하겠습니다."], "casual": ["가습기 켜.", "가습기 좀 틀어."], "short": ["가습기"]}, "dialogue": {"context": "건조한 겨울 밤에", "dialogue": [{"speaker": "A", "text": "목이 너무 건조해.", "romanization": "mogi neomu geonjohae.", "translation": "My throat is so dry."}, {"speaker": "B", "text": "가습기 켜고 자. 아침에 달라질 거야.", "romanization": "gaseupgi kyeogo ja. achime dallajil geoya.", "translation": "Turn on the humidifier and sleep. It''ll be different in the morning."}]}}, "en": {"word": "humidifier", "explanation": "An appliance that adds moisture to dry indoor air. Korean winters are very dry, making humidifiers a common household item.", "examples": {"beginner": "Please turn on the humidifier.", "intermediate": "A humidifier is essential in winter.", "advanced": "If you don''t change the humidifier water frequently, bacteria can grow.", "master": "They say natural evaporation humidifiers are more hygienic than ultrasonic ones."}, "variations": {"formal": ["I will turn on the humidifier.", "I will activate the humidifier."], "casual": ["Turn the humidifier on.", "Run the humidifier."], "short": ["humidifier"]}, "dialogue": {"context": "On a dry winter night", "dialogue": [{"speaker": "A", "text": "My throat is so dry.", "romanization": "", "translation": "목이 너무 건조해."}, {"speaker": "B", "text": "Turn on the humidifier and sleep. It''ll be different in the morning.", "romanization": "", "translation": "가습기 켜고 자. 아침에 달라질 거야."}]}}}'),
  ('seonpunggi', '선풍기', 'seonpunggi', 'noun', 'weather', 'beginner', 'common', '["weather", "summer", "appliance", "daily-life"]', '{"ko": {"word": "선풍기", "explanation": "날개를 회전시켜 바람을 일으키는 가전제품입니다. 한국에는 ''선풍기를 틀고 자면 죽는다''는 미신(선풍기 사망설)이 유명합니다.", "examples": {"beginner": "선풍기를 켜 주세요.", "intermediate": "에어컨 대신 선풍기를 쓰면 전기세가 적게 나와요.", "advanced": "선풍기 바람을 직접 쐬면 몸이 뻣뻣해질 수 있어요.", "master": "선풍기 사망설은 한국 고유의 도시 전설로 외국인들이 신기해한다."}, "variations": {"formal": ["선풍기를 켜겠습니다.", "선풍기를 작동하겠습니다."], "casual": ["선풍기 켜.", "선풍기 좀 틀어 줘."], "short": ["선풍기"]}, "dialogue": {"context": "더운 여름 방에서", "dialogue": [{"speaker": "A", "text": "에어컨 대신 선풍기 틀까?", "romanization": "eeokon daesin seonpunggi teulkka?", "translation": "Should we use the fan instead of AC?"}, {"speaker": "B", "text": "응, 전기세도 아끼고 좋지.", "romanization": "eung, jeongiisedo akkigo jochi.", "translation": "Yeah, it saves on electricity too."}]}}, "en": {"word": "fan", "explanation": "An appliance with rotating blades that creates airflow. Korea has a famous urban legend called ''fan death'' — the belief that sleeping with a fan on in a closed room can be fatal.", "examples": {"beginner": "Please turn on the fan.", "intermediate": "Using a fan instead of AC saves on electricity.", "advanced": "Direct fan wind on your body can make you stiff.", "master": "The fan death myth is a uniquely Korean urban legend that fascinates foreigners."}, "variations": {"formal": ["I will turn on the fan.", "I will activate the fan."], "casual": ["Turn the fan on.", "Hit the fan."], "short": ["fan"]}, "dialogue": {"context": "In a hot summer room", "dialogue": [{"speaker": "A", "text": "Should we use the fan instead of AC?", "romanization": "", "translation": "에어컨 대신 선풍기 틀까?"}, {"speaker": "B", "text": "Yeah, it saves on electricity too.", "romanization": "", "translation": "응, 전기세도 아끼고 좋지."}]}}}'),
  ('nanbang', '난방', 'nanbang', 'noun', 'weather', 'intermediate', 'common', '["weather", "winter", "home", "korean-culture"]', '{"ko": {"word": "난방", "explanation": "실내를 따뜻하게 하는 것을 뜻합니다. 한국은 전통적으로 온돌(바닥 난방)을 사용하며, 현대 아파트에서도 바닥 난방이 기본입니다.", "examples": {"beginner": "난방을 켜 주세요.", "intermediate": "한국 아파트는 바닥 난방이 기본이에요.", "advanced": "중앙난방 아파트는 개별 온도 조절이 어려워요.", "master": "온돌 문화 덕분에 한국인은 바닥에 앉거나 눕는 생활에 익숙하다."}, "variations": {"formal": ["난방을 가동하겠습니다.", "난방 시스템을 작동하겠습니다."], "casual": ["난방 켜.", "보일러 틀어."], "short": ["난방"]}, "dialogue": {"context": "추운 겨울 아파트에서", "dialogue": [{"speaker": "A", "text": "바닥이 따뜻해서 좋다.", "romanization": "badagi ttatteuthaeseol jota.", "translation": "The warm floor feels great."}, {"speaker": "B", "text": "한국 난방은 온돌이라서 바닥이 따뜻한 거야.", "romanization": "hanguk nanbang-eun ondolilaseo badagi ttatteutan geoya.", "translation": "Korean heating is ondol, that''s why the floor is warm."}]}}, "en": {"word": "heating", "explanation": "The act of warming indoor spaces. Korea traditionally uses ondol (underfloor heating), and modern apartments still feature radiant floor heating as standard.", "examples": {"beginner": "Please turn on the heating.", "intermediate": "Korean apartments have floor heating as standard.", "advanced": "Central heating apartments make individual temperature control difficult.", "master": "Thanks to ondol culture, Koreans are accustomed to sitting and lying on the floor."}, "variations": {"formal": ["I will activate the heating.", "I will start the heating system."], "casual": ["Turn on the heat.", "Fire up the boiler."], "short": ["heating"]}, "dialogue": {"context": "In an apartment during cold winter", "dialogue": [{"speaker": "A", "text": "The warm floor feels great.", "romanization": "", "translation": "바닥이 따뜻해서 좋다."}, {"speaker": "B", "text": "Korean heating is ondol, that''s why the floor is warm.", "romanization": "", "translation": "한국 난방은 온돌이라서 바닥이 따뜻한 거야."}]}}}'),
  ('naengbang', '냉방', 'naengbang', 'noun', 'weather', 'intermediate', 'common', '["weather", "summer", "home", "office"]', '{"ko": {"word": "냉방", "explanation": "실내 온도를 낮추는 것을 뜻합니다. 난방의 반대말이며, 주로 에어컨을 이용합니다. ''냉방병''은 에어컨을 과도하게 사용해 생기는 감기 증상입니다.", "examples": {"beginner": "냉방이 너무 세요.", "intermediate": "사무실 냉방 온도가 너무 낮아요.", "advanced": "냉방병에 걸리지 않으려면 실내외 온도 차를 줄여야 해요.", "master": "여름철 과도한 냉방은 에너지 낭비는 물론 건강에도 해롭다."}, "variations": {"formal": ["냉방을 가동하겠습니다.", "냉방 온도를 조절하겠습니다."], "casual": ["냉방 켜.", "에어컨 틀어."], "short": ["냉방"]}, "dialogue": {"context": "여름 사무실에서", "dialogue": [{"speaker": "A", "text": "냉방이 너무 강한 것 같아요.", "romanization": "naengbang-i neomu ganghan geot gatayo.", "translation": "I think the AC is too strong."}, {"speaker": "B", "text": "냉방병 걸리기 전에 온도 좀 올릴게요.", "romanization": "naengbangbyeong geolligi jeone ondo jom ollilgeyo.", "translation": "I''ll raise the temperature before we get AC sickness."}]}}, "en": {"word": "cooling/air conditioning", "explanation": "The act of lowering indoor temperature, the opposite of heating (난방). Primarily done through air conditioning. ''냉방병'' (AC sickness) refers to cold-like symptoms from excessive air conditioning.", "examples": {"beginner": "The AC is too strong.", "intermediate": "The office AC temperature is too low.", "advanced": "To avoid AC sickness, reduce the temperature difference between indoors and outdoors.", "master": "Excessive summer cooling wastes energy and is also harmful to health."}, "variations": {"formal": ["I will activate the cooling.", "I will adjust the AC temperature."], "casual": ["Turn on the AC.", "Blast the AC."], "short": ["cooling"]}, "dialogue": {"context": "In a summer office", "dialogue": [{"speaker": "A", "text": "I think the AC is too strong.", "romanization": "", "translation": "냉방이 너무 강한 것 같아요."}, {"speaker": "B", "text": "I''ll raise the temperature before we get AC sickness.", "romanization": "", "translation": "냉방병 걸리기 전에 온도 좀 올릴게요."}]}}}'),
  ('ondogye', '온도계', 'ondogye', 'noun', 'weather', 'intermediate', 'uncommon', '["weather", "measurement", "instrument"]', '{"ko": {"word": "온도계", "explanation": "온도를 측정하는 기구입니다. 한국은 섭씨(°C)를 사용합니다. 체온계, 기온계, 수온계 등 종류가 다양합니다.", "examples": {"beginner": "온도계를 봐 주세요.", "intermediate": "온도계가 영하 10도를 가리키고 있어요.", "advanced": "디지털 온도계가 수은 온도계보다 정확하다고 해요.", "master": "이 온도계는 습도까지 표시되는 복합 측정 장치다."}, "variations": {"formal": ["온도계를 확인하겠습니다.", "온도계를 살펴보겠습니다."], "casual": ["온도계 봐.", "몇 도야?"], "short": ["온도계"]}, "dialogue": {"context": "추운 아침에 외출 준비를 하며", "dialogue": [{"speaker": "A", "text": "밖에 몇 도야?", "romanization": "bakke myeot doya?", "translation": "What''s the temperature outside?"}, {"speaker": "B", "text": "온도계 보니까 영하 5도래.", "romanization": "ondogye bonikka yeongha odolae.", "translation": "The thermometer says minus 5 degrees."}]}}, "en": {"word": "thermometer", "explanation": "An instrument for measuring temperature. Korea uses Celsius (°C). There are various types including body thermometers, air thermometers, and water thermometers.", "examples": {"beginner": "Please check the thermometer.", "intermediate": "The thermometer is showing minus 10 degrees.", "advanced": "They say digital thermometers are more accurate than mercury ones.", "master": "This thermometer is a combined device that also displays humidity."}, "variations": {"formal": ["I will check the thermometer.", "I will examine the thermometer."], "casual": ["Check the thermometer.", "What''s the temp?"], "short": ["thermometer"]}, "dialogue": {"context": "Getting ready to go out on a cold morning", "dialogue": [{"speaker": "A", "text": "What''s the temperature outside?", "romanization": "", "translation": "밖에 몇 도야?"}, {"speaker": "B", "text": "The thermometer says minus 5 degrees.", "romanization": "", "translation": "온도계 보니까 영하 5도래."}]}}}'),
  ('gihu', '기후', 'gihu', 'noun', 'weather', 'intermediate', 'common', '["weather", "academic", "environment", "geography"]', '{"ko": {"word": "기후", "explanation": "한 지역의 장기간에 걸친 평균적인 날씨 상태를 말합니다. ''날씨''는 하루 단위, ''기후''는 수십 년 단위의 개념입니다. 한국은 사계절이 뚜렷한 온대 기후입니다.", "examples": {"beginner": "한국의 기후는 사계절이 있어요.", "intermediate": "열대 기후와 온대 기후는 매우 달라요.", "advanced": "한국의 기후는 최근 아열대 기후로 변하고 있다는 연구 결과가 있어요.", "master": "기후는 위도, 해발 고도, 해류 등 다양한 요인에 의해 결정된다."}, "variations": {"formal": ["기후 조건을 분석하겠습니다.", "기후 특성에 대해 말씀드리겠습니다."], "casual": ["기후가 달라.", "기후 때문이야."], "short": ["기후"]}, "dialogue": {"context": "외국인 친구와 한국 날씨에 대해 이야기하며", "dialogue": [{"speaker": "A", "text": "한국 기후는 어때요?", "romanization": "hanguk gihuneun eottaeyo?", "translation": "What''s the climate like in Korea?"}, {"speaker": "B", "text": "사계절이 뚜렷해서 계절마다 완전히 달라요.", "romanization": "sagyejeori tturyeotaeseo gyejeolmada wanjeonhi dallayo.", "translation": "The four seasons are distinct, so it''s completely different each season."}]}}, "en": {"word": "climate", "explanation": "The long-term average weather conditions of a region. ''Weather'' (날씨) is daily, while ''climate'' (기후) spans decades. Korea has a temperate climate with four distinct seasons.", "examples": {"beginner": "Korea''s climate has four seasons.", "intermediate": "Tropical and temperate climates are very different.", "advanced": "Research suggests Korea''s climate is shifting toward subtropical.", "master": "Climate is determined by various factors including latitude, altitude, and ocean currents."}, "variations": {"formal": ["I will analyze the climate conditions.", "I will discuss the climate characteristics."], "casual": ["The climate is different.", "It''s because of the climate."], "short": ["climate"]}, "dialogue": {"context": "Talking about Korean weather with a foreign friend", "dialogue": [{"speaker": "A", "text": "What''s the climate like in Korea?", "romanization": "", "translation": "한국 기후는 어때요?"}, {"speaker": "B", "text": "The four seasons are distinct, so it''s completely different each season.", "romanization": "", "translation": "사계절이 뚜렷해서 계절마다 완전히 달라요."}]}}}'),
  ('gihupyeonhwa', '기후변화', 'gihupyeonhwa', 'noun', 'weather', 'advanced', 'common', '["weather", "environment", "academic", "news"]', '{"ko": {"word": "기후변화", "explanation": "지구의 기후 패턴이 장기적으로 변화하는 현상입니다. 특히 인간 활동으로 인한 지구 온난화가 주요 원인으로, 한국에서도 폭염, 폭우 등 이상 기후가 증가하고 있습니다.", "examples": {"beginner": "기후변화는 심각한 문제예요.", "intermediate": "기후변화 때문에 여름이 점점 더워지고 있어요.", "advanced": "기후변화에 대응하기 위해 탄소 배출량을 줄여야 합니다.", "master": "기후변화 협약에 따라 각국이 탄소 중립을 선언하고 있지만 실효성에 의문이 제기된다."}, "variations": {"formal": ["기후변화에 대해 논의하겠습니다.", "기후변화 대응 방안을 검토하겠습니다."], "casual": ["기후변화 때문이야.", "기후가 변하고 있어."], "short": ["기후변화"]}, "dialogue": {"context": "뉴스를 보면서", "dialogue": [{"speaker": "A", "text": "올해 여름 정말 역대급으로 더웠어.", "romanization": "olhae yeoreum jeongmal yeokdaegeubeuro deowosseo.", "translation": "This summer was record-breakingly hot."}, {"speaker": "B", "text": "기후변화 때문에 해마다 더 심해지는 것 같아.", "romanization": "gihupyeonhwa ttaemune haemada deo simhaejineun geot gata.", "translation": "I think it''s getting worse every year because of climate change."}]}}, "en": {"word": "climate change", "explanation": "The long-term shift in global climate patterns. Human-caused global warming is the primary driver. Korea is experiencing more extreme weather events like heat waves and heavy rainfall.", "examples": {"beginner": "Climate change is a serious problem.", "intermediate": "Summers are getting hotter because of climate change.", "advanced": "We must reduce carbon emissions to address climate change.", "master": "Countries are declaring carbon neutrality per climate agreements, but their effectiveness is questioned."}, "variations": {"formal": ["I will discuss climate change.", "I will review climate change response measures."], "casual": ["It''s because of climate change.", "The climate is changing."], "short": ["climate change"]}, "dialogue": {"context": "Watching the news", "dialogue": [{"speaker": "A", "text": "This summer was record-breakingly hot.", "romanization": "", "translation": "올해 여름 정말 역대급으로 더웠어."}, {"speaker": "B", "text": "I think it''s getting worse every year because of climate change.", "romanization": "", "translation": "기후변화 때문에 해마다 더 심해지는 것 같아."}]}}}'),
  ('daegiolyeom', '대기오염', 'daegiolyeom', 'noun', 'weather', 'advanced', 'common', '["weather", "environment", "health", "urban"]', '{"ko": {"word": "대기오염", "explanation": "공기가 유해 물질로 오염되는 것을 뜻합니다. 한국에서는 미세먼지가 심각한 대기오염 문제이며, 봄철 중국에서 넘어오는 황사와 함께 큰 사회 문제입니다.", "examples": {"beginner": "대기오염이 심해요.", "intermediate": "대기오염 때문에 마스크를 써야 해요.", "advanced": "산업화 이후 대기오염이 심각해져서 호흡기 질환이 늘었어요.", "master": "대기오염 저감을 위한 경유차 운행 제한 정책이 시행되고 있다."}, "variations": {"formal": ["대기오염 수준을 확인하겠습니다.", "대기오염에 대해 보고드리겠습니다."], "casual": ["공기 나빠.", "오염이 심해."], "short": ["대기오염"]}, "dialogue": {"context": "미세먼지가 심한 날 외출하며", "dialogue": [{"speaker": "A", "text": "오늘 대기오염 수치가 ''매우 나쁨''이래.", "romanization": "oneul daegiolyeom suchiga ''maeu nappeum''irae.", "translation": "Today''s air pollution level is ''very bad.''"}, {"speaker": "B", "text": "마스크 꼭 쓰고 나가자.", "romanization": "maseukeu kkok sseugo nagaja.", "translation": "Let''s make sure to wear masks going out."}]}}, "en": {"word": "air pollution", "explanation": "Contamination of the air by harmful substances. Fine dust (미세먼지) is a severe air pollution issue in Korea, along with yellow dust (황사) from China in spring.", "examples": {"beginner": "Air pollution is severe.", "intermediate": "We need to wear masks because of air pollution.", "advanced": "Respiratory diseases have increased since industrialization worsened air pollution.", "master": "Diesel vehicle restrictions are being implemented to reduce air pollution."}, "variations": {"formal": ["I will check the air pollution levels.", "I will report on air pollution."], "casual": ["The air is bad.", "Pollution is terrible."], "short": ["air pollution"]}, "dialogue": {"context": "Going out on a day with heavy fine dust", "dialogue": [{"speaker": "A", "text": "Today''s air pollution level is ''very bad.''", "romanization": "", "translation": "오늘 대기오염 수치가 ''매우 나쁨''이래."}, {"speaker": "B", "text": "Let''s make sure to wear masks going out.", "romanization": "", "translation": "마스크 꼭 쓰고 나가자."}]}}}'),
  ('malgeun-haneul', '맑은 하늘', 'malgeun haneul', 'noun', 'weather', 'beginner', 'common', '["weather", "nature", "pleasant", "sky"]', '{"ko": {"word": "맑은 하늘", "explanation": "구름 없이 깨끗하고 파란 하늘을 뜻합니다. 한국에서는 가을(9~10월)에 맑은 하늘을 가장 자주 볼 수 있어 ''천고마비의 계절''이라고 합니다.", "examples": {"beginner": "오늘 하늘이 맑아요.", "intermediate": "맑은 하늘을 보면 기분이 좋아져요.", "advanced": "며칠간 미세먼지가 심하다가 드디어 맑은 하늘을 봤어요.", "master": "가을의 맑은 하늘 아래 단풍이 물드는 풍경은 한국의 백미다."}, "variations": {"formal": ["하늘이 맑겠습니다.", "맑은 날씨가 예상됩니다."], "casual": ["하늘 진짜 맑다!", "날씨 좋다!"], "short": ["맑은 하늘"]}, "dialogue": {"context": "맑은 가을 아침에", "dialogue": [{"speaker": "A", "text": "와, 오늘 하늘 진짜 맑다!", "romanization": "wa, oneul haneul jinjja makda!", "translation": "Wow, the sky is really clear today!"}, {"speaker": "B", "text": "이런 날 산책하면 딱이야.", "romanization": "ireon nal sanchaekamyeon ttagiya.", "translation": "A walk on a day like this would be perfect."}]}}, "en": {"word": "clear sky", "explanation": "A clean, blue sky without clouds. In Korea, clear skies are most common in autumn (Sept-Oct), known as the ''season of high skies and stout horses'' (천고마비).", "examples": {"beginner": "The sky is clear today.", "intermediate": "Clear skies put me in a good mood.", "advanced": "After days of heavy fine dust, I finally saw a clear sky.", "master": "The autumn foliage under a clear Korean sky is a masterpiece of nature."}, "variations": {"formal": ["The sky will be clear.", "Clear weather is expected."], "casual": ["The sky is so clear!", "Beautiful day!"], "short": ["clear sky"]}, "dialogue": {"context": "On a clear autumn morning", "dialogue": [{"speaker": "A", "text": "Wow, the sky is really clear today!", "romanization": "", "translation": "와, 오늘 하늘 진짜 맑다!"}, {"speaker": "B", "text": "A walk on a day like this would be perfect.", "romanization": "", "translation": "이런 날 산책하면 딱이야."}]}}}'),
  ('meokgureum', '먹구름', 'meokgureum', 'noun', 'weather', 'intermediate', 'common', '["weather", "nature", "rain", "ominous"]', '{"ko": {"word": "먹구름", "explanation": "검고 짙은 구름으로, 비나 폭풍이 올 것을 나타냅니다. ''먹''은 먹물처럼 검다는 뜻입니다. 비유적으로 ''불길한 징조''를 의미하기도 합니다.", "examples": {"beginner": "먹구름이 끼었어요.", "intermediate": "먹구름이 몰려오면 곧 비가 올 거예요.", "advanced": "하늘에 먹구름이 잔뜩 끼더니 소나기가 쏟아졌다.", "master": "경제에 먹구름이 드리우고 있다는 전문가들의 경고가 이어지고 있다."}, "variations": {"formal": ["먹구름이 끼고 있습니다.", "먹구름이 관측됩니다."], "casual": ["먹구름이다!", "비 올 것 같아."], "short": ["먹구름"]}, "dialogue": {"context": "야외 활동 중 하늘을 보며", "dialogue": [{"speaker": "A", "text": "저기 먹구름이 오고 있어!", "romanization": "jeogi meokgureumi ogo isseo!", "translation": "Dark clouds are coming over there!"}, {"speaker": "B", "text": "빨리 들어가자. 비 올 것 같아.", "romanization": "ppalli deureogaja. bi ol geot gata.", "translation": "Let''s go inside quickly. It looks like rain."}]}}, "en": {"word": "dark clouds", "explanation": "Dark, thick clouds indicating rain or storms. ''먹'' means ink-black. Figuratively, it also means ''ominous sign'' (e.g., dark clouds over the economy).", "examples": {"beginner": "Dark clouds have gathered.", "intermediate": "When dark clouds roll in, rain will come soon.", "advanced": "Dark clouds filled the sky, and then a sudden shower poured down.", "master": "Experts continue to warn that dark clouds are looming over the economy."}, "variations": {"formal": ["Dark clouds are forming.", "Dark clouds have been observed."], "casual": ["Dark clouds!", "Looks like rain."], "short": ["dark clouds"]}, "dialogue": {"context": "Looking at the sky during outdoor activity", "dialogue": [{"speaker": "A", "text": "Dark clouds are coming over there!", "romanization": "", "translation": "저기 먹구름이 오고 있어!"}, {"speaker": "B", "text": "Let''s go inside quickly. It looks like rain.", "romanization": "", "translation": "빨리 들어가자. 비 올 것 같아."}]}}}'),
  ('noeu', '뇌우', 'noeu', 'noun', 'weather', 'advanced', 'uncommon', '["weather", "storm", "summer", "danger"]', '{"ko": {"word": "뇌우", "explanation": "번개와 천둥을 동반한 강한 비를 뜻합니다. 한국에서는 여름철(7~8월)에 자주 발생하며, 갑작스러운 뇌우로 인한 피해 주의보가 내려지기도 합니다.", "examples": {"beginner": "뇌우가 오고 있어요.", "intermediate": "오후에 뇌우가 예상된다고 해요.", "advanced": "뇌우가 칠 때는 높은 곳이나 나무 아래에 있으면 안 됩니다.", "master": "이번 뇌우는 시간당 50mm 이상의 집중호우를 동반할 것으로 예보됐다."}, "variations": {"formal": ["뇌우가 예상됩니다.", "뇌우 주의보가 발령되었습니다."], "casual": ["천둥 번개 친다!", "폭풍우 온다!"], "short": ["뇌우"]}, "dialogue": {"context": "일기예보를 보면서", "dialogue": [{"speaker": "A", "text": "오후에 뇌우 예보 있대.", "romanization": "ohue noeu yebo itdae.", "translation": "There''s a thunderstorm forecast for the afternoon."}, {"speaker": "B", "text": "야외 일정은 취소하는 게 낫겠다.", "romanization": "yaoe iljeongeun chwisohaneun ge natgetda.", "translation": "We''d better cancel the outdoor plans."}]}}, "en": {"word": "thunderstorm", "explanation": "Heavy rain accompanied by lightning and thunder. Common in Korean summers (July-August), with warnings often issued for sudden thunderstorm damage.", "examples": {"beginner": "A thunderstorm is coming.", "intermediate": "They say a thunderstorm is expected this afternoon.", "advanced": "During a thunderstorm, you shouldn''t be in high places or under trees.", "master": "This thunderstorm is forecast to bring concentrated rainfall of over 50mm per hour."}, "variations": {"formal": ["A thunderstorm is expected.", "A thunderstorm advisory has been issued."], "casual": ["Thunder and lightning!", "A storm is coming!"], "short": ["thunderstorm"]}, "dialogue": {"context": "Watching the weather forecast", "dialogue": [{"speaker": "A", "text": "There''s a thunderstorm forecast for the afternoon.", "romanization": "", "translation": "오후에 뇌우 예보 있대."}, {"speaker": "B", "text": "We''d better cancel the outdoor plans.", "romanization": "", "translation": "야외 일정은 취소하는 게 낫겠다."}]}}}'),
  ('gangpung', '강풍', 'gangpung', 'noun', 'weather', 'intermediate', 'common', '["weather", "wind", "danger", "news"]', '{"ko": {"word": "강풍", "explanation": "매우 세게 부는 바람을 뜻합니다. 기상청 기준으로 초속 14m/s 이상의 바람을 강풍이라 합니다. 태풍, 계절풍 등으로 강풍이 발생합니다.", "examples": {"beginner": "강풍이 불고 있어요.", "intermediate": "강풍 주의보가 발령됐어요.", "advanced": "강풍에 간판이 날아가서 큰 사고가 날 뻔했어요.", "master": "강풍 특보 발효 시 야외 시설물 점검과 외출 자제가 권고된다."}, "variations": {"formal": ["강풍이 예상됩니다.", "강풍 주의보가 발령되었습니다."], "casual": ["바람 엄청 세!", "풍 장난 아니야."], "short": ["강풍"]}, "dialogue": {"context": "바람이 센 날 밖에서", "dialogue": [{"speaker": "A", "text": "바람이 너무 세서 걷기 힘들어!", "romanization": "barami neomu seseo geotgi himdeureo!", "translation": "The wind is so strong it''s hard to walk!"}, {"speaker": "B", "text": "강풍 주의보래. 조심해.", "romanization": "gangpung juuiborae. josimhae.", "translation": "There''s a strong wind advisory. Be careful."}]}}, "en": {"word": "strong wind", "explanation": "Very powerful wind. By Korea Meteorological Administration standards, wind speeds of 14m/s or higher qualify as strong wind. Caused by typhoons, seasonal winds, etc.", "examples": {"beginner": "Strong winds are blowing.", "intermediate": "A strong wind advisory has been issued.", "advanced": "A sign was blown away by strong winds and almost caused a major accident.", "master": "During strong wind warnings, inspecting outdoor facilities and avoiding going out are recommended."}, "variations": {"formal": ["Strong winds are expected.", "A strong wind advisory has been issued."], "casual": ["The wind is insane!", "So windy!"], "short": ["strong wind"]}, "dialogue": {"context": "Outside on a windy day", "dialogue": [{"speaker": "A", "text": "The wind is so strong it''s hard to walk!", "romanization": "", "translation": "바람이 너무 세서 걷기 힘들어!"}, {"speaker": "B", "text": "There''s a strong wind advisory. Be careful.", "romanization": "", "translation": "강풍 주의보래. 조심해."}]}}}'),
  ('taeyang', '태양', 'taeyang', 'noun', 'weather', 'beginner', 'common', '["weather", "nature", "sky", "science"]', '{"ko": {"word": "태양", "explanation": "우리 태양계의 중심에 있는 항성입니다. 일상에서는 ''해''라는 순우리말을 더 자주 사용합니다. ''태양''은 좀 더 격식 있는 표현입니다.", "examples": {"beginner": "태양이 밝아요.", "intermediate": "태양이 구름 뒤에 숨었어요.", "advanced": "태양 에너지는 친환경적인 대체 에너지로 주목받고 있다.", "master": "태양의 흑점 활동이 지구의 기후에 영향을 미친다는 연구가 있다."}, "variations": {"formal": ["태양이 떠오르고 있습니다.", "태양빛이 강합니다."], "casual": ["해 떴다!", "햇볕 강하다."], "short": ["태양"]}, "dialogue": {"context": "맑은 날 산책하며", "dialogue": [{"speaker": "A", "text": "오늘 태양이 진짜 뜨겁다.", "romanization": "oneul taeyangi jinjja tteugeopda.", "translation": "The sun is really scorching today."}, {"speaker": "B", "text": "선크림 바르고 나왔어?", "romanization": "seonkeurim bareuga nawasseo?", "translation": "Did you put on sunscreen?"}]}}, "en": {"word": "sun", "explanation": "The star at the center of our solar system. In everyday Korean, ''해'' (hae, native Korean word) is more commonly used than ''태양'' (taeyang, Sino-Korean), which is more formal/scientific.", "examples": {"beginner": "The sun is bright.", "intermediate": "The sun hid behind the clouds.", "advanced": "Solar energy is gaining attention as an eco-friendly alternative energy source.", "master": "Research suggests that solar sunspot activity affects Earth''s climate."}, "variations": {"formal": ["The sun is rising.", "The sunlight is strong."], "casual": ["The sun''s up!", "So sunny."], "short": ["sun"]}, "dialogue": {"context": "Taking a walk on a clear day", "dialogue": [{"speaker": "A", "text": "The sun is really scorching today.", "romanization": "", "translation": "오늘 태양이 진짜 뜨겁다."}, {"speaker": "B", "text": "Did you put on sunscreen?", "romanization": "", "translation": "선크림 바르고 나왔어?"}]}}}'),
  ('dal', '달', 'dal', 'noun', 'weather', 'beginner', 'common', '["weather", "nature", "night", "sky"]', '{"ko": {"word": "달", "explanation": "지구의 위성으로, 밤하늘에 보이는 천체입니다. 한국 문화에서 ''보름달''(음력 15일의 만월)은 소원을 비는 대상이며, 추석의 상징입니다.", "examples": {"beginner": "달이 밝아요.", "intermediate": "보름달이 정말 예뻐요.", "advanced": "추석에 보름달을 보며 소원을 빌었어요.", "master": "달이 지구의 조석 현상에 미치는 영향은 과학적으로 증명되었다."}, "variations": {"formal": ["달이 떠 있습니다.", "달빛이 밝습니다."], "casual": ["달 봐!", "달이 예쁘다!"], "short": ["달"]}, "dialogue": {"context": "밤에 산책하면서", "dialogue": [{"speaker": "A", "text": "저기 달 봐! 보름달이다!", "romanization": "jeogi dal bwa! boreumdal-ida!", "translation": "Look at the moon! It''s a full moon!"}, {"speaker": "B", "text": "진짜 예쁘다. 소원 빌자!", "romanization": "jinjja yeppeuda. sowon bilja!", "translation": "So beautiful. Let''s make a wish!"}]}}, "en": {"word": "moon", "explanation": "Earth''s natural satellite visible in the night sky. In Korean culture, the full moon (보름달) on the 15th of the lunar month is a symbol of Chuseok and is associated with making wishes.", "examples": {"beginner": "The moon is bright.", "intermediate": "The full moon is really beautiful.", "advanced": "I made a wish looking at the full moon during Chuseok.", "master": "The moon''s influence on Earth''s tidal phenomena has been scientifically proven."}, "variations": {"formal": ["The moon has risen.", "The moonlight is bright."], "casual": ["Look at the moon!", "The moon is beautiful!"], "short": ["moon"]}, "dialogue": {"context": "Taking a walk at night", "dialogue": [{"speaker": "A", "text": "Look at the moon! It''s a full moon!", "romanization": "", "translation": "저기 달 봐! 보름달이다!"}, {"speaker": "B", "text": "So beautiful. Let''s make a wish!", "romanization": "", "translation": "진짜 예쁘다. 소원 빌자!"}]}}}'),
  ('byeol', '별', 'byeol', 'noun', 'weather', 'beginner', 'common', '["weather", "nature", "night", "sky", "poetic"]', '{"ko": {"word": "별", "explanation": "밤하늘에 빛나는 천체입니다. 한국 문학에서 별은 희망, 그리움, 꿈의 상징으로 자주 등장합니다. 윤동주의 ''별 헤는 밤''은 한국인이 가장 사랑하는 시 중 하나입니다.", "examples": {"beginner": "별이 많아요.", "intermediate": "오늘 밤 별이 정말 잘 보여요.", "advanced": "도시에서는 빛 공해 때문에 별을 보기 어렵다.", "master": "윤동주의 ''별 헤는 밤''을 읽으면 별을 바라보는 시선이 달라진다."}, "variations": {"formal": ["별이 밝게 빛나고 있습니다.", "별이 아름답습니다."], "casual": ["별 봐!", "별이 진짜 많다!"], "short": ["별"]}, "dialogue": {"context": "시골에서 밤하늘을 보며", "dialogue": [{"speaker": "A", "text": "와, 별이 이렇게 많다니!", "romanization": "wa, byeori ireoke mandani!", "translation": "Wow, I can''t believe there are so many stars!"}, {"speaker": "B", "text": "도시에서는 절대 못 보는 풍경이야.", "romanization": "dosieseo-neun jeoldae mot boneun punggyeongiya.", "translation": "You''d never see this view in the city."}]}}, "en": {"word": "star", "explanation": "Celestial bodies that shine in the night sky. In Korean literature, stars symbolize hope, longing, and dreams. Yun Dong-ju''s ''Counting Stars at Night'' is one of Korea''s most beloved poems.", "examples": {"beginner": "There are many stars.", "intermediate": "The stars are really visible tonight.", "advanced": "It''s hard to see stars in the city due to light pollution.", "master": "Reading Yun Dong-ju''s ''Counting Stars at Night'' changes how you look at the stars."}, "variations": {"formal": ["The stars are shining brightly.", "The stars are beautiful."], "casual": ["Look at the stars!", "So many stars!"], "short": ["star"]}, "dialogue": {"context": "Looking at the night sky in the countryside", "dialogue": [{"speaker": "A", "text": "Wow, I can''t believe there are so many stars!", "romanization": "", "translation": "와, 별이 이렇게 많다니!"}, {"speaker": "B", "text": "You''d never see this view in the city.", "romanization": "", "translation": "도시에서는 절대 못 보는 풍경이야."}]}}}'),
  ('mupung', '무풍', 'mupung', 'noun', 'weather', 'advanced', 'rare', '["weather", "calm", "measurement"]', '{"ko": {"word": "무풍", "explanation": "바람이 전혀 불지 않는 상태를 뜻합니다. 기상 관측에서 풍속 0m/s를 의미합니다. 여름 무풍 상태에서는 열기가 빠지지 않아 더욱 덥게 느껴집니다.", "examples": {"beginner": "오늘은 무풍이에요.", "intermediate": "무풍 상태라 더위가 더 심해요.", "advanced": "무풍에 고온다습한 날씨가 이어지면 열사병 위험이 높아진다.", "master": "해안 지역에서 무풍이 지속되면 해무가 발생하여 항행에 지장을 준다."}, "variations": {"formal": ["무풍 상태입니다.", "바람이 관측되지 않습니다."], "casual": ["바람 하나 안 불어.", "완전 무풍이야."], "short": ["무풍"]}, "dialogue": {"context": "무더운 여름 오후에", "dialogue": [{"speaker": "A", "text": "바람이 하나도 안 불어서 숨이 막혀.", "romanization": "barami hanado an bureoseo sumi makhyeo.", "translation": "There''s no wind at all, it''s suffocating."}, {"speaker": "B", "text": "완전 무풍이네. 실내로 들어가자.", "romanization": "wanjeon mupung-ine. sillaero deureogaja.", "translation": "It''s completely calm. Let''s go inside."}]}}, "en": {"word": "no wind/calm", "explanation": "A state of absolutely no wind, meaning 0m/s wind speed in meteorological observation. Summer calm conditions trap heat and make it feel even hotter.", "examples": {"beginner": "There is no wind today.", "intermediate": "The calm conditions make the heat worse.", "advanced": "Calm, hot, and humid weather increases the risk of heatstroke.", "master": "Prolonged calm in coastal areas can cause sea fog, disrupting navigation."}, "variations": {"formal": ["It is calm.", "No wind has been observed."], "casual": ["Not a breeze.", "Totally dead calm."], "short": ["calm"]}, "dialogue": {"context": "On a sweltering summer afternoon", "dialogue": [{"speaker": "A", "text": "There''s no wind at all, it''s suffocating.", "romanization": "", "translation": "바람이 하나도 안 불어서 숨이 막혀."}, {"speaker": "B", "text": "It''s completely calm. Let''s go inside.", "romanization": "", "translation": "완전 무풍이네. 실내로 들어가자."}]}}}'),
  ('gyeolbing', '결빙', 'gyeolbing', 'noun', 'weather', 'advanced', 'uncommon', '["weather", "winter", "driving", "danger"]', '{"ko": {"word": "결빙", "explanation": "물이 얼어서 얼음이 되는 현상을 뜻합니다. 겨울철 도로 결빙은 교통사고의 주요 원인이며, 특히 ''블랙아이스''는 눈에 보이지 않아 매우 위험합니다.", "examples": {"beginner": "도로가 결빙되었어요.", "intermediate": "결빙 주의보가 내려서 운전 조심하세요.", "advanced": "다리 위는 결빙이 먼저 일어나니 속도를 줄여야 해요.", "master": "새벽 기온이 영하로 떨어지면서 도로 곳곳에 블랙아이스가 형성되었다."}, "variations": {"formal": ["결빙 주의보가 발령되었습니다.", "도로 결빙에 유의하시기 바랍니다."], "casual": ["길이 얼었어.", "빙판이야."], "short": ["결빙"]}, "dialogue": {"context": "추운 겨울 아침 운전하기 전에", "dialogue": [{"speaker": "A", "text": "오늘 결빙 주의보래. 운전 조심해.", "romanization": "oneul gyeolbing juuiborae. unjeon josimhae.", "translation": "There''s a freezing advisory today. Drive carefully."}, {"speaker": "B", "text": "알겠어. 천천히 갈게.", "romanization": "algesseo. cheoncheonhi galge.", "translation": "Got it. I''ll drive slowly."}]}}, "en": {"word": "freezing/icing", "explanation": "The phenomenon of water turning to ice. Road icing in winter is a major cause of traffic accidents. ''Black ice'' is especially dangerous as it''s invisible to drivers.", "examples": {"beginner": "The road is frozen.", "intermediate": "A freezing advisory has been issued, so drive carefully.", "advanced": "Bridges freeze first, so you should slow down.", "master": "As dawn temperatures dropped below zero, black ice formed on roads throughout the area."}, "variations": {"formal": ["A freezing advisory has been issued.", "Please be aware of road icing."], "casual": ["The road is icy.", "It''s a skating rink out there."], "short": ["icing"]}, "dialogue": {"context": "Before driving on a cold winter morning", "dialogue": [{"speaker": "A", "text": "There''s a freezing advisory today. Drive carefully.", "romanization": "", "translation": "오늘 결빙 주의보래. 운전 조심해."}, {"speaker": "B", "text": "Got it. I''ll drive slowly.", "romanization": "", "translation": "알겠어. 천천히 갈게."}]}}}'),
  ('haebing', '해빙', 'haebing', 'noun', 'weather', 'advanced', 'uncommon', '["weather", "spring", "nature", "seasonal"]', '{"ko": {"word": "해빙", "explanation": "얼음이 녹는 현상을 뜻합니다. 봄이 오면서 강이나 호수의 얼음이 녹는 계절적 현상이며, 비유적으로 ''관계나 상황이 풀리다''는 의미로도 사용됩니다.", "examples": {"beginner": "봄이 오면 해빙이 시작돼요.", "intermediate": "강의 해빙이 시작되면 봄이 온 거예요.", "advanced": "해빙기에는 강가에 가까이 가지 않도록 주의해야 합니다.", "master": "남북 관계의 해빙 무드가 조성되고 있다는 보도가 나왔다."}, "variations": {"formal": ["해빙이 시작되고 있습니다.", "해빙 현상이 관측됩니다."], "casual": ["얼음이 녹고 있어.", "봄이 오나 봐."], "short": ["해빙"]}, "dialogue": {"context": "이른 봄 강가를 걸으며", "dialogue": [{"speaker": "A", "text": "강 얼음이 녹기 시작했네.", "romanization": "gang eoreumi nokgi sijakhaenne.", "translation": "The river ice is starting to melt."}, {"speaker": "B", "text": "해빙이 시작됐으니 진짜 봄이 오는 거야.", "romanization": "haebing-i sijakdwaesseunikka jinjja bom-i oneun geoya.", "translation": "The thaw has begun, so spring is really coming."}]}}, "en": {"word": "thaw", "explanation": "The melting of ice. A seasonal phenomenon when rivers and lakes thaw in spring. Figuratively, it also means ''easing of relations or situations'' (e.g., diplomatic thaw).", "examples": {"beginner": "The thaw begins when spring comes.", "intermediate": "When the river starts thawing, spring has arrived.", "advanced": "During the thaw period, stay away from riverbanks for safety.", "master": "Reports emerged of a thaw in inter-Korean relations."}, "variations": {"formal": ["The thaw is beginning.", "Thawing has been observed."], "casual": ["The ice is melting.", "Spring must be coming."], "short": ["thaw"]}, "dialogue": {"context": "Walking by the river in early spring", "dialogue": [{"speaker": "A", "text": "The river ice is starting to melt.", "romanization": "", "translation": "강 얼음이 녹기 시작했네."}, {"speaker": "B", "text": "The thaw has begun, so spring is really coming.", "romanization": "", "translation": "해빙이 시작됐으니 진짜 봄이 오는 거야."}]}}}');

-- animals (50 entries)
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES
  ('gae', '개', 'gae', 'noun', 'animals', 'beginner', 'common', '["animals", "pets", "daily-life", "beginner-essential"]', '{"ko": {"word": "개", "explanation": "가정에서 키우는 반려동물입니다. 한국에서 강아지(puppy)라는 표현도 성견에게 자주 씁니다. 십이지 중 열한 번째 동물(戌)이기도 합니다.", "examples": {"beginner": "저는 개를 좋아해요.", "intermediate": "우리 집에 개 한 마리가 있어요.", "advanced": "한국에서 반려견 인구가 크게 늘었다.", "master": "동물 보호법 개정으로 반려견 등록이 의무화되었다."}, "variations": {"formal": ["개가 있습니다.", "반려견을 기르고 있습니다."], "casual": ["강아지 키워.", "개 좋아해."], "short": ["개"]}, "dialogue": {"context": "공원에서 산책 중", "dialogue": [{"speaker": "A", "text": "저 강아지 진짜 귀엽다!", "romanization": "jeo gangaji jinjja gwiyeopda!", "translation": "That puppy is so cute!"}, {"speaker": "B", "text": "만져 봐도 돼요?", "romanization": "manjyeo bwado dwaeyo?", "translation": "Can I pet it?"}]}}, "en": {"word": "dog", "explanation": "A domesticated companion animal. In Korea, the word ''강아지'' (puppy) is commonly used even for adult dogs as a term of endearment. The dog is also the 11th animal in the Korean zodiac.", "examples": {"beginner": "I like dogs.", "intermediate": "We have one dog at home.", "advanced": "The pet dog population in Korea has grown significantly.", "master": "Due to revised animal protection laws, pet dog registration has become mandatory."}, "variations": {"formal": ["There is a dog.", "I am raising a pet dog."], "casual": ["I have a dog.", "I love dogs."], "short": ["dog"]}, "dialogue": {"context": "Walking in the park", "dialogue": [{"speaker": "A", "text": "That puppy is so cute!", "romanization": "", "translation": "저 강아지 진짜 귀엽다!"}, {"speaker": "B", "text": "Can I pet it?", "romanization": "", "translation": "만져 봐도 돼요?"}]}}}'),
  ('goyangi', '고양이', 'goyangi', 'noun', 'animals', 'beginner', 'common', '["animals", "pets", "daily-life", "beginner-essential"]', '{"ko": {"word": "고양이", "explanation": "독립적인 성격으로 알려진 반려동물입니다. ''냥이''는 고양이의 귀여운 줄임말이며, 한국에서 ''캣맘''(길고양이를 돌보는 사람)이라는 신조어도 있습니다.", "examples": {"beginner": "고양이가 자고 있어요.", "intermediate": "우리 고양이는 참치를 좋아해요.", "advanced": "길고양이에게 밥을 주는 사람들이 많다.", "master": "고양이는 독립적이면서도 주인에게 애착을 보이는 동물이다."}, "variations": {"formal": ["고양이가 있습니다.", "고양이를 기르고 있습니다."], "casual": ["냥이 키워.", "고양이 좋아해."], "short": ["고양이"]}, "dialogue": {"context": "반려동물 이야기를 하면서", "dialogue": [{"speaker": "A", "text": "너 고양이 키워?", "romanization": "neo goyangi kiwo?", "translation": "Do you have a cat?"}, {"speaker": "B", "text": "응, 두 마리 키워. 이름은 나비랑 구름이야.", "romanization": "eung, du mari kiwo. ireumeun nabirang gureumiya.", "translation": "Yeah, I have two. Their names are Nabi and Gureum."}]}}, "en": {"word": "cat", "explanation": "A companion animal known for its independent personality. ''냥이'' is an affectionate shortened form of 고양이, similar to ''kitty.'' In Korea, ''캣맘'' (cat mom) refers to people who care for stray cats.", "examples": {"beginner": "The cat is sleeping.", "intermediate": "My cat likes tuna.", "advanced": "Many people feed stray cats.", "master": "Cats are animals that are independent yet show attachment to their owners."}, "variations": {"formal": ["There is a cat.", "I am raising a cat."], "casual": ["I have a cat.", "Love cats."], "short": ["cat"]}, "dialogue": {"context": "Talking about pets", "dialogue": [{"speaker": "A", "text": "Do you have a cat?", "romanization": "", "translation": "너 고양이 키워?"}, {"speaker": "B", "text": "Yeah, I have two. Their names are Nabi and Gureum.", "romanization": "", "translation": "응, 두 마리 키워. 이름은 나비랑 구름이야."}]}}}'),
  ('sae', '새', 'sae', 'noun', 'animals', 'beginner', 'common', '["animals", "nature", "sky", "sound"]', '{"ko": {"word": "새", "explanation": "날개가 있고 날 수 있는 동물의 총칭입니다. 동음이의어로 ''새''는 ''새로운(new)''이라는 뜻도 있습니다. 한국에서 까치는 길조, 까마귀는 흉조로 여겨집니다.", "examples": {"beginner": "새가 노래해요.", "intermediate": "창밖에 새가 앉아 있어요.", "advanced": "철새들이 가을이면 남쪽으로 날아간다.", "master": "한국에는 약 500종의 조류가 관찰된다."}, "variations": {"formal": ["새가 날고 있습니다.", "조류를 관찰합니다."], "casual": ["새 봐!", "새가 운다."], "short": ["새"]}, "dialogue": {"context": "공원 벤치에 앉아서", "dialogue": [{"speaker": "A", "text": "저기 새 소리 들려?", "romanization": "jeogi sae sori deullyeo?", "translation": "Do you hear the birds over there?"}, {"speaker": "B", "text": "응, 참새인 것 같아.", "romanization": "eung, chamsaein geot gata.", "translation": "Yeah, I think it''s a sparrow."}]}}, "en": {"word": "bird", "explanation": "A general term for feathered, winged animals. ''새'' is also a homonym meaning ''new'' in Korean. In Korean culture, magpies are considered lucky while crows are seen as bad omens.", "examples": {"beginner": "The bird is singing.", "intermediate": "A bird is sitting outside the window.", "advanced": "Migratory birds fly south in autumn.", "master": "About 500 species of birds have been observed in Korea."}, "variations": {"formal": ["The bird is flying.", "We are observing birds."], "casual": ["Look, a bird!", "The bird''s singing."], "short": ["bird"]}, "dialogue": {"context": "Sitting on a park bench", "dialogue": [{"speaker": "A", "text": "Do you hear the birds over there?", "romanization": "", "translation": "저기 새 소리 들려?"}, {"speaker": "B", "text": "Yeah, I think it''s a sparrow.", "romanization": "", "translation": "응, 참새인 것 같아."}]}}}'),
  ('mulgogi', '물고기', 'mulgogi', 'noun', 'animals', 'beginner', 'common', '["animals", "nature", "food", "water"]', '{"ko": {"word": "물고기", "explanation": "물속에 사는 동물의 총칭입니다. ''물''(water) + ''고기''(meat/fish)의 합성어입니다. 살아 있을 때는 ''물고기'', 식용일 때는 ''생선''이라고 구분합니다.", "examples": {"beginner": "물고기가 헤엄쳐요.", "intermediate": "이 호수에 물고기가 많아요.", "advanced": "열대어는 색이 화려한 물고기이다.", "master": "살아 있을 때는 물고기, 잡아서 먹을 때는 생선이라고 부른다."}, "variations": {"formal": ["물고기가 있습니다.", "어류가 서식하고 있습니다."], "casual": ["물고기다!", "고기 잡자."], "short": ["물고기"]}, "dialogue": {"context": "수족관에서", "dialogue": [{"speaker": "A", "text": "이 물고기 이름이 뭐야?", "romanization": "i mulgogi ireumi mwoya?", "translation": "What''s the name of this fish?"}, {"speaker": "B", "text": "흰동가리야. 니모 알지?", "romanization": "huindongariya. nimo alji?", "translation": "It''s a clownfish. You know Nemo, right?"}]}}, "en": {"word": "fish", "explanation": "A general term for aquatic animals. It''s a compound of ''물'' (water) + ''고기'' (meat). In Korean, living fish are called ''물고기'' while fish as food is called ''생선''.", "examples": {"beginner": "The fish is swimming.", "intermediate": "There are many fish in this lake.", "advanced": "Tropical fish are colorful species.", "master": "When alive they are called ''물고기''; when caught for eating, they are called ''생선''."}, "variations": {"formal": ["There are fish.", "Aquatic species inhabit this area."], "casual": ["Fish!", "Let''s go fishing."], "short": ["fish"]}, "dialogue": {"context": "At an aquarium", "dialogue": [{"speaker": "A", "text": "What''s the name of this fish?", "romanization": "", "translation": "이 물고기 이름이 뭐야?"}, {"speaker": "B", "text": "It''s a clownfish. You know Nemo, right?", "romanization": "", "translation": "흰동가리야. 니모 알지?"}]}}}'),
  ('tokki', '토끼', 'tokki', 'noun', 'animals', 'beginner', 'common', '["animals", "pets", "zodiac", "cute"]', '{"ko": {"word": "토끼", "explanation": "긴 귀와 짧은 꼬리가 특징인 동물입니다. 십이지 중 네 번째 동물(卯)이며, 한국 전래동화 ''별주부전''에서 토끼는 꾀를 써서 용궁에서 탈출하는 지혜로운 동물로 나옵니다.", "examples": {"beginner": "토끼가 귀여워요.", "intermediate": "토끼는 당근을 좋아해요.", "advanced": "별주부전에서 토끼는 용왕을 속이고 탈출한다.", "master": "십이지 중 묘(卯)에 해당하는 토끼는 영리함의 상징이다."}, "variations": {"formal": ["토끼가 있습니다.", "토끼를 기르고 있습니다."], "casual": ["토끼다!", "토끼 귀엽다."], "short": ["토끼"]}, "dialogue": {"context": "반려동물 가게에서", "dialogue": [{"speaker": "A", "text": "이 토끼 너무 귀엽다! 키우고 싶다.", "romanization": "i tokki neomu gwiyeopda! kiugo sipda.", "translation": "This rabbit is so cute! I want to keep it."}, {"speaker": "B", "text": "토끼는 생각보다 관리가 필요해.", "romanization": "tokkineun saenggakboda gwanriga piryohae.", "translation": "Rabbits need more care than you''d think."}]}}, "en": {"word": "rabbit", "explanation": "An animal with long ears and a short tail. The rabbit is the 4th animal in the Korean zodiac. In the classic Korean folktale ''Byeoljubu-jeon,'' the rabbit cleverly escapes the Dragon King''s underwater palace, symbolizing wit and resourcefulness.", "examples": {"beginner": "The rabbit is cute.", "intermediate": "Rabbits like carrots.", "advanced": "In the tale of Byeoljubu-jeon, the rabbit tricks the Dragon King and escapes.", "master": "The rabbit, corresponding to ''myo'' (卯) in the zodiac, is a symbol of cleverness."}, "variations": {"formal": ["There is a rabbit.", "I am raising a rabbit."], "casual": ["A rabbit!", "So cute!"], "short": ["rabbit"]}, "dialogue": {"context": "At a pet shop", "dialogue": [{"speaker": "A", "text": "This rabbit is so cute! I want to keep it.", "romanization": "", "translation": "이 토끼 너무 귀엽다! 키우고 싶다."}, {"speaker": "B", "text": "Rabbits need more care than you''d think.", "romanization": "", "translation": "토끼는 생각보다 관리가 필요해."}]}}}'),
  ('so', '소', 'so', 'noun', 'animals', 'beginner', 'common', '["animals", "farm", "zodiac", "food", "korean-culture"]', '{"ko": {"word": "소", "explanation": "농경 사회에서 매우 중요한 동물이었습니다. 십이지 중 두 번째 동물(丑)이며, 한국 전통 문화에서 소는 근면과 성실의 상징입니다. ''소잃고 외양간 고친다''라는 속담이 있습니다.", "examples": {"beginner": "소가 풀을 먹어요.", "intermediate": "한국에서 소고기는 특별한 음식이에요.", "advanced": "소잃고 외양간 고친다는 속담은 이미 늦었다는 뜻이다.", "master": "전통 농경 사회에서 소는 가족이나 다름없는 존재였다."}, "variations": {"formal": ["소가 있습니다.", "한우를 키우고 있습니다."], "casual": ["소다!", "소 봐."], "short": ["소"]}, "dialogue": {"context": "시골 농장을 방문하며", "dialogue": [{"speaker": "A", "text": "와, 소가 정말 크다!", "romanization": "wa, soga jeongmal keuda!", "translation": "Wow, the cow is really big!"}, {"speaker": "B", "text": "이게 한우야. 한국 소고기 중에 제일 비싸.", "romanization": "ige hanwuya. hanguk sogogi junge jeil bissa.", "translation": "This is Hanwoo. It''s the most expensive Korean beef."}]}}, "en": {"word": "cow", "explanation": "An animal of great importance in traditional Korean farming. The cow is the 2nd zodiac animal (丑) and symbolizes diligence and honesty. The proverb ''소잃고 외양간 고친다'' (fixing the barn after losing the cow) means it''s too late to act after the damage is done.", "examples": {"beginner": "The cow eats grass.", "intermediate": "Beef is a special food in Korea.", "advanced": "The proverb ''fixing the barn after losing the cow'' means acting too late.", "master": "In traditional farming society, cows were treated almost like family members."}, "variations": {"formal": ["There is a cow.", "We raise Hanwoo cattle."], "casual": ["A cow!", "Look at the cow."], "short": ["cow"]}, "dialogue": {"context": "Visiting a rural farm", "dialogue": [{"speaker": "A", "text": "Wow, the cow is really big!", "romanization": "", "translation": "와, 소가 정말 크다!"}, {"speaker": "B", "text": "This is Hanwoo. It''s the most expensive Korean beef.", "romanization": "", "translation": "이게 한우야. 한국 소고기 중에 제일 비싸."}]}}}'),
  ('mal', '말', 'mal', 'noun', 'animals', 'beginner', 'common', '["animals", "farm", "zodiac", "transportation"]', '{"ko": {"word": "말", "explanation": "십이지 중 일곱 번째 동물(午)입니다. 동음이의어로 ''말''은 ''언어/말씀(speech)''이라는 뜻도 있습니다. 제주도에는 조랑말(제주마)이 유명하며, 전통적으로 이동과 전투에 중요한 동물이었습니다.", "examples": {"beginner": "말이 달려요.", "intermediate": "제주도에 조랑말이 유명해요.", "advanced": "말은 예로부터 교통수단으로 사용되었다.", "master": "고구려 벽화에는 말을 탄 무사의 모습이 자주 등장한다."}, "variations": {"formal": ["말이 있습니다.", "승마를 즐깁니다."], "casual": ["말이다!", "말 타 보고 싶다."], "short": ["말"]}, "dialogue": {"context": "제주도 여행 중", "dialogue": [{"speaker": "A", "text": "제주도에서 말 타 봤어?", "romanization": "jejudo-eseo mal ta bwasseo?", "translation": "Have you ridden a horse in Jeju?"}, {"speaker": "B", "text": "응, 조랑말 체험 했어. 너무 재밌었어!", "romanization": "eung, jorangmal cheheom haesseo. neomu jaemisseosseo!", "translation": "Yeah, I did a pony experience. It was so fun!"}]}}, "en": {"word": "horse", "explanation": "The 7th animal in the Korean zodiac (午). The word ''말'' is also a homonym meaning ''speech/words.'' Jeju Island is famous for its native ponies (조랑말). Horses were historically vital for transportation and warfare in Korea.", "examples": {"beginner": "The horse is running.", "intermediate": "Jeju Island is famous for its ponies.", "advanced": "Horses have been used as transportation since ancient times.", "master": "Goguryeo tomb murals frequently depict mounted warriors."}, "variations": {"formal": ["There is a horse.", "I enjoy horseback riding."], "casual": ["A horse!", "I want to ride a horse."], "short": ["horse"]}, "dialogue": {"context": "Traveling in Jeju Island", "dialogue": [{"speaker": "A", "text": "Have you ridden a horse in Jeju?", "romanization": "", "translation": "제주도에서 말 타 봤어?"}, {"speaker": "B", "text": "Yeah, I did a pony experience. It was so fun!", "romanization": "", "translation": "응, 조랑말 체험 했어. 너무 재밌었어!"}]}}}'),
  ('dwaeji', '돼지', 'dwaeji', 'noun', 'animals', 'beginner', 'common', '["animals", "farm", "zodiac", "food"]', '{"ko": {"word": "돼지", "explanation": "십이지 중 열두 번째(마지막) 동물(亥)입니다. 한국 문화에서 돼지는 복과 재물의 상징입니다. 돼지꿈을 꾸면 좋은 일이 생긴다고 하여 로또를 사는 사람도 있습니다.", "examples": {"beginner": "돼지가 귀여워요.", "intermediate": "한국에서 삼겹살은 돼지고기예요.", "advanced": "돼지꿈을 꾸면 복이 온다는 속설이 있다.", "master": "돼지는 십이지의 마지막 동물로, 재물과 풍요의 상징이다."}, "variations": {"formal": ["돼지가 있습니다.", "양돈업을 하고 있습니다."], "casual": ["돼지다!", "돼지 귀엽다."], "short": ["돼지"]}, "dialogue": {"context": "음식 이야기를 하면서", "dialogue": [{"speaker": "A", "text": "삼겹살 먹으러 갈래?", "romanization": "samgyeopsal meogeulleo gallae?", "translation": "Want to go eat samgyeopsal?"}, {"speaker": "B", "text": "좋아! 돼지고기가 제일 맛있어.", "romanization": "joa! dwaejigogiga jeil masissseo.", "translation": "Sure! Pork is the most delicious."}]}}, "en": {"word": "pig", "explanation": "The 12th and final animal in the Korean zodiac (亥). In Korean culture, pigs symbolize wealth and good fortune. Dreaming of a pig is considered lucky — some people even buy lottery tickets after such a dream.", "examples": {"beginner": "The pig is cute.", "intermediate": "Samgyeopsal is pork in Korea.", "advanced": "There''s a folk belief that dreaming of a pig brings good fortune.", "master": "The pig, as the last animal of the zodiac, symbolizes wealth and abundance."}, "variations": {"formal": ["There is a pig.", "We operate a pig farm."], "casual": ["A pig!", "Pigs are cute."], "short": ["pig"]}, "dialogue": {"context": "Talking about food", "dialogue": [{"speaker": "A", "text": "Want to go eat samgyeopsal?", "romanization": "", "translation": "삼겹살 먹으러 갈래?"}, {"speaker": "B", "text": "Sure! Pork is the most delicious.", "romanization": "", "translation": "좋아! 돼지고기가 제일 맛있어."}]}}}'),
  ('dak', '닭', 'dak', 'noun', 'animals', 'beginner', 'common', '["animals", "farm", "zodiac", "food"]', '{"ko": {"word": "닭", "explanation": "십이지 중 열 번째 동물(酉)입니다. 한국 음식 문화에서 매우 중요하며, 치킨은 한국의 대표적인 야식입니다. 삼계탕(닭+인삼 수프)은 여름 보양식으로 유명합니다. 발음 주의: 받침 ''ㄺ''은 [ㄱ]으로 발음합니다.", "examples": {"beginner": "닭이 울어요.", "intermediate": "한국 치킨은 정말 맛있어요.", "advanced": "삼계탕은 복날에 먹는 한국 전통 보양식이다.", "master": "''닭''의 발음은 [닥]이며, ''닭도리탕''은 ''닭볶음탕''으로 순화된 표현이다."}, "variations": {"formal": ["닭이 있습니다.", "양계장을 운영하고 있습니다."], "casual": ["닭이다!", "치킨 먹자."], "short": ["닭"]}, "dialogue": {"context": "저녁 메뉴를 정하면서", "dialogue": [{"speaker": "A", "text": "오늘 치킨 시킬까?", "romanization": "oneul chikin sikilkka?", "translation": "Should we order chicken today?"}, {"speaker": "B", "text": "좋아! 양념이랑 후라이드 반반으로 하자.", "romanization": "joa! yangnyeomirang huraideu banbanneuro haja.", "translation": "Sure! Let''s get half seasoned and half fried."}]}}, "en": {"word": "chicken", "explanation": "The 10th animal in the Korean zodiac (酉). Chicken is deeply embedded in Korean food culture — fried chicken is the quintessential late-night snack. Samgyetang (chicken ginseng soup) is a famous summer health food. Pronunciation note: the final consonant cluster ''ㄺ'' is pronounced as [k].", "examples": {"beginner": "The chicken is crowing.", "intermediate": "Korean fried chicken is really delicious.", "advanced": "Samgyetang is a traditional Korean health food eaten on the hottest days.", "master": "''닭'' is pronounced [dak], and ''닭도리탕'' has been refined to ''닭볶음탕'' in standard Korean."}, "variations": {"formal": ["There is a chicken.", "We operate a poultry farm."], "casual": ["A chicken!", "Let''s eat chicken."], "short": ["chicken"]}, "dialogue": {"context": "Deciding on dinner", "dialogue": [{"speaker": "A", "text": "Should we order chicken today?", "romanization": "", "translation": "오늘 치킨 시킬까?"}, {"speaker": "B", "text": "Sure! Let''s get half seasoned and half fried.", "romanization": "", "translation": "좋아! 양념이랑 후라이드 반반으로 하자."}]}}}'),
  ('yang', '양', 'yang', 'noun', 'animals', 'beginner', 'common', '["animals", "farm", "zodiac"]', '{"ko": {"word": "양", "explanation": "십이지 중 여덟 번째 동물(未)입니다. 동음이의어로 ''양''은 ''량/양(amount)'', ''양(Western/foreign)'' 등 여러 뜻이 있습니다. 한국에서 양고기는 최근 인기가 높아진 음식입니다.", "examples": {"beginner": "양이 풀을 먹어요.", "intermediate": "대관령에 양떼 목장이 있어요.", "advanced": "한국에서 양갈비 전문점이 크게 늘었다.", "master": "''양''은 동음이의어가 많아 문맥에 따라 뜻이 달라진다."}, "variations": {"formal": ["양이 있습니다.", "목양업을 하고 있습니다."], "casual": ["양이다!", "양 귀엽다."], "short": ["양"]}, "dialogue": {"context": "대관령 양떼 목장을 방문하며", "dialogue": [{"speaker": "A", "text": "여기 양이 정말 많다!", "romanization": "yeogi yangi jeongmal manta!", "translation": "There are so many sheep here!"}, {"speaker": "B", "text": "먹이 줄 수 있대. 해 볼래?", "romanization": "meogi jul su itdae. hae bollae?", "translation": "They say we can feed them. Want to try?"}]}}, "en": {"word": "sheep", "explanation": "The 8th animal in the Korean zodiac (未). The word ''양'' is a homonym with multiple meanings including ''amount'' and ''Western/foreign.'' Daegwallyeong Sheep Farm is a famous tourist destination in Korea.", "examples": {"beginner": "The sheep eats grass.", "intermediate": "There is a sheep ranch at Daegwallyeong.", "advanced": "Lamb specialty restaurants have grown significantly in Korea.", "master": "''양'' has many homonyms, and meaning changes depending on context."}, "variations": {"formal": ["There are sheep.", "We run a sheep farm."], "casual": ["Sheep!", "Sheep are cute."], "short": ["sheep"]}, "dialogue": {"context": "Visiting Daegwallyeong Sheep Farm", "dialogue": [{"speaker": "A", "text": "There are so many sheep here!", "romanization": "", "translation": "여기 양이 정말 많다!"}, {"speaker": "B", "text": "They say we can feed them. Want to try?", "romanization": "", "translation": "먹이 줄 수 있대. 해 볼래?"}]}}}'),
  ('horangi', '호랑이', 'horangi', 'noun', 'animals', 'beginner', 'common', '["animals", "wild", "zodiac", "korean-culture", "symbol"]', '{"ko": {"word": "호랑이", "explanation": "한국을 상징하는 동물이자 십이지 중 세 번째 동물(寅)입니다. ''호랑이도 제 말하면 온다''라는 속담이 있으며, 1988 서울 올림픽 마스코트 ''호돌이'', 2018 평창 올림픽 마스코트 ''수호랑''으로도 유명합니다. 단군 신화에서 호랑이와 곰이 등장합니다.", "examples": {"beginner": "호랑이는 무서워요.", "intermediate": "호랑이는 한국의 상징 동물이에요.", "advanced": "옛날 이야기에는 호랑이가 자주 등장한다.", "master": "호랑이도 제 말 하면 온다더니, 마침 네가 왔구나."}, "variations": {"formal": ["호랑이는 한반도의 상징입니다.", "백두산 호랑이라고 합니다."], "casual": ["호랑이다!", "호랑이 무섭다."], "short": ["호랑이"]}, "dialogue": {"context": "동물원에서", "dialogue": [{"speaker": "A", "text": "호랑이 봐! 진짜 크다.", "romanization": "horangi bwa! jinjja keuda.", "translation": "Look at the tiger! It''s really big."}, {"speaker": "B", "text": "한국 호랑이는 백두산 호랑이라고 해.", "romanization": "hanguk horangineun baekdusan horangirago hae.", "translation": "Korean tigers are called Baekdu Mountain tigers."}]}}, "en": {"word": "tiger", "explanation": "Korea''s national symbol and the 3rd zodiac animal (寅). The proverb ''호랑이도 제 말하면 온다'' (speak of the tiger and it appears) is like ''speak of the devil.'' The tiger was the mascot of the 1988 Seoul Olympics (''Hodori'') and 2018 PyeongChang Olympics (''Soohorang''). In the Dangun creation myth, both a tiger and a bear appear.", "examples": {"beginner": "Tigers are scary.", "intermediate": "The tiger is Korea''s symbolic animal.", "advanced": "Tigers frequently appear in traditional Korean folktales.", "master": "Speak of the tiger and it appears — oh, there you are."}, "variations": {"formal": ["The tiger is a symbol of the Korean Peninsula.", "It is called the Baekdu Mountain tiger."], "casual": ["A tiger!", "Tigers are scary."], "short": ["tiger"]}, "dialogue": {"context": "At the zoo", "dialogue": [{"speaker": "A", "text": "Look at the tiger! It''s really big.", "romanization": "", "translation": "호랑이 봐! 진짜 크다."}, {"speaker": "B", "text": "Korean tigers are called Baekdu Mountain tigers.", "romanization": "", "translation": "한국 호랑이는 백두산 호랑이라고 해."}]}}}'),
  ('yong', '용', 'yong', 'noun', 'animals', 'beginner', 'common', '["animals", "mythical", "zodiac", "korean-culture"]', '{"ko": {"word": "용", "explanation": "십이지 중 다섯 번째 동물(辰)이며, 유일한 상상 속 동물입니다. 동양 문화에서 용은 왕권과 비, 물을 상징합니다. ''개천에서 용 난다''는 속담은 미천한 환경에서 큰 인물이 나온다는 뜻입니다. 용띠 해에는 출산율이 높아지는 경향이 있습니다.", "examples": {"beginner": "용은 상상 속 동물이에요.", "intermediate": "용은 하늘을 날 수 있어요.", "advanced": "개천에서 용 난다는 속담이 있다.", "master": "용띠 해에는 한국의 출산율이 일시적으로 높아지는 경향이 있다."}, "variations": {"formal": ["용은 상서로운 존재입니다.", "용은 왕권의 상징이었습니다."], "casual": ["용이다!", "용 멋있다."], "short": ["용"]}, "dialogue": {"context": "띠 이야기를 하면서", "dialogue": [{"speaker": "A", "text": "너 무슨 띠야?", "romanization": "neo museun ttiya?", "translation": "What''s your zodiac animal?"}, {"speaker": "B", "text": "나 용띠야. 2000년생이거든.", "romanization": "na yongttiya. icheonnyeonsaengigeodeun.", "translation": "I''m a dragon. I was born in 2000."}]}}, "en": {"word": "dragon", "explanation": "The 5th zodiac animal (辰) and the only mythical creature in the zodiac. In East Asian culture, the dragon symbolizes royalty, rain, and water. The proverb ''개천에서 용 난다'' (a dragon rises from a stream) means a great person can emerge from humble origins. Birth rates tend to rise in dragon years in Korea.", "examples": {"beginner": "The dragon is a mythical animal.", "intermediate": "Dragons can fly in the sky.", "advanced": "There is a proverb: ''A dragon rises from a stream.''", "master": "Birth rates in Korea tend to temporarily increase during dragon years."}, "variations": {"formal": ["The dragon is an auspicious being.", "The dragon was a symbol of royalty."], "casual": ["A dragon!", "Dragons are cool."], "short": ["dragon"]}, "dialogue": {"context": "Talking about zodiac signs", "dialogue": [{"speaker": "A", "text": "What''s your zodiac animal?", "romanization": "", "translation": "너 무슨 띠야?"}, {"speaker": "B", "text": "I''m a dragon. I was born in 2000.", "romanization": "", "translation": "나 용띠야. 2000년생이거든."}]}}}'),
  ('baem', '뱀', 'baem', 'noun', 'animals', 'beginner', 'common', '["animals", "wild", "zodiac", "fear"]', '{"ko": {"word": "뱀", "explanation": "십이지 중 여섯 번째 동물(巳)입니다. 한국에서 뱀은 두려움의 대상이면서도 집을 지키는 수호신으로 여겨지기도 합니다. ''구렁이 담 넘어가듯''이라는 관용구는 슬그머니 넘어가는 것을 뜻합니다.", "examples": {"beginner": "뱀이 무서워요.", "intermediate": "뱀은 다리가 없어요.", "advanced": "구렁이 담 넘어가듯 슬쩍 넘어가면 안 된다.", "master": "전통적으로 집에 나타난 뱀(구렁이)은 터주신으로 여겨 해치지 않았다."}, "variations": {"formal": ["뱀이 있습니다.", "파충류를 연구합니다."], "casual": ["뱀이다!", "뱀 무섭다."], "short": ["뱀"]}, "dialogue": {"context": "등산 중 뱀을 발견하고", "dialogue": [{"speaker": "A", "text": "앗, 저기 뱀이다! 조심해!", "romanization": "at, jeogi baemida! josimhae!", "translation": "Oh, there''s a snake! Be careful!"}, {"speaker": "B", "text": "괜찮아, 가만히 있으면 지나가.", "romanization": "gwaenchana, gamanhi isseumyeon jinaga.", "translation": "It''s okay, if we stay still it''ll pass."}]}}, "en": {"word": "snake", "explanation": "The 6th zodiac animal (巳). In Korea, snakes are feared but also traditionally regarded as guardian spirits of the home. The idiom ''구렁이 담 넘어가듯'' (like a snake going over a wall) means to slyly slip past something.", "examples": {"beginner": "Snakes are scary.", "intermediate": "Snakes don''t have legs.", "advanced": "You can''t just slyly slip past this like a snake over a wall.", "master": "Traditionally, a snake (구렁이) appearing in the home was regarded as a guardian spirit and was not harmed."}, "variations": {"formal": ["There is a snake.", "We study reptiles."], "casual": ["A snake!", "Snakes are scary."], "short": ["snake"]}, "dialogue": {"context": "Spotting a snake while hiking", "dialogue": [{"speaker": "A", "text": "Oh, there''s a snake! Be careful!", "romanization": "", "translation": "앗, 저기 뱀이다! 조심해!"}, {"speaker": "B", "text": "It''s okay, if we stay still it''ll pass.", "romanization": "", "translation": "괜찮아, 가만히 있으면 지나가."}]}}}'),
  ('wonsungi', '원숭이', 'wonsungi', 'noun', 'animals', 'beginner', 'common', '["animals", "wild", "zodiac", "zoo"]', '{"ko": {"word": "원숭이", "explanation": "십이지 중 아홉 번째 동물(申)입니다. 한국에는 야생 원숭이가 없지만, 옛 이야기에는 자주 등장합니다. ''원숭이도 나무에서 떨어진다''라는 속담은 아무리 능숙한 사람도 실수할 수 있다는 뜻입니다.", "examples": {"beginner": "원숭이가 바나나를 먹어요.", "intermediate": "원숭이는 똑똒해요.", "advanced": "원숭이도 나무에서 떨어진다는 속담이 있다.", "master": "한반도에는 야생 원숭이가 서식하지 않지만, 문화적으로는 친숙한 동물이다."}, "variations": {"formal": ["원숭이가 있습니다.", "영장류를 관찰합니다."], "casual": ["원숭이다!", "원숭이 귀엽다."], "short": ["원숭이"]}, "dialogue": {"context": "동물원에서 원숭이를 보며", "dialogue": [{"speaker": "A", "text": "원숭이가 사람이랑 비슷하게 생겼다.", "romanization": "wonsungiga saramirang biseutage saenggyeotda.", "translation": "The monkey looks similar to humans."}, {"speaker": "B", "text": "맞아, 원숭이도 나무에서 떨어진대.", "romanization": "maja, wonsungido namueseo tteoreojindae.", "translation": "Right, even monkeys fall from trees, they say."}]}}, "en": {"word": "monkey", "explanation": "The 9th zodiac animal (申). While there are no wild monkeys in Korea, they appear frequently in folktales. The proverb ''원숭이도 나무에서 떨어진다'' (even monkeys fall from trees) means that even experts can make mistakes.", "examples": {"beginner": "The monkey eats a banana.", "intermediate": "Monkeys are smart.", "advanced": "There is a proverb: ''Even monkeys fall from trees.''", "master": "Although wild monkeys don''t inhabit the Korean Peninsula, they are culturally familiar animals."}, "variations": {"formal": ["There is a monkey.", "We observe primates."], "casual": ["A monkey!", "Monkeys are cute."], "short": ["monkey"]}, "dialogue": {"context": "Watching monkeys at the zoo", "dialogue": [{"speaker": "A", "text": "The monkey looks similar to humans.", "romanization": "", "translation": "원숭이가 사람이랑 비슷하게 생겼다."}, {"speaker": "B", "text": "Right, even monkeys fall from trees, they say.", "romanization": "", "translation": "맞아, 원숭이도 나무에서 떨어진대."}]}}}'),
  ('jwi', '쥐', 'jwi', 'noun', 'animals', 'beginner', 'common', '["animals", "zodiac", "idiom"]', '{"ko": {"word": "쥐", "explanation": "십이지 중 첫 번째 동물(子)입니다. 한국 속담에 ''쥐구멍에도 볕 들 날 있다''(아무리 어려운 처지에도 좋은 날이 온다)가 있습니다. ''쥐도 새도 모르게''는 아무도 모르게 조용히 하는 것을 뜻합니다.", "examples": {"beginner": "쥐가 작아요.", "intermediate": "쥐가 치즈를 좋아해요.", "advanced": "쥐구멍에도 볕 들 날이 있다.", "master": "쥐도 새도 모르게 사라진 그 사건은 아직도 미스터리다."}, "variations": {"formal": ["쥐가 있습니다.", "설치류를 연구합니다."], "casual": ["쥐다!", "쥐 싫어."], "short": ["쥐"]}, "dialogue": {"context": "옛이야기를 하면서", "dialogue": [{"speaker": "A", "text": "십이지 중에 쥐가 첫 번째래.", "romanization": "sibiiji junge jwiga cheot beonjjarae.", "translation": "The rat is the first in the zodiac, apparently."}, {"speaker": "B", "text": "맞아, 소 등에 타고 가서 먼저 도착했다는 이야기가 있어.", "romanization": "maja, so deunge tago gaseo meonjeo dochakhaetdaneun iyagiga isseo.", "translation": "Right, there''s a story that it rode on the cow''s back and arrived first."}]}}, "en": {"word": "mouse/rat", "explanation": "The 1st animal in the Korean zodiac (子). The proverb ''쥐구멍에도 볕 들 날 있다'' (even a mouse hole gets sunshine) means good times will come even in the hardest circumstances. ''쥐도 새도 모르게'' (without even mice or birds knowing) means doing something in complete secrecy.", "examples": {"beginner": "The mouse is small.", "intermediate": "Mice like cheese.", "advanced": "Even a mouse hole gets sunshine someday.", "master": "That case, where someone vanished without even mice or birds knowing, remains a mystery."}, "variations": {"formal": ["There is a mouse.", "We study rodents."], "casual": ["A mouse!", "I hate mice."], "short": ["mouse"]}, "dialogue": {"context": "Talking about old stories", "dialogue": [{"speaker": "A", "text": "The rat is the first in the zodiac, apparently.", "romanization": "", "translation": "십이지 중에 쥐가 첫 번째래."}, {"speaker": "B", "text": "Right, there''s a story that it rode on the cow''s back and arrived first.", "romanization": "", "translation": "맞아, 소 등에 타고 가서 먼저 도착했다는 이야기가 있어."}]}}}'),
  ('saja', '사자', 'saja', 'noun', 'animals', 'beginner', 'common', '["animals", "wild", "zoo", "power"]', '{"ko": {"word": "사자", "explanation": "백수의 왕으로 불리는 동물입니다. 동음이의어로 ''사자''는 ''使者(심부름꾼)'', ''死者(죽은 사람)'', ''四字(네 글자)'' 등 여러 뜻이 있어, 한국어 학습 시 문맥 파악이 중요합니다. 한국 전통 문화에서 사자는 해태(해치)와 함께 수호 동물로 등장합니다.", "examples": {"beginner": "사자는 강해요.", "intermediate": "사자는 백수의 왕이에요.", "advanced": "사자성어(四字成語)에서의 ''사자''는 ''네 글자''라는 뜻이다.", "master": "''사자''는 동음이의어가 많아 문맥 없이는 뜻을 알 수 없다."}, "variations": {"formal": ["사자가 있습니다.", "사자를 관찰합니다."], "casual": ["사자다!", "사자 멋있다."], "short": ["사자"]}, "dialogue": {"context": "동물원에서 사자를 보며", "dialogue": [{"speaker": "A", "text": "사자가 자고 있네. 역시 여유롭다.", "romanization": "sajaga jago inne. yeoksi yeoyuropda.", "translation": "The lion is sleeping. So laid back."}, {"speaker": "B", "text": "백수의 왕이니까 여유 있지!", "romanization": "baeksuui wanginikka yeoyou itji!", "translation": "It''s the king of beasts, so of course it''s relaxed!"}]}}, "en": {"word": "lion", "explanation": "Known as the king of beasts. The word ''사자'' has many homonyms in Korean: ''使者'' (messenger), ''死者'' (deceased person), ''四字'' (four characters) — context is crucial. In Korean traditional culture, lions appear alongside 해태 (haetae) as guardian animals.", "examples": {"beginner": "Lions are strong.", "intermediate": "The lion is the king of beasts.", "advanced": "In ''사자성어'' (four-character idioms), ''사자'' means ''four characters.''", "master": "''사자'' has so many homonyms that its meaning cannot be determined without context."}, "variations": {"formal": ["There is a lion.", "We observe lions."], "casual": ["A lion!", "Lions are cool."], "short": ["lion"]}, "dialogue": {"context": "Watching a lion at the zoo", "dialogue": [{"speaker": "A", "text": "The lion is sleeping. So laid back.", "romanization": "", "translation": "사자가 자고 있네. 역시 여유롭다."}, {"speaker": "B", "text": "It''s the king of beasts, so of course it''s relaxed!", "romanization": "", "translation": "백수의 왕이니까 여유 있지!"}]}}}'),
  ('kokkiri', '코끼리', 'kokkiri', 'noun', 'animals', 'beginner', 'common', '["animals", "wild", "zoo", "large"]', '{"ko": {"word": "코끼리", "explanation": "육지 동물 중 가장 큰 동물입니다. ''코''(nose) + ''끼리''로 이루어진 단어로, 긴 코가 특징입니다. 한국 동요 ''코끼리 아저씨는 코가 손이래''는 어린이들에게 매우 친숙한 노래입니다.", "examples": {"beginner": "코끼리는 커요.", "intermediate": "코끼리 코는 정말 길어요.", "advanced": "코끼리 아저씨는 코가 손이래는 유명한 동요이다.", "master": "''코끼리''는 ''코''와 관련된 어원을 가진 순우리말이다."}, "variations": {"formal": ["코끼리가 있습니다.", "코끼리를 관찰합니다."], "casual": ["코끼리다!", "코끼리 크다."], "short": ["코끼리"]}, "dialogue": {"context": "동물원에서 코끼리를 보며", "dialogue": [{"speaker": "A", "text": "코끼리가 물 뿌리고 있어! 귀엽다.", "romanization": "kokkiriga mul ppurigo isseo! gwiyeopda.", "translation": "The elephant is spraying water! So cute."}, {"speaker": "B", "text": "코끼리 아저씨는 코가 손이래~", "romanization": "kokkiri ajeossineun koga sonirae~", "translation": "Mr. Elephant''s nose is like a hand~ (children''s song)"}]}}, "en": {"word": "elephant", "explanation": "The largest land animal. The Korean word ''코끼리'' is related to ''코'' (nose), reflecting its long trunk. The children''s song ''코끼리 아저씨는 코가 손이래'' (Mr. Elephant''s nose is like a hand) is very popular among Korean children.", "examples": {"beginner": "The elephant is big.", "intermediate": "The elephant''s trunk is really long.", "advanced": "''Mr. Elephant''s nose is like a hand'' is a famous children''s song.", "master": "''코끼리'' is a native Korean word with etymology related to ''코'' (nose)."}, "variations": {"formal": ["There is an elephant.", "We observe elephants."], "casual": ["An elephant!", "Elephants are big."], "short": ["elephant"]}, "dialogue": {"context": "Watching elephants at the zoo", "dialogue": [{"speaker": "A", "text": "The elephant is spraying water! So cute.", "romanization": "", "translation": "코끼리가 물 뿌리고 있어! 귀엽다."}, {"speaker": "B", "text": "Mr. Elephant''s nose is like a hand~ (children''s song)", "romanization": "", "translation": "코끼리 아저씨는 코가 손이래~"}]}}}'),
  ('gom', '곰', 'gom', 'noun', 'animals', 'beginner', 'common', '["animals", "wild", "korean-culture", "mythology"]', '{"ko": {"word": "곰", "explanation": "한국 신화에서 곰은 단군 신화의 웅녀로 등장합니다. 야생에서는 반달가슴곰이 한국의 대표 곰입니다.", "examples": {"beginner": "곰은 크고 힘이 세요.", "intermediate": "한국의 반달가슴곰은 멸종 위기 동물이에요.", "advanced": "단군 신화에서 곰이 사람으로 변했다는 이야기가 전해진다.", "master": "지리산 반달가슴곰 복원 사업은 생태계 보전의 성공적인 사례로 평가받고 있다."}, "variations": {"formal": ["곰이 있습니다.", "곰을 보았습니다."], "casual": ["곰이다!", "곰 봤어?"], "short": ["곰"]}, "dialogue": {"context": "동물원에서 곰을 보면서", "dialogue": [{"speaker": "A", "text": "와, 저 곰 진짜 크다!", "romanization": "wa, jeo gom jinjja keuda!", "translation": "Wow, that bear is really big!"}, {"speaker": "B", "text": "반달가슴곰이래. 한국 고유종이야.", "romanization": "bandalgaseumgomrae. hanguk goyujongiya.", "translation": "They say it''s a moon bear. It''s native to Korea."}]}}, "en": {"word": "bear", "explanation": "In Korean mythology, a bear transforms into a woman (Ungnyeo) in the Dangun founding myth. The Asiatic black bear (moon bear) is Korea''s representative bear species.", "examples": {"beginner": "Bears are big and strong.", "intermediate": "The Asiatic black bear in Korea is an endangered species.", "advanced": "In the Dangun myth, a bear is said to have transformed into a human.", "master": "The Jirisan moon bear restoration project is regarded as a successful case of ecosystem conservation."}, "variations": {"formal": ["There is a bear.", "I saw a bear."], "casual": ["It''s a bear!", "Did you see the bear?"], "short": ["bear"]}, "dialogue": {"context": "Watching bears at the zoo", "dialogue": [{"speaker": "A", "text": "Wow, that bear is really big!", "romanization": "", "translation": "와, 저 곰 진짜 크다!"}, {"speaker": "B", "text": "They say it''s a moon bear. It''s native to Korea.", "romanization": "", "translation": "반달가슴곰이래. 한국 고유종이야."}]}}}'),
  ('neukdae', '늑대', 'neukdae', 'noun', 'animals', 'intermediate', 'uncommon', '["animals", "wild", "folklore", "danger"]', '{"ko": {"word": "늑대", "explanation": "한국 전래동화에서 자주 등장하는 동물입니다. ''양의 탈을 쓴 늑대''처럼 속담에도 등장합니다.", "examples": {"beginner": "늑대는 무서운 동물이에요.", "intermediate": "늑대는 무리 지어 사냥해요.", "advanced": "한국 전래동화에서 늑대는 주로 악역으로 등장한다.", "master": "한반도에서 늑대는 일제강점기 이후 사실상 멸종된 것으로 알려져 있다."}, "variations": {"formal": ["늑대가 나타났습니다.", "늑대를 조심하십시오."], "casual": ["늑대다!", "늑대 나왔어!"], "short": ["늑대"]}, "dialogue": {"context": "전래동화를 읽으며", "dialogue": [{"speaker": "A", "text": "이 이야기에 늑대가 나와?", "romanization": "i iyagie neukdaega nawa?", "translation": "Does a wolf appear in this story?"}, {"speaker": "B", "text": "응, 늑대가 양을 잡으려고 해.", "romanization": "eung, neukdaega yangeul jabeuryeogo hae.", "translation": "Yeah, the wolf tries to catch the sheep."}]}}, "en": {"word": "wolf", "explanation": "A wild animal frequently appearing in Korean folktales. It also appears in proverbs like ''a wolf in sheep''s clothing.''", "examples": {"beginner": "Wolves are scary animals.", "intermediate": "Wolves hunt in packs.", "advanced": "In Korean folktales, wolves typically play the role of villains.", "master": "Wolves on the Korean Peninsula are believed to have gone virtually extinct after the Japanese colonial period."}, "variations": {"formal": ["A wolf has appeared.", "Please beware of wolves."], "casual": ["It''s a wolf!", "A wolf showed up!"], "short": ["wolf"]}, "dialogue": {"context": "Reading a folktale", "dialogue": [{"speaker": "A", "text": "Does a wolf appear in this story?", "romanization": "", "translation": "이 이야기에 늑대가 나와?"}, {"speaker": "B", "text": "Yeah, the wolf tries to catch the sheep.", "romanization": "", "translation": "응, 늑대가 양을 잡으려고 해."}]}}}'),
  ('yeou', '여우', 'yeou', 'noun', 'animals', 'beginner', 'common', '["animals", "wild", "folklore", "korean-culture"]', '{"ko": {"word": "여우", "explanation": "한국 전설에서 구미호(아홉 꼬리 여우)로 유명합니다. 비유적으로 ''여우 같다''는 영리하고 교활하다는 뜻입니다.", "examples": {"beginner": "여우는 영리한 동물이에요.", "intermediate": "그 사람은 여우처럼 똑똑해요.", "advanced": "구미호는 한국 전설에서 가장 유명한 요괴 중 하나이다.", "master": "여우의 상징성은 동아시아 문화권에서 공통적으로 영리함과 변신을 의미한다."}, "variations": {"formal": ["여우가 있습니다.", "여우를 발견했습니다."], "casual": ["여우다!", "여우 같아."], "short": ["여우"]}, "dialogue": {"context": "친구의 성격에 대해 이야기하며", "dialogue": [{"speaker": "A", "text": "그 사람 진짜 여우 같아.", "romanization": "geu saram jinjja yeou gata.", "translation": "That person is really fox-like (sly)."}, {"speaker": "B", "text": "맞아, 항상 머리를 잘 써.", "romanization": "maja, hangsang meorireul jal sseo.", "translation": "Right, they always use their head well."}]}}, "en": {"word": "fox", "explanation": "Famous in Korean legend as the gumiho (nine-tailed fox). Figuratively, ''여우 같다'' means someone is clever and cunning.", "examples": {"beginner": "Foxes are clever animals.", "intermediate": "That person is as smart as a fox.", "advanced": "The gumiho is one of the most famous mythical creatures in Korean legend.", "master": "The symbolism of the fox commonly represents cleverness and shapeshifting across East Asian cultures."}, "variations": {"formal": ["There is a fox.", "A fox was spotted."], "casual": ["It''s a fox!", "So fox-like."], "short": ["fox"]}, "dialogue": {"context": "Talking about a friend''s personality", "dialogue": [{"speaker": "A", "text": "That person is really fox-like (sly).", "romanization": "", "translation": "그 사람 진짜 여우 같아."}, {"speaker": "B", "text": "Right, they always use their head well.", "romanization": "", "translation": "맞아, 항상 머리를 잘 써."}]}}}'),
  ('saseum', '사슴', 'saseum', 'noun', 'animals', 'intermediate', 'uncommon', '["animals", "wild", "nature", "graceful"]', '{"ko": {"word": "사슴", "explanation": "우아한 모습으로 알려진 야생 동물입니다. ''사슴 눈''은 크고 맑은 눈을 뜻합니다.", "examples": {"beginner": "사슴이 뛰어가요.", "intermediate": "그 배우는 사슴 같은 눈을 가졌어요.", "advanced": "제주도에는 야생 사슴이 서식하고 있다.", "master": "녹용은 사슴의 뿔로 만든 한약재로 한국에서 전통적으로 사용되어 왔다."}, "variations": {"formal": ["사슴이 있습니다.", "사슴을 보았습니다."], "casual": ["사슴이다!", "사슴 봤어?"], "short": ["사슴"]}, "dialogue": {"context": "산에서 사슴을 발견하고", "dialogue": [{"speaker": "A", "text": "저기 사슴이다! 조용히 해.", "romanization": "jeogi saseumida! joyonghi hae.", "translation": "There''s a deer over there! Be quiet."}, {"speaker": "B", "text": "와, 진짜 예쁘다. 눈이 크네.", "romanization": "wa, jinjja yeppeuda. nuni keune.", "translation": "Wow, it''s really pretty. Its eyes are big."}]}}, "en": {"word": "deer", "explanation": "A wild animal known for its graceful appearance. ''사슴 눈'' (deer eyes) refers to big, clear eyes as a compliment.", "examples": {"beginner": "The deer is running.", "intermediate": "That actor has eyes like a deer.", "advanced": "Wild deer inhabit Jeju Island.", "master": "Deer antler velvet (noknyong) is a traditional Korean herbal medicine ingredient made from deer antlers."}, "variations": {"formal": ["There is a deer.", "I saw a deer."], "casual": ["It''s a deer!", "Did you see the deer?"], "short": ["deer"]}, "dialogue": {"context": "Spotting a deer in the mountains", "dialogue": [{"speaker": "A", "text": "There''s a deer over there! Be quiet.", "romanization": "", "translation": "저기 사슴이다! 조용히 해."}, {"speaker": "B", "text": "Wow, it''s really pretty. Its eyes are big.", "romanization": "", "translation": "와, 진짜 예쁘다. 눈이 크네."}]}}}'),
  ('doksuri', '독수리', 'doksuri', 'noun', 'animals', 'intermediate', 'uncommon', '["animals", "bird", "wild", "sky", "power"]', '{"ko": {"word": "독수리", "explanation": "하늘의 왕으로 불리는 대형 맹금류입니다. 힘과 자유의 상징으로 쓰입니다.", "examples": {"beginner": "독수리가 하늘을 날아요.", "intermediate": "독수리는 시력이 매우 좋아요.", "advanced": "독수리는 높은 곳에서 먹이를 발견하고 급강하한다.", "master": "한국에서 독수리는 겨울 철새로, 몽골과 시베리아에서 월동하러 찾아온다."}, "variations": {"formal": ["독수리가 보입니다.", "독수리를 관찰했습니다."], "casual": ["독수리다!", "독수리 멋있어!"], "short": ["독수리"]}, "dialogue": {"context": "산 정상에서 독수리를 보며", "dialogue": [{"speaker": "A", "text": "저기 독수리가 날고 있어!", "romanization": "jeogi doksuri nalgo isseo!", "translation": "An eagle is flying over there!"}, {"speaker": "B", "text": "날개가 진짜 크다. 멋있다.", "romanization": "nalgaega jinjja keuda. meosittda.", "translation": "Its wings are really big. So cool."}]}}, "en": {"word": "eagle", "explanation": "A large bird of prey known as the king of the sky. It symbolizes power and freedom.", "examples": {"beginner": "The eagle flies in the sky.", "intermediate": "Eagles have very good eyesight.", "advanced": "Eagles spot their prey from high up and dive down rapidly.", "master": "In Korea, eagles are winter migratory birds that come from Mongolia and Siberia to overwinter."}, "variations": {"formal": ["An eagle is visible.", "I observed an eagle."], "casual": ["It''s an eagle!", "Eagles are so cool!"], "short": ["eagle"]}, "dialogue": {"context": "Watching an eagle from a mountain top", "dialogue": [{"speaker": "A", "text": "An eagle is flying over there!", "romanization": "", "translation": "저기 독수리가 날고 있어!"}, {"speaker": "B", "text": "Its wings are really big. So cool.", "romanization": "", "translation": "날개가 진짜 크다. 멋있다."}]}}}'),
  ('kkamagwi', '까마귀', 'kkamagwi', 'noun', 'animals', 'intermediate', 'uncommon', '["animals", "bird", "superstition", "korean-culture"]', '{"ko": {"word": "까마귀", "explanation": "한국에서 까마귀는 불길한 새로 여겨집니다. ''까마귀 날자 배 떨어진다''는 우연의 일치를 뜻하는 속담입니다.", "examples": {"beginner": "까마귀는 검은 새예요.", "intermediate": "한국에서 까마귀는 불길하다고 해요.", "advanced": "까마귀 날자 배 떨어진다는 속담이 있다.", "master": "흥미롭게도 일본에서는 까마귀가 신의 사자로 여겨지는 반면, 한국에서는 흉조로 인식된다."}, "variations": {"formal": ["까마귀가 울고 있습니다.", "까마귀를 보았습니다."], "casual": ["까마귀다!", "까마귀 울어!"], "short": ["까마귀"]}, "dialogue": {"context": "까마귀 울음소리를 듣고", "dialogue": [{"speaker": "A", "text": "까마귀가 울어. 좀 무섭다.", "romanization": "kkamagwiga ureo. jom museopda.", "translation": "The crow is cawing. It''s kind of scary."}, {"speaker": "B", "text": "미신이야. 까마귀도 그냥 새야.", "romanization": "misiniya. kkamagwido geunyang saeya.", "translation": "That''s superstition. Crows are just birds."}]}}, "en": {"word": "crow", "explanation": "In Korea, crows are considered unlucky birds. The proverb ''까마귀 날자 배 떨어진다'' (a pear falls just as the crow flies) refers to unfortunate coincidences.", "examples": {"beginner": "Crows are black birds.", "intermediate": "In Korea, crows are considered bad luck.", "advanced": "There''s a proverb about crows flying and pears falling, meaning unfortunate coincidence.", "master": "Interestingly, while crows are seen as messengers of gods in Japan, they are perceived as bad omens in Korea."}, "variations": {"formal": ["A crow is cawing.", "I saw a crow."], "casual": ["It''s a crow!", "The crow is cawing!"], "short": ["crow"]}, "dialogue": {"context": "Hearing a crow cawing", "dialogue": [{"speaker": "A", "text": "The crow is cawing. It''s kind of scary.", "romanization": "", "translation": "까마귀가 울어. 좀 무섭다."}, {"speaker": "B", "text": "That''s superstition. Crows are just birds.", "romanization": "", "translation": "미신이야. 까마귀도 그냥 새야."}]}}}'),
  ('chamsae', '참새', 'chamsae', 'noun', 'animals', 'intermediate', 'common', '["animals", "bird", "common", "idiom"]', '{"ko": {"word": "참새", "explanation": "한국에서 가장 흔한 새 중 하나입니다. ''참새가 방앗간을 그냥 지나칠까''라는 속담이 유명합니다.", "examples": {"beginner": "참새가 지저귀고 있어요.", "intermediate": "참새가 방앗간을 그냥 지나칠까요?", "advanced": "도시화로 참새의 개체 수가 크게 줄었다.", "master": "참새가 방앗간을 그냥 지나칠까라는 속담은 좋아하는 것을 그냥 지나칠 수 없다는 뜻이다."}, "variations": {"formal": ["참새가 있습니다.", "참새를 관찰했습니다."], "casual": ["참새다!", "참새 귀여워!"], "short": ["참새"]}, "dialogue": {"context": "빵집 앞을 지나가면서", "dialogue": [{"speaker": "A", "text": "이 빵집 그냥 지나갈 수 없어.", "romanization": "i ppangjip geunyang jinagal su eopseo.", "translation": "I can''t just walk past this bakery."}, {"speaker": "B", "text": "참새가 방앗간을 못 지나치지!", "romanization": "chamsaega bangatkaneul mot jinachiji!", "translation": "A sparrow can''t pass a mill! (You can''t resist temptation!)"}]}}, "en": {"word": "sparrow", "explanation": "One of the most common birds in Korea. The proverb ''Can a sparrow pass by a mill?'' means one cannot resist temptation.", "examples": {"beginner": "A sparrow is chirping.", "intermediate": "Can a sparrow just pass by a mill?", "advanced": "The sparrow population has greatly decreased due to urbanization.", "master": "The proverb about sparrows and mills means that one cannot simply pass by something they love."}, "variations": {"formal": ["There is a sparrow.", "I observed a sparrow."], "casual": ["It''s a sparrow!", "Sparrows are cute!"], "short": ["sparrow"]}, "dialogue": {"context": "Walking past a bakery", "dialogue": [{"speaker": "A", "text": "I can''t just walk past this bakery.", "romanization": "", "translation": "이 빵집 그냥 지나갈 수 없어."}, {"speaker": "B", "text": "A sparrow can''t pass a mill! (You can''t resist temptation!)", "romanization": "", "translation": "참새가 방앗간을 못 지나치지!"}]}}}'),
  ('bidulgi', '비둘기', 'bidulgi', 'noun', 'animals', 'beginner', 'common', '["animals", "bird", "urban", "peace"]', '{"ko": {"word": "비둘기", "explanation": "도시에서 흔히 볼 수 있는 새입니다. 평화의 상징으로도 알려져 있습니다.", "examples": {"beginner": "비둘기가 공원에 있어요.", "intermediate": "비둘기는 평화의 상징이에요.", "advanced": "서울 광화문 광장에는 비둘기가 많이 모여든다.", "master": "도시 비둘기의 과밀 문제는 위생과 문화재 보호 측면에서 사회적 논의 대상이 되고 있다."}, "variations": {"formal": ["비둘기가 있습니다.", "비둘기를 보았습니다."], "casual": ["비둘기다!", "비둘기 많다!"], "short": ["비둘기"]}, "dialogue": {"context": "공원에서 비둘기에게 먹이를 주며", "dialogue": [{"speaker": "A", "text": "비둘기한테 빵 줘도 돼?", "romanization": "bidulgihante ppang jwodo dwae?", "translation": "Can I give bread to the pigeons?"}, {"speaker": "B", "text": "안 돼, 빵은 비둘기 건강에 안 좋아.", "romanization": "an dwae, ppangeun bidulgi geongage an joa.", "translation": "No, bread isn''t good for pigeons'' health."}]}}, "en": {"word": "pigeon/dove", "explanation": "A bird commonly seen in cities. Also known as a symbol of peace.", "examples": {"beginner": "There are pigeons in the park.", "intermediate": "Pigeons are a symbol of peace.", "advanced": "Many pigeons gather at Gwanghwamun Square in Seoul.", "master": "The overpopulation of urban pigeons has become a social issue regarding hygiene and cultural heritage protection."}, "variations": {"formal": ["There is a pigeon.", "I saw a pigeon."], "casual": ["It''s a pigeon!", "So many pigeons!"], "short": ["pigeon"]}, "dialogue": {"context": "Feeding pigeons in the park", "dialogue": [{"speaker": "A", "text": "Can I give bread to the pigeons?", "romanization": "", "translation": "비둘기한테 빵 줘도 돼?"}, {"speaker": "B", "text": "No, bread isn''t good for pigeons'' health.", "romanization": "", "translation": "안 돼, 빵은 비둘기 건강에 안 좋아."}]}}}'),
  ('gaeguri', '개구리', 'gaeguri', 'noun', 'animals', 'beginner', 'common', '["animals", "amphibian", "nature", "idiom"]', '{"ko": {"word": "개구리", "explanation": "양서류 동물입니다. ''우물 안 개구리''는 시야가 좁은 사람을 뜻하는 유명한 관용구입니다.", "examples": {"beginner": "개구리가 뛰어요.", "intermediate": "우물 안 개구리처럼 생각하면 안 돼요.", "advanced": "올챙이 적 생각 못 하는 개구리라는 속담이 있다.", "master": "양서류 감소는 전 세계적인 환경 문제이며, 한국의 맹꽁이도 멸종 위기에 처해 있다."}, "variations": {"formal": ["개구리가 있습니다.", "개구리를 발견했습니다."], "casual": ["개구리다!", "개구리 잡자!"], "short": ["개구리"]}, "dialogue": {"context": "여행을 권유하면서", "dialogue": [{"speaker": "A", "text": "넌 우물 안 개구리야. 여행 좀 다녀.", "romanization": "neon umul an gaeguriya. yeohaeng jom danyeo.", "translation": "You''re a frog in a well. Travel a bit."}, {"speaker": "B", "text": "맞아, 세상을 더 넓게 봐야지.", "romanization": "maja, sesangeul deo neolge bwayaji.", "translation": "You''re right, I should see the world more broadly."}]}}, "en": {"word": "frog", "explanation": "An amphibian animal. ''A frog in a well'' is a famous idiom meaning a person with a narrow worldview.", "examples": {"beginner": "The frog is jumping.", "intermediate": "You shouldn''t think like a frog in a well.", "advanced": "There''s a proverb about a frog that forgets its tadpole days, meaning forgetting one''s humble origins.", "master": "Amphibian decline is a global environmental issue, and Korea''s narrow-mouthed toad is also endangered."}, "variations": {"formal": ["There is a frog.", "A frog was found."], "casual": ["It''s a frog!", "Let''s catch a frog!"], "short": ["frog"]}, "dialogue": {"context": "Encouraging someone to travel", "dialogue": [{"speaker": "A", "text": "You''re a frog in a well. Travel a bit.", "romanization": "", "translation": "넌 우물 안 개구리야. 여행 좀 다녀."}, {"speaker": "B", "text": "You''re right, I should see the world more broadly.", "romanization": "", "translation": "맞아, 세상을 더 넓게 봐야지."}]}}}'),
  ('geobuki', '거북이', 'geobuki', 'noun', 'animals', 'beginner', 'common', '["animals", "reptile", "mythology", "longevity"]', '{"ko": {"word": "거북이", "explanation": "장수의 상징입니다. 거북선은 이순신 장군의 유명한 전함이며, 십장생 중 하나입니다.", "examples": {"beginner": "거북이는 느려요.", "intermediate": "거북이는 오래 살 수 있는 동물이에요.", "advanced": "거북이는 한국 문화에서 장수와 지혜의 상징이다.", "master": "거북선은 임진왜란에서 활약한 세계 최초의 철갑선으로, 거북이의 등딱지 모양에서 이름을 따왔다."}, "variations": {"formal": ["거북이가 있습니다.", "거북이를 보았습니다."], "casual": ["거북이다!", "거북이 귀여워!"], "short": ["거북이"]}, "dialogue": {"context": "수족관에서 거북이를 보며", "dialogue": [{"speaker": "A", "text": "거북이 진짜 느리다.", "romanization": "geobuki jinjja neurida.", "translation": "Turtles are really slow."}, {"speaker": "B", "text": "느려도 오래 산다. 100년 넘게 사는 거북이도 있어.", "romanization": "neuryeodo orae sanda. baengnyeon neomge saneun geobukido isseo.", "translation": "Even though they''re slow, they live long. Some turtles live over 100 years."}]}}, "en": {"word": "turtle", "explanation": "A symbol of longevity. The Geobukseon (turtle ship) was Admiral Yi Sun-sin''s famous warship, and the turtle is one of the ten symbols of longevity in Korean culture.", "examples": {"beginner": "Turtles are slow.", "intermediate": "Turtles can live for a very long time.", "advanced": "Turtles symbolize longevity and wisdom in Korean culture.", "master": "The turtle ship, the world''s first ironclad warship used in the Imjin War, was named after the turtle''s shell shape."}, "variations": {"formal": ["There is a turtle.", "I saw a turtle."], "casual": ["It''s a turtle!", "Turtles are cute!"], "short": ["turtle"]}, "dialogue": {"context": "Watching turtles at the aquarium", "dialogue": [{"speaker": "A", "text": "Turtles are really slow.", "romanization": "", "translation": "거북이 진짜 느리다."}, {"speaker": "B", "text": "Even though they''re slow, they live long. Some turtles live over 100 years.", "romanization": "", "translation": "느려도 오래 산다. 100년 넘게 사는 거북이도 있어."}]}}}'),
  ('nabi', '나비', 'nabi', 'noun', 'animals', 'beginner', 'common', '["animals", "insect", "nature", "beautiful"]', '{"ko": {"word": "나비", "explanation": "아름다운 날개를 가진 곤충입니다. 한국에서 고양이 이름으로도 많이 쓰이며, 나비의 꿈은 장자의 호접몽을 연상시킵니다.", "examples": {"beginner": "나비가 꽃 위에 앉아 있어요.", "intermediate": "봄에 나비가 많이 날아다녀요.", "advanced": "나비 효과라는 개념은 작은 변화가 큰 결과를 만들 수 있다는 뜻이다.", "master": "장자의 호접몽은 나비가 된 꿈을 꾸고 현실과 꿈의 경계를 사유한 철학적 우화이다."}, "variations": {"formal": ["나비가 있습니다.", "나비를 관찰했습니다."], "casual": ["나비다!", "나비 예쁘다!"], "short": ["나비"]}, "dialogue": {"context": "봄날 공원에서", "dialogue": [{"speaker": "A", "text": "나비 좀 봐! 날개가 정말 예쁘다.", "romanization": "nabi jom bwa! nalgaega jeongmal yeppeuda.", "translation": "Look at the butterfly! Its wings are really pretty."}, {"speaker": "B", "text": "호랑나비네. 봄이 왔구나.", "romanization": "horangnabine. bomi watguna.", "translation": "It''s a swallowtail butterfly. Spring has come."}]}}, "en": {"word": "butterfly", "explanation": "An insect with beautiful wings. In Korea, ''Nabi'' is also a popular cat name. The butterfly dream evokes Zhuangzi''s philosophical parable.", "examples": {"beginner": "A butterfly is sitting on a flower.", "intermediate": "Many butterflies fly around in spring.", "advanced": "The butterfly effect concept means small changes can produce large results.", "master": "Zhuangzi''s butterfly dream is a philosophical fable contemplating the boundary between reality and dreams."}, "variations": {"formal": ["There is a butterfly.", "I observed a butterfly."], "casual": ["It''s a butterfly!", "The butterfly is pretty!"], "short": ["butterfly"]}, "dialogue": {"context": "At the park on a spring day", "dialogue": [{"speaker": "A", "text": "Look at the butterfly! Its wings are really pretty.", "romanization": "", "translation": "나비 좀 봐! 날개가 정말 예쁘다."}, {"speaker": "B", "text": "It''s a swallowtail butterfly. Spring has come.", "romanization": "", "translation": "호랑나비네. 봄이 왔구나."}]}}}'),
  ('beol', '벌', 'beol', 'noun', 'animals', 'beginner', 'common', '["animals", "insect", "nature", "danger"]', '{"ko": {"word": "벌", "explanation": "꿀을 만드는 곤충입니다. 쏘일 수 있어 주의가 필요합니다. ''벌''은 처벌이라는 동음이의어도 있습니다.", "examples": {"beginner": "벌이 꽃에 앉았어요.", "intermediate": "벌에 쏘이면 많이 아파요.", "advanced": "꿀벌은 생태계에서 수분 매개체로서 매우 중요한 역할을 한다.", "master": "전 세계적으로 꿀벌 개체 수 감소 현상이 식량 안보에 심각한 위협이 되고 있다."}, "variations": {"formal": ["벌이 있습니다.", "벌을 조심하십시오."], "casual": ["벌이다!", "벌 조심해!"], "short": ["벌"]}, "dialogue": {"context": "소풍 중 벌을 발견하고", "dialogue": [{"speaker": "A", "text": "벌이다! 움직이지 마!", "romanization": "beorida! umjigiji ma!", "translation": "It''s a bee! Don''t move!"}, {"speaker": "B", "text": "가만히 있으면 안 쏴. 진정해.", "romanization": "gamanhi isseumyeon an sswa. jinjeong hae.", "translation": "It won''t sting if you stay still. Calm down."}]}}, "en": {"word": "bee", "explanation": "An insect that makes honey. Caution is needed as they can sting. Note: ''벌'' is also a homonym meaning ''punishment'' in Korean.", "examples": {"beginner": "A bee landed on the flower.", "intermediate": "It hurts a lot if you get stung by a bee.", "advanced": "Honeybees play a crucial role in ecosystems as pollinators.", "master": "The worldwide decline in honeybee populations poses a serious threat to food security."}, "variations": {"formal": ["There is a bee.", "Please be careful of bees."], "casual": ["It''s a bee!", "Watch out for the bee!"], "short": ["bee"]}, "dialogue": {"context": "Spotting a bee during a picnic", "dialogue": [{"speaker": "A", "text": "It''s a bee! Don''t move!", "romanization": "", "translation": "벌이다! 움직이지 마!"}, {"speaker": "B", "text": "It won''t sting if you stay still. Calm down.", "romanization": "", "translation": "가만히 있으면 안 쏴. 진정해."}]}}}'),
  ('gaemi', '개미', 'gaemi', 'noun', 'animals', 'beginner', 'common', '["animals", "insect", "diligence", "idiom"]', '{"ko": {"word": "개미", "explanation": "부지런함의 상징인 곤충입니다. ''개미처럼 일하다''는 열심히 일한다는 뜻이며, 주식 투자에서 개인 투자자를 ''개미''라고 부릅니다.", "examples": {"beginner": "개미가 줄지어 걸어가요.", "intermediate": "그는 개미처럼 부지런해요.", "advanced": "주식 시장에서 개미 투자자들의 영향력이 커지고 있다.", "master": "개미의 사회적 구조는 분업과 협력의 관점에서 인간 사회와 비교 연구되고 있다."}, "variations": {"formal": ["개미가 있습니다.", "개미를 관찰했습니다."], "casual": ["개미다!", "개미 많다!"], "short": ["개미"]}, "dialogue": {"context": "열심히 일하는 동료에 대해", "dialogue": [{"speaker": "A", "text": "그 사람 진짜 개미처럼 일해.", "romanization": "geu saram jinjja gaemicheoreom ilhae.", "translation": "That person works like an ant."}, {"speaker": "B", "text": "맞아, 쉬는 걸 본 적이 없어.", "romanization": "maja, swineun geol bon jeogi eopseo.", "translation": "Right, I''ve never seen them take a break."}]}}, "en": {"word": "ant", "explanation": "An insect symbolizing diligence. ''Working like an ant'' means working very hard. In Korean stock markets, individual investors are called ''ants'' (개미).", "examples": {"beginner": "Ants are walking in a line.", "intermediate": "He is as diligent as an ant.", "advanced": "The influence of individual ''ant'' investors in the stock market is growing.", "master": "The social structure of ants is studied comparatively with human society in terms of division of labor and cooperation."}, "variations": {"formal": ["There is an ant.", "I observed the ants."], "casual": ["It''s an ant!", "So many ants!"], "short": ["ant"]}, "dialogue": {"context": "Talking about a hardworking colleague", "dialogue": [{"speaker": "A", "text": "That person works like an ant.", "romanization": "", "translation": "그 사람 진짜 개미처럼 일해."}, {"speaker": "B", "text": "Right, I''ve never seen them take a break.", "romanization": "", "translation": "맞아, 쉬는 걸 본 적이 없어."}]}}}'),
  ('dolgorae', '돌고래', 'dolgorae', 'noun', 'animals', 'intermediate', 'uncommon', '["animals", "marine", "intelligence", "cute"]', '{"ko": {"word": "돌고래", "explanation": "높은 지능으로 알려진 해양 포유류입니다. 제주도 근해에서 남방큰돌고래를 볼 수 있습니다.", "examples": {"beginner": "돌고래가 물 위로 뛰어올라요.", "intermediate": "돌고래는 매우 똑똑한 동물이에요.", "advanced": "제주도 앞바다에는 남방큰돌고래 약 120마리가 서식하고 있다.", "master": "한국에서는 수족관 돌고래를 야생 방류하는 프로젝트가 국제적 주목을 받았다."}, "variations": {"formal": ["돌고래가 있습니다.", "돌고래를 관찰했습니다."], "casual": ["돌고래다!", "돌고래 귀여워!"], "short": ["돌고래"]}, "dialogue": {"context": "제주도에서 돌고래를 보며", "dialogue": [{"speaker": "A", "text": "저기 돌고래다! 뛰어오르고 있어!", "romanization": "jeogi dolgoraeda! ttwieooreugo isseo!", "translation": "There are dolphins! They''re jumping!"}, {"speaker": "B", "text": "제주 바다에 야생 돌고래가 살고 있대.", "romanization": "jeju badae yasaeng dolgoraega salgo ittdae.", "translation": "They say wild dolphins live in the Jeju seas."}]}}, "en": {"word": "dolphin", "explanation": "A marine mammal known for its high intelligence. Indo-Pacific bottlenose dolphins can be seen near Jeju Island.", "examples": {"beginner": "The dolphin jumps out of the water.", "intermediate": "Dolphins are very intelligent animals.", "advanced": "About 120 Indo-Pacific bottlenose dolphins inhabit the waters off Jeju Island.", "master": "Korea''s project to release captive dolphins back into the wild gained international attention."}, "variations": {"formal": ["There is a dolphin.", "I observed dolphins."], "casual": ["It''s a dolphin!", "Dolphins are cute!"], "short": ["dolphin"]}, "dialogue": {"context": "Watching dolphins in Jeju", "dialogue": [{"speaker": "A", "text": "There are dolphins! They''re jumping!", "romanization": "", "translation": "저기 돌고래다! 뛰어오르고 있어!"}, {"speaker": "B", "text": "They say wild dolphins live in the Jeju seas.", "romanization": "", "translation": "제주 바다에 야생 돌고래가 살고 있대."}]}}}'),
  ('sangeo', '상어', 'sangeo', 'noun', 'animals', 'intermediate', 'uncommon', '["animals", "marine", "danger", "ocean"]', '{"ko": {"word": "상어", "explanation": "바다의 최상위 포식자입니다. ''아기 상어'' 노래가 전 세계적으로 유명합니다.", "examples": {"beginner": "상어는 이빨이 날카로워요.", "intermediate": "아기 상어 뚜루루뚜루 노래 알아요?", "advanced": "상어는 바다 생태계에서 최상위 포식자로서 중요한 역할을 한다.", "master": "상어 지느러미 채취를 위한 핀닝은 국제적으로 금지 움직임이 확산되고 있다."}, "variations": {"formal": ["상어가 있습니다.", "상어를 발견했습니다."], "casual": ["상어다!", "상어 무서워!"], "short": ["상어"]}, "dialogue": {"context": "수족관에서 상어를 보며", "dialogue": [{"speaker": "A", "text": "상어 진짜 무섭다. 이빨 좀 봐.", "romanization": "sangeo jinjja museopda. ippal jom bwa.", "translation": "Sharks are really scary. Look at those teeth."}, {"speaker": "B", "text": "근데 상어가 사람을 공격하는 건 드물대.", "romanization": "geunde sangeoga sarameul gonggyeok haneun geon deumuldae.", "translation": "But shark attacks on humans are actually rare."}]}}, "en": {"word": "shark", "explanation": "An apex predator of the ocean. The Korean children''s song ''Baby Shark'' (아기 상어) became a worldwide viral hit.", "examples": {"beginner": "Sharks have sharp teeth.", "intermediate": "Do you know the Baby Shark song?", "advanced": "Sharks play an important role as apex predators in marine ecosystems.", "master": "There is a growing international movement to ban shark finning for fin harvesting."}, "variations": {"formal": ["There is a shark.", "A shark was spotted."], "casual": ["It''s a shark!", "Sharks are scary!"], "short": ["shark"]}, "dialogue": {"context": "Watching sharks at the aquarium", "dialogue": [{"speaker": "A", "text": "Sharks are really scary. Look at those teeth.", "romanization": "", "translation": "상어 진짜 무섭다. 이빨 좀 봐."}, {"speaker": "B", "text": "But shark attacks on humans are actually rare.", "romanization": "", "translation": "근데 상어가 사람을 공격하는 건 드물대."}]}}}'),
  ('gorae', '고래', 'gorae', 'noun', 'animals', 'intermediate', 'uncommon', '["animals", "marine", "large", "ocean"]', '{"ko": {"word": "고래", "explanation": "지구에서 가장 큰 동물입니다. 울산 반구대 암각화에는 고래 그림이 있어, 한국의 포경 역사를 보여줍니다.", "examples": {"beginner": "고래는 바다에서 살아요.", "intermediate": "고래는 지구에서 가장 큰 동물이에요.", "advanced": "울산 반구대 암각화에는 선사시대 고래 사냥 장면이 새겨져 있다.", "master": "고래싸움에 새우 등 터진다는 속담은 강대국 사이에서 약소국이 피해를 입는 상황을 비유한다."}, "variations": {"formal": ["고래가 있습니다.", "고래를 관찰했습니다."], "casual": ["고래다!", "고래 봤어?"], "short": ["고래"]}, "dialogue": {"context": "고래 관광을 하면서", "dialogue": [{"speaker": "A", "text": "고래가 물을 뿜고 있어!", "romanization": "goraega mureul ppumgo isseo!", "translation": "The whale is spouting water!"}, {"speaker": "B", "text": "대왕고래래! 지구에서 제일 큰 동물이야.", "romanization": "daewanggoraere! jigueseo jeil keun dongmuriya.", "translation": "It''s a blue whale! The largest animal on Earth."}]}}, "en": {"word": "whale", "explanation": "The largest animal on Earth. The Bangudae Petroglyphs in Ulsan contain whale carvings, showing Korea''s whaling history.", "examples": {"beginner": "Whales live in the ocean.", "intermediate": "Whales are the largest animals on Earth.", "advanced": "The Bangudae Petroglyphs in Ulsan contain prehistoric whale hunting scenes.", "master": "The Korean proverb ''When whales fight, the shrimp''s back breaks'' describes how small nations suffer between great powers."}, "variations": {"formal": ["There is a whale.", "I observed a whale."], "casual": ["It''s a whale!", "Did you see the whale?"], "short": ["whale"]}, "dialogue": {"context": "On a whale watching tour", "dialogue": [{"speaker": "A", "text": "The whale is spouting water!", "romanization": "", "translation": "고래가 물을 뿜고 있어!"}, {"speaker": "B", "text": "It''s a blue whale! The largest animal on Earth.", "romanization": "", "translation": "대왕고래래! 지구에서 제일 큰 동물이야."}]}}}'),
  ('ori', '오리', 'ori', 'noun', 'animals', 'beginner', 'common', '["animals", "bird", "farm", "food"]', '{"ko": {"word": "오리", "explanation": "농장이나 공원에서 볼 수 있는 새입니다. 한국에서 오리고기는 보양식으로 인기가 있습니다.", "examples": {"beginner": "오리가 물 위에 떠 있어요.", "intermediate": "오리 훈제 먹어 본 적 있어요?", "advanced": "한국에서 오리고기는 삼겹살과 함께 인기 있는 고기 요리이다.", "master": "오리농법은 논에 오리를 풀어 해충을 잡게 하는 친환경 농법으로 한국에서 활용되고 있다."}, "variations": {"formal": ["오리가 있습니다.", "오리를 보았습니다."], "casual": ["오리다!", "오리 귀여워!"], "short": ["오리"]}, "dialogue": {"context": "저녁 메뉴를 고르면서", "dialogue": [{"speaker": "A", "text": "오늘 저녁 오리고기 어때?", "romanization": "oneul jeonyeok origogi eottae?", "translation": "How about duck for dinner tonight?"}, {"speaker": "B", "text": "좋아! 오리 훈제 먹으러 가자.", "romanization": "joa! ori hunje meogeureo gaja.", "translation": "Great! Let''s go eat smoked duck."}]}}, "en": {"word": "duck", "explanation": "A bird found on farms and in parks. In Korea, duck meat is popular as a nourishing food.", "examples": {"beginner": "The duck is floating on the water.", "intermediate": "Have you ever tried smoked duck?", "advanced": "In Korea, duck meat is a popular dish alongside samgyeopsal (pork belly).", "master": "Duck farming in rice paddies is an eco-friendly agricultural method used in Korea where ducks eat pests."}, "variations": {"formal": ["There is a duck.", "I saw a duck."], "casual": ["It''s a duck!", "Ducks are cute!"], "short": ["duck"]}, "dialogue": {"context": "Choosing dinner", "dialogue": [{"speaker": "A", "text": "How about duck for dinner tonight?", "romanization": "", "translation": "오늘 저녁 오리고기 어때?"}, {"speaker": "B", "text": "Great! Let''s go eat smoked duck.", "romanization": "", "translation": "좋아! 오리 훈제 먹으러 가자."}]}}}'),
  ('penggwin', '펭귄', 'penggwin', 'noun', 'animals', 'beginner', '3', '["animals", "bird", "cold", "cute", "loanword"]', '{"ko": "펭귄", "en": "penguin"}'),
  ('girin', '기린', 'girin', 'noun', 'animals', 'beginner', '3', '["animals", "wild", "zoo", "tall"]', '{"ko": "기린", "en": "giraffe"}'),
  ('hama', '하마', 'hama', 'noun', 'animals', 'intermediate', '2', '["animals", "wild", "zoo", "large"]', '{"ko": "하마", "en": "hippo"}'),
  ('ageo', '악어', 'ageo', 'noun', 'animals', 'intermediate', '2', '["animals", "reptile", "danger", "zoo"]', '{"ko": "악어", "en": "crocodile"}'),
  ('daramjwi', '다람쥐', 'daramjwi', 'noun', 'animals', 'intermediate', '3', '["animals", "wild", "forest", "cute"]', '{"ko": "다람쥐", "en": "squirrel"}'),
  ('dudeoji', '두더지', 'dudeoji', 'noun', 'animals', 'intermediate', '2', '["animals", "wild", "underground", "rare"]', '{"ko": "두더지", "en": "mole"}'),
  ('bakjwi', '박쥐', 'bakjwi', 'noun', 'animals', 'intermediate', '2', '["animals", "wild", "nocturnal", "fear"]', '{"ko": "박쥐", "en": "bat"}'),
  ('mae', '매', 'mae', 'noun', 'animals', 'intermediate', '2', '["animals", "bird", "wild", "hunting"]', '{"ko": "매", "en": "hawk"}'),
  ('bueonggi', '부엉이', 'bueonggi', 'noun', 'animals', 'intermediate', '2', '["animals", "bird", "nocturnal", "wisdom"]', '{"ko": "부엉이", "en": "owl"}'),
  ('jamjari', '잠자리', 'jamjari', 'noun', 'animals', 'intermediate', '2', '["animals", "insect", "autumn", "nature"]', '{"ko": "잠자리", "en": "dragonfly"}'),
  ('mudangbeolle', '무당벌레', 'mudangbeolle', 'noun', 'animals', 'advanced', '1', '["animals", "insect", "luck", "cute"]', '{"ko": "무당벌레", "en": "ladybug"}'),
  ('jireonggi', '지렁이', 'jireonggi', 'noun', 'animals', 'intermediate', '2', '["animals", "insect", "soil", "nature"]', '{"ko": "지렁이", "en": "earthworm"}'),
  ('gangaji', '강아지', 'gangaji', 'noun', 'animals', 'beginner', '5', '["animals", "pets", "cute", "young"]', '{"ko": "강아지", "en": "puppy"}'),
  ('saekkigoyangi', '새끼고양이', 'saekkigoyangi', 'noun', 'animals', 'intermediate', '3', '["animals", "pets", "cute", "young"]', '{"ko": "새끼고양이", "en": "kitten"}'),
  ('haemseuteo', '햄스터', 'haemseuteo', 'noun', 'animals', 'beginner', '3', '["animals", "pets", "cute", "loanword"]', '{"ko": "햄스터", "en": "hamster"}'),
  ('aengmusae', '앵무새', 'aengmusae', 'noun', 'animals', 'intermediate', '2', '["animals", "bird", "pets", "talking"]', '{"ko": "앵무새", "en": "parrot"}');

-- nature (60 entries)
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES
  ('san', '산', 'san', 'noun', 'nature', 'beginner', 'common', '["nature", "hiking", "korean-culture", "geography", "exercise"]', '{"ko": {"word": "산", "explanation": "땅이 높이 솟아오른 지형입니다. 한국은 국토의 약 70%가 산지이며, 등산은 한국인이 가장 좋아하는 여가 활동 중 하나입니다.", "examples": {"beginner": "산에 가요.", "intermediate": "주말에 산에 등산하러 갔어요.", "advanced": "한국은 국토의 70%가 산지이다.", "master": "산세가 험준하여 예로부터 자연 방어벽 역할을 했다."}, "variations": {"formal": ["산에 올라가겠습니다.", "등산을 합니다."], "casual": ["산 가자.", "산 타자."], "short": ["산"]}, "dialogue": {"context": "주말 계획을 세우며", "dialogue": [{"speaker": "A", "text": "주말에 뭐 할까?", "romanization": "jumale mwo halkka?", "translation": "What should we do this weekend?"}, {"speaker": "B", "text": "북한산 가자! 단풍이 예쁠 거야.", "romanization": "bukhansan gaja! danpungi yeppeul geoya.", "translation": "Let''s go to Bukhansan! The fall leaves will be beautiful."}]}}, "en": {"word": "mountain", "explanation": "An elevated landform rising above the surrounding area. About 70% of Korea''s territory is mountainous, and hiking is one of the most popular leisure activities among Koreans.", "examples": {"beginner": "Let''s go to the mountain.", "intermediate": "I went hiking in the mountains on the weekend.", "advanced": "About 70% of Korea''s land is mountainous.", "master": "The rugged mountain terrain has served as a natural defense barrier since ancient times."}, "variations": {"formal": ["I will climb the mountain.", "I go hiking."], "casual": ["Let''s go hiking.", "Let''s hit the mountain."], "short": ["mountain"]}, "dialogue": {"context": "Making weekend plans", "dialogue": [{"speaker": "A", "text": "What should we do this weekend?", "romanization": "", "translation": "주말에 뭐 할까?"}, {"speaker": "B", "text": "Let''s go to Bukhansan! The fall leaves will be beautiful.", "romanization": "", "translation": "북한산 가자! 단풍이 예쁠 거야."}]}}}'),
  ('bada', '바다', 'bada', 'noun', 'nature', 'beginner', 'common', '["nature", "travel", "summer", "geography"]', '{"ko": {"word": "바다", "explanation": "넓은 짠물이 있는 곳입니다. 한국은 삼면이 바다(서해, 남해, 동해)로 둘러싸인 반도 국가입니다.", "examples": {"beginner": "바다가 예뻐요.", "intermediate": "여름에 바다에 수영하러 갔어요.", "advanced": "동해의 일출은 한국에서 가장 아름다운 풍경 중 하나이다.", "master": "삼면이 바다로 둘러싸인 한반도는 해양 자원이 풍부하다."}, "variations": {"formal": ["바다에 갔습니다.", "해변을 방문했습니다."], "casual": ["바다 가자!", "바다 좋다."], "short": ["바다"]}, "dialogue": {"context": "여름휴가 계획", "dialogue": [{"speaker": "A", "text": "이번 여름에 바다 갈까?", "romanization": "ibeon yeoreume bada galkka?", "translation": "Shall we go to the beach this summer?"}, {"speaker": "B", "text": "좋아! 제주도 바다가 제일 예뻐.", "romanization": "joa! jejudo badaga jeil yeppeo.", "translation": "Yes! Jeju Island has the prettiest sea."}]}}, "en": {"word": "sea / ocean", "explanation": "A large body of saltwater. Korea is a peninsula surrounded by sea on three sides: the West Sea (서해), the South Sea (남해), and the East Sea (동해).", "examples": {"beginner": "The sea is beautiful.", "intermediate": "I went swimming in the sea in summer.", "advanced": "The sunrise over the East Sea is one of Korea''s most beautiful sights.", "master": "The Korean Peninsula, surrounded by sea on three sides, is rich in marine resources."}, "variations": {"formal": ["I went to the sea.", "I visited the beach."], "casual": ["Let''s go to the beach!", "Love the sea."], "short": ["sea"]}, "dialogue": {"context": "Planning summer vacation", "dialogue": [{"speaker": "A", "text": "Shall we go to the beach this summer?", "romanization": "", "translation": "이번 여름에 바다 갈까?"}, {"speaker": "B", "text": "Yes! Jeju Island has the prettiest sea.", "romanization": "", "translation": "좋아! 제주도 바다가 제일 예뻐."}]}}}'),
  ('gang', '강', 'gang', 'noun', 'nature', 'beginner', 'common', '["nature", "geography", "water", "city"]', '{"ko": {"word": "강", "explanation": "물이 흐르는 큰 수로입니다. 서울의 한강은 한국에서 가장 유명한 강으로, 시민들의 휴식 공간입니다.", "examples": {"beginner": "강이 넓어요.", "intermediate": "한강에서 자전거를 타요.", "advanced": "한강은 서울 시민의 대표적인 휴식 공간이다.", "master": "한강의 기적이라는 표현은 한국의 경제 성장을 상징한다."}, "variations": {"formal": ["강에 갔습니다.", "한강을 방문했습니다."], "casual": ["한강 가자.", "강변 산책하자."], "short": ["강"]}, "dialogue": {"context": "저녁에 한강에서", "dialogue": [{"speaker": "A", "text": "한강에서 치킨 먹을까?", "romanization": "hangangeseo chikin meogeulkka?", "translation": "Shall we eat chicken by the Han River?"}, {"speaker": "B", "text": "좋지! 배달 시키자.", "romanization": "joji! baedal sikija.", "translation": "Sounds great! Let''s order delivery."}]}}, "en": {"word": "river", "explanation": "A large natural waterway. The Han River (한강) in Seoul is Korea''s most famous river and a beloved recreation area. ''The Miracle on the Han River'' refers to Korea''s rapid economic growth.", "examples": {"beginner": "The river is wide.", "intermediate": "I ride a bike along the Han River.", "advanced": "The Han River is Seoul citizens'' most iconic recreation space.", "master": "The phrase ''Miracle on the Han River'' symbolizes Korea''s economic growth."}, "variations": {"formal": ["I went to the river.", "I visited the Han River."], "casual": ["Let''s go to the Han River.", "Let''s walk by the river."], "short": ["river"]}, "dialogue": {"context": "By the Han River in the evening", "dialogue": [{"speaker": "A", "text": "Shall we eat chicken by the Han River?", "romanization": "", "translation": "한강에서 치킨 먹을까?"}, {"speaker": "B", "text": "Sounds great! Let''s order delivery.", "romanization": "", "translation": "좋지! 배달 시키자."}]}}}'),
  ('namu', '나무', 'namu', 'noun', 'nature', 'beginner', 'common', '["nature", "plant", "environment", "daily-life"]', '{"ko": {"word": "나무", "explanation": "줄기와 가지가 있는 큰 식물입니다. ''나무''는 재료로서의 목재(wood)도 뜻합니다. 한국에는 은행나무, 소나무 등이 흔합니다.", "examples": {"beginner": "나무가 커요.", "intermediate": "가을에 나무 잎이 빨갛게 변해요.", "advanced": "소나무는 한국인이 가장 사랑하는 나무이다.", "master": "나무를 심는 것은 미래 세대를 위한 투자이다."}, "variations": {"formal": ["나무가 자라고 있습니다.", "수목을 관찰합니다."], "casual": ["나무 크다.", "저 나무 봐."], "short": ["나무"]}, "dialogue": {"context": "숲속 산책", "dialogue": [{"speaker": "A", "text": "이 나무 엄청 오래된 것 같아.", "romanization": "i namu eomcheong oraedoen geot gata.", "translation": "This tree seems really old."}, {"speaker": "B", "text": "수백 년은 됐을 거야.", "romanization": "subaek nyeoneun dwaesseul geoya.", "translation": "It''s probably hundreds of years old."}]}}, "en": {"word": "tree", "explanation": "A large plant with a trunk and branches. ''나무'' also refers to wood as a material. Pine trees (소나무) and ginkgo trees (은행나무) are very common in Korea.", "examples": {"beginner": "The tree is big.", "intermediate": "In autumn, tree leaves turn red.", "advanced": "The pine tree is the most beloved tree among Koreans.", "master": "Planting trees is an investment for future generations."}, "variations": {"formal": ["The tree is growing.", "We observe the trees."], "casual": ["Big tree.", "Look at that tree."], "short": ["tree"]}, "dialogue": {"context": "Walking through the forest", "dialogue": [{"speaker": "A", "text": "This tree seems really old.", "romanization": "", "translation": "이 나무 엄청 오래된 것 같아."}, {"speaker": "B", "text": "It''s probably hundreds of years old.", "romanization": "", "translation": "수백 년은 됐을 거야."}]}}}'),
  ('kkot', '꽃', 'kkot', 'noun', 'nature', 'beginner', 'common', '["nature", "plant", "spring", "beautiful", "gift"]', '{"ko": {"word": "꽃", "explanation": "식물의 생식 기관으로, 아름다운 색과 향기가 있습니다. 한국의 국화는 무궁화입니다. ''꽃''의 받침 ㅌ은 뒤에 모음이 오면 연음됩니다: 꽃이 → [꼬치].", "examples": {"beginner": "꽃이 예뻐요.", "intermediate": "봄에 벚꽃이 피어요.", "advanced": "진달래는 한국의 대표적인 봄꽃이다.", "master": "꽃이 피고 지는 것은 자연의 순환을 상징한다."}, "variations": {"formal": ["꽃이 아름답습니다.", "꽃을 감상합니다."], "casual": ["꽃 예쁘다!", "꽃 봐!"], "short": ["꽃"]}, "dialogue": {"context": "봄에 벚꽃 구경하면서", "dialogue": [{"speaker": "A", "text": "벚꽃이 진짜 예쁘다!", "romanization": "beotkkochi jinjja yeppeuda!", "translation": "The cherry blossoms are really pretty!"}, {"speaker": "B", "text": "사진 찍자!", "romanization": "sajin jjikja!", "translation": "Let''s take a photo!"}]}}, "en": {"word": "flower", "explanation": "The reproductive part of a plant, known for its beauty and fragrance. Korea''s national flower is the 무궁화 (mugunghwa / Rose of Sharon). The final consonant ㅌ undergoes liaison: 꽃이 → [꼬치].", "examples": {"beginner": "The flowers are pretty.", "intermediate": "Cherry blossoms bloom in spring.", "advanced": "Azaleas are one of Korea''s most representative spring flowers.", "master": "The blooming and wilting of flowers symbolizes the cycle of nature."}, "variations": {"formal": ["The flowers are beautiful.", "I appreciate the flowers."], "casual": ["Pretty flowers!", "Look at the flowers!"], "short": ["flower"]}, "dialogue": {"context": "Viewing cherry blossoms in spring", "dialogue": [{"speaker": "A", "text": "The cherry blossoms are really pretty!", "romanization": "", "translation": "벚꽃이 진짜 예쁘다!"}, {"speaker": "B", "text": "Let''s take a photo!", "romanization": "", "translation": "사진 찍자!"}]}}}'),
  ('haneul', '하늘', 'haneul', 'noun', 'nature', 'beginner', 'common', '["nature", "sky", "poetic", "daily-life"]', '{"ko": {"word": "하늘", "explanation": "머리 위에 보이는 공간입니다. 한국어에서 ''하늘''은 하느님(God)의 어원이기도 하며, ''하늘이 무너져도 솟아날 구멍이 있다''는 유명한 속담이 있습니다.", "examples": {"beginner": "하늘이 파래요.", "intermediate": "오늘 하늘이 정말 맑아요.", "advanced": "노을이 지는 하늘이 아름답다.", "master": "하늘이 무너져도 솟아날 구멍이 있다."}, "variations": {"formal": ["하늘이 맑습니다.", "하늘을 바라봅니다."], "casual": ["하늘 예쁘다.", "하늘 봐!"], "short": ["하늘"]}, "dialogue": {"context": "저녁 산책 중", "dialogue": [{"speaker": "A", "text": "와, 오늘 하늘 진짜 예쁘다.", "romanization": "wa, oneul haneul jinjja yeppeuda.", "translation": "Wow, the sky is really beautiful today."}, {"speaker": "B", "text": "노을이 장관이다.", "romanization": "noeuri janggwanida.", "translation": "The sunset is spectacular."}]}}, "en": {"word": "sky", "explanation": "The expanse of air above the earth. In Korean, ''하늘'' is also the root of ''하느님'' (God). There''s a famous proverb: ''Even if the sky falls, there''s a hole to crawl out of'' — meaning there''s always a way out.", "examples": {"beginner": "The sky is blue.", "intermediate": "The sky is really clear today.", "advanced": "The sunset sky is beautiful.", "master": "Even if the sky falls, there''s a hole to crawl out of."}, "variations": {"formal": ["The sky is clear.", "I gaze at the sky."], "casual": ["Pretty sky.", "Look at the sky!"], "short": ["sky"]}, "dialogue": {"context": "During an evening walk", "dialogue": [{"speaker": "A", "text": "Wow, the sky is really beautiful today.", "romanization": "", "translation": "와, 오늘 하늘 진짜 예쁘다."}, {"speaker": "B", "text": "The sunset is spectacular.", "romanization": "", "translation": "노을이 장관이다."}]}}}'),
  ('sup', '숲', 'sup', 'noun', 'nature', 'beginner', 'common', '["nature", "plant", "hiking", "environment"]', '{"ko": {"word": "숲", "explanation": "나무가 빽빽하게 모여 있는 곳입니다. 한국에는 전국에 국립공원과 자연휴양림이 잘 조성되어 있어 숲 체험이 가능합니다. ''숲''은 받침 ㅂ이 있어 [숩]으로 발음됩니다.", "examples": {"beginner": "숲이 좋아요.", "intermediate": "숲에서 산책하면 기분이 좋아요.", "advanced": "산림욕은 숲에서 건강을 지키는 한국식 힐링 방법이다.", "master": "도시화로 인해 숲의 면적이 줄어드는 것은 심각한 환경 문제이다."}, "variations": {"formal": ["숲을 걷겠습니다.", "산림을 탐방합니다."], "casual": ["숲 가자.", "숲속 걷자."], "short": ["숲"]}, "dialogue": {"context": "주말 나들이 계획", "dialogue": [{"speaker": "A", "text": "오늘 숲에서 산책할까?", "romanization": "oneul supeseo sanchaekalkka?", "translation": "Shall we take a walk in the forest today?"}, {"speaker": "B", "text": "좋아! 공기도 좋고 힐링되겠다.", "romanization": "joa! gonggido joko hillingdoegetda.", "translation": "Great! The air will be nice and it''ll be healing."}]}}, "en": {"word": "forest", "explanation": "A large area densely covered with trees. Korea has many national parks and recreational forests across the country. Forest bathing (산림욕) is a popular Korean wellness practice. ''숲'' is pronounced [숩] due to the final consonant.", "examples": {"beginner": "I like the forest.", "intermediate": "Walking in the forest makes me feel good.", "advanced": "Forest bathing is a Korean healing method for maintaining health in the woods.", "master": "The reduction of forest area due to urbanization is a serious environmental issue."}, "variations": {"formal": ["I will walk through the forest.", "We explore the woods."], "casual": ["Let''s go to the forest.", "Let''s walk in the woods."], "short": ["forest"]}, "dialogue": {"context": "Planning a weekend outing", "dialogue": [{"speaker": "A", "text": "Shall we take a walk in the forest today?", "romanization": "", "translation": "오늘 숲에서 산책할까?"}, {"speaker": "B", "text": "Great! The air will be nice and it''ll be healing.", "romanization": "", "translation": "좋아! 공기도 좋고 힐링되겠다."}]}}}'),
  ('hosu', '호수', 'hosu', 'noun', 'nature', 'intermediate', 'common', '["nature", "water", "travel", "scenery"]', '{"ko": {"word": "호수", "explanation": "땅으로 둘러싸인 큰 물웅덩이입니다. 한국의 춘천 의암호, 충주호 등이 유명하며, 호수 주변에서 카페와 산책을 즐기는 문화가 있습니다.", "examples": {"beginner": "호수가 아름다워요.", "intermediate": "호수 옆에서 커피를 마셨어요.", "advanced": "춘천의 의암호는 드라마 촬영지로 유명하다.", "master": "인공 호수의 건설은 수자원 관리와 생태계 보전 사이의 균형을 요구한다."}, "variations": {"formal": ["호수를 방문했습니다.", "호숫가를 산책합니다."], "casual": ["호수 가자.", "호수 예쁘다."], "short": ["호수"]}, "dialogue": {"context": "춘천 여행 중", "dialogue": [{"speaker": "A", "text": "이 호수 정말 예쁘다!", "romanization": "i hosu jeongmal yeppeuda!", "translation": "This lake is really pretty!"}, {"speaker": "B", "text": "여기서 카페 갈까? 호수 뷰 좋대.", "romanization": "yeogiseo kape galkka? hosu byu jotdae.", "translation": "Shall we go to a cafe here? They say the lake view is great."}]}}, "en": {"word": "lake", "explanation": "A large body of water surrounded by land. Famous Korean lakes include Uiamho in Chuncheon and Chungju Lake. Koreans enjoy visiting lakeside cafes and taking walks around lakes.", "examples": {"beginner": "The lake is beautiful.", "intermediate": "I drank coffee by the lake.", "advanced": "Uiamho Lake in Chuncheon is famous as a drama filming location.", "master": "The construction of artificial lakes requires balancing water resource management with ecosystem preservation."}, "variations": {"formal": ["I visited the lake.", "I walk along the lakeshore."], "casual": ["Let''s go to the lake.", "Pretty lake."], "short": ["lake"]}, "dialogue": {"context": "Traveling in Chuncheon", "dialogue": [{"speaker": "A", "text": "This lake is really pretty!", "romanization": "", "translation": "이 호수 정말 예쁘다!"}, {"speaker": "B", "text": "Shall we go to a cafe here? They say the lake view is great.", "romanization": "", "translation": "여기서 카페 갈까? 호수 뷰 좋대."}]}}}'),
  ('pokpo', '폭포', 'pokpo', 'noun', 'nature', 'intermediate', 'uncommon', '["nature", "water", "travel", "scenery"]', '{"ko": {"word": "폭포", "explanation": "물이 높은 곳에서 떨어지는 곳입니다. 한국에는 제주도의 천지연폭포, 정방폭포 등이 유명합니다. ''폭포''는 한자어(瀑布)입니다.", "examples": {"beginner": "폭포가 멋있어요.", "intermediate": "제주도에서 폭포를 봤어요.", "advanced": "천지연폭포는 제주도의 대표적인 관광 명소이다.", "master": "폭포의 침식 작용은 오랜 세월에 걸쳐 지형을 변화시킨다."}, "variations": {"formal": ["폭포를 관람했습니다.", "폭포를 방문합니다."], "casual": ["폭포 보러 가자.", "폭포 대박이다."], "short": ["폭포"]}, "dialogue": {"context": "제주도 관광 중", "dialogue": [{"speaker": "A", "text": "천지연폭포 가 봤어?", "romanization": "cheonjiyeonpokpo ga bwasseo?", "translation": "Have you been to Cheonjiyeon Waterfall?"}, {"speaker": "B", "text": "아직! 물줄기가 엄청 크다던데.", "romanization": "ajik! muljulgiga eomcheong keudadeonde.", "translation": "Not yet! I heard the waterfall is huge."}]}}, "en": {"word": "waterfall", "explanation": "A place where water falls from a height. Famous Korean waterfalls include Cheonjiyeon and Jeongbang Falls on Jeju Island. ''폭포'' comes from Chinese characters (瀑布).", "examples": {"beginner": "The waterfall is amazing.", "intermediate": "I saw a waterfall on Jeju Island.", "advanced": "Cheonjiyeon Waterfall is one of Jeju''s most iconic tourist spots.", "master": "The erosive action of waterfalls reshapes the landscape over long periods of time."}, "variations": {"formal": ["I visited the waterfall.", "We viewed the waterfall."], "casual": ["Let''s go see the waterfall.", "The waterfall is insane."], "short": ["waterfall"]}, "dialogue": {"context": "Sightseeing on Jeju Island", "dialogue": [{"speaker": "A", "text": "Have you been to Cheonjiyeon Waterfall?", "romanization": "", "translation": "천지연폭포 가 봤어?"}, {"speaker": "B", "text": "Not yet! I heard the waterfall is huge.", "romanization": "", "translation": "아직! 물줄기가 엄청 크다던데."}]}}}'),
  ('seom', '섬', 'seom', 'noun', 'nature', 'beginner', 'common', '["nature", "geography", "travel", "ocean"]', '{"ko": {"word": "섬", "explanation": "물로 둘러싸인 땅입니다. 한국에는 약 3,300개 이상의 섬이 있으며, 제주도가 가장 큰 섬입니다. 독도는 한국의 영토 주권을 상징하는 섬입니다.", "examples": {"beginner": "섬에 가요.", "intermediate": "제주도는 한국에서 가장 큰 섬이에요.", "advanced": "한국에는 약 3,300개의 섬이 있다.", "master": "도서(島嶼) 지역의 생태계는 본토와 격리되어 독자적으로 발전한다."}, "variations": {"formal": ["섬을 방문했습니다.", "섬으로 여행합니다."], "casual": ["섬 가자.", "섬 여행 어때?"], "short": ["섬"]}, "dialogue": {"context": "여행지 추천", "dialogue": [{"speaker": "A", "text": "이번 휴가에 섬 여행 어때?", "romanization": "ibeon hyugae seom yeohaeng eottae?", "translation": "How about an island trip this vacation?"}, {"speaker": "B", "text": "좋아! 울릉도 가 보고 싶었어.", "romanization": "joa! ulleungdo ga bogo sipeosseo.", "translation": "Great! I''ve been wanting to visit Ulleungdo."}]}}, "en": {"word": "island", "explanation": "A piece of land surrounded by water. Korea has over 3,300 islands, with Jeju being the largest. Dokdo is an island symbolizing Korea''s territorial sovereignty.", "examples": {"beginner": "Let''s go to the island.", "intermediate": "Jeju Island is the largest island in Korea.", "advanced": "Korea has approximately 3,300 islands.", "master": "Island ecosystems develop independently due to isolation from the mainland."}, "variations": {"formal": ["I visited the island.", "I travel to the island."], "casual": ["Let''s go to an island.", "How about an island trip?"], "short": ["island"]}, "dialogue": {"context": "Recommending travel destinations", "dialogue": [{"speaker": "A", "text": "How about an island trip this vacation?", "romanization": "", "translation": "이번 휴가에 섬 여행 어때?"}, {"speaker": "B", "text": "Great! I''ve been wanting to visit Ulleungdo.", "romanization": "", "translation": "좋아! 울릉도 가 보고 싶었어."}]}}}'),
  ('gyegok', '계곡', 'gyegok', 'noun', 'nature', 'intermediate', 'common', '["nature", "hiking", "summer", "water"]', '{"ko": {"word": "계곡", "explanation": "산과 산 사이에 물이 흐르는 좁고 깊은 골짜기입니다. 한국에서는 여름에 계곡에서 물놀이하는 것이 인기 있는 피서 방법입니다.", "examples": {"beginner": "계곡 물이 차가워요.", "intermediate": "여름에 계곡에서 물놀이했어요.", "advanced": "설악산 계곡은 여름 피서지로 인기가 높다.", "master": "계곡의 생태계는 수온과 유속에 따라 다양한 수생 생물이 서식한다."}, "variations": {"formal": ["계곡을 방문했습니다.", "계곡에서 피서합니다."], "casual": ["계곡 가자!", "계곡 물놀이 하자."], "short": ["계곡"]}, "dialogue": {"context": "여름 피서 계획", "dialogue": [{"speaker": "A", "text": "너무 더워. 계곡 갈까?", "romanization": "neomu deowo. gyegok galkka?", "translation": "It''s so hot. Shall we go to the valley?"}, {"speaker": "B", "text": "가자! 물놀이하면 시원하겠다.", "romanization": "gaja! mulnorihhamyeon siwonhagetda.", "translation": "Let''s go! Playing in the water will be refreshing."}]}}, "en": {"word": "valley / gorge", "explanation": "A narrow, deep passage between mountains where water flows. In Korea, playing in valley streams is one of the most popular ways to escape the summer heat.", "examples": {"beginner": "The valley water is cold.", "intermediate": "I played in the water at the valley in summer.", "advanced": "Seoraksan''s valleys are popular summer getaway destinations.", "master": "Valley ecosystems host diverse aquatic organisms depending on water temperature and flow speed."}, "variations": {"formal": ["I visited the valley.", "I vacation at the valley."], "casual": ["Let''s go to the valley!", "Let''s play in the valley water."], "short": ["valley"]}, "dialogue": {"context": "Planning a summer escape", "dialogue": [{"speaker": "A", "text": "It''s so hot. Shall we go to the valley?", "romanization": "", "translation": "너무 더워. 계곡 갈까?"}, {"speaker": "B", "text": "Let''s go! Playing in the water will be refreshing.", "romanization": "", "translation": "가자! 물놀이하면 시원하겠다."}]}}}'),
  ('deulpan', '들판', 'deulpan', 'noun', 'nature', 'intermediate', 'uncommon', '["nature", "agriculture", "scenery", "rural"]', '{"ko": {"word": "들판", "explanation": "넓게 펼쳐진 평평한 땅입니다. 한국의 호남 지방(전라도)은 넓은 들판으로 유명하며, 한국 최대의 곡창 지대입니다.", "examples": {"beginner": "들판이 넓어요.", "intermediate": "가을에 들판이 황금색으로 변해요.", "advanced": "전라도의 넓은 들판은 한국 최대의 곡창 지대이다.", "master": "들판의 생태계는 농업과 자연의 공존을 보여주는 중요한 사례이다."}, "variations": {"formal": ["들판을 바라봅니다.", "들판을 가로지릅니다."], "casual": ["들판 넓다.", "저기 들판 봐."], "short": ["들판"]}, "dialogue": {"context": "시골 드라이브 중", "dialogue": [{"speaker": "A", "text": "와, 들판이 끝이 없다.", "romanization": "wa, deulpani kkeuti eopda.", "translation": "Wow, the field is endless."}, {"speaker": "B", "text": "가을이면 여기 전부 황금빛이래.", "romanization": "gaeulimyeon yeogi jeonbu hwanggeumbichirae.", "translation": "In autumn, this whole area turns golden."}]}}, "en": {"word": "field / plain", "explanation": "A wide, flat area of open land. The Honam region (Jeolla Province) in Korea is famous for its vast fields and is Korea''s largest granary.", "examples": {"beginner": "The field is wide.", "intermediate": "In autumn, the fields turn golden.", "advanced": "The wide fields of Jeolla Province form Korea''s largest granary.", "master": "Field ecosystems are important examples of coexistence between agriculture and nature."}, "variations": {"formal": ["I gaze at the field.", "We cross the field."], "casual": ["The field is huge.", "Look at that field."], "short": ["field"]}, "dialogue": {"context": "Driving through the countryside", "dialogue": [{"speaker": "A", "text": "Wow, the field is endless.", "romanization": "", "translation": "와, 들판이 끝이 없다."}, {"speaker": "B", "text": "In autumn, this whole area turns golden.", "romanization": "", "translation": "가을이면 여기 전부 황금빛이래."}]}}}'),
  ('samak', '사막', 'samak', 'noun', 'nature', 'intermediate', 'uncommon', '["nature", "geography", "extreme", "dry"]', '{"ko": {"word": "사막", "explanation": "비가 거의 오지 않는 건조한 땅입니다. 한국에는 사막이 없지만, 봄마다 중국 사막에서 오는 황사(미세먼지)로 사막의 영향을 간접적으로 경험합니다.", "examples": {"beginner": "사막은 더워요.", "intermediate": "사막에는 비가 거의 안 와요.", "advanced": "중국의 사막화가 한국의 황사에 직접적인 영향을 준다.", "master": "사막화 현상은 기후 변화와 과잉 경작이 맞물린 결과이다."}, "variations": {"formal": ["사막을 탐험합니다.", "사막 지대를 연구합니다."], "casual": ["사막 가 보고 싶다.", "사막 진짜 덥겠다."], "short": ["사막"]}, "dialogue": {"context": "지리 수업 후", "dialogue": [{"speaker": "A", "text": "사막에 가 본 적 있어?", "romanization": "samage ga bon jeok isseo?", "translation": "Have you ever been to a desert?"}, {"speaker": "B", "text": "아니, 근데 사하라 사막 꼭 가 보고 싶어.", "romanization": "ani, geunde sahara samak kkok ga bogo sipeo.", "translation": "No, but I really want to visit the Sahara Desert."}]}}, "en": {"word": "desert", "explanation": "A dry land with very little rainfall. While Korea has no deserts, it indirectly experiences their impact through yellow dust (황사) blown from Chinese deserts every spring.", "examples": {"beginner": "The desert is hot.", "intermediate": "It hardly ever rains in the desert.", "advanced": "Desertification in China directly contributes to yellow dust in Korea.", "master": "Desertification is the result of climate change intersecting with overfarming."}, "variations": {"formal": ["I explore the desert.", "We study desert regions."], "casual": ["I want to go to a desert.", "The desert must be so hot."], "short": ["desert"]}, "dialogue": {"context": "After a geography class", "dialogue": [{"speaker": "A", "text": "Have you ever been to a desert?", "romanization": "", "translation": "사막에 가 본 적 있어?"}, {"speaker": "B", "text": "No, but I really want to visit the Sahara Desert.", "romanization": "", "translation": "아니, 근데 사하라 사막 꼭 가 보고 싶어."}]}}}'),
  ('donggul', '동굴', 'donggul', 'noun', 'nature', 'intermediate', 'uncommon', '["nature", "geography", "adventure", "dark"]', '{"ko": {"word": "동굴", "explanation": "바위나 산속에 자연적으로 생긴 빈 공간입니다. 한국에는 제주도의 만장굴, 단양의 고수동굴 등 유명한 석회암 동굴이 있습니다.", "examples": {"beginner": "동굴이 어두워요.", "intermediate": "제주도에 유명한 동굴이 있어요.", "advanced": "만장굴은 세계에서 가장 긴 용암 동굴 중 하나이다.", "master": "석회암 동굴의 종유석은 수만 년에 걸쳐 탄산칼슘이 침전되어 형성된다."}, "variations": {"formal": ["동굴을 탐험했습니다.", "동굴을 관람합니다."], "casual": ["동굴 가 보자.", "동굴 안이 시원하대."], "short": ["동굴"]}, "dialogue": {"context": "제주도 관광 계획", "dialogue": [{"speaker": "A", "text": "만장굴 가 볼까?", "romanization": "manjanggul ga bolkka?", "translation": "Shall we visit Manjanggul Cave?"}, {"speaker": "B", "text": "좋아! 여름에 동굴은 시원하다더라.", "romanization": "joa! yeoreume donggureun siwonhadadeora.", "translation": "Sure! I heard caves are cool in summer."}]}}, "en": {"word": "cave", "explanation": "A natural hollow space formed in rock or underground. Famous Korean caves include Manjanggul on Jeju Island and Gosu Cave in Danyang.", "examples": {"beginner": "The cave is dark.", "intermediate": "There is a famous cave on Jeju Island.", "advanced": "Manjanggul is one of the longest lava tubes in the world.", "master": "Stalactites in limestone caves form over tens of thousands of years through calcium carbonate deposition."}, "variations": {"formal": ["I explored the cave.", "We tour the cave."], "casual": ["Let''s check out the cave.", "I heard it''s cool inside the cave."], "short": ["cave"]}, "dialogue": {"context": "Planning Jeju sightseeing", "dialogue": [{"speaker": "A", "text": "Shall we visit Manjanggul Cave?", "romanization": "", "translation": "만장굴 가 볼까?"}, {"speaker": "B", "text": "Sure! I heard caves are cool in summer.", "romanization": "", "translation": "좋아! 여름에 동굴은 시원하다더라."}]}}}'),
  ('jeolbyeok', '절벽', 'jeolbyeok', 'noun', 'nature', 'intermediate', 'uncommon', '["nature", "geography", "danger", "scenery"]', '{"ko": {"word": "절벽", "explanation": "수직으로 깎아지른 듯한 가파른 바위벽입니다. 한국의 주상절리(제주 중문), 해안 절벽 등이 유명합니다. ''절벽''은 한자어(絕壁)입니다.", "examples": {"beginner": "절벽이 높아요.", "intermediate": "절벽 위에서 바다가 보여요.", "advanced": "제주도의 주상절리는 자연이 만든 예술 작품이다.", "master": "절벽에 몰리다''라는 표현은 궁지에 처한 상황을 비유한다."}, "variations": {"formal": ["절벽을 바라봅니다.", "절벽 앞에 섰습니다."], "casual": ["절벽 무섭다.", "절벽 높다."], "short": ["절벽"]}, "dialogue": {"context": "해안 산책로에서", "dialogue": [{"speaker": "A", "text": "저 절벽 좀 봐. 진짜 높다.", "romanization": "jeo jeolbyeok jom bwa. jinjja nopda.", "translation": "Look at that cliff. It''s really high."}, {"speaker": "B", "text": "무서워. 가까이 가지 마.", "romanization": "museowo. gakkai gaji ma.", "translation": "Scary. Don''t go close."}]}}, "en": {"word": "cliff", "explanation": "A steep rock face, nearly vertical. Korea''s columnar joints (Jungmun, Jeju) and coastal cliffs are famous. ''절벽'' comes from Chinese characters (絕壁).", "examples": {"beginner": "The cliff is high.", "intermediate": "You can see the sea from the cliff.", "advanced": "Jeju''s columnar joints are works of art created by nature.", "master": "''Driven to a cliff'' is an expression used to describe being cornered."}, "variations": {"formal": ["I gaze at the cliff.", "I stood before the cliff."], "casual": ["The cliff is scary.", "That cliff is so tall."], "short": ["cliff"]}, "dialogue": {"context": "On a coastal trail", "dialogue": [{"speaker": "A", "text": "Look at that cliff. It''s really high.", "romanization": "", "translation": "저 절벽 좀 봐. 진짜 높다."}, {"speaker": "B", "text": "Scary. Don''t go close.", "romanization": "", "translation": "무서워. 가까이 가지 마."}]}}}'),
  ('haebyeon', '해변', 'haebyeon', 'noun', 'nature', 'intermediate', 'common', '["nature", "ocean", "summer", "travel", "vacation"]', '{"ko": {"word": "해변", "explanation": "바다와 육지가 만나는 모래사장입니다. 한국의 부산 해운대, 강릉 경포대 등이 유명한 해변입니다. ''해변''은 한자어(海邊)입니다.", "examples": {"beginner": "해변에서 놀아요.", "intermediate": "해운대 해변에 사람이 정말 많았어요.", "advanced": "해변 관광 산업은 연안 도시의 경제를 지탱한다.", "master": "해안 침식으로 인한 해변 소실은 전 세계적으로 심각한 환경 문제이다."}, "variations": {"formal": ["해변을 산책합니다.", "해변을 방문했습니다."], "casual": ["해변 가자!", "해변에서 놀자."], "short": ["해변"]}, "dialogue": {"context": "부산 여행 중", "dialogue": [{"speaker": "A", "text": "해운대 해변 진짜 넓다!", "romanization": "haeundae haebyeon jinjja neolda!", "translation": "Haeundae Beach is really wide!"}, {"speaker": "B", "text": "모래성 만들자!", "romanization": "moraeseong mandeulja!", "translation": "Let''s build a sandcastle!"}]}}, "en": {"word": "beach", "explanation": "A sandy shore where the sea meets the land. Famous Korean beaches include Haeundae in Busan and Gyeongpo in Gangneung. ''해변'' comes from Chinese characters (海邊).", "examples": {"beginner": "Let''s play at the beach.", "intermediate": "Haeundae Beach was really crowded.", "advanced": "Beach tourism sustains the economy of coastal cities.", "master": "Beach loss due to coastal erosion is a serious environmental issue worldwide."}, "variations": {"formal": ["I walk along the beach.", "I visited the beach."], "casual": ["Let''s go to the beach!", "Let''s hang out at the beach."], "short": ["beach"]}, "dialogue": {"context": "Traveling in Busan", "dialogue": [{"speaker": "A", "text": "Haeundae Beach is really wide!", "romanization": "", "translation": "해운대 해변 진짜 넓다!"}, {"speaker": "B", "text": "Let''s build a sandcastle!", "romanization": "", "translation": "모래성 만들자!"}]}}}'),
  ('jandi', '잔디', 'jandi', 'noun', 'nature', 'beginner', 'common', '["nature", "plant", "park", "daily-life"]', '{"ko": {"word": "잔디", "explanation": "키가 작은 풀로 공원이나 운동장에 깔려 있습니다. 한국의 공원에서 잔디밭에 앉아 피크닉을 즐기는 것이 인기입니다. 일부 잔디밭은 출입 금지인 곳도 있습니다.", "examples": {"beginner": "잔디가 초록색이에요.", "intermediate": "공원 잔디밭에서 피크닉했어요.", "advanced": "잔디 관리를 위해 출입을 제한하는 공원이 많다.", "master": "잔디밭은 도시의 열섬 현상을 완화하는 중요한 녹지 공간이다."}, "variations": {"formal": ["잔디밭에서 쉬겠습니다.", "잔디를 관리합니다."], "casual": ["잔디밭에 앉자.", "잔디 위에 누워 보자."], "short": ["잔디"]}, "dialogue": {"context": "공원에서 피크닉", "dialogue": [{"speaker": "A", "text": "여기 잔디밭에 앉을까?", "romanization": "yeogi jandibate anjeulkka?", "translation": "Shall we sit on the grass here?"}, {"speaker": "B", "text": "좋아! 돗자리 깔자.", "romanization": "joa! dotjari kkarja.", "translation": "Sure! Let''s spread out the picnic mat."}]}}, "en": {"word": "grass / lawn", "explanation": "Short-growing plants covering parks and fields. Sitting on grass for picnics is popular in Korean parks, though some lawn areas restrict entry for maintenance.", "examples": {"beginner": "The grass is green.", "intermediate": "I had a picnic on the park lawn.", "advanced": "Many parks restrict access to lawns for grass maintenance.", "master": "Lawns are important green spaces that mitigate the urban heat island effect."}, "variations": {"formal": ["I will rest on the lawn.", "We maintain the grass."], "casual": ["Let''s sit on the grass.", "Let''s lie down on the grass."], "short": ["grass"]}, "dialogue": {"context": "Picnic in the park", "dialogue": [{"speaker": "A", "text": "Shall we sit on the grass here?", "romanization": "", "translation": "여기 잔디밭에 앉을까?"}, {"speaker": "B", "text": "Sure! Let''s spread out the picnic mat.", "romanization": "", "translation": "좋아! 돗자리 깔자."}]}}}'),
  ('dol', '돌', 'dol', 'noun', 'nature', 'beginner', 'common', '["nature", "geology", "daily-life", "idiom"]', '{"ko": {"word": "돌", "explanation": "단단한 광물 덩어리입니다. 한국에서 ''돌''은 아기의 첫 번째 생일(돌잔치)도 뜻합니다. ''돌다리도 두들겨 보고 건너라''는 유명한 속담이 있습니다.", "examples": {"beginner": "돌이 딱딱해요.", "intermediate": "제주도에는 검은 돌이 많아요.", "advanced": "돌하르방은 제주도를 상징하는 돌 조각상이다.", "master": "돌다리도 두들겨 보고 건너라는 속담은 신중함을 강조한다."}, "variations": {"formal": ["돌을 관찰합니다.", "돌을 수집합니다."], "casual": ["돌 던지지 마.", "이 돌 예쁘다."], "short": ["돌"]}, "dialogue": {"context": "제주도 해변에서", "dialogue": [{"speaker": "A", "text": "제주도 돌은 왜 다 검은색이야?", "romanization": "jejudo doreun wae da geomeunsaegiya?", "translation": "Why are all the rocks on Jeju Island black?"}, {"speaker": "B", "text": "화산 폭발로 만들어진 현무암이래.", "romanization": "hwasan pokballo mandeureojin hyeonmuamirae.", "translation": "They''re basalt formed from volcanic eruptions."}]}}, "en": {"word": "stone / rock", "explanation": "A hard solid piece of mineral matter. In Korean, ''돌'' also means a baby''s first birthday (돌잔치). The proverb ''돌다리도 두들겨 보고 건너라'' means ''even a stone bridge should be tested before crossing'' — emphasizing caution.", "examples": {"beginner": "The rock is hard.", "intermediate": "There are many black rocks on Jeju Island.", "advanced": "Dolhareubang are stone statues that symbolize Jeju Island.", "master": "The proverb ''test even a stone bridge before crossing'' emphasizes the importance of caution."}, "variations": {"formal": ["I observe the rocks.", "I collect stones."], "casual": ["Don''t throw rocks.", "This stone is pretty."], "short": ["stone"]}, "dialogue": {"context": "On a Jeju Island beach", "dialogue": [{"speaker": "A", "text": "Why are all the rocks on Jeju Island black?", "romanization": "", "translation": "제주도 돌은 왜 다 검은색이야?"}, {"speaker": "B", "text": "They''re basalt formed from volcanic eruptions.", "romanization": "", "translation": "화산 폭발로 만들어진 현무암이래."}]}}}'),
  ('heuk', '흙', 'heuk', 'noun', 'nature', 'beginner', 'common', '["nature", "agriculture", "earth"]', '{"ko": {"word": "흙", "explanation": "식물이 자라는 땅의 표면 물질입니다. 한국 전통 문화에서 흙은 도자기(옹기, 백자)의 재료이며, 한옥의 벽에도 흙이 사용됩니다. 발음은 [흑]입니다.", "examples": {"beginner": "흙이 젖어 있어요.", "intermediate": "흙으로 도자기를 만들어요.", "advanced": "비옥한 흙은 농업의 가장 중요한 자원이다.", "master": "흙의 유기물 함량은 토양의 건강 상태를 나타내는 핵심 지표이다."}, "variations": {"formal": ["흙을 분석합니다.", "토양을 조사합니다."], "casual": ["흙 묻었어.", "흙 만지지 마."], "short": ["흙"]}, "dialogue": {"context": "도자기 체험 중", "dialogue": [{"speaker": "A", "text": "이 흙으로 뭘 만들 거야?", "romanization": "i heugeuro mwol mandeul geoya?", "translation": "What are you going to make with this clay?"}, {"speaker": "B", "text": "컵 만들어 볼게. 생각보다 어렵다.", "romanization": "keop mandeureo bolge. saenggakboda eoryeopda.", "translation": "I''ll try making a cup. It''s harder than I thought."}]}}, "en": {"word": "soil / dirt", "explanation": "The surface material of the earth where plants grow. In Korean traditional culture, clay (흙) is the material for pottery (onggi, baekja) and is also used in hanok walls. Pronounced [흑].", "examples": {"beginner": "The soil is wet.", "intermediate": "We make pottery with clay.", "advanced": "Fertile soil is agriculture''s most important resource.", "master": "The organic matter content of soil is a key indicator of its health."}, "variations": {"formal": ["I analyze the soil.", "We examine the terrain."], "casual": ["You got dirt on you.", "Don''t touch the dirt."], "short": ["soil"]}, "dialogue": {"context": "During a pottery experience", "dialogue": [{"speaker": "A", "text": "What are you going to make with this clay?", "romanization": "", "translation": "이 흙으로 뭘 만들 거야?"}, {"speaker": "B", "text": "I''ll try making a cup. It''s harder than I thought.", "romanization": "", "translation": "컵 만들어 볼게. 생각보다 어렵다."}]}}}'),
  ('morae', '모래', 'morae', 'noun', 'nature', 'beginner', 'common', '["nature", "beach", "desert", "play"]', '{"ko": {"word": "모래", "explanation": "아주 작은 돌 알갱이입니다. 해변이나 사막에서 볼 수 있습니다. 한국에서는 아이들이 모래놀이를 좋아하며, ''모래시계''는 시간의 흐름을 상징합니다.", "examples": {"beginner": "모래가 뜨거워요.", "intermediate": "아이들이 모래성을 만들어요.", "advanced": "해변의 모래는 수천 년에 걸쳐 바위가 풍화된 결과이다.", "master": "무분별한 모래 채취는 해안 침식과 생태계 파괴를 초래한다."}, "variations": {"formal": ["모래를 관찰합니다.", "모래 샘플을 채취합니다."], "casual": ["모래 뜨겁다.", "모래놀이 하자."], "short": ["모래"]}, "dialogue": {"context": "해변에서 아이들과", "dialogue": [{"speaker": "A", "text": "모래성 만들자!", "romanization": "moraeseong mandeulja!", "translation": "Let''s build a sandcastle!"}, {"speaker": "B", "text": "좋아! 삽 가져왔어.", "romanization": "joa! sap gajeowasseo.", "translation": "OK! I brought a shovel."}]}}, "en": {"word": "sand", "explanation": "Tiny granules of rock found on beaches and in deserts. Korean children love playing with sand, and ''모래시계'' (hourglass) symbolizes the passage of time.", "examples": {"beginner": "The sand is hot.", "intermediate": "The children are building sandcastles.", "advanced": "Beach sand is the result of rocks weathering over thousands of years.", "master": "Indiscriminate sand mining leads to coastal erosion and ecosystem destruction."}, "variations": {"formal": ["I observe the sand.", "We collect sand samples."], "casual": ["The sand is hot.", "Let''s play in the sand."], "short": ["sand"]}, "dialogue": {"context": "At the beach with children", "dialogue": [{"speaker": "A", "text": "Let''s build a sandcastle!", "romanization": "", "translation": "모래성 만들자!"}, {"speaker": "B", "text": "OK! I brought a shovel.", "romanization": "", "translation": "좋아! 삽 가져왔어."}]}}}'),
