-- honorifics (50 entries)
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES
  ('yo', '-요', 'yo', 'particle', 'honorifics', 'beginner', 'common', '["honorifics", "grammar", "polite", "beginner-essential", "daily-life"]', '{"ko": {"word": "-요", "explanation": "해요체의 종결어미로, 존댓말의 가장 기본적인 표현입니다. 동사나 형용사 뒤에 붙여 공손함을 나타냅니다. 일상 대화에서 가장 많이 쓰이는 존댓말 형태입니다.", "examples": {"beginner": "감사해요. (감사하다 + -요)", "intermediate": "이거 맛있어요. (맛있다 + -어요)", "advanced": "해요체는 격식과 비격식의 중간 단계로, 일상에서 가장 많이 쓰입니다.", "master": "해요체는 청자 높임법의 한 형태로, ''-습니다''보다 부드럽고 반말보다 공손합니다."}, "variations": {"formal": ["-요는 해요체의 종결어미입니다."], "casual": ["-요 붙이면 존댓말이야."], "short": ["-요"]}, "dialogue": {"context": "한국어 수업에서", "dialogue": [{"speaker": "A", "text": "\"먹다\"를 존댓말로 어떻게 해요?", "romanization": "\"meokda\"reul jondaenmallo eotteoke haeyo?", "translation": "How do you say ''먹다'' politely?"}, {"speaker": "B", "text": "\"먹어요\"라고 하면 돼요.", "romanization": "\"meogeoyo\"rago hamyeon dwaeyo.", "translation": "You can say ''먹어요''."}]}}, "en": {"word": "-yo (polite ending)", "explanation": "The most common polite sentence ending in Korean (해요체 / haeyo-che). Added to verbs and adjectives to show politeness. It''s the middle level of formality — more polite than casual speech (반말) but softer than formal speech (-습니다).", "examples": {"beginner": "감사해요 (Thank you — polite).", "intermediate": "이거 맛있어요 (This is delicious — polite).", "advanced": "The 해요체 is the most commonly used politeness level in everyday Korean.", "master": "The 해요체 is a form of addressee honorification, softer than -습니다 but more polite than 반말."}, "variations": {"formal": ["-요 is the polite sentence ending of 해요체."], "casual": ["Just add -요 to make it polite."], "short": ["-yo"]}, "dialogue": {"context": "In a Korean class", "dialogue": [{"speaker": "A", "text": "How do you say ''먹다'' politely?", "romanization": "", "translation": "\"먹다\"를 존댓말로 어떻게 해요?"}, {"speaker": "B", "text": "You can say ''먹어요''.", "romanization": "", "translation": "\"먹어요\"라고 하면 돼요."}]}}}'),
  ('seyo', '-세요', 'seyo', 'particle', 'honorifics', 'beginner', 'common', '["honorifics", "grammar", "polite", "request"]', '{"ko": {"word": "-세요", "explanation": "주체 높임 선어말어미 ''-시-''와 해요체 ''-어요''가 결합한 형태입니다. 상대방의 행동을 높여 말하거나 공손한 요청을 할 때 사용합니다. ''가세요'', ''드세요'', ''안녕하세요'' 등에 쓰입니다.", "examples": {"beginner": "안녕하세요.", "intermediate": "어서 오세요. 뭘 드시겠어요?", "advanced": "''-세요''는 ''-시-'' + ''-어요''의 축약형으로, 주체 높임과 상대 높임이 결합된 형태이다.", "master": "''-세요''는 명령문에서 공손한 요청으로, 청유문에서는 권유로 기능한다."}, "variations": {"formal": ["-세요는 주체 높임의 해요체입니다."], "casual": ["-세요는 공손하게 부탁할 때 써."], "short": ["-세요"]}, "dialogue": {"context": "식당에서", "dialogue": [{"speaker": "A", "text": "여기 앉으세요.", "romanization": "yeogi anjeuseyo.", "translation": "Please sit here."}, {"speaker": "B", "text": "감사합니다. 메뉴 주세요.", "romanization": "gamsahamnida. menyu juseyo.", "translation": "Thank you. Please give me the menu."}]}}, "en": {"word": "-seyo (polite honorific ending)", "explanation": "A combination of the subject honorific marker ''-시-'' and the polite ending ''-어요''. Used to elevate the listener''s actions or make polite requests. Found in expressions like ''가세요'' (please go), ''드세요'' (please eat), and ''안녕하세요'' (hello).", "examples": {"beginner": "안녕하세요 (Hello — polite honorific).", "intermediate": "어서 오세요 (Welcome — polite honorific).", "advanced": "''-세요'' is a contraction of ''-시-'' + ''-어요'', combining subject and addressee honorification.", "master": "''-세요'' functions as a polite request in imperative sentences and as a suggestion in propositive sentences."}, "variations": {"formal": ["-세요 is the 해요체 form with subject honorification."], "casual": ["Use -세요 when asking politely."], "short": ["-seyo"]}, "dialogue": {"context": "At a restaurant", "dialogue": [{"speaker": "A", "text": "Please sit here.", "romanization": "", "translation": "여기 앉으세요."}, {"speaker": "B", "text": "Thank you. Please give me the menu.", "romanization": "", "translation": "감사합니다. 메뉴 주세요."}]}}}'),
  ('nim', '님', 'nim', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "title", "respect", "formal"]', '{"ko": {"word": "님", "explanation": "상대방을 높여 부를 때 이름이나 직함 뒤에 붙이는 존칭 접미사입니다. ''선생님'', ''사장님'', ''손님'' 등에 쓰입니다. 인터넷에서는 닉네임 뒤에도 붙입니다.", "examples": {"beginner": "선생님, 안녕하세요.", "intermediate": "사장님께서 말씀하셨습니다.", "advanced": "인터넷에서는 아이디 뒤에 ''님''을 붙여 존칭으로 사용한다.", "master": "님은 본래 ''임(임금)''에서 유래한 존칭으로, 고려 가요에서도 사용되었다."}, "variations": {"formal": ["님은 존칭 접미사입니다."], "casual": ["님 붙이면 존댓말이야."], "short": ["님"]}, "dialogue": {"context": "회사에서", "dialogue": [{"speaker": "A", "text": "김 대리님, 회의 시간이에요.", "romanization": "gim daerinim, hoeui siganieyo.", "translation": "Mr./Ms. Kim, it''s time for the meeting."}, {"speaker": "B", "text": "네, 바로 가겠습니다.", "romanization": "ne, baro gagetseumnida.", "translation": "Yes, I''ll go right away."}]}}, "en": {"word": "-nim (honorific suffix)", "explanation": "An honorific suffix attached after a name or title to show respect. Used in ''선생님'' (teacher), ''사장님'' (boss), ''손님'' (guest/customer). On the internet, it''s commonly added after usernames as a sign of respect.", "examples": {"beginner": "선생님, hello. (Teacher, hello.)", "intermediate": "The boss said so. (사장님께서 말씀하셨습니다.)", "advanced": "On the internet, ''-님'' is added after usernames as a form of respect.", "master": "''-님'' originally derived from ''임'' (king/ruler), and has been used since the Goryeo Dynasty poetry."}, "variations": {"formal": ["-님 is an honorific suffix."], "casual": ["Add -님 to be polite."], "short": ["-nim"]}, "dialogue": {"context": "At the office", "dialogue": [{"speaker": "A", "text": "Mr./Ms. Kim, it''s time for the meeting.", "romanization": "", "translation": "김 대리님, 회의 시간이에요."}, {"speaker": "B", "text": "Yes, I''ll go right away.", "romanization": "", "translation": "네, 바로 가겠습니다."}]}}}'),
  ('ssi', '씨', 'ssi', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "title", "semi-formal", "name"]', '{"ko": {"word": "씨", "explanation": "이름 뒤에 붙여 상대를 보통 수준으로 높이는 호칭입니다. ''님''보다 격이 낮고, 주로 성+이름 뒤에 붙입니다. 성만 쓰고 ''씨''를 붙이면 무례할 수 있으므로 주의해야 합니다.", "examples": {"beginner": "김민수 씨, 안녕하세요.", "intermediate": "이 씨라고 부르면 실례가 될 수 있어요.", "advanced": "''씨''는 성+이름 전체 뒤에 붙이는 것이 예의이며, 성만 쓰면 격식이 낮아진다.", "master": "''씨(氏)''는 본래 가문을 뜻하는 한자어로, 현대에는 일반 호칭으로 변화했다."}, "variations": {"formal": ["씨는 이름 뒤에 붙이는 호칭입니다."], "casual": ["씨는 이름 뒤에 붙여."], "short": ["씨"]}, "dialogue": {"context": "직장 동료와", "dialogue": [{"speaker": "A", "text": "박지영 씨, 점심 먹었어요?", "romanization": "bakjiyeong ssi, jeomsim meogeosseoyo?", "translation": "Ms. Park Jiyoung, have you had lunch?"}, {"speaker": "B", "text": "아니요, 아직이요. 같이 갈래요?", "romanization": "aniyo, ajigiyo. gachi gallaeyo?", "translation": "No, not yet. Want to go together?"}]}}, "en": {"word": "-ssi (Mr./Ms./name suffix)", "explanation": "A moderately polite suffix attached after a person''s full name. Less formal than ''-님'' but polite enough for everyday use. Important: attaching ''-씨'' after only a surname (e.g., ''김 씨'') can sound rude; always use the full name (e.g., ''김민수 씨'').", "examples": {"beginner": "김민수 씨, hello. (Mr. Kim Minsu, hello.)", "intermediate": "Calling someone ''이 씨'' (just surname + 씨) can be rude.", "advanced": "It''s proper etiquette to use full name + 씨; using only the surname lowers the formality.", "master": "''씨 (氏)'' originally meant ''clan'' in Chinese characters and has evolved into a general honorific suffix in modern Korean."}, "variations": {"formal": ["-씨 is a name suffix showing moderate respect."], "casual": ["Add -씨 after someone''s full name."], "short": ["-ssi"]}, "dialogue": {"context": "With a coworker", "dialogue": [{"speaker": "A", "text": "Ms. Park Jiyoung, have you had lunch?", "romanization": "", "translation": "박지영 씨, 점심 먹었어요?"}, {"speaker": "B", "text": "No, not yet. Want to go together?", "romanization": "", "translation": "아니요, 아직이요. 같이 갈래요?"}]}}}'),
  ('jondaenmal', '존댓말', 'jondaenmal', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "concept", "korean-culture", "social", "beginner-essential"]', '{"ko": {"word": "존댓말", "explanation": "상대방을 높여 말하는 말투의 총칭입니다. 반대말은 ''반말''(casual speech)입니다. 한국어의 존비어 체계는 세계적으로 가장 복잡한 경어법 중 하나입니다.", "examples": {"beginner": "한국어에는 존댓말이 있어요.", "intermediate": "처음 만나는 사람에게는 존댓말을 써요.", "advanced": "한국어의 경어법은 주체 높임, 상대 높임, 객체 높임 세 가지로 나뉜다.", "master": "존댓말과 반말의 전환은 한국 사회의 인간관계를 이해하는 핵심이다."}, "variations": {"formal": ["존댓말을 사용합니다.", "경어를 사용합니다."], "casual": ["존댓말 쓰자.", "말 놓을까요?"], "short": ["존댓말"]}, "dialogue": {"context": "새로운 사람을 만나서", "dialogue": [{"speaker": "A", "text": "우리 말 놓을까요?", "romanization": "uri mal noeulkkayo?", "translation": "Shall we speak casually to each other?"}, {"speaker": "B", "text": "네, 편하게 말해요.", "romanization": "ne, pyeonhage malhaeyo.", "translation": "Sure, let''s speak comfortably."}]}}, "en": {"word": "formal/polite speech", "explanation": "The general term for polite or formal speech in Korean. The opposite is ''반말'' (casual speech). Korean has one of the world''s most complex honorific systems, with three types: subject, addressee, and object honorification.", "examples": {"beginner": "Korean has formal speech (존댓말).", "intermediate": "You use 존댓말 when meeting someone for the first time.", "advanced": "Korean honorifics are divided into subject, addressee, and object honorification.", "master": "The switch between 존댓말 and 반말 is key to understanding Korean social relationships."}, "variations": {"formal": ["I use formal speech.", "I use honorifics."], "casual": ["Let''s speak formally.", "Shall we drop the formalities?"], "short": ["jondaenmal"]}, "dialogue": {"context": "Meeting a new person", "dialogue": [{"speaker": "A", "text": "Shall we speak casually to each other?", "romanization": "", "translation": "우리 말 놓을까요?"}, {"speaker": "B", "text": "Sure, let''s speak comfortably.", "romanization": "", "translation": "네, 편하게 말해요."}]}}}'),
  ('banmal', '반말', 'banmal', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "concept", "casual", "korean-culture", "social"]', '{"ko": {"word": "반말", "explanation": "높임 표현 없이 편하게 말하는 말투입니다. 친구, 동생, 친한 사이에서 사용합니다. 처음 만난 사람이나 윗사람에게 반말을 쓰면 매우 무례합니다. ''말을 놓다''는 반말로 전환하겠다는 뜻입니다.", "examples": {"beginner": "친구한테는 반말 써.", "intermediate": "나이 차이가 적으면 반말 해도 돼요.", "advanced": "반말은 친밀감의 표현이지만, 상황에 따라 무례함으로 받아들여질 수 있다.", "master": "반말 사용 여부는 나이, 관계, 상황에 따라 결정되며, 한국 사회의 위계를 반영한다."}, "variations": {"formal": ["반말은 높임 표현이 없는 말투입니다."], "casual": ["반말은 편한 말투야."], "short": ["반말"]}, "dialogue": {"context": "친구 사이에서", "dialogue": [{"speaker": "A", "text": "야, 밥 먹었어?", "romanization": "ya, bap meogeosseo?", "translation": "Hey, did you eat?"}, {"speaker": "B", "text": "아니, 아직. 같이 먹자!", "romanization": "ani, ajik. gachi meokja!", "translation": "No, not yet. Let''s eat together!"}]}}, "en": {"word": "casual speech / informal speech", "explanation": "Informal speech without honorific markers, used among friends, younger people, or close relationships. Using 반말 with strangers or elders is considered very rude. The phrase ''말을 놓다'' means to switch to casual speech.", "examples": {"beginner": "Use 반말 with friends.", "intermediate": "If the age gap is small, it''s okay to use 반말.", "advanced": "반말 expresses intimacy but can be perceived as rude depending on the context.", "master": "Whether to use 반말 is determined by age, relationship, and context, reflecting Korean social hierarchy."}, "variations": {"formal": ["반말 is speech without honorifics."], "casual": ["반말 is how you talk to friends."], "short": ["banmal"]}, "dialogue": {"context": "Between friends", "dialogue": [{"speaker": "A", "text": "Hey, did you eat?", "romanization": "", "translation": "야, 밥 먹었어?"}, {"speaker": "B", "text": "No, not yet. Let''s eat together!", "romanization": "", "translation": "아니, 아직. 같이 먹자!"}]}}}'),
  ('nopimmal', '높임말', 'nopimmal', 'noun', 'honorifics', 'intermediate', 'common', '["honorifics", "concept", "formal", "respect"]', '{"ko": {"word": "높임말", "explanation": "상대방이나 주어를 높여서 말하는 표현의 총칭입니다. 존댓말과 비슷하지만 더 넓은 개념으로, 주체 높임(-시-), 상대 높임(-요, -습니다), 객체 높임(드리다, 여쭙다)을 모두 포함합니다.", "examples": {"beginner": "높임말을 쓰세요.", "intermediate": "어른 앞에서는 높임말을 써야 해요.", "advanced": "높임말에는 주체 높임, 상대 높임, 객체 높임의 세 가지가 있다.", "master": "높임말 체계는 한국어 문법의 핵심이며, 사회 언어학적으로 중요한 연구 대상이다."}, "variations": {"formal": ["높임말은 존경을 나타내는 말투입니다."], "casual": ["높임말은 공손하게 말하는 거야."], "short": ["높임말"]}, "dialogue": {"context": "한국어 수업에서", "dialogue": [{"speaker": "A", "text": "높임말이 뭐예요?", "romanization": "nopimmari mwoyeyo?", "translation": "What is honorific speech?"}, {"speaker": "B", "text": "상대방을 존경해서 높여 말하는 거예요.", "romanization": "sangdaebang-eul jongyeonghaeseo nopyeo malhaneun geoyeyo.", "translation": "It''s speaking in an elevated way to show respect."}]}}, "en": {"word": "honorific speech / elevated speech", "explanation": "A general term for speech that elevates the subject or addressee. Broader than 존댓말, it encompasses all three types of Korean honorification: subject honorifics (-시-), addressee honorifics (-요, -습니다), and object honorifics (드리다, 여쭙다).", "examples": {"beginner": "Please use honorific speech.", "intermediate": "You should use 높임말 in front of elders.", "advanced": "높임말 includes subject, addressee, and object honorification.", "master": "The 높임말 system is central to Korean grammar and a significant topic in sociolinguistics."}, "variations": {"formal": ["높임말 is speech showing respect."], "casual": ["높임말 means speaking politely."], "short": ["nopimmal"]}, "dialogue": {"context": "In a Korean class", "dialogue": [{"speaker": "A", "text": "What is honorific speech?", "romanization": "", "translation": "높임말이 뭐예요?"}, {"speaker": "B", "text": "It''s speaking in an elevated way to show respect.", "romanization": "", "translation": "상대방을 존경해서 높여 말하는 거예요."}]}}}'),
  ('seumnida', '-습니다', 'seumnida', 'particle', 'honorifics', 'beginner', 'common', '["honorifics", "grammar", "formal", "business"]', '{"ko": {"word": "-습니다 / -ㅂ니다", "explanation": "격식체의 종결어미로, 가장 공손한 존댓말 형태입니다. 뉴스, 발표, 비즈니스 등 공식적인 상황에서 사용합니다. 받침이 있으면 ''-습니다'', 없으면 ''-ㅂ니다''를 씁니다.", "examples": {"beginner": "감사합니다.", "intermediate": "만나서 반갑습니다.", "advanced": "합니다체는 공적인 상황에서 사용하는 최고 존칭의 종결어미입니다.", "master": "뉴스 앵커, 군대, 비즈니스에서 합니다체는 필수입니다."}, "variations": {"formal": ["-습니다는 격식체 종결어미입니다."], "casual": ["-습니다는 제일 공손한 말투야."], "short": ["-습니다"]}, "dialogue": {"context": "비즈니스 미팅에서", "dialogue": [{"speaker": "A", "text": "처음 뵙겠습니다. 김민수입니다.", "romanization": "cheoeum boepgesseumnida. gimminsuitmnida.", "translation": "Nice to meet you. I''m Kim Minsu."}, {"speaker": "B", "text": "반갑습니다. 이영희입니다.", "romanization": "bangapseumnida. iyeonghuitmnida.", "translation": "Nice to meet you. I''m Lee Younghee."}]}}, "en": {"word": "-seumnida (formal ending)", "explanation": "The most formal and polite sentence ending in Korean (합니다체 / hamnida-che). Used in news broadcasts, presentations, business, and official situations. Use ''-습니다'' after consonants and ''-ㅂ니다'' after vowels.", "examples": {"beginner": "감사합니다 (Thank you — formal).", "intermediate": "만나서 반갑습니다 (Nice to meet you — formal).", "advanced": "The 합니다체 is the highest formality level in Korean speech.", "master": "The 합니다체 is mandatory in news anchoring, military, and business contexts."}, "variations": {"formal": ["-습니다 is the formal sentence ending."], "casual": ["-습니다 is the most polite way to speak."], "short": ["-seumnida"]}, "dialogue": {"context": "At a business meeting", "dialogue": [{"speaker": "A", "text": "Nice to meet you. I''m Kim Minsu.", "romanization": "", "translation": "처음 뵙겠습니다. 김민수입니다."}, {"speaker": "B", "text": "Nice to meet you. I''m Lee Younghee.", "romanization": "", "translation": "반갑습니다. 이영희입니다."}]}}}'),
  ('imnida', '-입니다', 'imnida', 'particle', 'honorifics', 'beginner', 'common', '["honorifics", "grammar", "formal", "introduction"]', '{"ko": {"word": "-입니다", "explanation": "''이다''의 격식체 종결형으로, 자기 소개나 사실을 정중하게 말할 때 사용합니다. ''저는 학생입니다'', ''이것은 책입니다''처럼 명사 뒤에 붙습니다. 해요체 형태는 ''-이에요/-예요''입니다.", "examples": {"beginner": "저는 학생입니다.", "intermediate": "이것은 한국어 사전입니다.", "advanced": "''-입니다''는 서술격 조사 ''이다''의 합니다체로, 명사문의 격식 표현이다.", "master": "''이다''의 활용형은 격식/비격식, 평서/의문에 따라 다양하게 변화한다."}, "variations": {"formal": ["-입니다는 ''이다''의 격식체입니다."], "casual": ["-입니다는 ''이에요''의 격식 버전이야."], "short": ["-입니다"]}, "dialogue": {"context": "자기 소개에서", "dialogue": [{"speaker": "A", "text": "이름이 뭡니까?", "romanization": "ireumi mwomnikka?", "translation": "What is your name?"}, {"speaker": "B", "text": "저는 김민수입니다.", "romanization": "jeoneun gimminsuitmnida.", "translation": "I am Kim Minsu."}]}}, "en": {"word": "-imnida (to be — formal)", "explanation": "The formal declarative ending of ''이다'' (to be). Used for polite self-introductions and stating facts. Attached after nouns: ''학생입니다'' (I am a student), ''책입니다'' (It is a book). The 해요체 equivalent is ''-이에요/-예요''.", "examples": {"beginner": "저는 학생입니다 (I am a student — formal).", "intermediate": "이것은 한국어 사전입니다 (This is a Korean dictionary — formal).", "advanced": "''-입니다'' is the 합니다체 of the copula ''이다'', used for formal noun predicates.", "master": "The conjugation of ''이다'' varies across formality levels and sentence types (declarative, interrogative)."}, "variations": {"formal": ["-입니다 is the formal form of ''이다'' (to be)."], "casual": ["-입니다 is the formal version of ''-이에요''."], "short": ["-imnida"]}, "dialogue": {"context": "Self-introduction", "dialogue": [{"speaker": "A", "text": "What is your name?", "romanization": "", "translation": "이름이 뭡니까?"}, {"speaker": "B", "text": "I am Kim Minsu.", "romanization": "", "translation": "저는 김민수입니다."}]}}}'),
  ('deurida', '드리다', 'deurida', 'verb', 'honorifics', 'intermediate', 'common', '["honorifics", "humble", "verb", "respect"]', '{"ko": {"word": "드리다", "explanation": "''주다''의 겸양어(겸손 표현)로, 윗사람에게 무엇을 줄 때 사용합니다. 자신을 낮추어 상대를 높이는 객체 높임법의 대표적 표현입니다. ''선물을 드리다'', ''말씀을 드리다'' 등으로 씁니다.", "examples": {"beginner": "선생님께 꽃을 드렸어요.", "intermediate": "말씀드릴 것이 있습니다.", "advanced": "''드리다''는 객체 높임법의 겸양 동사로, 화자가 자신을 낮추어 객체를 높인다.", "master": "겸양어 체계(드리다, 여쭙다, 뵙다)는 한국어 높임법의 3축 중 하나이다."}, "variations": {"formal": ["드리다는 ''주다''의 겸양어입니다."], "casual": ["드리다는 윗사람한테 줄 때 쓰는 말이야."], "short": ["드리다"]}, "dialogue": {"context": "사무실에서 상사에게", "dialogue": [{"speaker": "A", "text": "부장님, 보고서 드리겠습니다.", "romanization": "bujangnim, bogoseo deurigesseumnida.", "translation": "Director, I''d like to give you the report."}, {"speaker": "B", "text": "네, 고마워요. 여기 놓으세요.", "romanization": "ne, gomawoyo. yeogi noheuseyo.", "translation": "Yes, thank you. Please put it here."}]}}, "en": {"word": "to give (humble)", "explanation": "The humble form of ''주다'' (to give), used when giving something to a superior. It''s a key example of object honorification where the speaker lowers themselves to elevate the recipient. Used in phrases like ''선물을 드리다'' (to give a gift) and ''말씀을 드리다'' (to tell/inform).", "examples": {"beginner": "I gave flowers to the teacher (선생님께 꽃을 드렸어요).", "intermediate": "I have something to tell you (말씀드릴 것이 있습니다).", "advanced": "''드리다'' is a humble verb in the object honorification system.", "master": "The humble verb system (드리다, 여쭙다, 뵙다) forms one of the three axes of Korean honorification."}, "variations": {"formal": ["드리다 is the humble form of ''주다'' (to give)."], "casual": ["Use 드리다 when giving to someone older or higher-ranked."], "short": ["deurida"]}, "dialogue": {"context": "At the office, to a boss", "dialogue": [{"speaker": "A", "text": "Director, I''d like to give you the report.", "romanization": "", "translation": "부장님, 보고서 드리겠습니다."}, {"speaker": "B", "text": "Yes, thank you. Please put it here.", "romanization": "", "translation": "네, 고마워요. 여기 놓으세요."}]}}}'),
  ('jusida', '주시다', 'jusida', 'verb', 'honorifics', 'intermediate', 'common', '["honorifics", "verb", "respect", "request"]', '{"ko": {"word": "주시다", "explanation": "''주다''의 주체 높임 표현으로, 윗사람이 아랫사람에게 무엇을 줄 때 사용합니다. ''-시-''가 들어가 주어(주는 사람)를 높입니다. ''선생님이 주시다'', ''부모님이 주시다'' 등으로 씁니다.", "examples": {"beginner": "선생님이 선물을 주셨어요.", "intermediate": "사장님께서 기회를 주셨습니다.", "advanced": "''주시다''는 주체 높임의 ''-시-''가 결합된 형태로, 주어를 높인다.", "master": "''주시다''(주체 높임)와 ''드리다''(객체 높임)는 같은 ''주다''의 서로 다른 높임 방향이다."}, "variations": {"formal": ["주시다는 ''주다''의 주체 높임형입니다."], "casual": ["주시다는 윗사람이 줄 때 쓰는 말이야."], "short": ["주시다"]}, "dialogue": {"context": "학생이 선생님에 대해 말할 때", "dialogue": [{"speaker": "A", "text": "선생님이 뭐라고 하셨어요?", "romanization": "seonsaengnimi mworago hasyeosseoyo?", "translation": "What did the teacher say?"}, {"speaker": "B", "text": "숙제를 내 주셨어요.", "romanization": "sukjereul nae jusyeosseoyo.", "translation": "The teacher gave us homework."}]}}, "en": {"word": "to give (honorific)", "explanation": "The subject-honorific form of ''주다'' (to give), used when the giver is someone of higher status. The honorific marker ''-시-'' elevates the subject (the giver). Compare with ''드리다'' which humbles the giver instead.", "examples": {"beginner": "The teacher gave me a gift (선생님이 선물을 주셨어요).", "intermediate": "The CEO gave us an opportunity (사장님께서 기회를 주셨습니다).", "advanced": "''주시다'' combines ''-시-'' with ''주다'' to honor the subject.", "master": "''주시다'' (subject honorific) and ''드리다'' (object honorific) represent opposite directions of honorification for the same verb ''주다''."}, "variations": {"formal": ["주시다 is the subject-honorific form of ''주다''."], "casual": ["Use 주시다 when an elder or superior gives something."], "short": ["jusida"]}, "dialogue": {"context": "A student talking about a teacher", "dialogue": [{"speaker": "A", "text": "What did the teacher say?", "romanization": "", "translation": "선생님이 뭐라고 하셨어요?"}, {"speaker": "B", "text": "The teacher gave us homework.", "romanization": "", "translation": "숙제를 내 주셨어요."}]}}}'),
  ('malsseum', '말씀', 'malsseum', 'noun', 'honorifics', 'intermediate', 'common', '["honorifics", "noun", "formal", "respect"]', '{"ko": {"word": "말씀", "explanation": "''말''의 높임말로, 윗사람의 말을 높이거나 자신의 말을 겸손하게 표현할 때 사용합니다. ''선생님의 말씀''(높임), ''제가 말씀드리다''(겸양) 두 가지 용법이 있습니다.", "examples": {"beginner": "선생님 말씀 잘 들으세요.", "intermediate": "말씀 중에 실례합니다.", "advanced": "''말씀''은 높임과 겸양 두 가지로 쓰이며, 맥락에 따라 의미가 달라진다.", "master": "''말씀하시다''(주체 높임)와 ''말씀드리다''(객체 겸양)는 대칭적 높임 구조를 형성한다."}, "variations": {"formal": ["말씀은 ''말''의 높임말입니다."], "casual": ["말씀은 높여서 하는 ''말''이야."], "short": ["말씀"]}, "dialogue": {"context": "회의에서", "dialogue": [{"speaker": "A", "text": "말씀 중에 죄송합니다만, 질문이 있습니다.", "romanization": "malsseum junge joesonghamnidaman, jilmuni itseumnida.", "translation": "Sorry to interrupt, but I have a question."}, {"speaker": "B", "text": "네, 말씀하세요.", "romanization": "ne, malsseum haseyo.", "translation": "Yes, please go ahead."}]}}, "en": {"word": "words / speech (honorific)", "explanation": "The honorific form of ''말'' (words/speech). Has two uses: to elevate a superior''s words (''선생님의 말씀'' — the teacher''s words) or to humble one''s own speech (''말씀드리다'' — I''d like to say/tell). Context determines which meaning applies.", "examples": {"beginner": "Listen well to the teacher''s words (선생님 말씀 잘 들으세요).", "intermediate": "Excuse me for interrupting (말씀 중에 실례합니다).", "advanced": "''말씀'' serves both honorific and humble functions depending on context.", "master": "''말씀하시다'' (subject honorific) and ''말씀드리다'' (object humble) form a symmetrical honorification structure."}, "variations": {"formal": ["말씀 is the honorific form of ''말'' (speech)."], "casual": ["말씀 is the polite way to say ''말''."], "short": ["malsseum"]}, "dialogue": {"context": "At a meeting", "dialogue": [{"speaker": "A", "text": "Sorry to interrupt, but I have a question.", "romanization": "", "translation": "말씀 중에 죄송합니다만, 질문이 있습니다."}, {"speaker": "B", "text": "Yes, please go ahead.", "romanization": "", "translation": "네, 말씀하세요."}]}}}'),
  ('daek', '댁', 'daek', 'noun', 'honorifics', 'advanced', 'uncommon', '["honorifics", "noun", "formal", "traditional"]', '{"ko": {"word": "댁", "explanation": "''집''의 높임말로, 상대방의 집을 높여 부를 때 사용합니다. 또한 상대방을 간접적으로 높여 부르는 대명사로도 쓰입니다. ''댁에서 오셨어요?''(어디서 오셨어요?의 높임). 전통적이고 격식 있는 표현입니다.", "examples": {"beginner": "댁이 어디세요?", "intermediate": "댁에 가족이 몇 분이세요?", "advanced": "''댁(宅)''은 한자어로 ''집''의 높임말이며, 2인칭 대명사로도 사용된다.", "master": "''댁''의 대명사적 용법은 ''당신''보다 격식 있으며, 노년층에서 주로 사용된다."}, "variations": {"formal": ["댁은 ''집''의 높임말입니다."], "casual": ["댁은 ''집''을 높여서 말하는 거야."], "short": ["댁"]}, "dialogue": {"context": "어른에게 인사할 때", "dialogue": [{"speaker": "A", "text": "댁이 어디세요?", "romanization": "daegi eodiseyo?", "translation": "Where is your home?"}, {"speaker": "B", "text": "서울에서 왔습니다.", "romanization": "seoureseo watseumnida.", "translation": "I came from Seoul."}]}}, "en": {"word": "home / residence (honorific)", "explanation": "The honorific form of ''집'' (house/home). Used to respectfully refer to someone''s house or as an indirect second-person pronoun. ''댁이 어디세요?'' can mean both ''Where is your home?'' and ''Where are you from?'' A traditional, formal expression mostly used by older generations.", "examples": {"beginner": "Where is your home? (댁이 어디세요?)", "intermediate": "How many family members are in your household? (댁에 가족이 몇 분이세요?)", "advanced": "''댁 (宅)'' is a Sino-Korean word for ''집'' and also functions as a second-person pronoun.", "master": "The pronominal use of ''댁'' is more formal than ''당신'' and is mainly used by the elderly."}, "variations": {"formal": ["댁 is the honorific form of ''집'' (house)."], "casual": ["댁 is the polite way to say someone''s house."], "short": ["daek"]}, "dialogue": {"context": "Greeting an elder", "dialogue": [{"speaker": "A", "text": "Where is your home?", "romanization": "", "translation": "댁이 어디세요?"}, {"speaker": "B", "text": "I came from Seoul.", "romanization": "", "translation": "서울에서 왔습니다."}]}}}'),
  ('yeonse', '연세', 'yeonse', 'noun', 'honorifics', 'intermediate', 'uncommon', '["honorifics", "noun", "formal", "respect", "age"]', '{"ko": {"word": "연세", "explanation": "''나이''의 높임말로, 어른의 나이를 여쭐 때 사용합니다. ''나이''를 직접 사용하면 버릇없게 들릴 수 있으므로, 윗사람에게는 반드시 ''연세''를 씁니다. ''연세가 어떻게 되세요?''가 올바른 표현입니다.", "examples": {"beginner": "할머니, 연세가 어떻게 되세요?", "intermediate": "연세에 비해 정정하시네요.", "advanced": "''연세(年歲)''는 한자어로, ''나이''의 객체 높임 표현이다.", "master": "나이 관련 높임어 체계: 나이(일반) → 연세(높임) → 춘추(최고 높임, 왕족)"}, "variations": {"formal": ["연세는 ''나이''의 높임말입니다."], "casual": ["연세는 나이를 높여서 말하는 거야."], "short": ["연세"]}, "dialogue": {"context": "어르신과 대화할 때", "dialogue": [{"speaker": "A", "text": "실례지만, 연세가 어떻게 되세요?", "romanization": "sillyejiman, yeonsega eotteoke doeseyo?", "translation": "Excuse me, may I ask your age?"}, {"speaker": "B", "text": "올해 일흔다섯이에요.", "romanization": "olhae ilheundaseosioeyo.", "translation": "I''m seventy-five this year."}]}}, "en": {"word": "age (honorific)", "explanation": "The honorific form of ''나이'' (age). Must be used when asking about an elder''s age, as using ''나이'' directly can sound rude. The standard polite question is ''연세가 어떻게 되세요?'' (How old are you? — honorific).", "examples": {"beginner": "Grandmother, how old are you? (할머니, 연세가 어떻게 되세요?)", "intermediate": "You look healthy for your age (연세에 비해 정정하시네요).", "advanced": "''연세 (年歲)'' is a Sino-Korean honorific for ''나이'' (age).", "master": "The age honorific hierarchy: 나이 (plain) → 연세 (honorific) → 춘추 (highest, for royalty)."}, "variations": {"formal": ["연세 is the honorific form of ''나이'' (age)."], "casual": ["연세 is the polite way to ask about someone''s age."], "short": ["yeonse"]}, "dialogue": {"context": "Talking with an elder", "dialogue": [{"speaker": "A", "text": "Excuse me, may I ask your age?", "romanization": "", "translation": "실례지만, 연세가 어떻게 되세요?"}, {"speaker": "B", "text": "I''m seventy-five this year.", "romanization": "", "translation": "올해 일흔다섯이에요."}]}}}'),
  ('jinji', '진지', 'jinji', 'noun', 'honorifics', 'intermediate', 'uncommon', '["honorifics", "noun", "formal", "food", "elderly"]', '{"ko": {"word": "진지", "explanation": "''밥''의 높임말로, 어른의 식사를 높여 말할 때 사용합니다. ''진지 드셨어요?''는 어른에게 식사했는지 묻는 공손한 인사입니다. 주로 할머니, 할아버지 등 어른에게 사용합니다.", "examples": {"beginner": "할아버지, 진지 드셨어요?", "intermediate": "진지 잡수세요.", "advanced": "''진지''는 ''밥''의 객체 높임어로, 식사를 대접하거나 안부를 물을 때 사용한다.", "master": "식사 관련 높임어: 밥(일반) → 진지(높임) → 수라(왕의 식사)"}, "variations": {"formal": ["진지는 ''밥''의 높임말입니다."], "casual": ["진지는 어른한테 밥을 높여서 말하는 거야."], "short": ["진지"]}, "dialogue": {"context": "할머니 댁 방문", "dialogue": [{"speaker": "A", "text": "할머니, 진지 드셨어요?", "romanization": "halmeoni, jinji deusyeosseoyo?", "translation": "Grandma, have you eaten?"}, {"speaker": "B", "text": "그럼, 아까 먹었단다.", "romanization": "geureom, akka meogeotdanda.", "translation": "Yes, I ate earlier."}]}}, "en": {"word": "meal / rice (honorific)", "explanation": "The honorific form of ''밥'' (rice/meal). Used when referring to an elder''s meal. ''진지 드셨어요?'' (Have you eaten?) is a polite greeting to elders. Primarily used with grandparents and senior figures.", "examples": {"beginner": "Grandfather, have you eaten? (할아버지, 진지 드셨어요?)", "intermediate": "Please eat (진지 잡수세요).", "advanced": "''진지'' is the object-honorific form of ''밥'', used when offering or asking about meals.", "master": "Meal honorific hierarchy: 밥 (plain) → 진지 (honorific) → 수라 (royal meal)."}, "variations": {"formal": ["진지 is the honorific form of ''밥'' (rice/meal)."], "casual": ["진지 is the polite word for an elder''s meal."], "short": ["jinji"]}, "dialogue": {"context": "Visiting grandmother''s house", "dialogue": [{"speaker": "A", "text": "Grandma, have you eaten?", "romanization": "", "translation": "할머니, 진지 드셨어요?"}, {"speaker": "B", "text": "Yes, I ate earlier.", "romanization": "", "translation": "그럼, 아까 먹었단다."}]}}}'),
  ('seongham', '성함', 'seongham', 'noun', 'honorifics', 'intermediate', 'common', '["honorifics", "noun", "formal", "introduction"]', '{"ko": {"word": "성함", "explanation": "''이름''의 높임말로, 상대방의 이름을 정중하게 여쭐 때 사용합니다. ''성함이 어떻게 되세요?''가 가장 일반적인 표현입니다. 고객 응대, 공식 상황에서 자주 쓰입니다.", "examples": {"beginner": "성함이 어떻게 되세요?", "intermediate": "여기에 성함을 적어 주세요.", "advanced": "''성함(姓銜)''은 한자어로, ''성''(姓)과 ''함''(銜, 직함)이 결합한 높임 표현이다.", "master": "이름 관련 높임어: 이름(일반) → 성함(높임) → 휘(왕의 이름, 역사적 표현)"}, "variations": {"formal": ["성함은 ''이름''의 높임말입니다."], "casual": ["성함은 이름을 높여서 말하는 거야."], "short": ["성함"]}, "dialogue": {"context": "호텔 체크인에서", "dialogue": [{"speaker": "A", "text": "성함이 어떻게 되세요?", "romanization": "seonghami eotteoke doeseyo?", "translation": "May I have your name?"}, {"speaker": "B", "text": "김민수입니다.", "romanization": "gimminsuitmnida.", "translation": "It''s Kim Minsu."}]}}, "en": {"word": "name (honorific)", "explanation": "The honorific form of ''이름'' (name). Used to politely ask someone''s name. ''성함이 어떻게 되세요?'' (May I have your name?) is the standard polite form. Frequently used in customer service and formal situations.", "examples": {"beginner": "May I have your name? (성함이 어떻게 되세요?)", "intermediate": "Please write your name here (여기에 성함을 적어 주세요).", "advanced": "''성함 (姓銜)'' combines ''성'' (surname) and ''함'' (title) as an honorific for ''name''.", "master": "Name honorific hierarchy: 이름 (plain) → 성함 (honorific) → 휘 (royal name, historical)."}, "variations": {"formal": ["성함 is the honorific form of ''이름'' (name)."], "casual": ["성함 is the polite way to ask someone''s name."], "short": ["seongham"]}, "dialogue": {"context": "Hotel check-in", "dialogue": [{"speaker": "A", "text": "May I have your name?", "romanization": "", "translation": "성함이 어떻게 되세요?"}, {"speaker": "B", "text": "It''s Kim Minsu.", "romanization": "", "translation": "김민수입니다."}]}}}'),
  ('gyesida', '계시다', 'gyesida', 'verb', 'honorifics', 'intermediate', 'common', '["honorifics", "verb", "formal", "respect"]', '{"ko": {"word": "계시다", "explanation": "''있다''의 주체 높임말로, 윗사람이 어딘가에 있거나 머물 때 사용합니다. ''선생님이 교실에 계세요'', ''할머니가 집에 계세요'' 등으로 씁니다. ''있다''를 직접 쓰면 높임이 되지 않습니다.", "examples": {"beginner": "선생님이 교실에 계세요.", "intermediate": "어머니가 집에 계시니까 편히 가세요.", "advanced": "''계시다''는 ''있다''의 주체 높임 특수 어휘로, ''-시-'' 결합이 아닌 별도 단어이다.", "master": "''있다''의 높임 체계: 있다(일반) → 계시다(주체 높임) vs. 있으시다(비표준이나 통용)"}, "variations": {"formal": ["계시다는 ''있다''의 높임말입니다."], "casual": ["계시다는 윗사람이 있을 때 쓰는 말이야."], "short": ["계시다"]}, "dialogue": {"context": "전화 통화에서", "dialogue": [{"speaker": "A", "text": "사장님 계세요?", "romanization": "sajangnim gyeseyo?", "translation": "Is the boss in?"}, {"speaker": "B", "text": "지금 회의 중이셔서 자리에 안 계세요.", "romanization": "jigeum hoeui jungisyeoseo jarie an gyeseyo.", "translation": "He''s not at his desk — he''s in a meeting."}]}}, "en": {"word": "to be / to exist (honorific)", "explanation": "The honorific form of ''있다'' (to be/exist). Used when a person of higher status is present somewhere. Unlike regular honorification with ''-시-'', ''계시다'' is a completely separate word. Examples: ''선생님이 계세요'' (The teacher is here), ''할머니가 집에 계세요'' (Grandmother is at home).", "examples": {"beginner": "The teacher is in the classroom (선생님이 교실에 계세요).", "intermediate": "Mother is at home, so don''t worry (어머니가 집에 계시니까 편히 가세요).", "advanced": "''계시다'' is a special honorific replacement for ''있다'', not simply ''있다 + -시-''.", "master": "Honorific system for ''있다'': 있다 (plain) → 계시다 (subject honorific) vs. 있으시다 (non-standard but widely used)."}, "variations": {"formal": ["계시다 is the honorific form of ''있다'' (to be)."], "casual": ["Use 계시다 when an elder or superior is somewhere."], "short": ["gyesida"]}, "dialogue": {"context": "On a phone call", "dialogue": [{"speaker": "A", "text": "Is the boss in?", "romanization": "", "translation": "사장님 계세요?"}, {"speaker": "B", "text": "He''s not at his desk — he''s in a meeting.", "romanization": "", "translation": "지금 회의 중이셔서 자리에 안 계세요."}]}}}'),
  ('japsusida', '잡수시다', 'japsusida', 'verb', 'honorifics', 'intermediate', 'common', '["honorifics", "verb", "formal", "food", "elderly"]', '{"ko": {"word": "잡수시다", "explanation": "''먹다''의 높임말로, 웃어른이 음식을 드실 때 사용하는 존경 표현입니다. ''드시다''보다 더 높은 경어로, 주로 조부모님이나 연세가 많은 분께 사용합니다.", "examples": {"beginner": "할머니, 많이 잡수세요.", "intermediate": "어르신께서 식사를 잡수시고 계십니다.", "advanced": "''잡수시다''는 ''먹다''의 최고 높임말로, ''드시다''보다 한 단계 더 높은 경어입니다.", "master": "현대 한국어에서 ''잡수시다''는 주로 노년층에 대한 존경을 표현할 때 사용되며, 일상에서는 ''드시다''가 더 보편적입니다."}, "variations": {"formal": ["어르신께서 잡수시고 계십니다."], "casual": ["할머니 많이 잡수셔."], "short": ["잡수세요"]}, "dialogue": {"context": "명절에 할머니 댁에서", "dialogue": [{"speaker": "A", "text": "할머니, 이거 맛있어요. 많이 잡수세요.", "romanization": "halmeoni, igeo masisseoyo. mani japseuseyo.", "translation": "Grandma, this is delicious. Please eat a lot."}, {"speaker": "B", "text": "그래, 너도 많이 먹어라.", "romanization": "geurae, neodo mani meogeora.", "translation": "Okay, you eat a lot too."}]}}, "en": {"word": "japsusida (to eat — highest honorific)", "explanation": "The highest honorific form of ''to eat'' (먹다) in Korean. Used when referring to elders eating, especially grandparents or very senior people. It is a step above ''드시다'' (deusida) in formality.", "examples": {"beginner": "할머니, 많이 잡수세요 (Grandma, please eat a lot).", "intermediate": "어르신께서 식사를 잡수시고 계십니다 (The elder is having a meal).", "advanced": "''잡수시다'' is the highest honorific form of ''먹다'', above ''드시다''.", "master": "In modern Korean, ''잡수시다'' is mainly reserved for elderly people, while ''드시다'' is more commonly used in everyday honorific speech."}, "variations": {"formal": ["The elder is eating (잡수시고 계십니다)."], "casual": ["Grandma, please eat up."], "short": ["japseuseyo"]}, "dialogue": {"context": "At grandma''s house during a holiday", "dialogue": [{"speaker": "A", "text": "Grandma, this is delicious. Please eat a lot.", "romanization": "", "translation": "할머니, 이거 맛있어요. 많이 잡수세요."}, {"speaker": "B", "text": "Okay, you eat a lot too.", "romanization": "", "translation": "그래, 너도 많이 먹어라."}]}}}'),
  ('jumusida', '주무시다', 'jumusida', 'verb', 'honorifics', 'intermediate', 'common', '["honorifics", "verb", "formal", "elderly"]', '{"ko": {"word": "주무시다", "explanation": "''자다''의 높임말로, 웃어른이 잠을 주무실 때 사용하는 존경 표현입니다. 부모님이나 어르신께 ''안녕히 주무세요''라고 인사하는 것이 일반적입니다.", "examples": {"beginner": "안녕히 주무세요.", "intermediate": "아버지께서 일찍 주무셨습니다.", "advanced": "''주무시다''는 ''자다''의 존경어로, 높임의 대상이 잠자는 행위를 할 때 사용합니다.", "master": "''주무시다''는 주체 높임법에 해당하며, 잠자리에 드는 행위를 높여 표현합니다."}, "variations": {"formal": ["어머니께서 주무시고 계십니다."], "casual": ["아빠 잘 주무셔."], "short": ["주무세요"]}, "dialogue": {"context": "밤에 부모님께 인사할 때", "dialogue": [{"speaker": "A", "text": "엄마, 저 먼저 잘게요. 안녕히 주무세요.", "romanization": "eomma, jeo meonjeo jalgeyo. annyeonghi jumuseyo.", "translation": "Mom, I''ll go to bed first. Good night."}, {"speaker": "B", "text": "그래, 잘 자.", "romanization": "geurae, jal ja.", "translation": "Okay, sleep well."}]}}, "en": {"word": "jumusida (to sleep — honorific)", "explanation": "The honorific form of ''to sleep'' (자다) in Korean. Used when referring to elders sleeping. The phrase ''안녕히 주무세요'' (sleep well) is the standard polite way to say goodnight to elders.", "examples": {"beginner": "안녕히 주무세요 (Good night — honorific).", "intermediate": "아버지께서 일찍 주무셨습니다 (Father went to sleep early).", "advanced": "''주무시다'' is the honorific verb replacing ''자다'' when the subject is an elder.", "master": "''주무시다'' falls under subject honorification (주체 높임법), elevating the act of sleeping."}, "variations": {"formal": ["Mother is sleeping (주무시고 계십니다)."], "casual": ["Dad, sleep well."], "short": ["jumuseyo"]}, "dialogue": {"context": "Saying goodnight to parents", "dialogue": [{"speaker": "A", "text": "Mom, I''ll go to bed first. Good night.", "romanization": "", "translation": "엄마, 저 먼저 잘게요. 안녕히 주무세요."}, {"speaker": "B", "text": "Okay, sleep well.", "romanization": "", "translation": "그래, 잘 자."}]}}}'),
  ('doragasida', '돌아가시다', 'doragasida', 'verb', 'honorifics', 'advanced', 'uncommon', '["honorifics", "verb", "formal", "death", "sensitive"]', '{"ko": {"word": "돌아가시다", "explanation": "''죽다''의 높임말로, 존경하는 분이 세상을 떠나셨을 때 사용하는 완곡한 존경 표현입니다. 직접적으로 ''죽다''라고 하면 무례하므로, 반드시 높임말을 사용해야 합니다.", "examples": {"beginner": "할아버지께서 돌아가셨습니다.", "intermediate": "작년에 선생님께서 돌아가셨다는 소식을 들었습니다.", "advanced": "''돌아가시다''는 ''죽다''의 존경어로, 존경받는 사람의 사망을 높여 표현합니다.", "master": "한국어에서 죽음을 표현하는 높임 단계: 죽다(평서) → 돌아가다(높임) → 돌아가시다(존경) → 별세하시다(격식 존경)."}, "variations": {"formal": ["선생님께서 돌아가셨습니다."], "casual": ["할아버지 돌아가셨어."], "short": ["돌아가셨어요"]}, "dialogue": {"context": "슬픈 소식을 전할 때", "dialogue": [{"speaker": "A", "text": "어제 이웃집 할아버지께서 돌아가셨대요.", "romanization": "eoje iutjip harabeojikkeseo doragasyeotdaeyo.", "translation": "I heard the neighbor''s grandfather passed away yesterday."}, {"speaker": "B", "text": "정말요? 삼가 고인의 명복을 빕니다.", "romanization": "jeongmalyo? samga goini myeongbogeul bimnida.", "translation": "Really? May he rest in peace."}]}}, "en": {"word": "doragasida (to pass away — honorific)", "explanation": "The honorific euphemism for ''to die'' (죽다) in Korean. Used when respectfully referring to someone''s death. It is considered very rude to use ''죽다'' for elders or respected people; ''돌아가시다'' must be used instead.", "examples": {"beginner": "할아버지께서 돌아가셨습니다 (Grandfather passed away).", "intermediate": "작년에 선생님께서 돌아가셨다는 소식을 들었습니다 (I heard the teacher passed away last year).", "advanced": "''돌아가시다'' is the honorific form of ''죽다'', used to respectfully describe death.", "master": "Korean has multiple levels for expressing death: 죽다 (plain) → 돌아가다 (polite) → 돌아가시다 (honorific) → 별세하시다 (formal honorific)."}, "variations": {"formal": ["The teacher has passed away (돌아가셨습니다)."], "casual": ["Grandpa passed away."], "short": ["doragasyeosseoyo"]}, "dialogue": {"context": "Sharing sad news", "dialogue": [{"speaker": "A", "text": "I heard the neighbor''s grandfather passed away yesterday.", "romanization": "", "translation": "어제 이웃집 할아버지께서 돌아가셨대요."}, {"speaker": "B", "text": "Really? May he rest in peace.", "romanization": "", "translation": "정말요? 삼가 고인의 명복을 빕니다."}]}}}'),
  ('pyeonchaneuisida', '편찮으시다', 'pyeonchaneuisida', 'adjective', 'honorifics', 'advanced', 'uncommon', '["honorifics", "adjective", "formal", "health"]', '{"ko": {"word": "편찮으시다", "explanation": "''아프다''의 높임말로, 웃어른의 건강이 좋지 않으실 때 사용하는 존경 표현입니다. ''편찮다''에 존경의 ''-시-''가 결합된 형태입니다.", "examples": {"beginner": "할머니께서 편찮으세요.", "intermediate": "어머니께서 편찮으셔서 병원에 가셨습니다.", "advanced": "''편찮으시다''는 ''아프다''의 존경어로, 높임 대상의 건강 상태를 완곡하게 표현합니다.", "master": "''편찮다''는 ''편하지 않다''의 줄임말에서 유래한 완곡 표현으로, 직접적인 ''아프다'' 대신 사용합니다."}, "variations": {"formal": ["교수님께서 편찮으십니다."], "casual": ["할머니 편찮으셔."], "short": ["편찮으세요"]}, "dialogue": {"context": "어르신의 건강을 걱정할 때", "dialogue": [{"speaker": "A", "text": "할머니께서 요즘 편찮으시다고 들었어요.", "romanization": "halmeonikkeseo yojeum pyeonchaneuisidago deureosseoyo.", "translation": "I heard grandma hasn''t been feeling well lately."}, {"speaker": "B", "text": "네, 빨리 나으셨으면 좋겠어요.", "romanization": "ne, ppalli naeusyeosseumyeon jokesseoyo.", "translation": "Yes, I hope she gets better soon."}]}}, "en": {"word": "pyeonchaneuisida (to be unwell — honorific)", "explanation": "The honorific form of ''to be sick/unwell'' (아프다) in Korean. Used when speaking about an elder''s poor health. It combines ''편찮다'' (unwell, euphemism) with the honorific suffix ''-시-''.", "examples": {"beginner": "할머니께서 편찮으세요 (Grandma is unwell).", "intermediate": "어머니께서 편찮으셔서 병원에 가셨습니다 (Mother went to the hospital because she was unwell).", "advanced": "''편찮으시다'' is the honorific form of ''아프다'', used as a euphemism for an elder''s illness.", "master": "''편찮다'' derives from ''편하지 않다'' (not comfortable), a euphemistic expression used instead of the direct ''아프다''."}, "variations": {"formal": ["The professor is unwell (편찮으십니다)."], "casual": ["Grandma is not feeling well."], "short": ["pyeonchaneuseyo"]}, "dialogue": {"context": "Worrying about an elder''s health", "dialogue": [{"speaker": "A", "text": "I heard grandma hasn''t been feeling well lately.", "romanization": "", "translation": "할머니께서 요즘 편찮으시다고 들었어요."}, {"speaker": "B", "text": "Yes, I hope she gets better soon.", "romanization": "", "translation": "네, 빨리 나으셨으면 좋겠어요."}]}}}'),
  ('seonsaengnim', '선생님', 'seonsaengnim', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "title", "respect", "education", "daily-life"]', '{"ko": {"word": "선생님", "explanation": "교사를 부르는 존칭이자, 전문가나 윗사람을 높여 부를 때 사용하는 호칭입니다. 학교에서뿐 아니라 의사, 변호사 등 전문직 종사자에게도 사용합니다.", "examples": {"beginner": "선생님, 안녕하세요!", "intermediate": "선생님께서 숙제를 내주셨습니다.", "advanced": "''선생님''은 교육자뿐 아니라 의사, 변호사, 작가 등 전문가에게도 쓰이는 범용 존칭입니다.", "master": "''선생(先生)''은 원래 ''먼저 태어난 사람''이라는 뜻으로, 가르침을 주는 사람에 대한 존경을 담고 있습니다."}, "variations": {"formal": ["선생님께서 말씀하셨습니다."], "casual": ["선생님이 그랬어."], "short": ["쌤"]}, "dialogue": {"context": "학교에서 선생님께 질문할 때", "dialogue": [{"speaker": "A", "text": "선생님, 이 문제 어떻게 풀어요?", "romanization": "seonsaengnim, i munje eotteoke pureoyo?", "translation": "Teacher, how do I solve this problem?"}, {"speaker": "B", "text": "이건 먼저 공식을 적용해 보렴.", "romanization": "igeon meonjeo gongsiceul jeogyonghae boryeom.", "translation": "First try applying the formula."}]}}, "en": {"word": "seonsaengnim (teacher / sir / ma''am)", "explanation": "An honorific title meaning ''teacher'' but used far more broadly in Korean. It is used for teachers, doctors, lawyers, writers, and other professionals. It conveys deep respect and is one of the most common honorific titles.", "examples": {"beginner": "선생님, 안녕하세요! (Hello, teacher!).", "intermediate": "선생님께서 숙제를 내주셨습니다 (The teacher assigned homework).", "advanced": "''선생님'' is a general honorific used for educators, doctors, lawyers, and other professionals.", "master": "''선생 (先生)'' literally means ''one born before,'' reflecting respect for those who provide teachings."}, "variations": {"formal": ["The teacher has spoken (선생님께서 말씀하셨습니다)."], "casual": ["The teacher said so."], "short": ["ssaem (슬랭)"]}, "dialogue": {"context": "Asking a question at school", "dialogue": [{"speaker": "A", "text": "Teacher, how do I solve this problem?", "romanization": "", "translation": "선생님, 이 문제 어떻게 풀어요?"}, {"speaker": "B", "text": "First try applying the formula.", "romanization": "", "translation": "이건 먼저 공식을 적용해 보렴."}]}}}'),
  ('sajangnim', '사장님', 'sajangnim', 'noun', 'honorifics', 'intermediate', 'common', '["honorifics", "title", "business", "workplace"]', '{"ko": {"word": "사장님", "explanation": "회사의 최고 경영자를 높여 부르는 호칭입니다. 한국 직장 문화에서 직급에 ''님''을 붙여 부르는 것이 기본 예의이며, 식당이나 가게 주인에게도 사용합니다.", "examples": {"beginner": "사장님, 안녕하세요.", "intermediate": "사장님께서 회의를 소집하셨습니다.", "advanced": "''사장님''은 회사 대표뿐 아니라 식당, 가게 주인에게도 관용적으로 사용됩니다.", "master": "한국에서 ''사장님''은 실제 직급과 관계없이 사업주에 대한 범용 존칭으로 확대 사용됩니다."}, "variations": {"formal": ["사장님께서 결정하셨습니다."], "casual": ["사장님이 그랬어."], "short": ["사장님"]}, "dialogue": {"context": "직장에서 상사에게 보고할 때", "dialogue": [{"speaker": "A", "text": "사장님, 이번 프로젝트 보고서 준비됐습니다.", "romanization": "sajangnim, ibeon peurojekteu bogoseo junbidwaetseumnida.", "translation": "Sir, the project report is ready."}, {"speaker": "B", "text": "수고했어요. 내일 회의에서 발표해 주세요.", "romanization": "sugohaesseoyo. naeil hoeuieseo balpyohae juseyo.", "translation": "Good work. Please present it at tomorrow''s meeting."}]}}, "en": {"word": "sajangnim (boss / company president)", "explanation": "An honorific title for the head of a company or business owner. In Korean workplace culture, titles are always followed by ''님'' (-nim) as a sign of respect. Also used colloquially for restaurant or shop owners.", "examples": {"beginner": "사장님, 안녕하세요 (Hello, boss).", "intermediate": "사장님께서 회의를 소집하셨습니다 (The boss called a meeting).", "advanced": "''사장님'' is used not only for CEOs but also colloquially for restaurant and shop owners.", "master": "In Korea, ''사장님'' has expanded beyond its literal meaning to become a general honorific for any business owner."}, "variations": {"formal": ["The president has decided (사장님께서 결정하셨습니다)."], "casual": ["The boss said so."], "short": ["sajangnim"]}, "dialogue": {"context": "Reporting to the boss at work", "dialogue": [{"speaker": "A", "text": "Sir, the project report is ready.", "romanization": "", "translation": "사장님, 이번 프로젝트 보고서 준비됐습니다."}, {"speaker": "B", "text": "Good work. Please present it at tomorrow''s meeting.", "romanization": "", "translation": "수고했어요. 내일 회의에서 발표해 주세요."}]}}}'),
  ('bujangnim', '부장님', 'bujangnim', 'noun', 'honorifics', 'intermediate', 'common', '["honorifics", "title", "business", "workplace"]', '{"ko": {"word": "부장님", "explanation": "회사에서 부서의 장을 높여 부르는 호칭입니다. 한국 기업의 직급 체계에서 차장과 이사 사이에 위치하며, 부서를 총괄하는 중간 관리직입니다.", "examples": {"beginner": "부장님, 서류 확인해 주세요.", "intermediate": "부장님께서 오늘 출장을 가셨습니다.", "advanced": "''부장''은 한국 기업의 대표적인 직급으로, 과장-차장-부장-이사 순서로 올라갑니다.", "master": "한국 기업 문화에서 직급 호칭은 단순한 명칭이 아니라 상하관계와 예절의 핵심입니다."}, "variations": {"formal": ["부장님께서 승인하셨습니다."], "casual": ["부장님이 오케이 했어."], "short": ["부장님"]}, "dialogue": {"context": "회사에서 업무 보고할 때", "dialogue": [{"speaker": "A", "text": "부장님, 거래처에서 연락이 왔습니다.", "romanization": "bujangnim, georaecheeseo yeollagi watseumnida.", "translation": "Department head, we received a call from the client."}, {"speaker": "B", "text": "알겠습니다. 제가 직접 전화하겠습니다.", "romanization": "algetseumnida. jega jikjeop jeonhwahagetseumnida.", "translation": "I see. I''ll call them myself."}]}}, "en": {"word": "bujangnim (department head)", "explanation": "An honorific title for a department head in a Korean company. In the Korean corporate hierarchy, ''부장'' sits between ''차장'' (deputy manager) and ''이사'' (director). It is a mid-to-senior management position overseeing an entire department.", "examples": {"beginner": "부장님, 서류 확인해 주세요 (Department head, please check the documents).", "intermediate": "부장님께서 오늘 출장을 가셨습니다 (The department head went on a business trip today).", "advanced": "''부장'' is a key title in Korean corporate hierarchy: 과장 → 차장 → 부장 → 이사.", "master": "In Korean corporate culture, title-based address is not just naming — it is fundamental to hierarchy and etiquette."}, "variations": {"formal": ["The department head has approved it (부장님께서 승인하셨습니다)."], "casual": ["The department head okayed it."], "short": ["bujangnim"]}, "dialogue": {"context": "Reporting at the office", "dialogue": [{"speaker": "A", "text": "Department head, we received a call from the client.", "romanization": "", "translation": "부장님, 거래처에서 연락이 왔습니다."}, {"speaker": "B", "text": "I see. I''ll call them myself.", "romanization": "", "translation": "알겠습니다. 제가 직접 전화하겠습니다."}]}}}'),
  ('gwajangnim', '과장님', 'gwajangnim', 'noun', 'honorifics', 'intermediate', 'common', '["honorifics", "title", "business", "workplace"]', '{"ko": {"word": "과장님", "explanation": "회사에서 과(課)의 장을 높여 부르는 호칭입니다. 대리 위, 차장 아래의 직급으로, 실무 관리를 담당하는 중간 관리직입니다.", "examples": {"beginner": "과장님, 회의 시간이 변경됐습니다.", "intermediate": "과장님께서 새 프로젝트를 맡으셨습니다.", "advanced": "''과장''은 대리-과장-차장-부장 직급 체계에서 실무 관리의 시작점입니다.", "master": "한국 드라마에서 ''과장님''은 직장 생활의 상징적 직급으로 자주 등장합니다."}, "variations": {"formal": ["과장님께서 지시하셨습니다."], "casual": ["과장님이 시켰어."], "short": ["과장님"]}, "dialogue": {"context": "직장에서 일정을 확인할 때", "dialogue": [{"speaker": "A", "text": "과장님, 내일 회의 몇 시인가요?", "romanization": "gwajangnim, naeil hoeui myeot siingayo?", "translation": "Section chief, what time is tomorrow''s meeting?"}, {"speaker": "B", "text": "오후 2시로 변경됐어요.", "romanization": "ohu dusiro byeongyeongdwaesseoyo.", "translation": "It''s been changed to 2 PM."}]}}, "en": {"word": "gwajangnim (section chief)", "explanation": "An honorific title for a section chief in a Korean company. It sits above ''대리'' (assistant manager) and below ''차장'' (deputy manager). This is a hands-on management role overseeing a section or team.", "examples": {"beginner": "과장님, 회의 시간이 변경됐습니다 (Section chief, the meeting time has changed).", "intermediate": "과장님께서 새 프로젝트를 맡으셨습니다 (The section chief took on a new project).", "advanced": "''과장'' marks the beginning of management in the 대리 → 과장 → 차장 → 부장 hierarchy.", "master": "In Korean dramas, ''과장님'' is an iconic workplace title that frequently appears as a symbol of office life."}, "variations": {"formal": ["The section chief has given instructions (과장님께서 지시하셨습니다)."], "casual": ["The section chief told us to."], "short": ["gwajangnim"]}, "dialogue": {"context": "Checking the schedule at work", "dialogue": [{"speaker": "A", "text": "Section chief, what time is tomorrow''s meeting?", "romanization": "", "translation": "과장님, 내일 회의 몇 시인가요?"}, {"speaker": "B", "text": "It''s been changed to 2 PM.", "romanization": "", "translation": "오후 2시로 변경됐어요."}]}}}'),
  ('daerinim', '대리님', 'daerinim', 'noun', 'honorifics', 'intermediate', 'common', '["honorifics", "title", "business", "workplace"]', '{"ko": {"word": "대리님", "explanation": "회사에서 사원 바로 위의 직급을 높여 부르는 호칭입니다. 한국 기업 직급 체계의 첫 번째 승진 단계로, 실무를 수행하면서 후배를 지도하는 역할입니다.", "examples": {"beginner": "대리님, 이 파일 확인해 주세요.", "intermediate": "김대리님께서 보고서를 작성해 주셨습니다.", "advanced": "''대리''는 사원에서 첫 번째로 올라가는 직급으로, 보통 입사 3~4년 차에 달성합니다.", "master": "최근 한국 기업들은 직급 간소화로 ''대리''를 폐지하고 ''매니저'' 등으로 통합하는 추세입니다."}, "variations": {"formal": ["대리님께서 처리해 주셨습니다."], "casual": ["대리님이 해줬어."], "short": ["대리님"]}, "dialogue": {"context": "신입 사원이 선배에게 도움을 요청할 때", "dialogue": [{"speaker": "A", "text": "대리님, 이 보고서 양식이 맞는지 봐주실 수 있나요?", "romanization": "daerinim, i bogoseo yangsigi manneungi bwajusil su innayo?", "translation": "Assistant manager, could you check if this report format is correct?"}, {"speaker": "B", "text": "네, 잠깐만요. 같이 봅시다.", "romanization": "ne, jamkkanmanyo. gachi bopsida.", "translation": "Sure, just a moment. Let''s look at it together."}]}}, "en": {"word": "daerinim (assistant manager)", "explanation": "An honorific title for an assistant manager in a Korean company. It is the first promotion level above ''사원'' (staff), typically achieved 3-4 years after joining. The role involves hands-on work while mentoring junior staff.", "examples": {"beginner": "대리님, 이 파일 확인해 주세요 (Assistant manager, please check this file).", "intermediate": "김대리님께서 보고서를 작성해 주셨습니다 (Assistant Manager Kim wrote the report).", "advanced": "''대리'' is the first promotion from ''사원'', typically after 3-4 years.", "master": "Recently, many Korean companies are simplifying titles, replacing ''대리'' with unified titles like ''manager''."}, "variations": {"formal": ["The assistant manager handled it (대리님께서 처리해 주셨습니다)."], "casual": ["The assistant manager did it for us."], "short": ["daerinim"]}, "dialogue": {"context": "A new employee asking a senior for help", "dialogue": [{"speaker": "A", "text": "Assistant manager, could you check if this report format is correct?", "romanization": "", "translation": "대리님, 이 보고서 양식이 맞는지 봐주실 수 있나요?"}, {"speaker": "B", "text": "Sure, just a moment. Let''s look at it together.", "romanization": "", "translation": "네, 잠깐만요. 같이 봅시다."}]}}}'),
  ('hyeong', '형', 'hyeong', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "family", "casual", "male", "korean-culture"]', '{"ko": {"word": "형", "explanation": "남자가 자기보다 나이 많은 남자를 부르는 호칭입니다. 친형제뿐 아니라 친한 선배나 친구 사이에서도 사용합니다. 한국 문화에서 나이와 성별에 따라 호칭이 달라지는 대표적인 예입니다.", "examples": {"beginner": "형, 같이 밥 먹자.", "intermediate": "우리 형은 대학생이에요.", "advanced": "''형''은 혈연관계뿐 아니라 친밀한 남성 선후배 관계에서도 사용됩니다.", "master": "한국 사회에서 ''형''이라고 부르는 것은 친밀감과 존경의 표현이며, 나이 서열 문화를 반영합니다."}, "variations": {"formal": ["형님께서 오셨습니다."], "casual": ["형, 뭐 해?"], "short": ["형"]}, "dialogue": {"context": "남동생이 형에게 말할 때", "dialogue": [{"speaker": "A", "text": "형, 오늘 뭐 해? 같이 축구하자.", "romanization": "hyeong, oneul mwo hae? gachi chukguhaja.", "translation": "Bro, what are you doing today? Let''s play soccer."}, {"speaker": "B", "text": "좋아, 3시에 공원에서 만나자.", "romanization": "joa, sesie gongwoneseo mannaja.", "translation": "Sure, let''s meet at the park at 3."}]}}, "en": {"word": "hyeong (older brother — used by males)", "explanation": "A term used by males to address an older male, whether a biological brother or a close older friend/senior. It reflects Korea''s age-based honorific system where different titles are used depending on the speaker''s and listener''s gender and age.", "examples": {"beginner": "형, 같이 밥 먹자 (Bro, let''s eat together).", "intermediate": "우리 형은 대학생이에요 (My older brother is a college student).", "advanced": "''형'' is used for both biological brothers and close older male friends/seniors.", "master": "Calling someone ''형'' in Korean society expresses both closeness and respect, reflecting Korea''s age-based hierarchy."}, "variations": {"formal": ["형님 has arrived (형님께서 오셨습니다)."], "casual": ["Hey bro, what''s up?"], "short": ["hyeong"]}, "dialogue": {"context": "A younger brother talking to his older brother", "dialogue": [{"speaker": "A", "text": "Bro, what are you doing today? Let''s play soccer.", "romanization": "", "translation": "형, 오늘 뭐 해? 같이 축구하자."}, {"speaker": "B", "text": "Sure, let''s meet at the park at 3.", "romanization": "", "translation": "좋아, 3시에 공원에서 만나자."}]}}}'),
  ('nuna', '누나', 'nuna', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "family", "casual", "male", "korean-culture"]', '{"ko": {"word": "누나", "explanation": "남자가 자기보다 나이 많은 여자를 부르는 호칭입니다. 친누나뿐 아니라 친한 여자 선배에게도 사용합니다. ''언니''는 여자가 쓰는 말이므로 혼동하지 않도록 주의해야 합니다.", "examples": {"beginner": "누나, 이거 뭐야?", "intermediate": "우리 누나는 요리를 잘해요.", "advanced": "''누나''는 남성 화자가 나이 많은 여성에게 사용하는 호칭으로, 혈연뿐 아니라 친밀한 관계에서도 씁니다.", "master": "''누나''와 ''언니''의 차이는 화자의 성별에 의해 결정됩니다: 남자 → 누나, 여자 → 언니."}, "variations": {"formal": ["누님께서 도와주셨습니다."], "casual": ["누나, 나 좀 도와줘."], "short": ["누나"]}, "dialogue": {"context": "남동생이 누나에게 부탁할 때", "dialogue": [{"speaker": "A", "text": "누나, 나 숙제 좀 도와줘.", "romanization": "nuna, na sukje jom dowajwo.", "translation": "Sis, help me with my homework."}, {"speaker": "B", "text": "뭔데? 어디 보여봐.", "romanization": "mwonde? eodi boyeobwa.", "translation": "What is it? Let me see."}]}}, "en": {"word": "nuna (older sister — used by males)", "explanation": "A term used by males to address an older female, whether a biological sister or a close older female friend/senior. Note that females use ''언니'' (eonni) instead. The distinction is based on the speaker''s gender.", "examples": {"beginner": "누나, 이거 뭐야? (Sis, what''s this?).", "intermediate": "우리 누나는 요리를 잘해요 (My older sister cooks well).", "advanced": "''누나'' is used by male speakers for older females, in both family and close social contexts.", "master": "The difference between ''누나'' and ''언니'' is determined by the speaker''s gender: males → 누나, females → 언니."}, "variations": {"formal": ["누님 helped us (누님께서 도와주셨습니다)."], "casual": ["Sis, help me out."], "short": ["nuna"]}, "dialogue": {"context": "A younger brother asking his older sister for help", "dialogue": [{"speaker": "A", "text": "Sis, help me with my homework.", "romanization": "", "translation": "누나, 나 숙제 좀 도와줘."}, {"speaker": "B", "text": "What is it? Let me see.", "romanization": "", "translation": "뭔데? 어디 보여봐."}]}}}'),
  ('oppa', '오빠', 'oppa', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "family", "casual", "female", "korean-culture"]', '{"ko": {"word": "오빠", "explanation": "여자가 자기보다 나이 많은 남자를 부르는 호칭입니다. 친오빠뿐 아니라 친한 남자 선배, 남자친구에게도 사용합니다. K-pop 팬들이 남자 아이돌을 부를 때도 자주 씁니다.", "examples": {"beginner": "오빠, 같이 가자.", "intermediate": "우리 오빠는 군대에 있어요.", "advanced": "''오빠''는 가족 호칭에서 출발했지만, 연인이나 친한 선배에게도 확대 사용됩니다.", "master": "K-pop 문화에서 ''오빠''는 팬이 남자 아이돌에게 친밀감을 표현하는 대표적 호칭이 되었습니다."}, "variations": {"formal": ["오빠가 먼저 도착하셨어요."], "casual": ["오빠, 뭐 해?"], "short": ["오빠"]}, "dialogue": {"context": "여동생이 오빠에게 말할 때", "dialogue": [{"speaker": "A", "text": "오빠, 오늘 엄마 생일인데 선물 같이 사러 가자.", "romanization": "oppa, oneul eomma saengirinde seonmul gachi sareo gaja.", "translation": "Oppa, it''s mom''s birthday today. Let''s go buy a gift together."}, {"speaker": "B", "text": "그래, 점심 먹고 나가자.", "romanization": "geurae, jeomsim meokgo nagaja.", "translation": "Sure, let''s go after lunch."}]}}, "en": {"word": "oppa (older brother — used by females)", "explanation": "A term used by females to address an older male, whether a biological brother, close older male friend, or boyfriend. It has become widely known globally through K-pop culture, where female fans use it to address male idols.", "examples": {"beginner": "오빠, 같이 가자 (Oppa, let''s go together).", "intermediate": "우리 오빠는 군대에 있어요 (My older brother is in the military).", "advanced": "''오빠'' started as a family term but has expanded to include boyfriends and close older males.", "master": "In K-pop culture, ''오빠'' has become the iconic term fans use to express closeness with male idols."}, "variations": {"formal": ["오빠 arrived first."], "casual": ["Oppa, what are you doing?"], "short": ["oppa"]}, "dialogue": {"context": "A younger sister talking to her older brother", "dialogue": [{"speaker": "A", "text": "Oppa, it''s mom''s birthday today. Let''s go buy a gift together.", "romanization": "", "translation": "오빠, 오늘 엄마 생일인데 선물 같이 사러 가자."}, {"speaker": "B", "text": "Sure, let''s go after lunch.", "romanization": "", "translation": "그래, 점심 먹고 나가자."}]}}}'),
  ('eonni', '언니', 'eonni', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "family", "casual", "female", "korean-culture"]', '{"ko": {"word": "언니", "explanation": "여자가 자기보다 나이 많은 여자를 부르는 호칭입니다. 친언니뿐 아니라 친한 여자 선배에게도 사용합니다. 남자가 나이 많은 여자를 부를 때는 ''누나''를 사용합니다.", "examples": {"beginner": "언니, 같이 쇼핑 가자.", "intermediate": "우리 언니는 대학교에 다녀요.", "advanced": "''언니''는 여성 화자가 나이 많은 여성에게 사용하는 호칭으로, 친밀한 관계에서 널리 쓰입니다.", "master": "''언니''는 한국 여성 문화에서 유대감과 친밀감을 나타내는 중요한 호칭입니다."}, "variations": {"formal": ["언니께서 먼저 오셨어요."], "casual": ["언니, 나 좀 도와줘."], "short": ["언니"]}, "dialogue": {"context": "여동생이 언니에게 말할 때", "dialogue": [{"speaker": "A", "text": "언니, 이 옷 어때? 나한테 어울려?", "romanization": "eonni, i ot eottae? nahante eoullyeo?", "translation": "Sis, how''s this outfit? Does it suit me?"}, {"speaker": "B", "text": "예쁘다! 그 색깔 잘 어울린다.", "romanization": "yeppeuda! geu saekkal jal eoulrinda.", "translation": "Pretty! That color looks great on you."}]}}, "en": {"word": "eonni (older sister — used by females)", "explanation": "A term used by females to address an older female, whether a biological sister or a close older female friend/senior. Males use ''누나'' (nuna) instead. This distinction is one of the key features of Korean''s gender-specific honorific system.", "examples": {"beginner": "언니, 같이 쇼핑 가자 (Sis, let''s go shopping).", "intermediate": "우리 언니는 대학교에 다녀요 (My older sister goes to university).", "advanced": "''언니'' is used by female speakers for older females, widely used in close relationships.", "master": "''언니'' is an important term in Korean female culture, expressing bonds and closeness."}, "variations": {"formal": ["언니 arrived first."], "casual": ["Sis, help me out."], "short": ["eonni"]}, "dialogue": {"context": "A younger sister talking to her older sister", "dialogue": [{"speaker": "A", "text": "Sis, how''s this outfit? Does it suit me?", "romanization": "", "translation": "언니, 이 옷 어때? 나한테 어울려?"}, {"speaker": "B", "text": "Pretty! That color looks great on you.", "romanization": "", "translation": "예쁘다! 그 색깔 잘 어울린다."}]}}}'),
  ('ajeossi', '아저씨', 'ajeossi', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "title", "casual", "age", "daily-life"]', '{"ko": {"word": "아저씨", "explanation": "중년 남성을 부르는 일반적인 호칭입니다. 삼촌이라는 뜻도 있지만, 일상에서는 이름을 모르는 중년 남성에게 널리 사용합니다. 젊은 사람에게 쓰면 실례가 될 수 있습니다.", "examples": {"beginner": "아저씨, 여기 물 한 잔 주세요.", "intermediate": "길에서 아저씨가 길을 알려주셨어요.", "advanced": "''아저씨''는 중년 남성에 대한 일반 호칭이지만, 젊은 남성에게 쓰면 나이 들어 보인다는 뜻으로 실례가 됩니다.", "master": "''아저씨''의 사용 범위는 세대에 따라 달라지며, 30대 남성에게 쓰면 불쾌감을 줄 수 있습니다."}, "variations": {"formal": ["아저씨께서 도와주셨습니다."], "casual": ["아저씨, 이거 얼마예요?"], "short": ["아저씨"]}, "dialogue": {"context": "시장에서 물건을 살 때", "dialogue": [{"speaker": "A", "text": "아저씨, 이 사과 한 봉지 얼마예요?", "romanization": "ajeossi, i sagwa han bongji eolmayeyo?", "translation": "Mister, how much is a bag of these apples?"}, {"speaker": "B", "text": "5천 원이요. 싸게 드릴게요.", "romanization": "ocheon woniyo. ssage deurilgeyo.", "translation": "5,000 won. I''ll give you a good price."}]}}, "en": {"word": "ajeossi (uncle / mister)", "explanation": "A common title for middle-aged men in Korean. While it literally means ''uncle,'' it is widely used to address any middle-aged man whose name you don''t know. Using it for younger men can be considered rude as it implies they look old.", "examples": {"beginner": "아저씨, 여기 물 한 잔 주세요 (Mister, a glass of water please).", "intermediate": "길에서 아저씨가 길을 알려주셨어요 (A man on the street gave me directions).", "advanced": "''아저씨'' is a general title for middle-aged men, but using it for younger men can be offensive.", "master": "The acceptable age range for ''아저씨'' varies by generation; using it for men in their 30s may cause offense."}, "variations": {"formal": ["The gentleman helped us (아저씨께서 도와주셨습니다)."], "casual": ["Mister, how much is this?"], "short": ["ajeossi"]}, "dialogue": {"context": "Buying something at a market", "dialogue": [{"speaker": "A", "text": "Mister, how much is a bag of these apples?", "romanization": "", "translation": "아저씨, 이 사과 한 봉지 얼마예요?"}, {"speaker": "B", "text": "5,000 won. I''ll give you a good price.", "romanization": "", "translation": "5천 원이요. 싸게 드릴게요."}]}}}'),
  ('ajumeoni', '아주머니', 'ajumeoni', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "title", "casual", "age", "daily-life"]', '{"ko": {"word": "아주머니", "explanation": "중년 여성을 부르는 일반적인 호칭입니다. ''아줌마''보다 정중한 표현이며, 이름을 모르는 중년 여성에게 사용합니다. 젊은 여성에게 사용하면 실례가 될 수 있습니다.", "examples": {"beginner": "아주머니, 감사합니다.", "intermediate": "옆집 아주머니께서 음식을 나눠주셨어요.", "advanced": "''아주머니''는 ''아줌마''의 정중한 형태로, 공적인 상황에서는 ''아주머니''를 사용하는 것이 좋습니다.", "master": "''아줌마''와 ''아주머니''의 어감 차이는 한국어 존비어 체계의 미묘한 예시입니다."}, "variations": {"formal": ["아주머니께서 친절히 안내해 주셨습니다."], "casual": ["아줌마, 이거 주세요."], "short": ["아주머니"]}, "dialogue": {"context": "식당에서 주문할 때", "dialogue": [{"speaker": "A", "text": "아주머니, 여기 김치찌개 하나 주세요.", "romanization": "ajumeoni, yeogi gimchijjigae hana juseyo.", "translation": "Ma''am, one kimchi stew please."}, {"speaker": "B", "text": "네, 잠깐만 기다리세요.", "romanization": "ne, jamkkanman gidariseyo.", "translation": "Sure, please wait a moment."}]}}, "en": {"word": "ajumeoni (aunt / ma''am)", "explanation": "A polite title for middle-aged women in Korean. It is the more respectful form of ''아줌마'' (ajumma). Used to address middle-aged women whose name you don''t know. Like ''아저씨'', using it for younger women can be considered rude.", "examples": {"beginner": "아주머니, 감사합니다 (Thank you, ma''am).", "intermediate": "옆집 아주머니께서 음식을 나눠주셨어요 (The neighbor lady shared food with us).", "advanced": "''아주머니'' is the polite form of ''아줌마''; in formal situations, ''아주머니'' is preferred.", "master": "The nuance difference between ''아줌마'' and ''아주머니'' is a subtle example of Korean''s honorific gradation."}, "variations": {"formal": ["The lady kindly guided us (아주머니께서 친절히 안내해 주셨습니다)."], "casual": ["아줌마, give me this please."], "short": ["ajumeoni"]}, "dialogue": {"context": "Ordering at a restaurant", "dialogue": [{"speaker": "A", "text": "Ma''am, one kimchi stew please.", "romanization": "", "translation": "아주머니, 여기 김치찌개 하나 주세요."}, {"speaker": "B", "text": "Sure, please wait a moment.", "romanization": "", "translation": "네, 잠깐만 기다리세요."}]}}}'),
  ('harabeoji', '할아버지', 'harabeoji', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "family", "elderly", "respect"]', '{"ko": {"word": "할아버지", "explanation": "아버지의 아버지, 또는 노년 남성을 부르는 호칭입니다. 친할아버지뿐 아니라 나이 많은 남성 어르신에게도 사용합니다. 한국 문화에서 어른을 공경하는 마음이 담긴 호칭입니다.", "examples": {"beginner": "할아버지, 안녕하세요!", "intermediate": "할아버지께서 옛날이야기를 해주셨어요.", "advanced": "''할아버지''는 친조부뿐 아니라 나이 많은 남성 어르신에 대한 일반 호칭으로도 쓰입니다.", "master": "한국의 유교 전통에서 ''할아버지''는 가족의 최고 어른으로서 특별한 존경의 대상입니다."}, "variations": {"formal": ["할아버지께서 말씀하셨습니다."], "casual": ["할아버지, 나 왔어!"], "short": ["할아버지"]}, "dialogue": {"context": "명절에 할아버지 댁을 방문할 때", "dialogue": [{"speaker": "A", "text": "할아버지, 새해 복 많이 받으세요!", "romanization": "harabeoji, saehae bok mani badeuseyo!", "translation": "Grandpa, Happy New Year!"}, {"speaker": "B", "text": "그래, 우리 손주 왔구나. 많이 컸네.", "romanization": "geurae, uri sonju watguna. mani keonne.", "translation": "Oh, our grandchild is here. You''ve grown so much."}]}}, "en": {"word": "harabeoji (grandfather)", "explanation": "The Korean word for ''grandfather,'' also used as a respectful title for elderly men in general. In Korean culture, it reflects the deep respect for elders rooted in Confucian values.", "examples": {"beginner": "할아버지, 안녕하세요! (Hello, grandpa!).", "intermediate": "할아버지께서 옛날이야기를 해주셨어요 (Grandpa told us old stories).", "advanced": "''할아버지'' is used for both one''s grandfather and elderly men in general.", "master": "In Korea''s Confucian tradition, ''할아버지'' holds a special place as the most senior family figure deserving utmost respect."}, "variations": {"formal": ["Grandfather has spoken (할아버지께서 말씀하셨습니다)."], "casual": ["Grandpa, I''m here!"], "short": ["harabeoji"]}, "dialogue": {"context": "Visiting grandpa during a holiday", "dialogue": [{"speaker": "A", "text": "Grandpa, Happy New Year!", "romanization": "", "translation": "할아버지, 새해 복 많이 받으세요!"}, {"speaker": "B", "text": "Oh, our grandchild is here. You''ve grown so much.", "romanization": "", "translation": "그래, 우리 손주 왔구나. 많이 컸네."}]}}}'),
  ('halmeoni', '할머니', 'halmeoni', 'noun', 'honorifics', 'beginner', 'common', '["honorifics", "family", "elderly", "respect"]', '{"ko": {"word": "할머니", "explanation": "아버지의 어머니, 또는 노년 여성을 부르는 호칭입니다. 친할머니뿐 아니라 나이 많은 여성 어르신에게도 사용합니다. 한국 가정에서 할머니는 따뜻함과 사랑의 상징입니다.", "examples": {"beginner": "할머니, 사랑해요!", "intermediate": "할머니께서 맛있는 음식을 만들어 주셨어요.", "advanced": "''할머니''는 친조모뿐 아니라 나이 많은 여성 어르신에 대한 일반 호칭으로도 쓰입니다.", "master": "한국 문화에서 ''할머니''는 가족의 정서적 중심으로, 손주에 대한 무한한 사랑을 상징합니다."}, "variations": {"formal": ["할머니께서 건강하시길 바랍니다."], "casual": ["할머니, 배고파!"], "short": ["할머니"]}, "dialogue": {"context": "할머니 댁에서 식사할 때", "dialogue": [{"speaker": "A", "text": "할머니, 이 음식 정말 맛있어요!", "romanization": "halmeoni, i eumsik jeongmal masisseoyo!", "translation": "Grandma, this food is really delicious!"}, {"speaker": "B", "text": "그래? 더 먹어라, 많이 해놨다.", "romanization": "geurae? deo meogeora, mani haenwatda.", "translation": "Really? Eat more, I made a lot."}]}}, "en": {"word": "halmeoni (grandmother)", "explanation": "The Korean word for ''grandmother,'' also used as a respectful title for elderly women in general. In Korean families, grandmothers symbolize warmth, love, and care, often associated with home-cooked meals and affection for grandchildren.", "examples": {"beginner": "할머니, 사랑해요! (Grandma, I love you!).", "intermediate": "할머니께서 맛있는 음식을 만들어 주셨어요 (Grandma made delicious food for us).", "advanced": "''할머니'' is used for both one''s grandmother and elderly women in general.", "master": "In Korean culture, ''할머니'' represents the emotional center of the family, symbolizing boundless love for grandchildren."}, "variations": {"formal": ["We wish grandma good health (할머니께서 건강하시길 바랍니다)."], "casual": ["Grandma, I''m hungry!"], "short": ["halmeoni"]}, "dialogue": {"context": "Having a meal at grandma''s house", "dialogue": [{"speaker": "A", "text": "Grandma, this food is really delicious!", "romanization": "", "translation": "할머니, 이 음식 정말 맛있어요!"}, {"speaker": "B", "text": "Really? Eat more, I made a lot.", "romanization": "", "translation": "그래? 더 먹어라, 많이 해놨다."}]}}}'),
  ('honorifics-035', '어르신', 'eoreusin', 'noun', 'honorifics', 'intermediate', 'high', '["honorifics", "title", "formal", "elderly", "respect"]', '{"ko": "나이가 많은 분을 높여 부르는 말", "en": "Elder; senior (respectful term for an elderly person)"}'),
  ('honorifics-036', '귀하', 'gwiha', 'noun', 'honorifics', 'advanced', 'medium', '["honorifics", "title", "very-formal", "letter", "business"]', '{"ko": "편지나 공문에서 상대방을 높여 부르는 말", "en": "Esteemed person; Dear Sir/Madam (used in letters and official documents)"}'),
  ('honorifics-037', '폐하', 'pyeha', 'noun', 'honorifics', 'advanced', 'low', '["honorifics", "title", "royal", "historical"]', '{"ko": "임금을 가장 높여 부르는 말", "en": "Your Majesty (highest royal honorific for a king or emperor)"}'),
  ('honorifics-038', '전하', 'jeonha', 'noun', 'honorifics', 'advanced', 'low', '["honorifics", "title", "royal", "historical"]', '{"ko": "왕세자나 왕족을 높여 부르는 말", "en": "Your Highness (royal honorific for a prince or royal family member)"}'),
  ('honorifics-039', '각하', 'gakha', 'noun', 'honorifics', 'advanced', 'low', '["honorifics", "title", "political", "historical"]', '{"ko": "대통령이나 고위 관직자를 높여 부르는 말", "en": "Your Excellency (honorific for a president or high-ranking official)"}'),
  ('honorifics-040', '-시-', 'si', 'particle', 'honorifics', 'beginner', 'very-high', '["honorifics", "grammar", "respect", "essential"]', '{"ko": "동사나 형용사에 붙어 주어를 높이는 선어말 어미", "en": "Honorific infix added to verbs/adjectives to show respect to the subject"}'),
  ('honorifics-041', '-께서', 'kkeseo', 'particle', 'honorifics', 'intermediate', 'high', '["honorifics", "grammar", "formal", "subject"]', '{"ko": "''이/가''의 높임말로, 주어를 높일 때 쓰는 조사", "en": "Honorific subject marker (respectful equivalent of 이/가)"}'),
  ('honorifics-042', '-께', 'kke', 'particle', 'honorifics', 'intermediate', 'high', '["honorifics", "grammar", "formal", "dative"]', '{"ko": "''에게''의 높임말로, 높여야 할 대상에게 쓰는 조사", "en": "Honorific dative particle meaning ''to/for'' (respectful equivalent of 에게)"}'),
  ('honorifics-043', '저', 'jeo', 'pronoun', 'honorifics', 'beginner', 'very-high', '["honorifics", "pronoun", "humble", "formal"]', '{"ko": "''나''의 낮춤말로, 윗사람 앞에서 자신을 가리키는 말", "en": "I/me (humble form, used when speaking to someone of higher status)"}'),
  ('honorifics-044', '저희', 'jeohui', 'pronoun', 'honorifics', 'beginner', 'high', '["honorifics", "pronoun", "humble", "formal"]', '{"ko": "''우리''의 낮춤말로, 윗사람 앞에서 자기 쪽을 가리키는 말", "en": "We/our (humble form, used when speaking to someone of higher status)"}'),
  ('honorifics-045', '여쭈다', 'yeojjuda', 'verb', 'honorifics', 'advanced', 'medium', '["honorifics", "verb", "humble", "formal"]', '{"ko": "''묻다''의 겸양어로, 윗사람에게 물을 때 쓰는 말", "en": "To ask (humble form, used when asking someone of higher status)"}'),
  ('honorifics-046', '뵙다', 'boepda', 'verb', 'honorifics', 'intermediate', 'high', '["honorifics", "verb", "humble", "formal", "greeting"]', '{"ko": "''보다''의 겸양어로, 윗사람을 만날 때 쓰는 말", "en": "To see/meet (humble form, used when meeting someone of higher status)"}'),
  ('honorifics-047', '모시다', 'mosida', 'verb', 'honorifics', 'intermediate', 'high', '["honorifics", "verb", "humble", "formal"]', '{"ko": "윗사람을 받들어 섬기거나 함께 가다", "en": "To serve, attend to, or accompany (someone of higher status)"}'),
  ('honorifics-048', '경어', 'gyeongeo', 'noun', 'honorifics', 'advanced', 'medium', '["honorifics", "concept", "academic", "linguistics"]', '{"ko": "상대방을 높여 말하는 언어 표현의 총칭", "en": "Respectful language; honorific speech (general term for polite/formal language)"}'),
  ('honorifics-049', '겸양어', 'gyeomyangeo', 'noun', 'honorifics', 'advanced', 'low', '["honorifics", "concept", "academic", "humble"]', '{"ko": "자신을 낮추어 상대방을 높이는 말", "en": "Humble language; self-deprecating speech used to elevate the listener"}'),
  ('honorifics-050', '호칭', 'hochin', 'noun', 'honorifics', 'intermediate', 'medium', '["honorifics", "concept", "social", "korean-culture"]', '{"ko": "사람을 부르거나 가리키는 이름이나 칭호", "en": "Form of address; title or name used to call or refer to someone"}');

-- seasons (60 entries)
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES
  ('bom', '봄', 'bom', 'noun', 'seasons', 'beginner', 'common', '["seasons", "spring", "nature", "beginning", "korean-culture"]', '{"ko": {"word": "봄", "explanation": "3월~5월의 계절입니다. 꽃이 피고 날씨가 따뜻해지는 시기입니다. 한국에서는 봄에 벚꽃 축제가 많이 열립니다.", "examples": {"beginner": "봄이 왔어요.", "intermediate": "봄에는 벚꽃이 아름다워요.", "advanced": "봄에는 미세먼지가 심해서 마스크가 필수이다.", "master": "봄은 만물이 소생하는 계절이라 새 학기, 새 출발의 시기이다."}, "variations": {"formal": ["봄이 되었습니다.", "봄 날씨입니다."], "casual": ["봄이다!", "봄 왔다."], "short": ["봄"]}, "dialogue": {"context": "따뜻한 봄날", "dialogue": [{"speaker": "A", "text": "드디어 봄이다! 꽃구경 가자.", "romanization": "deudieo bomida! kkotgugyeong gaja.", "translation": "Spring is finally here! Let''s go see flowers."}, {"speaker": "B", "text": "여의도 벚꽃 축제 가자!", "romanization": "yeoido beotkkot chukje gaja!", "translation": "Let''s go to the Yeouido cherry blossom festival!"}]}}, "en": {"word": "spring", "explanation": "The season from March to May, when flowers bloom and the weather warms up. Cherry blossom festivals are popular in Korea during spring.", "examples": {"beginner": "Spring has come.", "intermediate": "Cherry blossoms are beautiful in spring.", "advanced": "Fine dust is severe in spring, making masks essential.", "master": "Spring is the season of renewal — the time for new school terms and fresh starts."}, "variations": {"formal": ["Spring has arrived.", "It''s spring weather."], "casual": ["It''s spring!", "Spring''s here."], "short": ["spring"]}, "dialogue": {"context": "On a warm spring day", "dialogue": [{"speaker": "A", "text": "Spring is finally here! Let''s go see flowers.", "romanization": "", "translation": "드디어 봄이다! 꽃구경 가자."}, {"speaker": "B", "text": "Let''s go to the Yeouido cherry blossom festival!", "romanization": "", "translation": "여의도 벚꽃 축제 가자!"}]}}}'),
  ('yeoreum', '여름', 'yeoreum', 'noun', 'seasons', 'beginner', 'common', '["seasons", "summer", "hot", "vacation"]', '{"ko": {"word": "여름", "explanation": "6월~8월의 계절입니다. 무덥고 장마철이 있습니다. 한국에서는 삼복(초복, 중복, 말복)에 보양식을 먹는 문화가 있습니다.", "examples": {"beginner": "여름에 수영해요.", "intermediate": "한국의 여름은 덥고 습해요.", "advanced": "장마철에는 집중호우로 인한 피해가 발생하기도 한다.", "master": "삼복더위에 삼계탕을 먹는 것은 이열치열의 지혜이다."}, "variations": {"formal": ["여름이 되었습니다.", "한여름입니다."], "casual": ["여름이다!", "여름 왔다."], "short": ["여름"]}, "dialogue": {"context": "여름휴가 계획", "dialogue": [{"speaker": "A", "text": "이번 여름 휴가 어디 갈 거야?", "romanization": "ibeon yeoreum hyuga eodi gal geoya?", "translation": "Where are you going for summer vacation?"}, {"speaker": "B", "text": "제주도 가려고. 바다 보고 싶어.", "romanization": "jejudo garyeogo. bada bogo sipeo.", "translation": "I''m planning to go to Jeju. I want to see the ocean."}]}}, "en": {"word": "summer", "explanation": "The season from June to August, characterized by heat and monsoon rains. During the ''sambok'' (three hottest days), Koreans traditionally eat nourishing foods like samgyetang (ginseng chicken soup) — fighting heat with heat (이열치열).", "examples": {"beginner": "I swim in summer.", "intermediate": "Korean summers are hot and humid.", "advanced": "Heavy rain during monsoon season can cause significant damage.", "master": "Eating samgyetang during the hottest days embodies the wisdom of ''fighting fire with fire.''"}, "variations": {"formal": ["Summer has arrived.", "It''s midsummer."], "casual": ["It''s summer!", "Summer''s here."], "short": ["summer"]}, "dialogue": {"context": "Planning summer vacation", "dialogue": [{"speaker": "A", "text": "Where are you going for summer vacation?", "romanization": "", "translation": "이번 여름 휴가 어디 갈 거야?"}, {"speaker": "B", "text": "I''m planning to go to Jeju. I want to see the ocean.", "romanization": "", "translation": "제주도 가려고. 바다 보고 싶어."}]}}}'),
  ('gaeul', '가을', 'gaeul', 'noun', 'seasons', 'beginner', 'common', '["seasons", "autumn", "harvest", "beautiful"]', '{"ko": {"word": "가을", "explanation": "9월~11월의 계절입니다. 단풍이 들고 하늘이 높아지는 시기입니다. ''천고마비의 계절''(하늘은 높고 말은 살찌는 계절)이라고 합니다.", "examples": {"beginner": "가을에 단풍이 예뻐요.", "intermediate": "가을은 독서의 계절이에요.", "advanced": "설악산의 가을 단풍은 장관이다.", "master": "천고마비의 계절이라 불리는 가을은 수확과 풍요의 시기이다."}, "variations": {"formal": ["가을이 되었습니다.", "가을 날씨입니다."], "casual": ["가을이다!", "가을 왔다."], "short": ["가을"]}, "dialogue": {"context": "단풍 구경하면서", "dialogue": [{"speaker": "A", "text": "단풍이 정말 예쁘다.", "romanization": "danpungi jeongmal yeppeuda.", "translation": "The autumn leaves are really beautiful."}, {"speaker": "B", "text": "가을이 제일 좋아.", "romanization": "gaeuri jeil joa.", "translation": "I like autumn the most."}]}}, "en": {"word": "autumn / fall", "explanation": "The season from September to November, known for colorful foliage and high, clear skies. Korea calls it ''천고마비의 계절'' (season of high skies and fat horses), meaning ideal weather and bountiful harvest.", "examples": {"beginner": "The fall foliage is pretty in autumn.", "intermediate": "Autumn is the season for reading.", "advanced": "The autumn foliage at Seoraksan is spectacular.", "master": "Autumn, called the season of high skies and fat horses, is a time of harvest and abundance."}, "variations": {"formal": ["Autumn has arrived.", "It''s autumn weather."], "casual": ["It''s fall!", "Autumn''s here."], "short": ["autumn"]}, "dialogue": {"context": "Viewing autumn leaves", "dialogue": [{"speaker": "A", "text": "The autumn leaves are really beautiful.", "romanization": "", "translation": "단풍이 정말 예쁘다."}, {"speaker": "B", "text": "I like autumn the most.", "romanization": "", "translation": "가을이 제일 좋아."}]}}}'),
  ('gyeoul', '겨울', 'gyeoul', 'noun', 'seasons', 'beginner', 'common', '["seasons", "winter", "cold", "holiday"]', '{"ko": {"word": "겨울", "explanation": "12월~2월의 계절입니다. 춥고 눈이 오는 시기입니다. 한국의 겨울은 시베리아 기단의 영향으로 매우 춥습니다.", "examples": {"beginner": "겨울에 눈이 와요.", "intermediate": "겨울에는 따뜻한 옷을 입어야 해요.", "advanced": "한국의 겨울은 영하 10도 이하로 떨어지기도 한다.", "master": "한국의 온돌 문화는 추운 겨울을 나기 위한 선조들의 지혜이다."}, "variations": {"formal": ["겨울이 되었습니다.", "겨울 날씨입니다."], "casual": ["겨울이다!", "겨울 왔다."], "short": ["겨울"]}, "dialogue": {"context": "겨울 첫눈이 내릴 때", "dialogue": [{"speaker": "A", "text": "겨울이라 너무 추워.", "romanization": "gyeoura neomu chuwo.", "translation": "It''s so cold because it''s winter."}, {"speaker": "B", "text": "따뜻한 국물 먹으러 가자.", "romanization": "ttatteutan gungmul meogeureo gaja.", "translation": "Let''s go eat some hot soup."}]}}, "en": {"word": "winter", "explanation": "The season from December to February. Korean winters are very cold due to Siberian air masses. The traditional ondol (floor heating) system was developed to endure the harsh cold.", "examples": {"beginner": "It snows in winter.", "intermediate": "You need to wear warm clothes in winter.", "advanced": "Korean winters can drop below minus 10°C.", "master": "Korea''s ondol culture reflects the wisdom of ancestors in enduring cold winters."}, "variations": {"formal": ["Winter has arrived.", "It''s winter weather."], "casual": ["It''s winter!", "Winter''s here."], "short": ["winter"]}, "dialogue": {"context": "When the first snow falls in winter", "dialogue": [{"speaker": "A", "text": "It''s so cold because it''s winter.", "romanization": "", "translation": "겨울이라 너무 추워."}, {"speaker": "B", "text": "Let''s go eat some hot soup.", "romanization": "", "translation": "따뜻한 국물 먹으러 가자."}]}}}'),
  ('gyejeol', '계절', 'gyejeol', 'noun', 'seasons', 'beginner', 'common', '["seasons", "concept", "time", "nature"]', '{"ko": {"word": "계절", "explanation": "일 년을 기후 변화에 따라 나눈 시기를 말합니다. 봄, 여름, 가을, 겨울의 네 계절이 있습니다.", "examples": {"beginner": "좋아하는 계절이 뭐예요?", "intermediate": "한국은 사계절이 뚜렷해요.", "advanced": "계절이 바뀌면 옷차림도 달라진다.", "master": "지구 온난화로 인해 계절의 경계가 점점 모호해지고 있다."}, "variations": {"formal": ["계절이 바뀌었습니다.", "어떤 계절을 좋아하십니까?"], "casual": ["무슨 계절 좋아해?", "계절이 바뀌었네."], "short": ["계절"]}, "dialogue": {"context": "좋아하는 계절에 대해 이야기할 때", "dialogue": [{"speaker": "A", "text": "어떤 계절을 좋아해?", "romanization": "eotteon gyejeoreul joahae?", "translation": "Which season do you like?"}, {"speaker": "B", "text": "나는 가을이 좋아. 날씨가 시원해서.", "romanization": "naneun gaeuri joa. nalssiga siwonhaeseo.", "translation": "I like autumn. Because the weather is cool."}]}}, "en": {"word": "season", "explanation": "A division of the year based on climate changes. There are four seasons: spring, summer, autumn, and winter. Korea is known for having four distinct seasons.", "examples": {"beginner": "What is your favorite season?", "intermediate": "Korea has four distinct seasons.", "advanced": "When seasons change, clothing styles change too.", "master": "Due to global warming, the boundaries between seasons are becoming increasingly blurred."}, "variations": {"formal": ["The season has changed.", "Which season do you prefer?"], "casual": ["What season do you like?", "The season changed."], "short": ["season"]}, "dialogue": {"context": "Talking about favorite seasons", "dialogue": [{"speaker": "A", "text": "Which season do you like?", "romanization": "", "translation": "어떤 계절을 좋아해?"}, {"speaker": "B", "text": "I like autumn. Because the weather is cool.", "romanization": "", "translation": "나는 가을이 좋아. 날씨가 시원해서."}]}}}'),
  ('sagyejeol', '사계절', 'sagyejeol', 'noun', 'seasons', 'beginner', 'common', '["seasons", "concept", "korean-culture", "climate"]', '{"ko": {"word": "사계절", "explanation": "봄, 여름, 가을, 겨울의 네 계절을 통틀어 이르는 말입니다. 한국은 사계절이 뚜렷한 나라로 유명합니다.", "examples": {"beginner": "한국은 사계절이 있어요.", "intermediate": "사계절이 뚜렷한 나라가 좋아요.", "advanced": "사계절의 변화는 한국 문화와 음식에 큰 영향을 미쳤다.", "master": "비발디의 사계절은 자연의 변화를 음악으로 표현한 걸작이다."}, "variations": {"formal": ["사계절이 뚜렷합니다.", "사계절의 아름다움이 있습니다."], "casual": ["사계절 다 좋아!", "사계절이 있어서 좋다."], "short": ["사계절"]}, "dialogue": {"context": "한국의 기후에 대해 이야기할 때", "dialogue": [{"speaker": "A", "text": "한국은 사계절이 뚜렷하다며?", "romanization": "hanguguen sagyejeori tturyeotadamyeo?", "translation": "I heard Korea has four distinct seasons?"}, {"speaker": "B", "text": "응, 그래서 계절마다 다른 매력이 있어.", "romanization": "eung, geuraeseo gyejeolmada dareun maeryeogi isseo.", "translation": "Yes, so each season has its own charm."}]}}, "en": {"word": "four seasons", "explanation": "A term referring to all four seasons: spring, summer, autumn, and winter. Korea is famous for having four clearly distinct seasons, each influencing culture, food, and lifestyle.", "examples": {"beginner": "Korea has four seasons.", "intermediate": "I like countries with four distinct seasons.", "advanced": "The four seasons have greatly influenced Korean culture and cuisine.", "master": "Vivaldi''s Four Seasons is a masterpiece expressing nature''s changes through music."}, "variations": {"formal": ["The four seasons are distinct.", "There is beauty in all four seasons."], "casual": ["I love all four seasons!", "It''s great having four seasons."], "short": ["four seasons"]}, "dialogue": {"context": "Talking about Korea''s climate", "dialogue": [{"speaker": "A", "text": "I heard Korea has four distinct seasons?", "romanization": "", "translation": "한국은 사계절이 뚜렷하다며?"}, {"speaker": "B", "text": "Yes, so each season has its own charm.", "romanization": "", "translation": "응, 그래서 계절마다 다른 매력이 있어."}]}}}'),
  ('seollal', '설날', 'seollal', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "holiday", "korean-culture", "winter", "family"]', '{"ko": {"word": "설날", "explanation": "음력 1월 1일, 한국의 가장 큰 명절 중 하나입니다. 세배(새해 인사), 떡국 먹기, 세뱃돈 주고받기 등의 전통이 있습니다.", "examples": {"beginner": "설날에 떡국을 먹어요.", "intermediate": "설날에는 온 가족이 모여요.", "advanced": "설날 아침에 세배를 드리고 세뱃돈을 받는 것이 전통이다.", "master": "설날은 음력 기준이라 양력 날짜가 매년 달라진다."}, "variations": {"formal": ["설날을 축하합니다.", "새해 복 많이 받으세요."], "casual": ["설날이다!", "새해 복 많이 받아!"], "short": ["설날"]}, "dialogue": {"context": "설날 아침", "dialogue": [{"speaker": "A", "text": "할머니, 새해 복 많이 받으세요.", "romanization": "halmeoni, saehae bok mani badeuseyo.", "translation": "Grandma, Happy New Year."}, {"speaker": "B", "text": "그래, 너도 복 많이 받아. 세뱃돈 여기 있다.", "romanization": "geurae, neodo bok mani bada. sebaetdon yeogi itda.", "translation": "You too. Here''s your New Year''s money."}]}}, "en": {"word": "Lunar New Year (Seollal)", "explanation": "January 1st of the lunar calendar, one of Korea''s biggest holidays. Traditions include sebae (New Year''s bow), eating tteokguk (rice cake soup — aging one year), and giving/receiving sebaedon (New Year''s money).", "examples": {"beginner": "We eat tteokguk on Seollal.", "intermediate": "The whole family gathers on Seollal.", "advanced": "On Seollal morning, it''s tradition to bow to elders and receive New Year''s money.", "master": "Since Seollal follows the lunar calendar, the date in the solar calendar changes every year."}, "variations": {"formal": ["Happy Seollal.", "Happy New Year."], "casual": ["It''s Seollal!", "Happy New Year!"], "short": ["Seollal"]}, "dialogue": {"context": "Seollal morning", "dialogue": [{"speaker": "A", "text": "Grandma, Happy New Year.", "romanization": "", "translation": "할머니, 새해 복 많이 받으세요."}, {"speaker": "B", "text": "You too. Here''s your New Year''s money.", "romanization": "", "translation": "그래, 너도 복 많이 받아. 세뱃돈 여기 있다."}]}}}'),
  ('chuseok', '추석', 'chuseok', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "holiday", "korean-culture", "autumn", "family"]', '{"ko": {"word": "추석", "explanation": "음력 8월 15일, 한국의 추수감사절입니다. 설날과 함께 가장 큰 명절로, 성묘(조상 묘 방문), 송편 만들기, 가족 모임 등의 전통이 있습니다.", "examples": {"beginner": "추석에 송편을 먹어요.", "intermediate": "추석에는 고향에 가서 가족을 만나요.", "advanced": "추석 연휴에는 전국적으로 교통 체증이 심하다.", "master": "추석은 한 해의 수확에 감사하는 한국 고유의 명절이다."}, "variations": {"formal": ["즐거운 추석 되세요.", "추석을 축하합니다."], "casual": ["추석이다!", "즐거운 추석!"], "short": ["추석"]}, "dialogue": {"context": "추석 연휴 전", "dialogue": [{"speaker": "A", "text": "추석에 고향 가?", "romanization": "chuseoge gohyang ga?", "translation": "Are you going to your hometown for Chuseok?"}, {"speaker": "B", "text": "응, 부모님이 기다리고 계셔.", "romanization": "eung, bumonimi gidarigo gyesyeo.", "translation": "Yeah, my parents are waiting."}]}}, "en": {"word": "Chuseok (Korean Thanksgiving)", "explanation": "August 15th of the lunar calendar, Korea''s harvest festival. Along with Seollal, it''s the biggest holiday. Traditions include visiting ancestral graves (seongmyo), making songpyeon (rice cakes), and family gatherings.", "examples": {"beginner": "We eat songpyeon on Chuseok.", "intermediate": "On Chuseok, people go to their hometown to see family.", "advanced": "Traffic congestion is severe nationwide during the Chuseok holiday.", "master": "Chuseok is a uniquely Korean holiday to give thanks for the year''s harvest."}, "variations": {"formal": ["Have a happy Chuseok.", "Happy Chuseok."], "casual": ["It''s Chuseok!", "Happy Chuseok!"], "short": ["Chuseok"]}, "dialogue": {"context": "Before the Chuseok holiday", "dialogue": [{"speaker": "A", "text": "Are you going to your hometown for Chuseok?", "romanization": "", "translation": "추석에 고향 가?"}, {"speaker": "B", "text": "Yeah, my parents are waiting.", "romanization": "", "translation": "응, 부모님이 기다리고 계셔."}]}}}'),
  ('hansik', '한식', 'hansik', 'noun', 'seasons', 'advanced', 'uncommon', '["seasons", "holiday", "korean-culture", "spring", "traditional"]', '{"ko": {"word": "한식", "explanation": "동지로부터 105일째 되는 날로, 찬 음식을 먹는 전통 명절입니다. 조상의 묘를 찾아 성묘하고 잔디를 다듬는 날이기도 합니다. 보통 4월 5~6일경입니다.", "examples": {"beginner": "한식에는 찬 음식을 먹어요.", "intermediate": "한식에 성묘를 가는 사람이 많아요.", "advanced": "한식은 동지 후 105일째 되는 날로, 봄의 절기 중 하나이다.", "master": "한식의 유래는 중국 진나라 개자추의 이야기에서 비롯되었다고 전해진다."}, "variations": {"formal": ["한식날입니다.", "한식에 성묘하셨습니까?"], "casual": ["한식이야.", "한식에 성묘 갔어?"], "short": ["한식"]}, "dialogue": {"context": "한식날 가족과", "dialogue": [{"speaker": "A", "text": "내일 한식이니까 성묘 가자.", "romanization": "naeil hansikinikka seongmyo gaja.", "translation": "Tomorrow is Hansik, so let''s visit the graves."}, {"speaker": "B", "text": "알겠어. 아침 일찍 출발하자.", "romanization": "algesseo. achim iljjik chulbalhaja.", "translation": "Got it. Let''s leave early in the morning."}]}}, "en": {"word": "Cold Food Day (Hansik)", "explanation": "A traditional holiday falling on the 105th day after the winter solstice (around April 5-6). On this day, people eat cold food, visit ancestral graves, and tend to the grassy mounds. The tradition originates from an ancient Chinese story.", "examples": {"beginner": "We eat cold food on Hansik.", "intermediate": "Many people visit graves on Hansik.", "advanced": "Hansik falls on the 105th day after the winter solstice, marking a spring seasonal day.", "master": "The origin of Hansik is said to come from the story of Gae Ja-chu of the Jin Dynasty in China."}, "variations": {"formal": ["It is Hansik day.", "Did you visit the graves on Hansik?"], "casual": ["It''s Hansik.", "Did you visit graves on Hansik?"], "short": ["Hansik"]}, "dialogue": {"context": "With family on Hansik day", "dialogue": [{"speaker": "A", "text": "Tomorrow is Hansik, so let''s visit the graves.", "romanization": "", "translation": "내일 한식이니까 성묘 가자."}, {"speaker": "B", "text": "Got it. Let''s leave early in the morning.", "romanization": "", "translation": "알겠어. 아침 일찍 출발하자."}]}}}'),
  ('dano', '단오', 'dano', 'noun', 'seasons', 'advanced', 'uncommon', '["seasons", "holiday", "korean-culture", "summer", "traditional"]', '{"ko": {"word": "단오", "explanation": "음력 5월 5일로, 한국의 전통 명절입니다. 창포물에 머리 감기, 그네뛰기, 씨름 등의 전통 놀이가 있습니다. 강릉 단오제는 유네스코 무형문화유산입니다.", "examples": {"beginner": "단오에 그네를 타요.", "intermediate": "단오에는 창포물에 머리를 감아요.", "advanced": "강릉 단오제는 유네스코 무형문화유산으로 등재되었다.", "master": "단오는 양의 기운이 가장 강한 날로, 풍요와 건강을 기원하는 명절이다."}, "variations": {"formal": ["단오절입니다.", "단오를 맞이하였습니다."], "casual": ["단오다!", "단오라서 놀자!"], "short": ["단오"]}, "dialogue": {"context": "단오절에", "dialogue": [{"speaker": "A", "text": "오늘 단오라서 강릉 축제 간다.", "romanization": "oneul danoraseo gangneung chukje ganda.", "translation": "It''s Dano today, so I''m going to the Gangneung festival."}, {"speaker": "B", "text": "좋겠다! 씨름 구경해 봐.", "romanization": "joketta! ssireum gugyeonghae bwa.", "translation": "Lucky you! Check out the ssireum wrestling."}]}}, "en": {"word": "Dano (Dragon Boat Festival)", "explanation": "May 5th of the lunar calendar, a traditional Korean holiday. Customs include washing hair in changpo (iris) water, swinging on swings, and ssireum (Korean wrestling). The Gangneung Danoje is a UNESCO Intangible Cultural Heritage.", "examples": {"beginner": "We ride swings on Dano.", "intermediate": "On Dano, people wash their hair in iris water.", "advanced": "The Gangneung Danoje was inscribed as a UNESCO Intangible Cultural Heritage.", "master": "Dano, the day when yang energy is strongest, is a holiday for praying for abundance and health."}, "variations": {"formal": ["It is Dano.", "Dano has arrived."], "casual": ["It''s Dano!", "Let''s celebrate Dano!"], "short": ["Dano"]}, "dialogue": {"context": "On Dano day", "dialogue": [{"speaker": "A", "text": "It''s Dano today, so I''m going to the Gangneung festival.", "romanization": "", "translation": "오늘 단오라서 강릉 축제 간다."}, {"speaker": "B", "text": "Lucky you! Check out the ssireum wrestling.", "romanization": "", "translation": "좋겠다! 씨름 구경해 봐."}]}}}'),
  ('ipchun', '입춘', 'ipchun', 'noun', 'seasons', 'advanced', 'uncommon', '["seasons", "solar-term", "spring", "traditional"]', '{"ko": {"word": "입춘", "explanation": "24절기 중 첫 번째로, 봄이 시작되는 날입니다. 보통 양력 2월 4일경이며, ''입춘대길''(봄이 오니 크게 길하다)이라는 글귀를 대문에 붙이는 풍습이 있습니다.", "examples": {"beginner": "입춘이면 봄이 시작돼요.", "intermediate": "입춘에 ''입춘대길''을 대문에 붙여요.", "advanced": "입춘은 24절기의 첫 번째 절기로 양력 2월 4일경이다.", "master": "입춘이 지나도 꽃샘추위가 이어지므로 봄을 체감하기엔 이른 시기이다."}, "variations": {"formal": ["입춘입니다.", "입춘이 지났습니다."], "casual": ["입춘이다!", "봄이 시작이래."], "short": ["입춘"]}, "dialogue": {"context": "입춘날", "dialogue": [{"speaker": "A", "text": "오늘 입춘이래. 봄이 시작이야.", "romanization": "oneul ipchunirae. bomi sijagjiya.", "translation": "They say today is Ipchun. Spring is starting."}, {"speaker": "B", "text": "근데 아직 추운데? 꽃샘추위인가 봐.", "romanization": "geunde ajik chuwunde? kkotsamchuwiinga bwa.", "translation": "But it''s still cold, right? Must be a late cold snap."}]}}, "en": {"word": "start of spring (Ipchun)", "explanation": "The first of the 24 solar terms, marking the beginning of spring (around February 4). Koreans traditionally post the phrase ''입춘대길'' (great fortune with spring''s arrival) on their front doors.", "examples": {"beginner": "Spring starts with Ipchun.", "intermediate": "On Ipchun, people post ''입춘대길'' on their doors.", "advanced": "Ipchun is the first of the 24 solar terms, falling around February 4.", "master": "Even after Ipchun, late cold snaps continue, making it too early to feel spring."}, "variations": {"formal": ["It is Ipchun.", "Ipchun has passed."], "casual": ["It''s Ipchun!", "Spring is starting, they say."], "short": ["Ipchun"]}, "dialogue": {"context": "On Ipchun day", "dialogue": [{"speaker": "A", "text": "They say today is Ipchun. Spring is starting.", "romanization": "", "translation": "오늘 입춘이래. 봄이 시작이야."}, {"speaker": "B", "text": "But it''s still cold, right? Must be a late cold snap.", "romanization": "", "translation": "근데 아직 추운데? 꽃샘추위인가 봐."}]}}}'),
  ('haji', '하지', 'haji', 'noun', 'seasons', 'advanced', 'uncommon', '["seasons", "solar-term", "summer", "astronomy"]', '{"ko": {"word": "하지", "explanation": "24절기 중 하나로, 일 년 중 낮이 가장 긴 날입니다. 보통 양력 6월 21일경이며, 이날을 기점으로 낮의 길이가 줄어들기 시작합니다.", "examples": {"beginner": "하지는 낮이 가장 길어요.", "intermediate": "하지가 지나면 낮이 짧아져요.", "advanced": "하지는 태양이 북회귀선에 위치하는 날로, 북반구에서 낮이 가장 길다.", "master": "하지 무렵 장마가 시작되어 농사에 필요한 물을 충분히 공급받을 수 있다."}, "variations": {"formal": ["오늘이 하지입니다.", "하지가 지났습니다."], "casual": ["하지래!", "오늘 낮이 제일 길대."], "short": ["하지"]}, "dialogue": {"context": "하지에 대해 이야기할 때", "dialogue": [{"speaker": "A", "text": "오늘 하지라서 낮이 제일 길대.", "romanization": "oneul hajiraseo naji jeil gildae.", "translation": "Today is the summer solstice, so it''s the longest day."}, {"speaker": "B", "text": "그래서 저녁 8시인데도 밝구나.", "romanization": "geuraeseo jeonyeok yeodeolsiindedo balkguna.", "translation": "That''s why it''s still bright at 8 PM."}]}}, "en": {"word": "summer solstice (Haji)", "explanation": "One of the 24 solar terms, the longest day of the year (around June 21). After this day, daylight hours gradually decrease. In Korea, the monsoon season typically begins around this time.", "examples": {"beginner": "Haji has the longest daylight.", "intermediate": "After Haji, the days get shorter.", "advanced": "Haji is when the sun reaches the Tropic of Cancer, making it the longest day in the Northern Hemisphere.", "master": "The monsoon begins around Haji, providing ample water needed for farming."}, "variations": {"formal": ["Today is Haji.", "Haji has passed."], "casual": ["It''s Haji!", "Today''s the longest day, they say."], "short": ["Haji"]}, "dialogue": {"context": "Talking about the summer solstice", "dialogue": [{"speaker": "A", "text": "Today is the summer solstice, so it''s the longest day.", "romanization": "", "translation": "오늘 하지라서 낮이 제일 길대."}, {"speaker": "B", "text": "That''s why it''s still bright at 8 PM.", "romanization": "", "translation": "그래서 저녁 8시인데도 밝구나."}]}}}'),
  ('chubun', '추분', 'chubun', 'noun', 'seasons', 'advanced', 'uncommon', '["seasons", "solar-term", "autumn", "astronomy"]', '{"ko": {"word": "추분", "explanation": "24절기 중 하나로, 낮과 밤의 길이가 같아지는 가을의 절기입니다. 보통 양력 9월 23일경이며, 이후로 밤이 낮보다 길어집니다.", "examples": {"beginner": "추분에는 낮과 밤이 같아요.", "intermediate": "추분이 지나면 밤이 길어져요.", "advanced": "추분은 태양이 적도 위를 지나는 날로 낮과 밤의 길이가 같다.", "master": "추분을 기점으로 가을이 깊어지며 농작물의 수확이 본격화된다."}, "variations": {"formal": ["추분입니다.", "추분이 지났습니다."], "casual": ["추분이래.", "오늘부터 밤이 더 길대."], "short": ["추분"]}, "dialogue": {"context": "추분에 대해 이야기할 때", "dialogue": [{"speaker": "A", "text": "오늘 추분이라 낮과 밤이 같대.", "romanization": "oneul chubunira najgwa bami gatdae.", "translation": "Today is the autumn equinox, so day and night are equal."}, {"speaker": "B", "text": "이제부터 가을 날씨가 본격적이겠다.", "romanization": "ijebuteo gaeul nalssiga bongyeokjeogigetda.", "translation": "From now on, autumn weather will really set in."}]}}, "en": {"word": "autumn equinox (Chubun)", "explanation": "One of the 24 solar terms when day and night are of equal length (around September 23). After this day, nights become longer than days, and autumn deepens.", "examples": {"beginner": "Day and night are equal on Chubun.", "intermediate": "After Chubun, nights get longer.", "advanced": "Chubun is when the sun crosses the equator, making day and night equal.", "master": "From Chubun onward, autumn deepens and crop harvesting begins in earnest."}, "variations": {"formal": ["It is Chubun.", "Chubun has passed."], "casual": ["It''s Chubun.", "From today, nights are longer."], "short": ["Chubun"]}, "dialogue": {"context": "Talking about the autumn equinox", "dialogue": [{"speaker": "A", "text": "Today is the autumn equinox, so day and night are equal.", "romanization": "", "translation": "오늘 추분이라 낮과 밤이 같대."}, {"speaker": "B", "text": "From now on, autumn weather will really set in.", "romanization": "", "translation": "이제부터 가을 날씨가 본격적이겠다."}]}}}'),
  ('dongji', '동지', 'dongji', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "solar-term", "winter", "korean-culture", "food"]', '{"ko": {"word": "동지", "explanation": "24절기 중 하나로, 일 년 중 밤이 가장 긴 날입니다. 보통 양력 12월 22일경이며, 팥죽을 먹는 전통이 있습니다. ''작은 설''이라고도 불립니다.", "examples": {"beginner": "동지에 팥죽을 먹어요.", "intermediate": "동지는 밤이 가장 긴 날이에요.", "advanced": "동지에 팥죽을 먹는 것은 나쁜 기운을 쫓기 위한 풍습이다.", "master": "동지는 ''작은 설''이라 불리며, 이날을 기점으로 낮이 다시 길어진다."}, "variations": {"formal": ["동지입니다.", "동지팥죽 드셨습니까?"], "casual": ["동지다!", "팥죽 먹었어?"], "short": ["동지"]}, "dialogue": {"context": "동지날", "dialogue": [{"speaker": "A", "text": "오늘 동지니까 팥죽 먹자.", "romanization": "oneul dongjiinikka patjuk meokja.", "translation": "It''s Dongji today, so let''s eat red bean porridge."}, {"speaker": "B", "text": "좋아! 새알심 많이 넣어 줘.", "romanization": "joa! saealsim mani neoeo jwo.", "translation": "Great! Put lots of rice ball dumplings in it."}]}}, "en": {"word": "winter solstice (Dongji)", "explanation": "One of the 24 solar terms, the longest night of the year (around December 22). Koreans traditionally eat patjuk (red bean porridge) to ward off evil spirits. It''s also called ''little New Year.''", "examples": {"beginner": "We eat red bean porridge on Dongji.", "intermediate": "Dongji has the longest night of the year.", "advanced": "Eating red bean porridge on Dongji is a tradition to drive away evil spirits.", "master": "Dongji is called ''little New Year,'' and from this day onward, daylight hours begin to increase again."}, "variations": {"formal": ["It is Dongji.", "Did you eat Dongji red bean porridge?"], "casual": ["It''s Dongji!", "Did you eat red bean porridge?"], "short": ["Dongji"]}, "dialogue": {"context": "On Dongji day", "dialogue": [{"speaker": "A", "text": "It''s Dongji today, so let''s eat red bean porridge.", "romanization": "", "translation": "오늘 동지니까 팥죽 먹자."}, {"speaker": "B", "text": "Great! Put lots of rice ball dumplings in it.", "romanization": "", "translation": "좋아! 새알심 많이 넣어 줘."}]}}}'),
  ('jangmacheol', '장마철', 'jangmacheol', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "summer", "rain", "weather"]', '{"ko": {"word": "장마철", "explanation": "6월 말~7월 말까지 이어지는 긴 비의 계절입니다. 북태평양 고기압과 오호츠크해 고기압이 만나 장마전선을 형성합니다. 집중호우와 습한 날씨가 특징입니다.", "examples": {"beginner": "장마철에는 비가 많이 와요.", "intermediate": "장마철이라 우산을 꼭 가지고 다녀요.", "advanced": "장마철 집중호우로 인한 침수 피해가 매년 반복된다.", "master": "기후변화로 인해 장마 패턴이 변하고 있어 예측이 점점 어려워지고 있다."}, "variations": {"formal": ["장마철입니다.", "장마가 시작되었습니다."], "casual": ["장마다!", "비 또 온다."], "short": ["장마철"]}, "dialogue": {"context": "장마철에 비가 올 때", "dialogue": [{"speaker": "A", "text": "또 비야. 장마 언제 끝나?", "romanization": "tto biya. jangma eonje kkeunna?", "translation": "Rain again. When does the monsoon end?"}, {"speaker": "B", "text": "아직 2주 더 남았대. 우산 챙겨.", "romanization": "ajik iju deo namatdae. usan chaenggyeo.", "translation": "They say two more weeks. Bring an umbrella."}]}}, "en": {"word": "rainy season (monsoon)", "explanation": "The rainy season lasting from late June to late July, caused by the monsoon front formed where the North Pacific and Okhotsk Sea high-pressure systems meet. It features heavy rain and high humidity.", "examples": {"beginner": "It rains a lot during the rainy season.", "intermediate": "Always carry an umbrella during monsoon season.", "advanced": "Flood damage from heavy monsoon rains repeats every year.", "master": "Climate change is altering monsoon patterns, making predictions increasingly difficult."}, "variations": {"formal": ["It is monsoon season.", "The monsoon has started."], "casual": ["It''s monsoon season!", "It''s raining again."], "short": ["monsoon"]}, "dialogue": {"context": "When it rains during monsoon season", "dialogue": [{"speaker": "A", "text": "Rain again. When does the monsoon end?", "romanization": "", "translation": "또 비야. 장마 언제 끝나?"}, {"speaker": "B", "text": "They say two more weeks. Bring an umbrella.", "romanization": "", "translation": "아직 2주 더 남았대. 우산 챙겨."}]}}}'),
  ('hwanggeumyeonhyu', '황금연휴', 'hwanggeumyeonhyu', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "holiday", "travel", "modern"]', '{"ko": {"word": "황금연휴", "explanation": "공휴일과 주말이 이어져 긴 연휴가 되는 것을 말합니다. 특히 5월 초(근로자의 날, 어린이날, 부처님오신날 등)에 자주 발생합니다. 여행과 관광 수요가 급증합니다.", "examples": {"beginner": "황금연휴에 여행 가요.", "intermediate": "올해 황금연휴는 5일이에요.", "advanced": "황금연휴 기간에는 항공권과 숙소 가격이 크게 오른다.", "master": "황금연휴라는 개념은 일본의 ''골든위크''에서 유래한 것으로 알려져 있다."}, "variations": {"formal": ["황금연휴가 다가옵니다.", "황금연휴 계획이 있으신가요?"], "casual": ["황금연휴다!", "연휴에 뭐 할 거야?"], "short": ["황금연휴"]}, "dialogue": {"context": "황금연휴를 앞두고", "dialogue": [{"speaker": "A", "text": "이번 황금연휴 어디 갈 거야?", "romanization": "ibeon hwanggeumyeonhyu eodi gal geoya?", "translation": "Where are you going for the golden holiday week?"}, {"speaker": "B", "text": "부산 가려고. 벌써 숙소 예약했어.", "romanization": "busan garyeogo. beolsseo sukso yeyakaesseo.", "translation": "I''m going to Busan. I already booked accommodation."}]}}, "en": {"word": "golden holiday week", "explanation": "A long holiday period created when public holidays align with weekends. Common in early May (Workers'' Day, Children''s Day, Buddha''s Birthday). Travel demand surges during this period. The concept originates from Japan''s ''Golden Week.''", "examples": {"beginner": "We travel during golden holiday week.", "intermediate": "This year''s golden holiday is 5 days.", "advanced": "Flight and hotel prices surge during the golden holiday period.", "master": "The concept of golden holiday week is said to originate from Japan''s ''Golden Week.''"}, "variations": {"formal": ["The golden holiday is approaching.", "Do you have plans for the golden holiday?"], "casual": ["It''s golden holiday week!", "What are you doing for the holidays?"], "short": ["golden week"]}, "dialogue": {"context": "Before the golden holiday week", "dialogue": [{"speaker": "A", "text": "Where are you going for the golden holiday week?", "romanization": "", "translation": "이번 황금연휴 어디 갈 거야?"}, {"speaker": "B", "text": "I''m going to Busan. I already booked accommodation.", "romanization": "", "translation": "부산 가려고. 벌써 숙소 예약했어."}]}}}'),
  ('banghak', '방학', 'banghak', 'noun', 'seasons', 'beginner', 'common', '["seasons", "school", "vacation", "youth"]', '{"ko": {"word": "방학", "explanation": "학교에서 수업을 쉬는 기간입니다. 한국에서는 여름방학(7~8월)과 겨울방학(12~2월)이 있습니다. 학생들이 가장 기다리는 시기입니다.", "examples": {"beginner": "방학이에요! 학교 안 가요.", "intermediate": "방학 때 뭐 할 거예요?", "advanced": "방학 동안 학원을 다니는 학생이 많다.", "master": "방학은 학업 스트레스에서 벗어나 다양한 경험을 쌓을 수 있는 소중한 시간이다."}, "variations": {"formal": ["방학이 시작되었습니다.", "방학 계획이 있으십니까?"], "casual": ["방학이다!", "방학 때 뭐 해?"], "short": ["방학"]}, "dialogue": {"context": "방학이 시작될 때", "dialogue": [{"speaker": "A", "text": "드디어 방학이다! 뭐 할 거야?", "romanization": "deudieo banghagida! mwo hal geoya?", "translation": "It''s finally vacation! What are you going to do?"}, {"speaker": "B", "text": "나는 수영 배우려고. 너는?", "romanization": "naneun suyeong baeuryeogo. neoneun?", "translation": "I''m going to learn swimming. You?"}]}}, "en": {"word": "school vacation", "explanation": "A period when schools take a break from classes. In Korea, there is summer vacation (July-August) and winter vacation (December-February). It''s the most anticipated time for students.", "examples": {"beginner": "It''s vacation! No school.", "intermediate": "What will you do during vacation?", "advanced": "Many students attend hagwon (cram school) during vacation.", "master": "School vacation is precious time to escape academic stress and gain diverse experiences."}, "variations": {"formal": ["Vacation has started.", "Do you have vacation plans?"], "casual": ["It''s vacation!", "What are you doing for vacation?"], "short": ["vacation"]}, "dialogue": {"context": "When vacation starts", "dialogue": [{"speaker": "A", "text": "It''s finally vacation! What are you going to do?", "romanization": "", "translation": "드디어 방학이다! 뭐 할 거야?"}, {"speaker": "B", "text": "I''m going to learn swimming. You?", "romanization": "", "translation": "나는 수영 배우려고. 너는?"}]}}}'),
  ('hyuga', '휴가', 'hyuga', 'noun', 'seasons', 'beginner', 'common', '["seasons", "vacation", "work", "travel"]', '{"ko": {"word": "휴가", "explanation": "직장이나 군대에서 일정 기간 쉬는 것을 말합니다. 한국에서는 연차휴가, 여름휴가, 특별휴가 등이 있습니다. 대부분 여름에 휴가를 사용합니다.", "examples": {"beginner": "휴가 때 바다에 가요.", "intermediate": "이번 여름 휴가는 일주일이에요.", "advanced": "한국 직장인의 평균 연차 사용률은 아직 낮은 편이다.", "master": "일과 삶의 균형을 위해 휴가를 적극적으로 사용하는 문화가 확산되고 있다."}, "variations": {"formal": ["휴가를 신청합니다.", "휴가 계획이 있으십니까?"], "casual": ["휴가다!", "휴가 어디 가?"], "short": ["휴가"]}, "dialogue": {"context": "휴가 계획을 이야기할 때", "dialogue": [{"speaker": "A", "text": "휴가 언제 내?", "romanization": "hyuga eonje nae?", "translation": "When are you taking vacation?"}, {"speaker": "B", "text": "8월 첫째 주에 제주도 갈 거야.", "romanization": "palwol cheotjjae jue jejudo gal geoya.", "translation": "I''m going to Jeju the first week of August."}]}}, "en": {"word": "vacation / leave", "explanation": "Time off from work or military service. In Korea, types include annual leave, summer vacation, and special leave. Most Koreans take their vacation in summer.", "examples": {"beginner": "I go to the beach on vacation.", "intermediate": "This summer vacation is one week.", "advanced": "The average annual leave usage rate for Korean workers is still relatively low.", "master": "A culture of actively using vacation for work-life balance is spreading."}, "variations": {"formal": ["I''m requesting vacation.", "Do you have vacation plans?"], "casual": ["It''s vacation!", "Where are you going on vacation?"], "short": ["vacation"]}, "dialogue": {"context": "Talking about vacation plans", "dialogue": [{"speaker": "A", "text": "When are you taking vacation?", "romanization": "", "translation": "휴가 언제 내?"}, {"speaker": "B", "text": "I''m going to Jeju the first week of August.", "romanization": "", "translation": "8월 첫째 주에 제주도 갈 거야."}]}}}'),
  ('kkotnori', '꽃놀이', 'kkotnori', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "spring", "leisure", "korean-culture"]', '{"ko": {"word": "꽃놀이", "explanation": "봄에 꽃이 핀 곳에 가서 꽃을 감상하며 노는 것을 말합니다. 한국에서는 벚꽃, 개나리, 진달래 등을 보며 봄을 즐깁니다. 여의도, 석촌호수, 경주 등이 유명합니다.", "examples": {"beginner": "봄에 꽃놀이 가요.", "intermediate": "주말에 꽃놀이 가려고 해요.", "advanced": "벚꽃 시즌에는 꽃놀이 인파로 교통이 마비된다.", "master": "꽃놀이는 일본의 하나미(花見)와 유사하지만, 한국만의 독특한 문화적 맥락이 있다."}, "variations": {"formal": ["꽃놀이를 다녀왔습니다.", "꽃놀이 가실 계획이 있으신가요?"], "casual": ["꽃놀이 가자!", "꽃구경 갈래?"], "short": ["꽃놀이"]}, "dialogue": {"context": "봄에 꽃놀이를 계획할 때", "dialogue": [{"speaker": "A", "text": "이번 주말에 꽃놀이 갈래?", "romanization": "ibeon jumale kkotnori gallae?", "translation": "Do you want to go flower viewing this weekend?"}, {"speaker": "B", "text": "좋아! 여의도 벚꽃이 만개했대.", "romanization": "joa! yeoido beotkkochi mangaehaetdae.", "translation": "Sure! They say Yeouido cherry blossoms are in full bloom."}]}}, "en": {"word": "flower viewing", "explanation": "Going to places where flowers bloom in spring to enjoy and appreciate them. In Korea, people enjoy cherry blossoms, forsythia, and azaleas. Famous spots include Yeouido, Seokchon Lake, and Gyeongju.", "examples": {"beginner": "We go flower viewing in spring.", "intermediate": "I''m planning to go flower viewing this weekend.", "advanced": "During cherry blossom season, traffic is paralyzed by flower viewing crowds.", "master": "Flower viewing is similar to Japan''s hanami but has its own unique Korean cultural context."}, "variations": {"formal": ["I went flower viewing.", "Are you planning to go flower viewing?"], "casual": ["Let''s go flower viewing!", "Want to see flowers?"], "short": ["flower viewing"]}, "dialogue": {"context": "Planning flower viewing in spring", "dialogue": [{"speaker": "A", "text": "Do you want to go flower viewing this weekend?", "romanization": "", "translation": "이번 주말에 꽃놀이 갈래?"}, {"speaker": "B", "text": "Sure! They say Yeouido cherry blossoms are in full bloom.", "romanization": "", "translation": "좋아! 여의도 벚꽃이 만개했대."}]}}}'),
  ('danpungnori', '단풍놀이', 'danpungnori', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "autumn", "leisure", "korean-culture", "travel"]', '{"ko": {"word": "단풍놀이", "explanation": "가을에 단풍이 든 산이나 공원에 가서 단풍을 감상하며 노는 것을 말합니다. 설악산, 내장산, 남산 등이 유명한 단풍놀이 장소입니다.", "examples": {"beginner": "가을에 단풍놀이 가요.", "intermediate": "설악산으로 단풍놀이 가려고요.", "advanced": "단풍놀이 시즌에는 국립공원 주차장이 꽉 찬다.", "master": "단풍의 절정 시기는 기온에 따라 달라지며, 보통 설악산에서 시작해 남쪽으로 내려온다."}, "variations": {"formal": ["단풍놀이를 다녀왔습니다.", "단풍 구경 가실 건가요?"], "casual": ["단풍놀이 가자!", "단풍 보러 갈래?"], "short": ["단풍놀이"]}, "dialogue": {"context": "가을에 단풍놀이를 계획할 때", "dialogue": [{"speaker": "A", "text": "이번 가을에 단풍놀이 어디로 갈까?", "romanization": "ibeon gaeule danpungnori eodiro galkka?", "translation": "Where should we go leaf viewing this autumn?"}, {"speaker": "B", "text": "내장산이 좋대. 단풍이 정말 예쁘다고.", "romanization": "naejangsani jotdae. danpungi jeongmal yeppeudago.", "translation": "They say Naejangsan is great. The foliage is really beautiful."}]}}, "en": {"word": "autumn leaf viewing", "explanation": "Going to mountains or parks in autumn to enjoy the colorful fall foliage. Famous leaf viewing spots include Seoraksan, Naejangsan, and Namsan. The foliage peak starts from Seoraksan and moves southward.", "examples": {"beginner": "We go leaf viewing in autumn.", "intermediate": "I''m planning to go leaf viewing at Seoraksan.", "advanced": "During leaf viewing season, national park parking lots are completely full.", "master": "The peak foliage timing varies by temperature, typically starting at Seoraksan and moving southward."}, "variations": {"formal": ["I went leaf viewing.", "Are you going leaf viewing?"], "casual": ["Let''s go leaf viewing!", "Want to see fall colors?"], "short": ["leaf viewing"]}, "dialogue": {"context": "Planning leaf viewing in autumn", "dialogue": [{"speaker": "A", "text": "Where should we go leaf viewing this autumn?", "romanization": "", "translation": "이번 가을에 단풍놀이 어디로 갈까?"}, {"speaker": "B", "text": "They say Naejangsan is great. The foliage is really beautiful.", "romanization": "", "translation": "내장산이 좋대. 단풍이 정말 예쁘다고."}]}}}'),
