  ('deungsan', '등산', 'deungsan', 'noun', 'seasons', 'beginner', '4', '["seasons", "autumn", "exercise", "korean-culture"]', '{"ko": "산에 오르는 운동 또는 여가 활동", "en": "hiking"}'),
