  ('nagyeop', '낙엽', 'nagyeop', 'noun', 'seasons', 'intermediate', '3', '["seasons", "autumn", "nature", "poetic"]', '{"ko": "가을에 나무에서 떨어지는 잎", "en": "fallen leaves"}'),
  ('saessak', '새싹', 'saessak', 'noun', 'seasons', 'intermediate', '2', '["seasons", "spring", "nature", "growth"]', '{"ko": "봄에 새로 돋아나는 어린 싹", "en": "sprout"}'),
  ('maemi', '매미', 'maemi', 'noun', 'seasons', 'intermediate', '2', '["seasons", "summer", "insect", "sound"]', '{"ko": "여름에 시끄럽게 우는 곤충", "en": "cicada"}'),
  ('gwittturami', '귀뚜라미', 'gwittturami', 'noun', 'seasons', 'advanced', '2', '["seasons", "autumn", "insect", "sound"]', '{"ko": "가을밤에 울음소리를 내는 곤충", "en": "cricket"}'),
  ('jebi', '제비', 'jebi', 'noun', 'seasons', 'intermediate', '2', '["seasons", "spring", "bird", "korean-culture"]', '{"ko": "봄에 돌아오는 철새로 한국 전래 동화에 자주 등장하는 새", "en": "swallow"}'),
  ('keuriseumaseu', '크리스마스', 'keuriseumaseu', 'noun', 'seasons', 'beginner', '4', '["seasons", "winter", "holiday", "loanword"]', '{"ko": "12월 25일에 기념하는 서양의 명절", "en": "Christmas"}'),
  ('eorininal', '어린이날', 'eorininal', 'noun', 'seasons', 'beginner', '3', '["seasons", "spring", "holiday", "korean-culture", "children"]', '{"ko": "5월 5일, 어린이의 인격을 소중히 여기고 행복을 도모하는 날", "en": "Children''s Day"}'),
  ('gwangbokjeol', '광복절', 'gwangbokjeol', 'noun', 'seasons', 'intermediate', '2', '["seasons", "summer", "holiday", "history", "korean-culture"]', '{"ko": "8월 15일, 일본으로부터 해방된 것을 기념하는 국경일", "en": "Liberation Day"}'),
  ('hangeulnal', '한글날', 'hangeulnal', 'noun', 'seasons', 'beginner', '3', '["seasons", "autumn", "holiday", "korean-culture", "language"]', '{"ko": "10월 9일, 한글 창제를 기념하는 국경일", "en": "Hangul Day"}'),
  ('gaecheonjeol', '개천절', 'gaecheonjeol', 'noun', 'seasons', 'intermediate', '2', '["seasons", "autumn", "holiday", "history"]', '{"ko": "10월 3일, 단군이 고조선을 건국한 것을 기념하는 국경일", "en": "National Foundation Day"}'),
  ('samiljeol', '삼일절', 'samiljeol', 'noun', 'seasons', 'intermediate', '2', '["seasons", "spring", "holiday", "history"]', '{"ko": "3월 1일, 1919년 독립운동을 기념하는 국경일", "en": "March 1st Movement Day"}'),
  ('hyeonchungil', '현충일', 'hyeonchungil', 'noun', 'seasons', 'intermediate', '2', '["seasons", "summer", "holiday", "history", "solemn"]', '{"ko": "6월 6일, 나라를 위해 희생한 분들을 추모하는 날", "en": "Memorial Day"}'),
  ('ppepperodei', '빼빼로데이', 'ppepperodei', 'noun', 'seasons', 'intermediate', '2', '["seasons", "autumn", "modern", "korean-culture", "youth"]', '{"ko": "11월 11일, 빼빼로를 주고받는 한국의 기념일", "en": "Pepero Day"}'),
  ('hwaiteu-dei', '화이트데이', 'hwaiteu dei', 'noun', 'seasons', 'beginner', '3', '["seasons", "spring", "modern", "love", "loanword"]', '{"ko": "3월 14일, 밸런타인데이에 선물을 받은 사람이 답례하는 날", "en": "White Day"}'),
  ('ballentain-dei', '발렌타인데이', 'ballentain dei', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "winter", "modern", "love", "loanword"]', '{"ko": "연인에게 초콜릿을 선물하는 2월 14일의 기념일", "en": "Valentine''s Day"}'),
  ('seuseunguinal', '스승의날', 'seuseunguinal', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "spring", "holiday", "education", "korean-culture"]', '{"ko": "스승의 은혜에 감사하는 5월 15일의 기념일", "en": "Teachers'' Day"}'),
  ('bucheonimoshinnal', '부처님오신날', 'bucheonimoshinnal', 'noun', 'seasons', 'advanced', 'uncommon', '["seasons", "spring", "holiday", "religion", "korean-culture"]', '{"ko": "석가모니의 탄생을 기념하는 음력 4월 8일의 공휴일", "en": "Buddha''s Birthday"}'),
