  ('songpyeon', '송편', 'songpyeon', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "autumn", "food", "korean-culture", "chuseok"]', '{"ko": "추석에 먹는 반달 모양의 전통 떡", "en": "rice cake for Chuseok"}'),
