  ('patjuk', '팥죽', 'patjuk', 'noun', 'seasons', 'intermediate', 'uncommon', '["seasons", "winter", "food", "korean-culture", "traditional"]', '{"ko": "동지에 먹는 팥으로 만든 죽", "en": "red bean porridge for winter solstice"}'),
  ('naengmyeon', '냉면', 'naengmyeon', 'noun', 'seasons', 'beginner', 'high', '["seasons", "summer", "food", "korean-culture", "refreshing"]', '{"ko": "차가운 육수에 말아 먹는 면 요리", "en": "cold noodles"}'),
  ('samgyetang', '삼계탕', 'samgyetang', 'noun', 'seasons', 'beginner', 'high', '["seasons", "summer", "food", "korean-culture", "health"]', '{"ko": "삼복 더위에 보양식으로 먹는 닭백숙 요리", "en": "ginseng chicken soup"}'),
  ('sebae', '세배', 'sebae', 'noun', 'seasons', 'beginner', 'common', '["seasons", "winter", "korean-culture", "family", "seollal"]', '{"ko": "설날에 어른에게 하는 공손한 큰절", "en": "New Year''s bow"}'),
  ('sebaetdon', '세뱃돈', 'sebaetdon', 'noun', 'seasons', 'beginner', 'common', '["seasons", "winter", "korean-culture", "children", "seollal"]', '{"ko": "설날에 세배를 한 후 어른에게 받는 돈", "en": "New Year''s money"}'),
  ('hangawi', '한가위', 'hangawi', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "autumn", "korean-culture", "traditional"]', '{"ko": "추석의 순우리말 이름으로 음력 8월 15일", "en": "another name for Chuseok"}'),
  ('seongmyo', '성묘', 'seongmyo', 'noun', 'seasons', 'advanced', 'uncommon', '["seasons", "korean-culture", "family", "traditional", "respect"]', '{"ko": "명절에 조상의 무덤을 찾아가 돌보는 일", "en": "visiting ancestral graves"}'),
  ('charye', '차례', 'charye', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "korean-culture", "family", "traditional", "seollal"]', '{"ko": "명절에 조상에게 올리는 제사 의식", "en": "ancestral rites"}'),
  ('beotkkot-chukje', '벚꽃축제', 'beotkkot chukje', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "spring", "festival", "travel", "flower"]', '{"ko": "봄에 벚꽃이 피는 시기에 열리는 축제", "en": "cherry blossom festival"}'),
  ('haesuyokjang', '해수욕장', 'haesuyokjang', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "summer", "travel", "water", "vacation"]', '{"ko": "바닷물에서 수영할 수 있도록 시설을 갖춘 곳", "en": "beach/swimming area"}'),
  ('seukeiteu', '스케이트', 'seukeiteu', 'noun', 'seasons', 'beginner', 'common', '["seasons", "winter", "sports", "loanword", "fun"]', '{"ko": "얼음 위에서 날이 달린 신발을 신고 미끄러지듯 타는 운동", "en": "ice skating"}'),
  ('gimjang', '김장', 'gimjang', 'noun', 'seasons', 'intermediate', 'common', '["seasons", "autumn", "korean-culture", "food", "family"]', '{"ko": "겨울을 대비하여 대량의 김치를 담그는 한국 전통 풍습", "en": "kimchi making season"}'),
  ('daecheongso', '대청소', 'daecheongso', 'noun', 'seasons', 'beginner', 'common', '["seasons", "winter", "korean-culture", "home", "new-year"]', '{"ko": "연말에 집안을 깨끗이 정리하고 닦는 대규모 청소", "en": "big cleaning/year-end cleaning"}');

-- professions (50 entries)
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES
  ('uisa', '의사', 'uisa', 'noun', 'professions', 'beginner', 'common', '["professions", "medical", "korean-culture", "respect", "science"]', '{"ko": {"word": "의사", "explanation": "병을 치료하는 전문직입니다. 한국에서 의사는 ''선생님''이라는 호칭으로 불립니다. 한자어 ''醫師''에서 유래했습니다.", "examples": {"beginner": "의사가 되고 싶어요.", "intermediate": "의사 선생님께 진찰을 받았어요.", "advanced": "한국에서 의사는 가장 선호하는 직업 중 하나이다.", "master": "의사의 사회적 지위와 경제적 보상은 한국에서 최상위권이다."}, "variations": {"formal": ["의사입니다.", "의사 선생님이십니다."], "casual": ["의사야.", "의사 선생님."], "short": ["의사"]}, "dialogue": {"context": "병원에서", "dialogue": [{"speaker": "A", "text": "어디가 아프세요?", "romanization": "eodiga apeuseyo?", "translation": "Where does it hurt?"}, {"speaker": "B", "text": "머리가 아프고 열이 나요.", "romanization": "meoriga apeugo yeori nayo.", "translation": "I have a headache and a fever."}]}}, "en": {"word": "doctor", "explanation": "A medical professional who treats illness. In Korea, doctors are addressed as ''선생님'' (teacher/sir/ma''am) as a sign of respect. The word comes from the Chinese characters ''醫師''.", "examples": {"beginner": "I want to become a doctor.", "intermediate": "I was examined by the doctor.", "advanced": "Being a doctor is one of the most preferred professions in Korea.", "master": "Doctors hold top-tier social status and economic compensation in Korea."}, "variations": {"formal": ["I am a doctor.", "This is Doctor (name)."], "casual": ["I''m a doctor.", "The doctor."], "short": ["doctor"]}, "dialogue": {"context": "At the hospital", "dialogue": [{"speaker": "A", "text": "Where does it hurt?", "romanization": "", "translation": "어디가 아프세요?"}, {"speaker": "B", "text": "I have a headache and a fever.", "romanization": "", "translation": "머리가 아프고 열이 나요."}]}}}'),
  ('gyeongchal', '경찰', 'gyeongchal', 'noun', 'professions', 'beginner', 'common', '["professions", "public-service", "safety", "daily-life"]', '{"ko": {"word": "경찰", "explanation": "법과 질서를 유지하고 시민을 보호하는 공무원입니다. 한국 경찰의 긴급 전화번호는 112입니다.", "examples": {"beginner": "경찰이 왔어요.", "intermediate": "경찰에 신고했어요.", "advanced": "한국에서 경찰 긴급 전화번호는 112이다.", "master": "경찰은 시민의 안전과 사회 질서 유지를 책임진다."}, "variations": {"formal": ["경찰관입니다.", "경찰에 연락하겠습니다."], "casual": ["경찰 불러.", "경찰이다."], "short": ["경찰"]}, "dialogue": {"context": "길을 잃었을 때", "dialogue": [{"speaker": "A", "text": "저기 경찰관님한테 길 물어보자.", "romanization": "jeogi gyeongchalgwannimhante gil mureo boja.", "translation": "Let''s ask that police officer for directions."}, {"speaker": "B", "text": "좋은 생각이다.", "romanization": "joeun saenggagida.", "translation": "Good idea."}]}}, "en": {"word": "police", "explanation": "A public servant who maintains law and order and protects citizens. Korea''s emergency police number is 112.", "examples": {"beginner": "The police came.", "intermediate": "I reported it to the police.", "advanced": "In Korea, the police emergency number is 112.", "master": "The police are responsible for public safety and maintaining social order."}, "variations": {"formal": ["I am a police officer.", "I will contact the police."], "casual": ["Call the police.", "It''s the police."], "short": ["police"]}, "dialogue": {"context": "When lost", "dialogue": [{"speaker": "A", "text": "Let''s ask that police officer for directions.", "romanization": "", "translation": "저기 경찰관님한테 길 물어보자."}, {"speaker": "B", "text": "Good idea.", "romanization": "", "translation": "좋은 생각이다."}]}}}'),
  ('yorisa', '요리사', 'yorisa', 'noun', 'professions', 'beginner', 'common', '["professions", "food", "creative", "restaurant"]', '{"ko": {"word": "요리사", "explanation": "음식을 만드는 것이 직업인 사람입니다. ''셰프''라는 외래어도 많이 씁니다. 한국에서는 요리 예능 프로그램의 인기로 요리사에 대한 관심이 높아졌습니다.", "examples": {"beginner": "요리사가 되고 싶어요.", "intermediate": "이 식당의 요리사는 유명해요.", "advanced": "한식 요리사의 세계적 위상이 높아지고 있다.", "master": "요리사는 식재료의 특성을 이해하고 창의적으로 조합하는 예술가이다."}, "variations": {"formal": ["요리사입니다.", "주방장이십니다."], "casual": ["요리사야.", "셰프야."], "short": ["요리사"]}, "dialogue": {"context": "식당에서", "dialogue": [{"speaker": "A", "text": "이 음식 진짜 맛있다. 요리사가 누구야?", "romanization": "i eumsik jinjja masitda. yorisaga nuguya?", "translation": "This food is really delicious. Who''s the chef?"}, {"speaker": "B", "text": "유명한 한식 셰프래.", "romanization": "yumyeonghan hansik syepeurae.", "translation": "I heard it''s a famous Korean cuisine chef."}]}}, "en": {"word": "chef / cook", "explanation": "A professional who cooks food. The loanword ''셰프'' (chef) is also commonly used. Korean cooking shows have boosted public interest in the culinary profession.", "examples": {"beginner": "I want to become a chef.", "intermediate": "The chef at this restaurant is famous.", "advanced": "The global reputation of Korean cuisine chefs is rising.", "master": "A chef is an artist who understands ingredients and combines them creatively."}, "variations": {"formal": ["I am a chef.", "This is the head chef."], "casual": ["I''m a chef.", "The chef."], "short": ["chef"]}, "dialogue": {"context": "At a restaurant", "dialogue": [{"speaker": "A", "text": "This food is really delicious. Who''s the chef?", "romanization": "", "translation": "이 음식 진짜 맛있다. 요리사가 누구야?"}, {"speaker": "B", "text": "I heard it''s a famous Korean cuisine chef.", "romanization": "", "translation": "유명한 한식 셰프래."}]}}}'),
  ('hoesawon', '회사원', 'hoesawon', 'noun', 'professions', 'beginner', 'common', '["professions", "business", "workplace", "daily-life"]', '{"ko": {"word": "회사원", "explanation": "회사에 다니는 직장인입니다. 한국에서 가장 흔한 직업 형태로, ''직장인'', ''샐러리맨''이라고도 합니다.", "examples": {"beginner": "저는 회사원이에요.", "intermediate": "회사원은 보통 9시에 출근해요.", "advanced": "한국 회사원의 평균 근무 시간은 OECD 국가 중 상위권이다.", "master": "워라밸(work-life balance)을 중시하는 직장 문화가 확산되고 있다."}, "variations": {"formal": ["회사원입니다.", "직장인입니다."], "casual": ["회사 다녀.", "직장인이야."], "short": ["회사원"]}, "dialogue": {"context": "자기소개하면서", "dialogue": [{"speaker": "A", "text": "무슨 일 하세요?", "romanization": "museun il haseyo?", "translation": "What do you do for work?"}, {"speaker": "B", "text": "IT 회사에 다니고 있어요.", "romanization": "aithi hoesae danigo isseoyo.", "translation": "I work at an IT company."}]}}, "en": {"word": "office worker", "explanation": "A person who works at a company. It''s the most common type of employment in Korea. Also called ''직장인'' (worker) or colloquially ''salaryman.''", "examples": {"beginner": "I''m an office worker.", "intermediate": "Office workers usually start work at 9 AM.", "advanced": "Korean office workers'' average working hours rank among the highest in OECD countries.", "master": "A work culture emphasizing work-life balance (워라밸) is spreading."}, "variations": {"formal": ["I am an office worker.", "I am employed."], "casual": ["I work at a company.", "I''m a salaryman."], "short": ["office worker"]}, "dialogue": {"context": "Introducing yourself", "dialogue": [{"speaker": "A", "text": "What do you do for work?", "romanization": "", "translation": "무슨 일 하세요?"}, {"speaker": "B", "text": "I work at an IT company.", "romanization": "", "translation": "IT 회사에 다니고 있어요."}]}}}'),
  ('haksaeng', '학생', 'haksaeng', 'noun', 'professions', 'beginner', 'common', '["professions", "education", "youth", "daily-life", "beginner-essential"]', '{"ko": {"word": "학생", "explanation": "학교에서 공부하는 사람입니다. 한국의 교육 체계는 초등학교(6년), 중학교(3년), 고등학교(3년), 대학교(4년)입니다.", "examples": {"beginner": "저는 학생이에요.", "intermediate": "한국 학생들은 공부를 많이 해요.", "advanced": "한국의 교육열은 세계적으로 유명하다.", "master": "학생 시절은 인생에서 가장 귀중한 배움의 시기이다."}, "variations": {"formal": ["학생입니다.", "학생이십니까?"], "casual": ["학생이야.", "학생이야?"], "short": ["학생"]}, "dialogue": {"context": "처음 만나서", "dialogue": [{"speaker": "A", "text": "학생이세요?", "romanization": "haksaengiseyo?", "translation": "Are you a student?"}, {"speaker": "B", "text": "네, 대학교 2학년이에요.", "romanization": "ne, daehakgyo ihangnyeonieyo.", "translation": "Yes, I''m a second-year university student."}]}}, "en": {"word": "student", "explanation": "A person studying at a school. Korea''s education system consists of elementary school (6 years), middle school (3 years), high school (3 years), and university (4 years). Korea is known worldwide for its intense education culture.", "examples": {"beginner": "I''m a student.", "intermediate": "Korean students study a lot.", "advanced": "Korea''s passion for education is world-renowned.", "master": "The student years are the most precious period of learning in life."}, "variations": {"formal": ["I am a student.", "Are you a student?"], "casual": ["I''m a student.", "Are you a student?"], "short": ["student"]}, "dialogue": {"context": "Meeting for the first time", "dialogue": [{"speaker": "A", "text": "Are you a student?", "romanization": "", "translation": "학생이세요?"}, {"speaker": "B", "text": "Yes, I''m a second-year university student.", "romanization": "", "translation": "네, 대학교 2학년이에요."}]}}}'),
  ('seonsaengnim-jigeop', '선생님', 'seonsaengnim', 'noun', 'professions', 'beginner', 'common', '["professions", "education", "respect", "korean-culture"]', '{"ko": {"word": "선생님", "explanation": "학교에서 학생을 가르치는 사람입니다. 한국에서 ''선생님''은 교사뿐 아니라 의사, 변호사 등 전문직에게도 존경의 의미로 사용하는 호칭입니다.", "examples": {"beginner": "선생님, 안녕하세요.", "intermediate": "우리 선생님은 정말 친절하세요.", "advanced": "한국에서 선생님이라는 호칭은 존경의 표현이다.", "master": "선생님은 단순한 직업이 아니라 사회적 존경을 받는 호칭이다."}, "variations": {"formal": ["선생님이십니다.", "선생님께서 말씀하셨습니다."], "casual": ["선생님이야.", "우리 선생님."], "short": ["선생님"]}, "dialogue": {"context": "교실에서", "dialogue": [{"speaker": "A", "text": "선생님, 질문이 있어요.", "romanization": "seonsaengnim, jilmuni isseoyo.", "translation": "Teacher, I have a question."}, {"speaker": "B", "text": "네, 뭐가 궁금하니?", "romanization": "ne, mwoga gunggeumhani?", "translation": "Yes, what are you curious about?"}]}}, "en": {"word": "teacher", "explanation": "A person who teaches students at school. In Korea, ''선생님'' is not only used for teachers but also as a respectful title for professionals like doctors and lawyers.", "examples": {"beginner": "Hello, teacher.", "intermediate": "Our teacher is really kind.", "advanced": "In Korea, the title ''선생님'' is an expression of respect.", "master": "''선생님'' is not just a profession but a socially respected title."}, "variations": {"formal": ["This is the teacher.", "The teacher has spoken."], "casual": ["It''s the teacher.", "Our teacher."], "short": ["teacher"]}, "dialogue": {"context": "In the classroom", "dialogue": [{"speaker": "A", "text": "Teacher, I have a question.", "romanization": "", "translation": "선생님, 질문이 있어요."}, {"speaker": "B", "text": "Yes, what are you curious about?", "romanization": "", "translation": "네, 뭐가 궁금하니?"}]}}}'),
  ('gyosu', '교수', 'gyosu', 'noun', 'professions', 'intermediate', 'common', '["professions", "education", "academic", "university"]', '{"ko": {"word": "교수", "explanation": "대학교에서 학문을 연구하고 학생을 가르치는 사람입니다. 한국에서 교수는 높은 사회적 지위를 가지며, ''교수님''이라는 존칭으로 불립니다.", "examples": {"beginner": "교수님, 안녕하세요.", "intermediate": "그 교수님은 수업을 정말 잘 하세요.", "advanced": "한국 대학에서 교수가 되려면 박사 학위가 필수이다.", "master": "교수의 역할은 연구와 교육을 통해 학문 발전에 기여하는 것이다."}, "variations": {"formal": ["교수님이십니다.", "교수님께서 강의하십니다."], "casual": ["교수님이야.", "우리 교수님."], "short": ["교수"]}, "dialogue": {"context": "대학교에서", "dialogue": [{"speaker": "A", "text": "교수님, 논문 주제를 상담하고 싶어요.", "romanization": "gyosunim, nonmun jujereul sangdamhago sipeoyo.", "translation": "Professor, I''d like to discuss my thesis topic."}, {"speaker": "B", "text": "좋아요, 내일 연구실로 오세요.", "romanization": "joayo, naeil yeongusillo oseyo.", "translation": "Sure, come to my office tomorrow."}]}}, "en": {"word": "professor", "explanation": "A person who researches and teaches at a university. In Korea, professors hold high social status and are addressed as ''교수님'' (Professor) with the honorific suffix.", "examples": {"beginner": "Hello, Professor.", "intermediate": "That professor teaches really well.", "advanced": "In Korea, a doctoral degree is required to become a professor.", "master": "A professor''s role is to contribute to academic advancement through research and education."}, "variations": {"formal": ["This is the professor.", "The professor is giving a lecture."], "casual": ["It''s the professor.", "Our professor."], "short": ["professor"]}, "dialogue": {"context": "At the university", "dialogue": [{"speaker": "A", "text": "Professor, I''d like to discuss my thesis topic.", "romanization": "", "translation": "교수님, 논문 주제를 상담하고 싶어요."}, {"speaker": "B", "text": "Sure, come to my office tomorrow.", "romanization": "", "translation": "좋아요, 내일 연구실로 오세요."}]}}}'),
  ('ganhosa', '간호사', 'ganhosa', 'noun', 'professions', 'intermediate', 'common', '["professions", "medical", "hospital", "care"]', '{"ko": {"word": "간호사", "explanation": "병원에서 환자를 돌보고 의사를 보조하는 의료 전문직입니다. 한국에서 간호사는 국가 면허 시험을 통과해야 합니다.", "examples": {"beginner": "간호사가 주사를 놓았어요.", "intermediate": "간호사는 환자를 잘 돌봐요.", "advanced": "한국의 간호사 부족 문제는 심각한 사회 이슈이다.", "master": "간호사는 환자의 회복 과정에서 핵심적인 역할을 담당한다."}, "variations": {"formal": ["간호사입니다.", "간호사 선생님이십니다."], "casual": ["간호사야.", "간호사 선생님."], "short": ["간호사"]}, "dialogue": {"context": "병원에서", "dialogue": [{"speaker": "A", "text": "간호사 선생님, 열이 많이 나요.", "romanization": "ganhosa seonsaengnim, yeori mani nayo.", "translation": "Nurse, I have a high fever."}, {"speaker": "B", "text": "체온을 먼저 재볼게요.", "romanization": "cheoneul meonjeo jaevolgeyo.", "translation": "Let me take your temperature first."}]}}, "en": {"word": "nurse", "explanation": "A medical professional who cares for patients and assists doctors at hospitals. In Korea, nurses must pass a national licensing exam.", "examples": {"beginner": "The nurse gave me a shot.", "intermediate": "Nurses take good care of patients.", "advanced": "The nursing shortage in Korea is a serious social issue.", "master": "Nurses play a pivotal role in patients'' recovery process."}, "variations": {"formal": ["I am a nurse.", "This is the nurse."], "casual": ["I''m a nurse.", "The nurse."], "short": ["nurse"]}, "dialogue": {"context": "At the hospital", "dialogue": [{"speaker": "A", "text": "Nurse, I have a high fever.", "romanization": "", "translation": "간호사 선생님, 열이 많이 나요."}, {"speaker": "B", "text": "Let me take your temperature first.", "romanization": "", "translation": "체온을 먼저 재볼게요."}]}}}'),
  ('yaksa', '약사', 'yaksa', 'noun', 'professions', 'intermediate', 'common', '["professions", "medical", "health", "daily-life"]', '{"ko": {"word": "약사", "explanation": "약국에서 약을 조제하고 복약 지도를 하는 전문직입니다. 한국에서는 의약분업으로 처방전 없이 살 수 없는 약이 많습니다.", "examples": {"beginner": "약사에게 약을 받았어요.", "intermediate": "약사가 복용 방법을 설명해 주셨어요.", "advanced": "한국의 의약분업 제도는 2000년에 시행되었다.", "master": "약사는 환자의 약물 상호작용을 검토하는 중요한 역할을 한다."}, "variations": {"formal": ["약사입니다.", "약사 선생님이십니다."], "casual": ["약사야.", "약사 선생님."], "short": ["약사"]}, "dialogue": {"context": "약국에서", "dialogue": [{"speaker": "A", "text": "감기약 주세요.", "romanization": "gamgiyak juseyo.", "translation": "Please give me cold medicine."}, {"speaker": "B", "text": "콧물이 나세요, 기침이 나세요?", "romanization": "konmuri naseyo, gichimi naseyo?", "translation": "Do you have a runny nose or a cough?"}]}}, "en": {"word": "pharmacist", "explanation": "A professional who dispenses medicine and provides medication guidance at a pharmacy. In Korea, due to the separation of prescribing and dispensing, many medicines require a prescription.", "examples": {"beginner": "I got medicine from the pharmacist.", "intermediate": "The pharmacist explained how to take the medicine.", "advanced": "Korea''s separation of prescribing and dispensing was implemented in 2000.", "master": "Pharmacists play a crucial role in reviewing drug interactions for patients."}, "variations": {"formal": ["I am a pharmacist.", "This is the pharmacist."], "casual": ["I''m a pharmacist.", "The pharmacist."], "short": ["pharmacist"]}, "dialogue": {"context": "At the pharmacy", "dialogue": [{"speaker": "A", "text": "Please give me cold medicine.", "romanization": "", "translation": "감기약 주세요."}, {"speaker": "B", "text": "Do you have a runny nose or a cough?", "romanization": "", "translation": "콧물이 나세요, 기침이 나세요?"}]}}}'),
  ('chigwauisa', '치과의사', 'chigwauisa', 'noun', 'professions', 'intermediate', 'common', '["professions", "medical", "dental", "health"]', '{"ko": {"word": "치과의사", "explanation": "이와 구강 건강을 전문적으로 치료하는 의료 전문직입니다. 한국에서는 보통 ''치과''라고만 해도 치과의사를 의미합니다.", "examples": {"beginner": "치과의사에게 갔어요.", "intermediate": "치과의사가 충치를 치료해 주셨어요.", "advanced": "한국에서 치과 치료비는 비급여 항목이 많아 비용 부담이 크다.", "master": "치과의사는 구강 건강뿐 아니라 전신 건강과의 연관성도 연구한다."}, "variations": {"formal": ["치과의사입니다.", "치과 선생님이십니다."], "casual": ["치과의사야.", "치과 선생님."], "short": ["치과의사"]}, "dialogue": {"context": "치과에서", "dialogue": [{"speaker": "A", "text": "이가 아파서 왔어요.", "romanization": "iga apaseo wasseoyo.", "translation": "I came because my tooth hurts."}, {"speaker": "B", "text": "어디 한번 볼게요. 입을 크게 벌려 주세요.", "romanization": "eodi hanbeon bolgeyo. ibeul keuge beollyeo juseyo.", "translation": "Let me take a look. Please open your mouth wide."}]}}, "en": {"word": "dentist", "explanation": "A medical professional specializing in treating teeth and oral health. In Korea, people often just say ''치과'' (dental clinic) to refer to the dentist.", "examples": {"beginner": "I went to the dentist.", "intermediate": "The dentist treated my cavity.", "advanced": "In Korea, dental treatment costs can be high due to many non-covered items.", "master": "Dentists study not only oral health but also its connection to overall health."}, "variations": {"formal": ["I am a dentist.", "This is the dentist."], "casual": ["I''m a dentist.", "The dentist."], "short": ["dentist"]}, "dialogue": {"context": "At the dental clinic", "dialogue": [{"speaker": "A", "text": "I came because my tooth hurts.", "romanization": "", "translation": "이가 아파서 왔어요."}, {"speaker": "B", "text": "Let me take a look. Please open your mouth wide.", "romanization": "", "translation": "어디 한번 볼게요. 입을 크게 벌려 주세요."}]}}}'),
  ('byeonhosa', '변호사', 'byeonhosa', 'noun', 'professions', 'intermediate', 'common', '["professions", "legal", "justice", "business"]', '{"ko": {"word": "변호사", "explanation": "법률 문제에 대해 조언하고 법정에서 의뢰인을 대리하는 전문직입니다. 한국에서 변호사가 되려면 로스쿨을 졸업하고 변호사 시험에 합격해야 합니다.", "examples": {"beginner": "변호사를 만났어요.", "intermediate": "변호사에게 법률 상담을 받았어요.", "advanced": "한국은 2009년부터 로스쿨 제도를 도입했다.", "master": "변호사는 의뢰인의 권리를 보호하고 법적 정의를 실현하는 역할을 한다."}, "variations": {"formal": ["변호사입니다.", "변호사님이십니다."], "casual": ["변호사야.", "변호사님."], "short": ["변호사"]}, "dialogue": {"context": "법률 사무소에서", "dialogue": [{"speaker": "A", "text": "변호사님, 이 계약서를 검토해 주세요.", "romanization": "byeonhosanim, i gyeyakseoreul geomtohae juseyo.", "translation": "Lawyer, please review this contract."}, {"speaker": "B", "text": "네, 자세히 살펴보겠습니다.", "romanization": "ne, jasehi salpyeobogesseumnida.", "translation": "Yes, I''ll look into it carefully."}]}}, "en": {"word": "lawyer", "explanation": "A professional who advises on legal matters and represents clients in court. In Korea, one must graduate from law school and pass the bar exam to become a lawyer.", "examples": {"beginner": "I met a lawyer.", "intermediate": "I received legal consultation from a lawyer.", "advanced": "Korea introduced the law school system in 2009.", "master": "Lawyers serve to protect clients'' rights and realize legal justice."}, "variations": {"formal": ["I am a lawyer.", "This is the lawyer."], "casual": ["I''m a lawyer.", "The lawyer."], "short": ["lawyer"]}, "dialogue": {"context": "At the law office", "dialogue": [{"speaker": "A", "text": "Lawyer, please review this contract.", "romanization": "", "translation": "변호사님, 이 계약서를 검토해 주세요."}, {"speaker": "B", "text": "Yes, I''ll look into it carefully.", "romanization": "", "translation": "네, 자세히 살펴보겠습니다."}]}}}'),
  ('pansa', '판사', 'pansa', 'noun', 'professions', 'intermediate', 'uncommon', '["professions", "legal", "justice", "authority"]', '{"ko": {"word": "판사", "explanation": "법정에서 재판을 주재하고 판결을 내리는 법관입니다. 한국에서 판사는 사법 시험 또는 법학전문대학원을 통해 임용됩니다.", "examples": {"beginner": "판사가 판결을 내렸어요.", "intermediate": "판사는 법정에서 공정한 판결을 내려요.", "advanced": "한국의 판사 임용 절차는 엄격한 심사를 거친다.", "master": "판사의 독립성은 민주주의 사법 체계의 핵심 요소이다."}, "variations": {"formal": ["판사님이십니다.", "재판장님께서 판결하셨습니다."], "casual": ["판사야.", "판사님."], "short": ["판사"]}, "dialogue": {"context": "법정에서", "dialogue": [{"speaker": "A", "text": "재판장님, 이의 있습니다.", "romanization": "jaepanjangnim, iui itseumnida.", "translation": "Your Honor, I object."}, {"speaker": "B", "text": "이의를 인정합니다.", "romanization": "iuireul injeonghamnida.", "translation": "Objection sustained."}]}}, "en": {"word": "judge", "explanation": "A judicial officer who presides over court proceedings and delivers verdicts. In Korea, judges are appointed through the judicial exam or law school system.", "examples": {"beginner": "The judge made a ruling.", "intermediate": "Judges deliver fair verdicts in court.", "advanced": "The process for appointing judges in Korea involves rigorous review.", "master": "Judicial independence is a core element of a democratic legal system."}, "variations": {"formal": ["This is the judge.", "The presiding judge has ruled."], "casual": ["It''s the judge.", "The judge."], "short": ["judge"]}, "dialogue": {"context": "In the courtroom", "dialogue": [{"speaker": "A", "text": "Your Honor, I object.", "romanization": "", "translation": "재판장님, 이의 있습니다."}, {"speaker": "B", "text": "Objection sustained.", "romanization": "", "translation": "이의를 인정합니다."}]}}}'),
  ('geomsa', '검사', 'geomsa', 'noun', 'professions', 'intermediate', 'uncommon', '["professions", "legal", "justice", "government"]', '{"ko": {"word": "검사", "explanation": "범죄를 수사하고 법정에서 피고인을 기소하는 법률 전문직입니다. 한국의 검찰은 수사권과 기소권을 모두 가지고 있습니다.", "examples": {"beginner": "검사가 수사를 했어요.", "intermediate": "검사는 법정에서 피고인을 기소해요.", "advanced": "한국 검찰의 수사권과 기소권 분리가 논의되고 있다.", "master": "검사는 공익의 대표자로서 법과 정의를 수호하는 역할을 한다."}, "variations": {"formal": ["검사입니다.", "검사님이십니다."], "casual": ["검사야.", "검사님."], "short": ["검사"]}, "dialogue": {"context": "법정에서", "dialogue": [{"speaker": "A", "text": "검사님, 증거를 제시해 주세요.", "romanization": "geomsanim, jeungeoreul jesihae juseyo.", "translation": "Prosecutor, please present the evidence."}, {"speaker": "B", "text": "네, 이 증거 자료를 제출합니다.", "romanization": "ne, i jeungeo jaryoreul jechulhamnida.", "translation": "Yes, I submit this evidence."}]}}, "en": {"word": "prosecutor", "explanation": "A legal professional who investigates crimes and prosecutes defendants in court. In Korea, prosecutors hold both investigative and prosecutorial powers.", "examples": {"beginner": "The prosecutor investigated.", "intermediate": "Prosecutors prosecute defendants in court.", "advanced": "The separation of investigative and prosecutorial powers in Korea is being debated.", "master": "Prosecutors serve as representatives of the public interest, upholding law and justice."}, "variations": {"formal": ["I am a prosecutor.", "This is the prosecutor."], "casual": ["I''m a prosecutor.", "The prosecutor."], "short": ["prosecutor"]}, "dialogue": {"context": "In the courtroom", "dialogue": [{"speaker": "A", "text": "Prosecutor, please present the evidence.", "romanization": "", "translation": "검사님, 증거를 제시해 주세요."}, {"speaker": "B", "text": "Yes, I submit this evidence.", "romanization": "", "translation": "네, 이 증거 자료를 제출합니다."}]}}}'),
  ('gunin', '군인', 'gunin', 'noun', 'professions', 'beginner', 'common', '["professions", "military", "korean-culture", "service"]', '{"ko": {"word": "군인", "explanation": "국가를 방위하는 것이 직업인 사람입니다. 한국은 징병제로 만 18세 이상 남성은 약 18개월간 의무 복무를 해야 합니다.", "examples": {"beginner": "오빠가 군인이에요.", "intermediate": "한국 남자는 군대에 가야 해요.", "advanced": "한국의 병역 의무는 헌법에 명시되어 있다.", "master": "군인의 헌신은 국가 안보의 근간을 이루며, 징병제는 한국 사회의 중요한 특징이다."}, "variations": {"formal": ["군인입니다.", "군인이십니다."], "casual": ["군인이야.", "군인이다."], "short": ["군인"]}, "dialogue": {"context": "군대 이야기를 하면서", "dialogue": [{"speaker": "A", "text": "군대 다녀왔어요?", "romanization": "gundae danyeowasseoyo?", "translation": "Have you done your military service?"}, {"speaker": "B", "text": "네, 작년에 전역했어요.", "romanization": "ne, jangnyeone jeonyeokhaesseoyo.", "translation": "Yes, I was discharged last year."}]}}, "en": {"word": "soldier", "explanation": "A person whose profession is to defend the nation. Korea has mandatory military service, requiring males aged 18 and over to serve approximately 18 months.", "examples": {"beginner": "My brother is a soldier.", "intermediate": "Korean men have to go to the military.", "advanced": "Military service obligation in Korea is stipulated in the constitution.", "master": "Soldiers'' dedication forms the foundation of national security, and conscription is a key feature of Korean society."}, "variations": {"formal": ["I am a soldier.", "He is a soldier."], "casual": ["I''m a soldier.", "He''s in the army."], "short": ["soldier"]}, "dialogue": {"context": "Talking about military service", "dialogue": [{"speaker": "A", "text": "Have you done your military service?", "romanization": "", "translation": "군대 다녀왔어요?"}, {"speaker": "B", "text": "Yes, I was discharged last year.", "romanization": "", "translation": "네, 작년에 전역했어요."}]}}}'),
  ('sobangwan', '소방관', 'sobangwan', 'noun', 'professions', 'intermediate', 'common', '["professions", "public-service", "safety", "hero"]', '{"ko": {"word": "소방관", "explanation": "화재 진압, 인명 구조 등을 담당하는 공무원입니다. 한국 소방의 긴급 전화번호는 119입니다.", "examples": {"beginner": "소방관이 불을 껐어요.", "intermediate": "소방관은 위험한 상황에서 사람을 구해요.", "advanced": "한국의 소방관 처우 개선이 사회적 이슈이다.", "master": "소방관은 생명의 위험을 무릅쓰고 시민을 보호하는 공공 영웅이다."}, "variations": {"formal": ["소방관입니다.", "소방관님이십니다."], "casual": ["소방관이야.", "소방관님."], "short": ["소방관"]}, "dialogue": {"context": "화재 현장에서", "dialogue": [{"speaker": "A", "text": "119에 신고했어요?", "romanization": "baeksibi-gue singohasseoyo?", "translation": "Did you call 119?"}, {"speaker": "B", "text": "네, 소방차가 오고 있어요.", "romanization": "ne, sobangchaga ogo isseoyo.", "translation": "Yes, the fire truck is on its way."}]}}, "en": {"word": "firefighter", "explanation": "A public servant responsible for extinguishing fires and rescuing people. Korea''s fire emergency number is 119.", "examples": {"beginner": "The firefighter put out the fire.", "intermediate": "Firefighters rescue people in dangerous situations.", "advanced": "Improving working conditions for firefighters is a social issue in Korea.", "master": "Firefighters are public heroes who protect citizens at the risk of their own lives."}, "variations": {"formal": ["I am a firefighter.", "This is a firefighter."], "casual": ["I''m a firefighter.", "The firefighter."], "short": ["firefighter"]}, "dialogue": {"context": "At a fire scene", "dialogue": [{"speaker": "A", "text": "Did you call 119?", "romanization": "", "translation": "119에 신고했어요?"}, {"speaker": "B", "text": "Yes, the fire truck is on its way.", "romanization": "", "translation": "네, 소방차가 오고 있어요."}]}}}'),
  ('gongmuwon', '공무원', 'gongmuwon', 'noun', 'professions', 'intermediate', 'common', '["professions", "government", "korean-culture", "stable"]', '{"ko": {"word": "공무원", "explanation": "국가나 지방자치단체에서 근무하는 사람입니다. 한국에서 공무원은 안정적인 직업으로 인기가 매우 높으며, 공무원 시험 경쟁률이 매우 치열합니다.", "examples": {"beginner": "공무원이 되고 싶어요.", "intermediate": "공무원 시험은 경쟁이 치열해요.", "advanced": "한국에서 공무원은 가장 안정적인 직업으로 꼽힌다.", "master": "공무원의 안정성 선호는 한국 사회의 고용 불안정성을 반영한다."}, "variations": {"formal": ["공무원입니다.", "공무원이십니다."], "casual": ["공무원이야.", "공무원이다."], "short": ["공무원"]}, "dialogue": {"context": "진로 상담에서", "dialogue": [{"speaker": "A", "text": "졸업 후에 뭐 할 거예요?", "romanization": "joreop hue mwo hal geoyeyo?", "translation": "What are you going to do after graduation?"}, {"speaker": "B", "text": "공무원 시험을 준비하려고요.", "romanization": "gongmuwon siheomeul junbiharyeogoyo.", "translation": "I''m planning to prepare for the civil service exam."}]}}, "en": {"word": "civil servant", "explanation": "A person who works for a national or local government. In Korea, civil service is extremely popular as a stable career, and the civil service exam is highly competitive.", "examples": {"beginner": "I want to become a civil servant.", "intermediate": "The civil service exam is very competitive.", "advanced": "In Korea, civil service is considered the most stable career.", "master": "The preference for civil service stability reflects employment insecurity in Korean society."}, "variations": {"formal": ["I am a civil servant.", "He is a civil servant."], "casual": ["I''m a civil servant.", "A government worker."], "short": ["civil servant"]}, "dialogue": {"context": "Career counseling", "dialogue": [{"speaker": "A", "text": "What are you going to do after graduation?", "romanization": "", "translation": "졸업 후에 뭐 할 거예요?"}, {"speaker": "B", "text": "I''m planning to prepare for the civil service exam.", "romanization": "", "translation": "공무원 시험을 준비하려고요."}]}}}'),
  ('gija', '기자', 'gija', 'noun', 'professions', 'intermediate', 'common', '["professions", "media", "writing", "news"]', '{"ko": {"word": "기자", "explanation": "뉴스를 취재하고 보도하는 언론인입니다. 한국에는 주요 일간지, 방송사, 그리고 온라인 미디어까지 다양한 언론 매체가 있습니다.", "examples": {"beginner": "기자가 인터뷰를 했어요.", "intermediate": "기자는 매일 뉴스를 취재해요.", "advanced": "한국의 언론 자유 지수는 세계적으로 주목받고 있다.", "master": "기자는 사회의 감시자로서 권력을 견제하고 진실을 보도하는 역할을 한다."}, "variations": {"formal": ["기자입니다.", "기자님이십니다."], "casual": ["기자야.", "기자님."], "short": ["기자"]}, "dialogue": {"context": "인터뷰 현장에서", "dialogue": [{"speaker": "A", "text": "기자님, 한 말씀 부탁드립니다.", "romanization": "gijanim, han malsseum butakdeurimnida.", "translation": "Reporter, could you give us a comment?"}, {"speaker": "B", "text": "네, 이번 사건에 대해 설명드리겠습니다.", "romanization": "ne, ibeon sageone daehae seolmyeongdeurigesseumnida.", "translation": "Yes, let me explain about this incident."}]}}, "en": {"word": "journalist", "explanation": "A media professional who covers and reports news. Korea has diverse media outlets including major daily newspapers, broadcasting companies, and online media.", "examples": {"beginner": "The journalist did an interview.", "intermediate": "Journalists cover news every day.", "advanced": "Korea''s press freedom index is gaining global attention.", "master": "Journalists serve as society''s watchdogs, checking power and reporting the truth."}, "variations": {"formal": ["I am a journalist.", "This is the reporter."], "casual": ["I''m a journalist.", "The reporter."], "short": ["journalist"]}, "dialogue": {"context": "At an interview", "dialogue": [{"speaker": "A", "text": "Reporter, could you give us a comment?", "romanization": "", "translation": "기자님, 한 말씀 부탁드립니다."}, {"speaker": "B", "text": "Yes, let me explain about this incident.", "romanization": "", "translation": "네, 이번 사건에 대해 설명드리겠습니다."}]}}}'),
