  ('hwaga', '화가', 'hwaga', 'noun', 'professions', 'intermediate', '3', '["professions", "creative", "arts", "visual"]', '{"ko": "그림을 그리는 것을 직업으로 하는 사람", "en": "painter; artist"}'),
