  ('peurogeuraemeo', '프로그래머', 'peurogeuraemeo', 'noun', 'professions', 'intermediate', '4', '["professions", "technology", "IT", "modern", "loanword"]', '{"ko": "컴퓨터 프로그램을 만드는 사람", "en": "programmer"}'),
