  ('dijaineo', '디자이너', 'dijaineo', 'noun', 'professions', 'intermediate', '4', '["professions", "creative", "technology", "loanword"]', '{"ko": "제품이나 시각물의 디자인을 하는 사람", "en": "designer"}'),
  ('geonchukga', '건축가', 'geonchukga', 'noun', 'professions', 'advanced', '3', '["professions", "creative", "engineering", "design"]', '{"ko": "건물을 설계하고 짓는 전문가", "en": "architect"}'),
  ('gwahakja', '과학자', 'gwahakja', 'noun', 'professions', 'intermediate', '4', '["professions", "science", "research", "academic"]', '{"ko": "과학을 연구하는 사람", "en": "scientist"}'),
  ('yeonguwon', '연구원', 'yeonguwon', 'noun', 'professions', 'intermediate', '3', '["professions", "science", "academic", "lab"]', '{"ko": "연구 기관에서 연구하는 사람", "en": "researcher"}'),
  ('tongyeoksa', '통역사', 'tongyeoksa', 'noun', 'professions', 'advanced', '3', '["professions", "language", "communication", "international"]', '{"ko": "말을 다른 언어로 바꾸어 전달하는 사람", "en": "interpreter"}'),
  ('beonyeokga', '번역가', 'beonyeokga', 'noun', 'professions', 'advanced', '3', '["professions", "language", "writing", "international"]', '{"ko": "글을 다른 언어로 옮기는 사람", "en": "translator"}'),
  ('anaunseo', '아나운서', 'anaunseo', 'noun', 'professions', 'intermediate', '3', '["professions", "media", "broadcasting", "loanword"]', '{"ko": "방송에서 뉴스나 프로그램을 진행하는 사람", "en": "announcer; news anchor"}'),
  ('paillot', '파일럿', 'paillot', 'noun', 'professions', 'intermediate', '3', '["professions", "transportation", "aviation", "loanword"]', '{"ko": "비행기를 조종하는 사람", "en": "pilot"}'),
  ('seungmuwon', '승무원', 'seungmuwon', 'noun', 'professions', 'intermediate', '4', '["professions", "transportation", "service", "aviation"]', '{"ko": "비행기나 배에서 승객을 돌보는 사람", "en": "flight attendant; cabin crew"}'),
