-- drinks (60 entries)
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES
  ('mul', '물', 'mul', 'noun', 'drinks', 'beginner', 'common', '["drinks", "daily-life", "essential", "beginner-essential", "restaurant"]', '{"ko": {"word": "물", "explanation": "마시는 액체의 기본입니다. 한국 식당에서는 물이 무료로 제공됩니다. ''물''은 다양한 합성어에 쓰입니다: 물고기, 물가, 물건 등.", "examples": {"beginner": "물 주세요.", "intermediate": "한국 식당에서는 물이 무료예요.", "advanced": "한국에서는 수돗물보다 정수기 물을 마시는 경우가 많다.", "master": "물은 생명의 근원이라는 인식은 동서양 모두 공통이다."}, "variations": {"formal": ["물을 드시겠습니까?", "물을 가져다 드리겠습니다."], "casual": ["물 줘.", "물 마실래?"], "short": ["물"]}, "dialogue": {"context": "식당에서", "dialogue": [{"speaker": "A", "text": "물 좀 주세요.", "romanization": "mul jom juseyo.", "translation": "Could I have some water, please?"}, {"speaker": "B", "text": "네, 바로 가져다 드릴게요.", "romanization": "ne, baro gajyeoda deurilgeyo.", "translation": "Sure, I''ll bring it right away."}]}}, "en": {"word": "water", "explanation": "The most basic drink. In Korean restaurants, water is provided for free. ''물'' is used in many compound words: 물고기 (fish), 물가 (waterside/prices), etc.", "examples": {"beginner": "Water, please.", "intermediate": "Water is free in Korean restaurants.", "advanced": "In Korea, people often drink filtered water rather than tap water.", "master": "The recognition that water is the source of life is universal across cultures."}, "variations": {"formal": ["Would you like water?", "I''ll bring you water."], "casual": ["Give me water.", "Want some water?"], "short": ["water"]}, "dialogue": {"context": "At a restaurant", "dialogue": [{"speaker": "A", "text": "Could I have some water, please?", "romanization": "", "translation": "물 좀 주세요."}, {"speaker": "B", "text": "Sure, I''ll bring it right away.", "romanization": "", "translation": "네, 바로 가져다 드릴게요."}]}}}'),
  ('keopi', '커피', 'keopi', 'noun', 'drinks', 'beginner', 'common', '["drinks", "daily-life", "cafe", "loanword", "modern"]', '{"ko": {"word": "커피", "explanation": "영어 ''coffee''에서 온 외래어입니다. 한국은 세계적인 커피 소비국으로, 서울에만 수만 개의 카페가 있습니다. ''커피숍''보다 ''카페''라는 표현을 더 많이 씁니다.", "examples": {"beginner": "커피 마셔요.", "intermediate": "한국 사람들은 커피를 정말 많이 마셔요.", "advanced": "한국의 1인당 커피 소비량은 세계 상위권이다.", "master": "카페 문화는 한국 사회에서 소통과 휴식의 공간으로 자리 잡았다."}, "variations": {"formal": ["커피 드시겠습니까?", "커피를 준비하겠습니다."], "casual": ["커피 마실래?", "커피 한 잔 할까?"], "short": ["커피"]}, "dialogue": {"context": "카페에서", "dialogue": [{"speaker": "A", "text": "뭐 마실래? 내가 살게.", "romanization": "mwo masillae? naega salge.", "translation": "What do you want to drink? My treat."}, {"speaker": "B", "text": "아이스 아메리카노 주세요.", "romanization": "aiseu amerikano juseyo.", "translation": "Iced Americano, please."}]}}, "en": {"word": "coffee", "explanation": "A loanword from English. Korea is one of the world''s top coffee-consuming countries, with tens of thousands of cafes in Seoul alone. Koreans say ''카페'' (cafe) more often than ''커피숍'' (coffee shop).", "examples": {"beginner": "I drink coffee.", "intermediate": "Koreans drink a lot of coffee.", "advanced": "Korea''s per capita coffee consumption ranks among the highest in the world.", "master": "Cafe culture has become established as a space for socializing and relaxation in Korean society."}, "variations": {"formal": ["Would you like coffee?", "I''ll prepare coffee."], "casual": ["Want coffee?", "How about a cup of coffee?"], "short": ["coffee"]}, "dialogue": {"context": "At a cafe", "dialogue": [{"speaker": "A", "text": "What do you want to drink? My treat.", "romanization": "", "translation": "뭐 마실래? 내가 살게."}, {"speaker": "B", "text": "Iced Americano, please.", "romanization": "", "translation": "아이스 아메리카노 주세요."}]}}}'),
  ('cha', '차', 'cha', 'noun', 'drinks', 'beginner', 'common', '["drinks", "traditional", "korean-culture", "health"]', '{"ko": {"word": "차", "explanation": "잎이나 열매를 우린 음료입니다. 동음이의어로 ''차(車)''는 ''자동차''를 뜻합니다. 한국의 전통 차로는 녹차, 보리차, 유자차, 대추차 등이 있습니다.", "examples": {"beginner": "차를 마셔요.", "intermediate": "한국에서는 보리차를 물처럼 마셔요.", "advanced": "유자차는 겨울에 감기 예방으로 많이 마신다.", "master": "한국의 다도(茶道)는 조선 시대에 선비 문화의 일부였다."}, "variations": {"formal": ["차를 드시겠습니까?", "차를 한 잔 대접하겠습니다."], "casual": ["차 마실래?", "차 한 잔 할까?"], "short": ["차"]}, "dialogue": {"context": "집에서 손님을 맞으며", "dialogue": [{"speaker": "A", "text": "차 한 잔 드릴까요?", "romanization": "cha han jan deurilkkayo?", "translation": "Shall I offer you a cup of tea?"}, {"speaker": "B", "text": "네, 유자차 있으면 좋겠어요.", "romanization": "ne, yujacha isseumyeon jokeseoyo.", "translation": "Yes, I''d love some yuzu tea if you have it."}]}}, "en": {"word": "tea", "explanation": "A drink made by steeping leaves or fruits. ''차'' is also a homonym meaning ''car'' (車). Traditional Korean teas include green tea (녹차), barley tea (보리차), yuzu tea (유자차), and jujube tea (대추차).", "examples": {"beginner": "I drink tea.", "intermediate": "In Korea, barley tea is drunk like water.", "advanced": "Yuzu tea is commonly consumed in winter to prevent colds.", "master": "Korea''s tea ceremony (다도) was part of scholarly culture during the Joseon Dynasty."}, "variations": {"formal": ["Would you like tea?", "Let me offer you a cup of tea."], "casual": ["Want tea?", "How about a cup of tea?"], "short": ["tea"]}, "dialogue": {"context": "Welcoming a guest at home", "dialogue": [{"speaker": "A", "text": "Shall I offer you a cup of tea?", "romanization": "", "translation": "차 한 잔 드릴까요?"}, {"speaker": "B", "text": "Yes, I''d love some yuzu tea if you have it.", "romanization": "", "translation": "네, 유자차 있으면 좋겠어요."}]}}}'),
  ('juseu', '주스', 'juseu', 'noun', 'drinks', 'beginner', 'common', '["drinks", "non-alcoholic", "refreshment", "loanword"]', '{"ko": {"word": "주스", "explanation": "영어 ''juice''에서 온 외래어입니다. 과일이나 채소를 짜서 만든 음료입니다.", "examples": {"beginner": "오렌지 주스 주세요.", "intermediate": "아침에 주스를 마시면 건강에 좋아요.", "advanced": "생과일 주스와 농축 주스는 영양 차이가 크다.", "master": "착즙 주스 시장이 건강 트렌드와 함께 급성장했다."}, "variations": {"formal": ["주스를 드시겠습니까?", "주스를 준비했습니다."], "casual": ["주스 마실래?", "주스 줘."], "short": ["주스"]}, "dialogue": {"context": "편의점에서", "dialogue": [{"speaker": "A", "text": "목이 마른데 뭐 마실까?", "romanization": "mogi mareuunde mwo masilkka?", "translation": "I''m thirsty. What should we drink?"}, {"speaker": "B", "text": "오렌지 주스 어때?", "romanization": "orenji juseu eottae?", "translation": "How about orange juice?"}]}}, "en": {"word": "juice", "explanation": "A loanword from English. A drink made by squeezing fruits or vegetables.", "examples": {"beginner": "Orange juice, please.", "intermediate": "Drinking juice in the morning is good for your health.", "advanced": "There''s a big nutritional difference between fresh-squeezed and concentrated juice.", "master": "The cold-pressed juice market has grown rapidly along with health trends."}, "variations": {"formal": ["Would you like juice?", "I''ve prepared juice."], "casual": ["Want juice?", "Give me juice."], "short": ["juice"]}, "dialogue": {"context": "At a convenience store", "dialogue": [{"speaker": "A", "text": "I''m thirsty. What should we drink?", "romanization": "", "translation": "목이 마른데 뭐 마실까?"}, {"speaker": "B", "text": "How about orange juice?", "romanization": "", "translation": "오렌지 주스 어때?"}]}}}'),
  ('soju', '소주', 'soju', 'noun', 'drinks', 'intermediate', 'common', '["drinks", "alcohol", "korean-culture", "social", "restaurant"]', '{"ko": {"word": "소주", "explanation": "한국의 대표적인 증류주입니다. 도수는 보통 16~20%이며, 초록색 병에 담겨 있습니다. 한국의 음주 문화에서 빠질 수 없는 술입니다.", "examples": {"beginner": "소주 한 병 주세요.", "intermediate": "한국 사람들은 삼겹살에 소주를 마셔요.", "advanced": "소주는 전 세계에서 가장 많이 팔리는 증류주 브랜드이다.", "master": "소주잔을 돌려서 받거나 두 손으로 따르는 것은 한국 음주 예절이다."}, "variations": {"formal": ["소주를 드시겠습니까?", "소주 한 잔 하시겠습니까?"], "casual": ["소주 한 잔 할까?", "소주 마시자."], "short": ["소주"]}, "dialogue": {"context": "회식에서", "dialogue": [{"speaker": "A", "text": "소주 한 잔 하실래요?", "romanization": "soju han jan hasillaeyo?", "translation": "Would you like a glass of soju?"}, {"speaker": "B", "text": "네, 한 잔만요.", "romanization": "ne, han janmanyo.", "translation": "Yes, just one glass."}]}}, "en": {"word": "soju", "explanation": "Korea''s signature distilled liquor, typically 16–20% ABV, sold in iconic green bottles. Soju is one of the best-selling spirits in the world. Drinking etiquette includes pouring with two hands and turning away from elders when drinking.", "examples": {"beginner": "One bottle of soju, please.", "intermediate": "Koreans drink soju with grilled pork belly.", "advanced": "Soju is one of the world''s best-selling distilled spirit brands.", "master": "Receiving a glass with two hands or turning away when drinking are Korean drinking customs."}, "variations": {"formal": ["Would you like soju?", "May I offer you a glass of soju?"], "casual": ["Want a glass of soju?", "Let''s drink soju."], "short": ["soju"]}, "dialogue": {"context": "At a company dinner", "dialogue": [{"speaker": "A", "text": "Would you like a glass of soju?", "romanization": "", "translation": "소주 한 잔 하실래요?"}, {"speaker": "B", "text": "Yes, just one glass.", "romanization": "", "translation": "네, 한 잔만요."}]}}}'),
  ('maekju', '맥주', 'maekju', 'noun', 'drinks', 'beginner', 'common', '["drinks", "alcohol", "social", "restaurant"]', '{"ko": {"word": "맥주", "explanation": "보리를 발효시켜 만든 술입니다. 한자어 ''麥酒''(보리 맥 + 술 주)에서 유래했습니다. 소주와 맥주를 섞은 ''소맥''은 한국 특유의 음주 문화입니다.", "examples": {"beginner": "맥주 한 잔 주세요.", "intermediate": "치킨에 맥주는 한국의 국민 조합이에요.", "advanced": "한국의 수제 맥주 시장이 빠르게 성장하고 있다.", "master": "소맥(소주+맥주)은 한국 특유의 혼합주 문화이다."}, "variations": {"formal": ["맥주를 드시겠습니까?", "맥주를 주문하겠습니다."], "casual": ["맥주 마시자.", "치맥 하자!"], "short": ["맥주"]}, "dialogue": {"context": "치킨집에서", "dialogue": [{"speaker": "A", "text": "치맥 하자!", "romanization": "chimaek haja!", "translation": "Let''s have chicken and beer!"}, {"speaker": "B", "text": "좋아! 생맥주로 시키자.", "romanization": "joa! saengmaekjuro sikija.", "translation": "Great! Let''s order draft beer."}]}}, "en": {"word": "beer", "explanation": "An alcoholic drink made by fermenting barley. The word comes from Chinese characters ''麥酒'' (barley + alcohol). ''소맥'' (somaek), a mix of soju and beer, is uniquely Korean. ''치맥'' (chimaek = chicken + maekju) is Korea''s iconic food-drink pairing.", "examples": {"beginner": "A glass of beer, please.", "intermediate": "Chicken and beer is Korea''s national food combo.", "advanced": "Korea''s craft beer market is growing rapidly.", "master": "Somaek (soju + beer mix) is a uniquely Korean cocktail culture."}, "variations": {"formal": ["Would you like beer?", "I''ll order beer."], "casual": ["Let''s drink beer.", "Chicken and beer!"], "short": ["beer"]}, "dialogue": {"context": "At a chicken restaurant", "dialogue": [{"speaker": "A", "text": "Let''s have chicken and beer!", "romanization": "", "translation": "치맥 하자!"}, {"speaker": "B", "text": "Great! Let''s order draft beer.", "romanization": "", "translation": "좋아! 생맥주로 시키자."}]}}}'),
  ('nokcha', '녹차', 'nokcha', 'noun', 'drinks', 'beginner', 'common', '["drinks", "tea", "traditional", "health", "korean-culture"]', '{"ko": {"word": "녹차", "explanation": "찻잎을 발효시키지 않고 덖어 만든 차입니다. ''녹(綠)''은 ''초록''이라는 뜻입니다. 한국에서는 보성과 제주도가 녹차 산지로 유명합니다. 녹차 아이스크림, 녹차 라떼 등 다양한 파생 제품이 있습니다.", "examples": {"beginner": "녹차 한 잔 주세요.", "intermediate": "녹차는 카페인이 커피보다 적어요.", "advanced": "보성 녹차밭은 한국 최대의 차 재배지이다.", "master": "녹차의 카테킨 성분은 항산화 효과가 뛰어나 건강 음료로 주목받고 있다."}, "variations": {"formal": ["녹차를 드시겠습니까?", "녹차를 준비하겠습니다."], "casual": ["녹차 마실래?", "녹차 한 잔 할까?"], "short": ["녹차"]}, "dialogue": {"context": "카페에서", "dialogue": [{"speaker": "A", "text": "녹차 라떼 한 잔 주세요.", "romanization": "nokcha latte han jan juseyo.", "translation": "One green tea latte, please."}, {"speaker": "B", "text": "아이스로 드릴까요, 핫으로 드릴까요?", "romanization": "aiseuro deurilkkayo, haseuro deurilkkayo?", "translation": "Would you like it iced or hot?"}]}}, "en": {"word": "green tea", "explanation": "Tea made from unfermented tea leaves that are pan-fired. ''녹(綠)'' means ''green.'' Boseong and Jeju Island are famous green tea regions in Korea. Many derivative products exist, such as green tea ice cream and green tea lattes.", "examples": {"beginner": "One cup of green tea, please.", "intermediate": "Green tea has less caffeine than coffee.", "advanced": "Boseong tea fields are Korea''s largest tea cultivation area.", "master": "The catechin compounds in green tea have excellent antioxidant effects, drawing attention as a health beverage."}, "variations": {"formal": ["Would you like green tea?", "I''ll prepare green tea."], "casual": ["Want green tea?", "How about a cup of green tea?"], "short": ["green tea"]}, "dialogue": {"context": "At a cafe", "dialogue": [{"speaker": "A", "text": "One green tea latte, please.", "romanization": "", "translation": "녹차 라떼 한 잔 주세요."}, {"speaker": "B", "text": "Would you like it iced or hot?", "romanization": "", "translation": "아이스로 드릴까요, 핫으로 드릴까요?"}]}}}'),
  ('hongcha', '홍차', 'hongcha', 'noun', 'drinks', 'beginner', 'common', '["drinks", "tea", "cafe", "western"]', '{"ko": {"word": "홍차", "explanation": "찻잎을 완전히 발효시켜 만든 차입니다. ''홍(紅)''은 ''붉다''는 뜻으로, 우린 물의 색이 붉어서 붙은 이름입니다. 영어로는 ''black tea''라고 합니다. 밀크티의 베이스로 많이 사용됩니다.", "examples": {"beginner": "홍차 한 잔 주세요.", "intermediate": "홍차에 우유를 넣으면 밀크티가 돼요.", "advanced": "홍차는 녹차와 같은 찻잎이지만 발효 과정이 다르다.", "master": "영국의 애프터눈 티 문화가 한국 카페에도 영향을 미쳤다."}, "variations": {"formal": ["홍차를 드시겠습니까?", "홍차를 준비하겠습니다."], "casual": ["홍차 마실래?", "홍차 한 잔 할까?"], "short": ["홍차"]}, "dialogue": {"context": "카페에서", "dialogue": [{"speaker": "A", "text": "따뜻한 홍차 있어요?", "romanization": "ttatteutan hongcha isseoyo?", "translation": "Do you have hot black tea?"}, {"speaker": "B", "text": "네, 얼그레이랑 잉글리시 블렉퍼스트 있어요.", "romanization": "ne, eolgeureiirang inggeullisi beullekpeoseuteu isseoyo.", "translation": "Yes, we have Earl Grey and English Breakfast."}]}}, "en": {"word": "black tea", "explanation": "Tea made from fully fermented tea leaves. ''홍(紅)'' means ''red,'' named for the reddish color of the brewed liquid. In English it''s called ''black tea,'' while in Korean it''s literally ''red tea.'' It''s commonly used as a base for milk tea.", "examples": {"beginner": "One cup of black tea, please.", "intermediate": "Adding milk to black tea makes milk tea.", "advanced": "Black tea comes from the same leaves as green tea, but the fermentation process differs.", "master": "British afternoon tea culture has influenced Korean cafe culture as well."}, "variations": {"formal": ["Would you like black tea?", "I''ll prepare black tea."], "casual": ["Want black tea?", "How about a cup of black tea?"], "short": ["black tea"]}, "dialogue": {"context": "At a cafe", "dialogue": [{"speaker": "A", "text": "Do you have hot black tea?", "romanization": "", "translation": "따뜻한 홍차 있어요?"}, {"speaker": "B", "text": "Yes, we have Earl Grey and English Breakfast.", "romanization": "", "translation": "네, 얼그레이랑 잉글리시 블렉퍼스트 있어요."}]}}}'),
  ('boricha', '보리차', 'boricha', 'noun', 'drinks', 'beginner', 'common', '["drinks", "tea", "traditional", "korean-culture", "daily-life"]', '{"ko": {"word": "보리차", "explanation": "볶은 보리를 끓여 만든 차입니다. 카페인이 없어 아이부터 어른까지 모두 마실 수 있습니다. 한국 가정에서는 물 대신 보리차를 냉장고에 넣어두고 마시는 경우가 많습니다.", "examples": {"beginner": "보리차 마셔요.", "intermediate": "한국 집에서는 보리차를 물처럼 마셔요.", "advanced": "보리차는 카페인이 없어서 아이들도 안심하고 마실 수 있다.", "master": "보리차 문화는 한국과 일본에서 공통적으로 나타나는 동아시아 식문화이다."}, "variations": {"formal": ["보리차를 드시겠습니까?", "보리차를 끓여 드리겠습니다."], "casual": ["보리차 마실래?", "보리차 줘."], "short": ["보리차"]}, "dialogue": {"context": "한국 친구 집에서", "dialogue": [{"speaker": "A", "text": "목마르면 냉장고에 보리차 있어.", "romanization": "mongmareumyeon naengjanggo-e boricha isseo.", "translation": "If you''re thirsty, there''s barley tea in the fridge."}, {"speaker": "B", "text": "고마워! 한국 집에는 보리차가 항상 있구나.", "romanization": "gomawo! hanguk jibeneun borichaga hangsang itguna.", "translation": "Thanks! Korean homes always have barley tea, huh."}]}}, "en": {"word": "barley tea", "explanation": "Tea made from roasted barley. It''s caffeine-free, so everyone from children to adults can enjoy it. In many Korean households, barley tea is kept in the fridge and drunk instead of plain water.", "examples": {"beginner": "I drink barley tea.", "intermediate": "In Korean homes, barley tea is drunk like water.", "advanced": "Barley tea is caffeine-free, making it safe for children to drink.", "master": "Barley tea culture is a shared East Asian food tradition found in both Korea and Japan."}, "variations": {"formal": ["Would you like barley tea?", "I''ll boil some barley tea for you."], "casual": ["Want barley tea?", "Give me barley tea."], "short": ["barley tea"]}, "dialogue": {"context": "At a Korean friend''s home", "dialogue": [{"speaker": "A", "text": "If you''re thirsty, there''s barley tea in the fridge.", "romanization": "", "translation": "목마르면 냉장고에 보리차 있어."}, {"speaker": "B", "text": "Thanks! Korean homes always have barley tea, huh.", "romanization": "", "translation": "고마워! 한국 집에는 보리차가 항상 있구나."}]}}}'),
  ('oksusucha', '옥수수차', 'oksusucha', 'noun', 'drinks', 'intermediate', 'common', '["drinks", "tea", "traditional", "korean-culture"]', '{"ko": {"word": "옥수수차", "explanation": "볶은 옥수수를 끓여 만든 차입니다. 고소한 맛이 특징이며, 보리차와 함께 한국 가정에서 흔히 마시는 차입니다. 카페인이 없어 누구나 부담 없이 마실 수 있습니다.", "examples": {"beginner": "옥수수차 주세요.", "intermediate": "옥수수차는 고소해서 맛있어요.", "advanced": "한국에서는 보리차와 옥수수차를 일상적으로 끓여 마신다.", "master": "옥수수차와 보리차는 한국 가정의 수분 섭취 문화를 대표하는 곡물차이다."}, "variations": {"formal": ["옥수수차를 드시겠습니까?", "옥수수차를 준비하겠습니다."], "casual": ["옥수수차 마실래?", "옥수수차 한 잔 할까?"], "short": ["옥수수차"]}, "dialogue": {"context": "집에서", "dialogue": [{"speaker": "A", "text": "오늘은 옥수수차 끓였어.", "romanization": "oneureun oksusucha kkeurieosseo.", "translation": "I boiled corn tea today."}, {"speaker": "B", "text": "좋다! 옥수수차가 고소해서 좋아.", "romanization": "jota! oksusuchaga gosohaeseo joa.", "translation": "Nice! I like corn tea because it''s nutty."}]}}, "en": {"word": "corn tea", "explanation": "Tea made from roasted corn kernels. It has a distinctive nutty flavor and is one of the most common household teas in Korea alongside barley tea. It''s caffeine-free and enjoyed by all ages.", "examples": {"beginner": "Corn tea, please.", "intermediate": "Corn tea tastes good because it''s nutty.", "advanced": "In Korea, barley tea and corn tea are routinely boiled and consumed daily.", "master": "Corn tea and barley tea are grain-based teas that represent Korea''s everyday hydration culture."}, "variations": {"formal": ["Would you like corn tea?", "I''ll prepare corn tea."], "casual": ["Want corn tea?", "How about a cup of corn tea?"], "short": ["corn tea"]}, "dialogue": {"context": "At home", "dialogue": [{"speaker": "A", "text": "I boiled corn tea today.", "romanization": "", "translation": "오늘은 옥수수차 끓였어."}, {"speaker": "B", "text": "Nice! I like corn tea because it''s nutty.", "romanization": "", "translation": "좋다! 옥수수차가 고소해서 좋아."}]}}}'),
  ('yujacha', '유자차', 'yujacha', 'noun', 'drinks', 'intermediate', 'common', '["drinks", "tea", "traditional", "winter", "health"]', '{"ko": {"word": "유자차", "explanation": "유자 과육과 껍질을 설탕이나 꿀에 절여 만든 청을 뜨거운 물에 타서 마시는 차입니다. 비타민 C가 풍부하여 감기 예방에 좋다고 알려져 있습니다. 겨울철 대표 음료입니다.", "examples": {"beginner": "유자차 한 잔 주세요.", "intermediate": "감기 걸리면 유자차를 마셔요.", "advanced": "유자차는 비타민 C가 레몬의 세 배나 들어 있다.", "master": "유자청을 담그는 것은 한국 가정의 겨울 준비 문화 중 하나이다."}, "variations": {"formal": ["유자차를 드시겠습니까?", "유자차를 한 잔 드리겠습니다."], "casual": ["유자차 마실래?", "유자차 한 잔 할까?"], "short": ["유자차"]}, "dialogue": {"context": "겨울에 카페에서", "dialogue": [{"speaker": "A", "text": "감기 기운이 있어서 유자차 마시려고.", "romanization": "gamgi giuni isseoseo yujacha masiryeogo.", "translation": "I feel a cold coming on, so I''m going to have yuzu tea."}, {"speaker": "B", "text": "좋은 생각이야. 유자차가 감기에 좋잖아.", "romanization": "joeun saenggagiya. yujachaga gamgie jojana.", "translation": "Good idea. Yuzu tea is good for colds."}]}}, "en": {"word": "yuzu tea", "explanation": "A tea made by dissolving yuzu marmalade (fruit flesh and peel preserved in sugar or honey) in hot water. Rich in vitamin C, it''s known for preventing colds. It''s a signature winter beverage in Korea.", "examples": {"beginner": "One cup of yuzu tea, please.", "intermediate": "When you have a cold, drink yuzu tea.", "advanced": "Yuzu tea contains three times more vitamin C than lemon.", "master": "Making yuzu preserves (유자청) is one of the Korean household traditions for winter preparation."}, "variations": {"formal": ["Would you like yuzu tea?", "I''ll bring you a cup of yuzu tea."], "casual": ["Want yuzu tea?", "How about yuzu tea?"], "short": ["yuzu tea"]}, "dialogue": {"context": "At a cafe in winter", "dialogue": [{"speaker": "A", "text": "I feel a cold coming on, so I''m going to have yuzu tea.", "romanization": "", "translation": "감기 기운이 있어서 유자차 마시려고."}, {"speaker": "B", "text": "Good idea. Yuzu tea is good for colds.", "romanization": "", "translation": "좋은 생각이야. 유자차가 감기에 좋잖아."}]}}}'),
  ('saenggangcha', '생강차', 'saenggangcha', 'noun', 'drinks', 'intermediate', 'common', '["drinks", "tea", "traditional", "health", "winter"]', '{"ko": {"word": "생강차", "explanation": "생강을 얇게 썰어 꿀이나 설탕과 함께 끓여 만든 차입니다. 몸을 따뜻하게 해주는 효과가 있어 겨울철에 특히 인기가 많습니다. 감기 초기 증상에도 효과적입니다.", "examples": {"beginner": "생강차 한 잔 주세요.", "intermediate": "추울 때 생강차를 마시면 몸이 따뜻해져요.", "advanced": "생강은 항염증 효과가 있어 한방에서 약재로 쓰인다.", "master": "생강은 동의보감에서 소화 촉진과 해열 효과가 있는 약재로 기록되어 있다."}, "variations": {"formal": ["생강차를 드시겠습니까?", "생강차를 준비하겠습니다."], "casual": ["생강차 마실래?", "생강차 한 잔 할까?"], "short": ["생강차"]}, "dialogue": {"context": "추운 겨울날", "dialogue": [{"speaker": "A", "text": "너무 추워. 뭐 따뜻한 거 마시고 싶어.", "romanization": "neomu chuwo. mwo ttatteutan geo masigo sipeo.", "translation": "It''s so cold. I want to drink something warm."}, {"speaker": "B", "text": "생강차 어때? 몸이 따뜻해질 거야.", "romanization": "saenggangcha eottae? momi ttatteuthejil geoya.", "translation": "How about ginger tea? It''ll warm you up."}]}}, "en": {"word": "ginger tea", "explanation": "Tea made by boiling sliced ginger with honey or sugar. It has a warming effect on the body, making it especially popular in winter. It''s also effective for early cold symptoms.", "examples": {"beginner": "One cup of ginger tea, please.", "intermediate": "Drinking ginger tea when it''s cold warms your body up.", "advanced": "Ginger has anti-inflammatory properties and is used as a medicinal ingredient in traditional Korean medicine.", "master": "Ginger is recorded in the Dongui Bogam as an herbal remedy with digestive and fever-reducing properties."}, "variations": {"formal": ["Would you like ginger tea?", "I''ll prepare ginger tea."], "casual": ["Want ginger tea?", "How about ginger tea?"], "short": ["ginger tea"]}, "dialogue": {"context": "On a cold winter day", "dialogue": [{"speaker": "A", "text": "It''s so cold. I want to drink something warm.", "romanization": "", "translation": "너무 추워. 뭐 따뜻한 거 마시고 싶어."}, {"speaker": "B", "text": "How about ginger tea? It''ll warm you up.", "romanization": "", "translation": "생강차 어때? 몸이 따뜻해질 거야."}]}}}'),
  ('daechucha', '대추차', 'daechucha', 'noun', 'drinks', 'intermediate', 'uncommon', '["drinks", "tea", "traditional", "health"]', '{"ko": {"word": "대추차", "explanation": "말린 대추를 푹 끓여 만든 차입니다. 자연스러운 단맛이 나며, 긴장을 풀어주고 숙면에 도움이 된다고 알려져 있습니다. 한방에서 자주 쓰이는 약재이기도 합니다.", "examples": {"beginner": "대추차 한 잔 주세요.", "intermediate": "대추차는 달아서 아이들도 좋아해요.", "advanced": "대추는 한방에서 보혈(補血) 작용을 하는 약재로 쓰인다.", "master": "대추차는 불면증에 효과적이라는 연구 결과가 있다."}, "variations": {"formal": ["대추차를 드시겠습니까?", "대추차를 한 잔 드리겠습니다."], "casual": ["대추차 마실래?", "대추차 한 잔 할까?"], "short": ["대추차"]}, "dialogue": {"context": "전통 찻집에서", "dialogue": [{"speaker": "A", "text": "여기 전통차가 많네요. 뭐가 좋을까요?", "romanization": "yeogi jeontongchaga manneyo. mwoga joeulkkayo?", "translation": "There are many traditional teas here. What''s good?"}, {"speaker": "B", "text": "대추차가 달고 맛있어요. 추천해요.", "romanization": "daechuchaga dalgo masisseoyo. chucheonhaeyo.", "translation": "Jujube tea is sweet and delicious. I recommend it."}]}}, "en": {"word": "jujube tea", "explanation": "Tea made by boiling dried jujubes (Korean dates). It has a natural sweetness and is known to help with relaxation and better sleep. Jujubes are also frequently used as a medicinal ingredient in traditional Korean medicine.", "examples": {"beginner": "One cup of jujube tea, please.", "intermediate": "Jujube tea is sweet, so even children like it.", "advanced": "Jujubes are used in traditional medicine for their blood-nourishing properties.", "master": "Research has shown that jujube tea can be effective for insomnia."}, "variations": {"formal": ["Would you like jujube tea?", "I''ll bring you a cup of jujube tea."], "casual": ["Want jujube tea?", "How about jujube tea?"], "short": ["jujube tea"]}, "dialogue": {"context": "At a traditional tea house", "dialogue": [{"speaker": "A", "text": "There are many traditional teas here. What''s good?", "romanization": "", "translation": "여기 전통차가 많네요. 뭐가 좋을까요?"}, {"speaker": "B", "text": "Jujube tea is sweet and delicious. I recommend it.", "romanization": "", "translation": "대추차가 달고 맛있어요. 추천해요."}]}}}'),
  ('insamcha', '인삼차', 'insamcha', 'noun', 'drinks', 'intermediate', 'uncommon', '["drinks", "tea", "traditional", "korean-culture", "health"]', '{"ko": {"word": "인삼차", "explanation": "인삼을 우려 만든 차입니다. 한국산 인삼(고려인삼)은 세계적으로 유명합니다. 피로 회복과 면역력 강화에 좋다고 알려져 있으며, 한국의 대표적인 건강 음료입니다.", "examples": {"beginner": "인삼차 한 잔 주세요.", "intermediate": "한국 인삼은 세계적으로 유명해요.", "advanced": "고려인삼은 사포닌 함량이 높아 건강 식품으로 각광받는다.", "master": "인삼은 동아시아 전통 의학에서 수천 년간 만병통치약으로 여겨져 왔다."}, "variations": {"formal": ["인삼차를 드시겠습니까?", "인삼차를 준비했습니다."], "casual": ["인삼차 마실래?", "인삼차 한 잔 할까?"], "short": ["인삼차"]}, "dialogue": {"context": "선물 가게에서", "dialogue": [{"speaker": "A", "text": "한국 선물로 뭐가 좋을까요?", "romanization": "hanguk seonmullo mwoga joeulkkayo?", "translation": "What''s a good Korean souvenir?"}, {"speaker": "B", "text": "인삼차 세트 어때요? 외국인들에게 인기가 많아요.", "romanization": "insamcha seteu eottaeyo? oegugindeulege ingiga manayo.", "translation": "How about a ginseng tea set? It''s popular with foreigners."}]}}, "en": {"word": "ginseng tea", "explanation": "Tea brewed from ginseng root. Korean ginseng (Goryeo ginseng) is world-renowned. Known for fatigue recovery and immune system strengthening, it''s one of Korea''s signature health beverages.", "examples": {"beginner": "One cup of ginseng tea, please.", "intermediate": "Korean ginseng is famous worldwide.", "advanced": "Korean ginseng is prized as a health food due to its high saponin content.", "master": "Ginseng has been regarded as a cure-all in East Asian traditional medicine for thousands of years."}, "variations": {"formal": ["Would you like ginseng tea?", "I''ve prepared ginseng tea."], "casual": ["Want ginseng tea?", "How about ginseng tea?"], "short": ["ginseng tea"]}, "dialogue": {"context": "At a gift shop", "dialogue": [{"speaker": "A", "text": "What''s a good Korean souvenir?", "romanization": "", "translation": "한국 선물로 뭐가 좋을까요?"}, {"speaker": "B", "text": "How about a ginseng tea set? It''s popular with foreigners.", "romanization": "", "translation": "인삼차 세트 어때요? 외국인들에게 인기가 많아요."}]}}}'),
  ('ssanghwatang', '쌍화탕', 'ssanghwatang', 'noun', 'drinks', 'advanced', 'uncommon', '["drinks", "traditional", "health", "korean-culture", "medicine"]', '{"ko": {"word": "쌍화탕", "explanation": "여러 한약재를 달여 만든 전통 보양 음료입니다. 작약, 숙지황, 당귀 등이 들어갑니다. 피로 회복과 체력 보강에 효과적이라고 알려져 있으며, 편의점에서 병에 담긴 제품도 쉽게 구할 수 있습니다.", "examples": {"beginner": "쌍화탕 한 잔 주세요.", "intermediate": "피곤할 때 쌍화탕을 마셔요.", "advanced": "쌍화탕은 한의학에서 기혈을 보하는 처방이다.", "master": "쌍화탕(雙和湯)은 ''두 가지를 조화롭게 한다''는 의미로, 기와 혈의 균형을 맞추는 처방이다."}, "variations": {"formal": ["쌍화탕을 드시겠습니까?", "쌍화탕을 준비했습니다."], "casual": ["쌍화탕 마실래?", "쌍화탕 한 잔 할까?"], "short": ["쌍화탕"]}, "dialogue": {"context": "편의점에서", "dialogue": [{"speaker": "A", "text": "요즘 너무 피곤해. 뭐 좀 마실까?", "romanization": "yojeum neomu pigonhae. mwo jom masilkka?", "translation": "I''m so tired these days. Should I drink something?"}, {"speaker": "B", "text": "쌍화탕 마셔봐. 효과 좋아.", "romanization": "ssanghwatang masyeobwa. hyogwa joa.", "translation": "Try ssanghwatang. It works well."}]}}, "en": {"word": "herbal tonic", "explanation": "A traditional Korean herbal tonic drink made by boiling various medicinal herbs including peony root, rehmannia, and angelica. Known for fatigue recovery and stamina enhancement. Bottled versions are readily available at convenience stores.", "examples": {"beginner": "One cup of ssanghwatang, please.", "intermediate": "I drink ssanghwatang when I''m tired.", "advanced": "Ssanghwatang is a traditional medicine prescription for replenishing qi and blood.", "master": "Ssanghwatang (雙和湯) means ''harmonizing two elements,'' referring to balancing qi and blood."}, "variations": {"formal": ["Would you like ssanghwatang?", "I''ve prepared ssanghwatang."], "casual": ["Want ssanghwatang?", "How about ssanghwatang?"], "short": ["ssanghwatang"]}, "dialogue": {"context": "At a convenience store", "dialogue": [{"speaker": "A", "text": "I''m so tired these days. Should I drink something?", "romanization": "", "translation": "요즘 너무 피곤해. 뭐 좀 마실까?"}, {"speaker": "B", "text": "Try ssanghwatang. It works well.", "romanization": "", "translation": "쌍화탕 마셔봐. 효과 좋아."}]}}}'),
  ('sikhye', '식혜', 'sikhye', 'noun', 'drinks', 'intermediate', 'common', '["drinks", "traditional", "korean-culture", "dessert", "fermented"]', '{"ko": {"word": "식혜", "explanation": "엿기름(맥아)으로 밥을 삭혀 만든 한국 전통 음료입니다. 달콤한 맛과 동동 떠 있는 밥알이 특징입니다. 설날이나 추석 같은 명절에 디저트로 마시며, 소화를 돕는 효과가 있습니다.", "examples": {"beginner": "식혜 한 잔 주세요.", "intermediate": "명절에 식혜를 마셔요.", "advanced": "식혜는 엿기름의 아밀레이스 효소가 밥의 전분을 분해해서 만들어진다.", "master": "식혜는 발효 과정을 통해 만들어지는 한국 전통 발효 음료의 대표격이다."}, "variations": {"formal": ["식혜를 드시겠습니까?", "식혜를 준비했습니다."], "casual": ["식혜 마실래?", "식혜 먹을래?"], "short": ["식혜"]}, "dialogue": {"context": "설날 가족 모임에서", "dialogue": [{"speaker": "A", "text": "밥 먹고 식혜 한 잔 하자.", "romanization": "bap meokgo sikhye han jan haja.", "translation": "Let''s have a cup of sikhye after the meal."}, {"speaker": "B", "text": "좋아! 엄마가 만든 식혜 최고야.", "romanization": "joa! eommaga mandeun sikhye choegoya.", "translation": "Great! Mom''s homemade sikhye is the best."}]}}, "en": {"word": "sweet rice drink", "explanation": "A traditional Korean beverage made by fermenting cooked rice with malt water (yeotgireum). It features a sweet taste and floating rice grains. Commonly served as a dessert during holidays like Seollal (Lunar New Year) and Chuseok. It also aids digestion.", "examples": {"beginner": "One cup of sikhye, please.", "intermediate": "We drink sikhye during holidays.", "advanced": "Sikhye is made when the amylase enzymes in malt break down the starch in rice.", "master": "Sikhye is a representative example of traditional Korean fermented beverages."}, "variations": {"formal": ["Would you like sikhye?", "I''ve prepared sikhye."], "casual": ["Want sikhye?", "Want some sikhye?"], "short": ["sikhye"]}, "dialogue": {"context": "At a Lunar New Year family gathering", "dialogue": [{"speaker": "A", "text": "Let''s have a cup of sikhye after the meal.", "romanization": "", "translation": "밥 먹고 식혜 한 잔 하자."}, {"speaker": "B", "text": "Great! Mom''s homemade sikhye is the best.", "romanization": "", "translation": "좋아! 엄마가 만든 식혜 최고야."}]}}}'),
  ('sujeonggwa', '수정과', 'sujeonggwa', 'noun', 'drinks', 'intermediate', 'uncommon', '["drinks", "traditional", "korean-culture", "dessert", "winter"]', '{"ko": {"word": "수정과", "explanation": "계피와 생강을 끓인 물에 설탕이나 꿀을 넣고 곶감을 띄워 만든 한국 전통 음료입니다. 차갑게 마시며, 식혜와 함께 명절 음료로 유명합니다. ''수정과(水正果)''는 ''맑은 과일 음료''라는 뜻입니다.", "examples": {"beginner": "수정과 한 잔 주세요.", "intermediate": "수정과는 계피 맛이 나요.", "advanced": "수정과와 식혜는 한국 전통 명절 음료의 양대 산맥이다.", "master": "수정과(水正果)는 조선 시대 궁중에서 후식으로 즐기던 전통 음료이다."}, "variations": {"formal": ["수정과를 드시겠습니까?", "수정과를 준비했습니다."], "casual": ["수정과 마실래?", "수정과 먹을래?"], "short": ["수정과"]}, "dialogue": {"context": "전통 한식당에서", "dialogue": [{"speaker": "A", "text": "후식으로 수정과 드시겠어요?", "romanization": "husigero sujeonggwa deusigesseoyo?", "translation": "Would you like sujeonggwa for dessert?"}, {"speaker": "B", "text": "네, 수정과 좋아요. 계피 향이 좋거든요.", "romanization": "ne, sujeonggwa joayo. gyepi hyangi jokkeodeunyo.", "translation": "Yes, I''d love sujeonggwa. I like the cinnamon aroma."}]}}, "en": {"word": "cinnamon punch", "explanation": "A traditional Korean cold drink made by boiling cinnamon and ginger, sweetened with sugar or honey, and garnished with dried persimmon. Served chilled, it''s famous as a holiday beverage alongside sikhye. ''수정과 (水正果)'' means ''clear fruit drink.''", "examples": {"beginner": "One cup of sujeonggwa, please.", "intermediate": "Sujeonggwa has a cinnamon flavor.", "advanced": "Sujeonggwa and sikhye are the two pillars of Korean traditional holiday beverages.", "master": "Sujeonggwa (水正果) was a dessert drink enjoyed in the Joseon Dynasty royal court."}, "variations": {"formal": ["Would you like sujeonggwa?", "I''ve prepared sujeonggwa."], "casual": ["Want sujeonggwa?", "Want some sujeonggwa?"], "short": ["sujeonggwa"]}, "dialogue": {"context": "At a traditional Korean restaurant", "dialogue": [{"speaker": "A", "text": "Would you like sujeonggwa for dessert?", "romanization": "", "translation": "후식으로 수정과 드시겠어요?"}, {"speaker": "B", "text": "Yes, I''d love sujeonggwa. I like the cinnamon aroma.", "romanization": "", "translation": "네, 수정과 좋아요. 계피 향이 좋거든요."}]}}}'),
  ('maesilcha', '매실차', 'maesilcha', 'noun', 'drinks', 'intermediate', 'common', '["drinks", "tea", "traditional", "health", "digestive"]', '{"ko": {"word": "매실차", "explanation": "매실을 설탕에 절여 만든 매실청을 물에 타서 마시는 차입니다. 새콤달콤한 맛이 특징이며, 소화 촉진과 피로 회복에 효과적입니다. 여름에는 차갑게, 겨울에는 따뜻하게 마십니다.", "examples": {"beginner": "매실차 한 잔 주세요.", "intermediate": "소화가 안 될 때 매실차를 마셔요.", "advanced": "매실청 담그기는 한국 가정의 대표적인 여름 준비 문화이다.", "master": "매실의 구연산 성분이 젖산 분해를 촉진하여 피로 회복에 도움을 준다."}, "variations": {"formal": ["매실차를 드시겠습니까?", "매실차를 준비했습니다."], "casual": ["매실차 마실래?", "매실차 한 잔 할까?"], "short": ["매실차"]}, "dialogue": {"context": "식사 후에", "dialogue": [{"speaker": "A", "text": "너무 많이 먹었더니 배가 더부룩해.", "romanization": "neomu mani meogeotdeoni baega deobururkae.", "translation": "I ate too much and my stomach feels bloated."}, {"speaker": "B", "text": "매실차 마셔. 소화에 좋아.", "romanization": "maesilcha masyeo. sohwa-e joa.", "translation": "Drink plum tea. It''s good for digestion."}]}}, "en": {"word": "plum tea", "explanation": "A tea made by dissolving plum syrup (green plums preserved in sugar) in water. It has a sweet-and-sour taste and is effective for aiding digestion and recovering from fatigue. Served cold in summer and warm in winter.", "examples": {"beginner": "One cup of plum tea, please.", "intermediate": "I drink plum tea when I have indigestion.", "advanced": "Making plum syrup is a quintessential Korean household summer preparation tradition.", "master": "The citric acid in plums promotes lactic acid breakdown, aiding fatigue recovery."}, "variations": {"formal": ["Would you like plum tea?", "I''ve prepared plum tea."], "casual": ["Want plum tea?", "How about plum tea?"], "short": ["plum tea"]}, "dialogue": {"context": "After a meal", "dialogue": [{"speaker": "A", "text": "I ate too much and my stomach feels bloated.", "romanization": "", "translation": "너무 많이 먹었더니 배가 더부룩해."}, {"speaker": "B", "text": "Drink plum tea. It''s good for digestion.", "romanization": "", "translation": "매실차 마셔. 소화에 좋아."}]}}}'),
  ('amerikano', '아메리카노', 'amerikano', 'noun', 'drinks', 'beginner', 'common', '["drinks", "coffee", "cafe", "loanword", "daily-life"]', '{"ko": {"word": "아메리카노", "explanation": "에스프레소에 물을 넣어 만든 커피입니다. 한국에서 가장 인기 있는 커피 메뉴로, ''아아''(아이스 아메리카노)는 계절에 관계없이 사랑받습니다. 줄임말 ''아아''(아이스), ''뜨아''(뜨거운)는 한국 특유의 표현입니다.", "examples": {"beginner": "아메리카노 한 잔 주세요.", "intermediate": "한국 사람들은 겨울에도 아이스 아메리카노를 마셔요.", "advanced": "아이스 아메리카노를 줄여서 ''아아''라고 부르는 것은 한국 카페 문화의 특징이다.", "master": "한국의 아메리카노 소비량은 문화적 현상으로, ''아아''는 하나의 사회적 코드가 되었다."}, "variations": {"formal": ["아메리카노를 드시겠습니까?", "아메리카노를 준비하겠습니다."], "casual": ["아아 마실래?", "아메리카노 한 잔 할까?"], "short": ["아아", "아메리카노"]}, "dialogue": {"context": "카페에서 주문할 때", "dialogue": [{"speaker": "A", "text": "아이스 아메리카노 한 잔이요.", "romanization": "aiseu amerikano han janiyo.", "translation": "One iced Americano, please."}, {"speaker": "B", "text": "사이즈 어떤 걸로 하시겠어요?", "romanization": "saijeu eotteon geollo hasigesseoyo?", "translation": "What size would you like?"}]}}, "en": {"word": "Americano", "explanation": "Coffee made by adding water to espresso. It''s the most popular coffee menu item in Korea. ''Ah-ah'' (아아, iced Americano) is beloved year-round regardless of season. The abbreviations ''아아'' (iced) and ''뜨아'' (hot) are uniquely Korean expressions.", "examples": {"beginner": "One Americano, please.", "intermediate": "Koreans drink iced Americano even in winter.", "advanced": "Shortening iced Americano to ''ah-ah'' is a characteristic of Korean cafe culture.", "master": "Korea''s Americano consumption is a cultural phenomenon; ''ah-ah'' has become a social code."}, "variations": {"formal": ["Would you like an Americano?", "I''ll prepare an Americano."], "casual": ["Want an iced Americano?", "How about an Americano?"], "short": ["Americano", "iced Americano"]}, "dialogue": {"context": "Ordering at a cafe", "dialogue": [{"speaker": "A", "text": "One iced Americano, please.", "romanization": "", "translation": "아이스 아메리카노 한 잔이요."}, {"speaker": "B", "text": "What size would you like?", "romanization": "", "translation": "사이즈 어떤 걸로 하시겠어요?"}]}}}'),
  ('latte', '라떼', 'latte', 'noun', 'drinks', 'beginner', 'common', '["drinks", "coffee", "cafe", "loanword"]', '{"ko": {"word": "라떼", "explanation": "에스프레소에 스팀 우유를 넣어 만든 커피입니다. 이탈리아어 ''latte(우유)''에서 유래했습니다. 한국에서는 ''카페 라떼'' 외에도 녹차 라떼, 고구마 라떼 등 다양한 변형이 인기입니다. ''라떼는 말이야''는 ''나 때는 말이야''의 말장난입니다.", "examples": {"beginner": "라떼 한 잔 주세요.", "intermediate": "카페 라떼에 시럽 추가할 수 있어요.", "advanced": "한국에서는 커피 라떼 외에도 녹차, 고구마, 밤 라떼 등 다양한 종류가 있다.", "master": "''라떼는 말이야''라는 유행어는 세대 차이를 풍자하는 한국 특유의 언어 유머이다."}, "variations": {"formal": ["라떼를 드시겠습니까?", "라떼를 준비하겠습니다."], "casual": ["라떼 마실래?", "라떼 한 잔 할까?"], "short": ["라떼"]}, "dialogue": {"context": "카페에서", "dialogue": [{"speaker": "A", "text": "바닐라 라떼 한 잔 주세요.", "romanization": "banilla latte han jan juseyo.", "translation": "One vanilla latte, please."}, {"speaker": "B", "text": "핫으로 드릴까요, 아이스로 드릴까요?", "romanization": "haseuro deurilkkayo, aiseuro deurilkkayo?", "translation": "Would you like it hot or iced?"}]}}, "en": {"word": "latte", "explanation": "Coffee made with espresso and steamed milk. From the Italian word ''latte'' meaning ''milk.'' In Korea, besides cafe lattes, variations like green tea latte, sweet potato latte, and chestnut latte are popular. ''라떼는 말이야'' is a Korean pun meaning ''back in my day,'' playing on ''latte'' sounding like ''나 때'' (my time).", "examples": {"beginner": "One latte, please.", "intermediate": "You can add syrup to a cafe latte.", "advanced": "In Korea, besides coffee lattes, there are green tea, sweet potato, and chestnut latte varieties.", "master": "The catchphrase ''라떼는 말이야'' is a uniquely Korean linguistic humor satirizing generational gaps."}, "variations": {"formal": ["Would you like a latte?", "I''ll prepare a latte."], "casual": ["Want a latte?", "How about a latte?"], "short": ["latte"]}, "dialogue": {"context": "At a cafe", "dialogue": [{"speaker": "A", "text": "One vanilla latte, please.", "romanization": "", "translation": "바닐라 라떼 한 잔 주세요."}, {"speaker": "B", "text": "Would you like it hot or iced?", "romanization": "", "translation": "핫으로 드릴까요, 아이스로 드릴까요?"}]}}}'),
  ('kapuchino', '카푸치노', 'kapuchino', 'noun', 'drinks', 'beginner', '3', '["drinks", "coffee", "cafe", "loanword"]', '{"ko": "카푸치노", "en": "cappuccino"}'),
  ('eseupeuleso', '에스프레소', 'eseupeuleso', 'noun', 'drinks', 'beginner', '3', '["drinks", "coffee", "cafe", "loanword", "strong"]', '{"ko": "에스프레소", "en": "espresso"}'),
  ('moka', '모카', 'moka', 'noun', 'drinks', 'beginner', '3', '["drinks", "coffee", "cafe", "loanword", "chocolate"]', '{"ko": "모카", "en": "mocha"}'),
  ('aiseu-keopi', '아이스커피', 'aiseu keopi', 'noun', 'drinks', 'beginner', '5', '["drinks", "coffee", "cafe", "summer"]', '{"ko": "아이스커피", "en": "iced coffee"}'),
  ('koldeuburu', '콜드브루', 'koldeuburu', 'noun', 'drinks', 'intermediate', '3', '["drinks", "coffee", "cafe", "loanword", "modern"]', '{"ko": "콜드브루", "en": "cold brew"}'),
  ('uyu', '우유', 'uyu', 'noun', 'drinks', 'beginner', '5', '["drinks", "dairy", "daily-life", "health", "children"]', '{"ko": "우유", "en": "milk"}'),
  ('duyu', '두유', 'duyu', 'noun', 'drinks', 'beginner', '4', '["drinks", "non-dairy", "health", "korean-culture"]', '{"ko": "두유", "en": "soy milk"}'),
  ('yogureuteu', '요구르트', 'yogureuteu', 'noun', 'drinks', 'beginner', '4', '["drinks", "dairy", "health", "loanword"]', '{"ko": "요구르트", "en": "yogurt drink"}'),
  ('chokollit', '초콜릿', 'chokollit', 'noun', 'drinks', 'beginner', '4', '["drinks", "sweet", "winter", "cafe", "loanword"]', '{"ko": "초콜릿", "en": "hot chocolate"}'),
  ('seumudi', '스무디', 'seumudi', 'noun', 'drinks', 'beginner', '3', '["drinks", "fruit", "cafe", "loanword", "health"]', '{"ko": "스무디", "en": "smoothie"}'),
  ('milkeu-syeikeu', '밀크셰이크', 'milkeu syeikeu', 'noun', 'drinks', 'intermediate', '2', '["drinks", "sweet", "cafe", "loanword"]', '{"ko": "밀크셰이크", "en": "milkshake"}'),
  ('tansansu', '탄산수', 'tansansu', 'noun', 'drinks', 'intermediate', '3', '["drinks", "non-alcoholic", "refreshment", "modern"]', '{"ko": "탄산수", "en": "sparkling water"}'),
  ('saida', '사이다', 'saida', 'noun', 'drinks', 'beginner', '4', '["drinks", "non-alcoholic", "sweet", "korean-culture"]', '{"ko": "사이다", "en": "lemon-lime soda"}'),
  ('kolla', '콜라', 'kolla', 'noun', 'drinks', 'beginner', '4', '["drinks", "non-alcoholic", "sweet", "loanword"]', '{"ko": "콜라", "en": "cola"}'),
  ('eneoji-deuringkeu', '에너지드링크', 'eneoji deuringkeu', 'noun', 'drinks', 'intermediate', '3', '["drinks", "modern", "caffeine", "loanword"]', '{"ko": "에너지드링크", "en": "energy drink"}'),
  ('ion-eumnyo', '이온음료', 'ion eumnyo', 'noun', 'drinks', 'intermediate', '3', '["drinks", "sports", "health", "refreshment"]', '{"ko": "이온음료", "en": "sports drink"}'),
  ('orenji-juseu', '오렌지주스', 'orenji juseu', 'noun', 'drinks', 'beginner', '4', '["drinks", "juice", "fruit", "breakfast"]', '{"ko": "오렌지주스", "en": "orange juice"}'),
  ('podo-juseu', '포도주스', 'podo juseu', 'noun', 'drinks', 'beginner', '3', '["drinks", "juice", "fruit", "sweet"]', '{"ko": "포도주스", "en": "grape juice"}'),
  ('sagwa-juseu', '사과주스', 'sagwa juseu', 'noun', 'drinks', 'beginner', '3', '["drinks", "juice", "fruit", "children"]', '{"ko": "사과주스", "en": "apple juice"}'),
  ('tomato-juseu', '토마토주스', 'tomato juseu', 'noun', 'drinks', 'beginner', '3', '["drinks", "juice", "health", "vegetable"]', '{"ko": "토마토주스", "en": "tomato juice"}'),
  ('makgeolli', '막걸리', 'makgeolli', 'noun', 'drinks', 'intermediate', 'common', '["drinks", "alcohol", "traditional", "korean-culture", "fermented"]', '{"ko": "쌀로 만든 전통 발효주로, 탁한 흰색을 띠며 약간 달고 톡 쏘는 맛이 특징이다.", "en": "A traditional Korean fermented rice wine with a milky, cloudy appearance and a slightly sweet, tangy taste."}'),
  ('dongdongju', '동동주', 'dongdongju', 'noun', 'drinks', 'advanced', 'uncommon', '["drinks", "alcohol", "traditional", "korean-culture"]', '{"ko": "밥알이 둥둥 떠 있는 전통 쌀 발효주로, 막걸리보다 맑고 부드러운 맛이 특징이다.", "en": "A traditional Korean rice wine with floating rice grains, clearer and smoother than makgeolli."}'),
  ('cheongju', '청주', 'cheongju', 'noun', 'drinks', 'advanced', 'uncommon', '["drinks", "alcohol", "traditional", "formal"]', '{"ko": "맑게 거른 전통 쌀 발효주로, 제사나 공식 행사에서 주로 사용된다.", "en": "A clear, refined traditional Korean rice wine often used in ceremonies and formal occasions."}'),
  ('yakju', '약주', 'yakju', 'noun', 'drinks', 'advanced', 'uncommon', '["drinks", "alcohol", "traditional", "health"]', '{"ko": "약재를 넣어 빚은 전통 술로, 건강에 좋다고 알려져 있다.", "en": "A traditional Korean medicinal wine brewed with herbal ingredients, believed to have health benefits."}'),
  ('gwail-soju', '과일소주', 'gwail soju', 'noun', 'drinks', 'beginner', 'common', '["drinks", "alcohol", "modern", "sweet", "youth"]', '{"ko": "과일 맛이 나는 소주로, 일반 소주보다 도수가 낮고 달콤하여 젊은 층에게 인기가 많다.", "en": "Fruit-flavored soju with a lower alcohol content and sweeter taste, popular among younger drinkers."}'),
  ('wain', '와인', 'wain', 'noun', 'drinks', 'beginner', 'common', '["drinks", "alcohol", "western", "loanword", "formal"]', '{"ko": "포도를 발효시켜 만든 서양 술로, 레드와인과 화이트와인이 대표적이다.", "en": "Wine; an alcoholic beverage made from fermented grapes, commonly red or white."}'),
  ('wiseuky', '위스키', 'wiseuky', 'noun', 'drinks', 'beginner', 'common', '["drinks", "alcohol", "western", "loanword", "strong"]', '{"ko": "곡물을 발효·증류하여 오크통에서 숙성시킨 서양 증류주.", "en": "Whiskey; a distilled alcoholic spirit made from fermented grain and aged in oak barrels."}'),
  ('bodeka', '보드카', 'bodeka', 'noun', 'drinks', 'beginner', 'common', '["drinks", "alcohol", "western", "loanword", "strong"]', '{"ko": "곡물이나 감자를 증류하여 만든 무색투명한 독한 술.", "en": "Vodka; a clear, strong distilled spirit typically made from grains or potatoes."}'),
  ('reom', '럼', 'reom', 'noun', 'drinks', 'intermediate', 'uncommon', '["drinks", "alcohol", "western", "loanword"]', '{"ko": "사탕수수를 원료로 만든 증류주로, 칵테일에 많이 사용된다.", "en": "Rum; a distilled spirit made from sugarcane, commonly used in cocktails."}'),
  ('kakteil', '칵테일', 'kakteil', 'noun', 'drinks', 'beginner', 'common', '["drinks", "alcohol", "bar", "loanword", "social"]', '{"ko": "여러 종류의 술과 음료를 섞어 만든 혼합 음료.", "en": "Cocktail; a mixed alcoholic drink made by combining spirits with other beverages."}'),
  ('haibor', '하이볼', 'haibor', 'noun', 'drinks', 'intermediate', 'common', '["drinks", "alcohol", "bar", "loanword", "modern"]', '{"ko": "위스키에 탄산수를 섞어 만든 칵테일로, 최근 한국에서 큰 인기를 얻고 있다.", "en": "Highball; a cocktail of whiskey and carbonated water, recently trending in Korea."}'),
  ('saengmaekju', '생맥주', 'saengmaekju', 'noun', 'drinks', 'intermediate', 'common', '["drinks", "alcohol", "beer", "restaurant", "fresh"]', '{"ko": "열처리하지 않은 신선한 맥주로, 맥주집이나 식당에서 탭으로 제공된다.", "en": "Draft beer; unpasteurized fresh beer served on tap at restaurants and pubs."}'),
  ('suje-maekju', '수제맥주', 'suje maekju', 'noun', 'drinks', 'intermediate', 'common', '["drinks", "alcohol", "beer", "modern", "trend"]', '{"ko": "소규모 양조장에서 수작업으로 만든 맥주로, 다양한 맛과 스타일이 특징이다.", "en": "Craft beer; handmade beer from small breweries, known for diverse flavors and styles."}'),
  ('heukmaekju', '흑맥주', 'heukmaekju', 'noun', 'drinks', 'intermediate', 'uncommon', '["drinks", "alcohol", "beer", "western"]', '{"ko": "볶은 맥아로 만든 검은색 맥주로, 진한 풍미와 쓴맛이 특징이다.", "en": "Dark beer or stout; a black beer made from roasted malt with a rich, bitter flavor."}'),
  ('boksunga-aiseu-ti', '복숭아아이스티', 'boksunga aiseu ti', 'noun', 'drinks', 'beginner', 'common', '["drinks", "tea", "sweet", "cafe", "summer"]', '{"ko": "복숭아 맛이 나는 차가운 홍차 음료로, 카페에서 인기 있는 여름 음료이다.", "en": "Peach iced tea; a cold tea drink with peach flavor, a popular summer cafe beverage."}'),
  ('lemoneideu', '레모네이드', 'lemoneideu', 'noun', 'drinks', 'beginner', 'common', '["drinks", "non-alcoholic", "summer", "refreshment", "loanword"]', '{"ko": "레몬즙에 물과 설탕을 넣어 만든 상큼한 음료.", "en": "Lemonade; a refreshing drink made from lemon juice, water, and sugar."}'),
  ('eideu', '에이드', 'eideu', 'noun', 'drinks', 'beginner', 'common', '["drinks", "non-alcoholic", "cafe", "summer", "loanword"]', '{"ko": "과일 시럽이나 퓌레에 탄산수를 넣어 만든 카페 음료.", "en": "Fruit ade; a cafe drink made with fruit syrup or puree mixed with sparkling water."}'),
  ('bingsu', '빙수', 'bingsu', 'noun', 'drinks', 'beginner', 'common', '["drinks", "dessert", "summer", "korean-culture", "sweet"]', '{"ko": "곱게 간 얼음 위에 팥, 떡, 과일 등을 올린 한국 전통 여름 디저트.", "en": "Shaved ice; a Korean summer dessert with finely shaved ice topped with red beans, rice cakes, and fruit."}'),
  ('heobeu-ti', '허브티', 'heobeu ti', 'noun', 'drinks', 'beginner', 'common', '["drinks", "tea", "health", "cafe", "loanword"]', '{"ko": "카모마일, 페퍼민트 등의 허브를 우려낸 차로, 카페인이 없어 건강 음료로 인기가 있다.", "en": "Herbal tea; a caffeine-free tea made from herbs such as chamomile and peppermint, popular as a health drink."}'),
  ('yulmucha', '율무차', 'yulmucha', 'noun', 'drinks', 'advanced', 'uncommon', '["drinks", "tea", "traditional", "health", "beauty"]', '{"ko": "율무를 볶아 우려낸 전통 차로, 피부 미용과 건강에 좋다고 알려져 있다.", "en": "Job''s tears tea; a traditional Korean tea made from roasted Job''s tears, known for skin and health benefits."}');

-- conjunctions (50 entries)
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES
  ('geurigo', '그리고', 'geurigo', 'conjunction', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "addition", "speaking", "beginner-essential"]', '{"ko": {"word": "그리고", "explanation": "앞의 내용에 뒤의 내용을 더할 때 쓰는 접속사입니다. 문장과 문장을 연결하거나 나열할 때 사용합니다.", "examples": {"beginner": "사과 그리고 바나나를 샀어요.", "intermediate": "공부를 했어요. 그리고 운동도 했어요.", "advanced": "그리고는 병렬 접속사로, 대등한 내용을 연결한다.", "master": "구어체에서는 ''그리고''를 ''그리구''로 발음하는 경우도 있다."}, "variations": {"formal": ["그리고 다음 사항을 말씀드리겠습니다."], "casual": ["그리고 또...", "그리구..."], "short": ["그리고"]}, "dialogue": {"context": "쇼핑 목록을 말하면서", "dialogue": [{"speaker": "A", "text": "뭐 사야 해?", "romanization": "mwo saya hae?", "translation": "What do we need to buy?"}, {"speaker": "B", "text": "우유, 빵, 그리고 계란.", "romanization": "uyu, ppang, geurigo gyeran.", "translation": "Milk, bread, and eggs."}]}}, "en": {"word": "and / and then", "explanation": "A conjunction used to add or list items. It connects sentences or items of equal importance. Equivalent to ''and'' or ''and then'' in English.", "examples": {"beginner": "I bought apples and bananas.", "intermediate": "I studied. And I also exercised.", "advanced": "''그리고'' is a parallel conjunction that connects equal content.", "master": "In casual speech, ''그리고'' is sometimes pronounced as ''그리구''."}, "variations": {"formal": ["And I would like to mention the following."], "casual": ["And also...", "And then..."], "short": ["and"]}, "dialogue": {"context": "Going over a shopping list", "dialogue": [{"speaker": "A", "text": "What do we need to buy?", "romanization": "", "translation": "뭐 사야 해?"}, {"speaker": "B", "text": "Milk, bread, and eggs.", "romanization": "", "translation": "우유, 빵, 그리고 계란."}]}}}'),
  ('hajiman', '하지만', 'hajiman', 'conjunction', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "contrast", "speaking", "beginner-essential"]', '{"ko": {"word": "하지만", "explanation": "앞의 내용과 반대되거나 대조되는 내용을 연결하는 접속사입니다. ''그렇지만'', ''그러나''와 같은 뜻입니다.", "examples": {"beginner": "비싸요. 하지만 맛있어요.", "intermediate": "피곤해요. 하지만 공부해야 해요.", "advanced": "하지만은 역접 접속사로, 앞 내용과 대조되는 내용을 이끈다.", "master": "하지만과 그러나의 차이는 구어/문어 차이가 크다."}, "variations": {"formal": ["하지만 한 가지 문제가 있습니다.", "그러나 상황이 다릅니다."], "casual": ["하지만...", "근데..."], "short": ["하지만"]}, "dialogue": {"context": "식당 추천하면서", "dialogue": [{"speaker": "A", "text": "이 식당 맛있어. 하지만 좀 비싸.", "romanization": "i sikdang masisseo. hajiman jom bissa.", "translation": "This restaurant is good. But it''s a bit expensive."}, {"speaker": "B", "text": "괜찮아, 오늘은 특별한 날이니까.", "romanization": "gwaenchana, oneureun teukbyeolhan narnikka.", "translation": "That''s okay, it''s a special day."}]}}, "en": {"word": "but / however", "explanation": "A conjunction that introduces a contrasting or opposing idea. Equivalent to ''but'' or ''however.'' Similar expressions include ''그렇지만'' and ''그러나'' (more formal/literary).", "examples": {"beginner": "It''s expensive. But it''s delicious.", "intermediate": "I''m tired. But I have to study.", "advanced": "''하지만'' is an adversative conjunction introducing contrasting content.", "master": "The difference between ''하지만'' and ''그러나'' largely lies in spoken vs. written register."}, "variations": {"formal": ["However, there is one problem.", "Nevertheless, the situation differs."], "casual": ["But...", "Though..."], "short": ["but"]}, "dialogue": {"context": "Recommending a restaurant", "dialogue": [{"speaker": "A", "text": "This restaurant is good. But it''s a bit expensive.", "romanization": "", "translation": "이 식당 맛있어. 하지만 좀 비싸."}, {"speaker": "B", "text": "That''s okay, it''s a special day.", "romanization": "", "translation": "괜찮아, 오늘은 특별한 날이니까."}]}}}'),
  ('geuraeseo', '그래서', 'geuraeseo', 'conjunction', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "cause-effect", "speaking"]', '{"ko": {"word": "그래서", "explanation": "앞 문장의 원인이나 이유에 대한 결과를 나타내는 접속사입니다. ''그러므로'', ''따라서''보다 구어적인 표현입니다.", "examples": {"beginner": "비가 와요. 그래서 우산을 가져갔어요.", "intermediate": "시험이 있어요. 그래서 열심히 공부해요.", "advanced": "그래서는 인과 접속사로, 원인과 결과를 연결한다.", "master": "그래서와 그러니까의 차이는 결과 서술과 이유 강조의 차이이다."}, "variations": {"formal": ["그래서 다음과 같이 결정했습니다.", "따라서 조치를 취하겠습니다."], "casual": ["그래서?", "그래서 어떻게 됐어?"], "short": ["그래서"]}, "dialogue": {"context": "이야기하면서", "dialogue": [{"speaker": "A", "text": "어제 늦게 잤어.", "romanization": "eoje neutge jasseo.", "translation": "I went to bed late yesterday."}, {"speaker": "B", "text": "그래서 피곤해 보이는구나.", "romanization": "geuraeseo pigonhae boineguna.", "translation": "So that''s why you look tired."}]}}, "en": {"word": "so / therefore", "explanation": "A conjunction that shows the result or consequence of a preceding cause. More conversational than ''그러므로'' or ''따라서'' (therefore — more formal/written).", "examples": {"beginner": "It''s raining. So I brought an umbrella.", "intermediate": "There''s an exam. So I''m studying hard.", "advanced": "''그래서'' is a causal conjunction connecting cause and effect.", "master": "The difference between ''그래서'' and ''그러니까'' is stating a result vs. emphasizing a reason."}, "variations": {"formal": ["Therefore, we have decided as follows.", "Accordingly, we will take action."], "casual": ["So?", "So what happened?"], "short": ["so"]}, "dialogue": {"context": "Chatting", "dialogue": [{"speaker": "A", "text": "I went to bed late yesterday.", "romanization": "", "translation": "어제 늦게 잤어."}, {"speaker": "B", "text": "So that''s why you look tired.", "romanization": "", "translation": "그래서 피곤해 보이는구나."}]}}}'),
  ('go', '-고', 'go', 'particle', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "connective-ending", "addition"]', '{"ko": {"word": "-고", "explanation": "동사나 형용사 어간 뒤에 붙어 두 가지 동작이나 상태를 나열하는 연결어미입니다. 시간 순서(~하고 나서) 또는 동시 동작(~하면서)을 나타냅니다.", "examples": {"beginner": "밥을 먹고 학교에 갔어요.", "intermediate": "노래를 듣고 춤을 춰요.", "advanced": "-고는 대등적 연결어미로, 나열, 순서, 대조를 나타낸다.", "master": "-고의 시제는 뒤 절의 시제에 의존하며, 앞 절에는 시제 표시를 하지 않는다."}, "variations": {"formal": ["보고서를 작성하고 제출하겠습니다."], "casual": ["먹고 가자.", "씻고 자."], "short": ["-고"]}, "dialogue": {"context": "하루 일과를 말하면서", "dialogue": [{"speaker": "A", "text": "오늘 뭐 했어?", "romanization": "oneul mwo haesseo?", "translation": "What did you do today?"}, {"speaker": "B", "text": "운동하고 친구 만났어.", "romanization": "undonghago chingu mannasseo.", "translation": "I exercised and met a friend."}]}}, "en": {"word": "-go (and / and then)", "explanation": "A connective ending attached to verb/adjective stems to list two actions or states. Can indicate sequential actions (did X and then Y) or simultaneous actions. The tense is determined by the final verb.", "examples": {"beginner": "I ate and went to school.", "intermediate": "I listen to music and dance.", "advanced": "''-고'' is a coordinating connective ending for listing, sequencing, or contrasting.", "master": "The tense of ''-고'' depends on the final clause; the preceding clause doesn''t carry its own tense marker."}, "variations": {"formal": ["I will write the report and submit it."], "casual": ["Let''s eat and go.", "Wash up and sleep."], "short": ["-go"]}, "dialogue": {"context": "Talking about the day", "dialogue": [{"speaker": "A", "text": "What did you do today?", "romanization": "", "translation": "오늘 뭐 했어?"}, {"speaker": "B", "text": "I exercised and met a friend.", "romanization": "", "translation": "운동하고 친구 만났어."}]}}}'),
  ('myeon', '-면', 'myeon', 'particle', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "connective-ending", "condition"]', '{"ko": {"word": "-면 / -으면", "explanation": "조건을 나타내는 연결어미입니다. ''~한다면'', ''~할 경우''의 뜻입니다. 받침이 있으면 ''-으면'', 없으면 ''-면''을 씁니다.", "examples": {"beginner": "시간이 있으면 같이 가요.", "intermediate": "비가 오면 집에 있을 거예요.", "advanced": "-면은 가정, 조건, 전제를 나타내는 연결어미이다.", "master": "-면의 쓰임은 조건문뿐 아니라 소망(-면 좋겠다), 습관(-면 ~하다) 등에도 확장된다."}, "variations": {"formal": ["문제가 있으시면 말씀해 주세요."], "casual": ["시간 되면 연락해.", "가고 싶으면 가."], "short": ["-면"]}, "dialogue": {"context": "약속을 정하면서", "dialogue": [{"speaker": "A", "text": "내일 시간 되면 만날까?", "romanization": "naeil sigan doemyeon mannalkka?", "translation": "Shall we meet tomorrow if you''re free?"}, {"speaker": "B", "text": "좋아, 오후면 괜찮아.", "romanization": "joa, ohumyeon gwaenchana.", "translation": "Sure, afternoon works for me."}]}}, "en": {"word": "-myeon (if / when)", "explanation": "A conditional connective ending meaning ''if'' or ''when.'' Use ''-으면'' after consonants and ''-면'' after vowels. Beyond simple conditionals, it extends to wishes (-면 좋겠다 = ''I wish'') and habitual actions.", "examples": {"beginner": "If you have time, let''s go together.", "intermediate": "If it rains, I''ll stay home.", "advanced": "''-면'' is a connective ending expressing conditions, assumptions, and premises.", "master": "''-면'' extends beyond conditionals to express wishes (-면 좋겠다) and habitual actions."}, "variations": {"formal": ["If you have any questions, please let me know."], "casual": ["Contact me if you''re free.", "Go if you want to."], "short": ["-myeon"]}, "dialogue": {"context": "Making plans", "dialogue": [{"speaker": "A", "text": "Shall we meet tomorrow if you''re free?", "romanization": "", "translation": "내일 시간 되면 만날까?"}, {"speaker": "B", "text": "Sure, afternoon works for me.", "romanization": "", "translation": "좋아, 오후면 괜찮아."}]}}}'),
  ('geureonde', '그런데', 'geureonde', 'conjunction', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "contrast", "topic-change", "speaking"]', '{"ko": {"word": "그런데", "explanation": "앞의 내용과 대조되는 내용을 이어가거나, 화제를 전환할 때 사용하는 접속사입니다. 구어에서 ''근데''로 줄여 쓰기도 합니다.", "examples": {"beginner": "맛있어요. 그런데 너무 매워요.", "intermediate": "열심히 공부했어요. 그런데 시험을 못 봤어요.", "advanced": "그런데는 역접과 화제 전환을 모두 나타내는 다기능 접속사이다.", "master": "''그런데''의 축약형 ''근데''는 구어에서 가장 빈번히 사용되는 접속사 중 하나이다."}, "variations": {"formal": ["그런데 한 가지 여쭤봐도 될까요?"], "casual": ["근데 말이야...", "근데 있잖아..."], "short": ["근데"]}, "dialogue": {"context": "친구와 대화하면서 화제를 바꿀 때", "dialogue": [{"speaker": "A", "text": "오늘 날씨 좋다. 그런데 내일 비 온대.", "romanization": "oneul nalssi jota. geureonde naeil bi ondae.", "translation": "The weather is nice today. But I heard it''ll rain tomorrow."}, {"speaker": "B", "text": "정말? 그럼 우산 가져가야겠다.", "romanization": "jeongmal? geureom usan gajyeogayagetda.", "translation": "Really? Then I should bring an umbrella."}]}}, "en": {"word": "but / by the way", "explanation": "A conjunction used to introduce contrasting information or to change the topic. Often shortened to ''근데'' in casual speech. Functions both as ''but'' (contrast) and ''by the way'' (topic shift).", "examples": {"beginner": "It''s delicious. But it''s too spicy.", "intermediate": "I studied hard. But I didn''t do well on the exam.", "advanced": "''그런데'' is a multifunctional conjunction for both contrast and topic change.", "master": "The shortened form ''근데'' is one of the most frequently used conjunctions in spoken Korean."}, "variations": {"formal": ["By the way, may I ask you something?"], "casual": ["But you know...", "By the way..."], "short": ["but"]}, "dialogue": {"context": "Changing the topic during a conversation", "dialogue": [{"speaker": "A", "text": "The weather is nice today. But I heard it''ll rain tomorrow.", "romanization": "", "translation": "오늘 날씨 좋다. 그런데 내일 비 온대."}, {"speaker": "B", "text": "Really? Then I should bring an umbrella.", "romanization": "", "translation": "정말? 그럼 우산 가져가야겠다."}]}}}'),
  ('geureona', '그러나', 'geureona', 'conjunction', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "contrast", "formal", "writing"]', '{"ko": {"word": "그러나", "explanation": "앞의 내용과 반대되는 내용을 연결하는 접속사입니다. ''하지만''보다 격식적이며 주로 문어체에서 사용합니다.", "examples": {"beginner": "노력했다. 그러나 실패했다.", "intermediate": "경제가 성장했다. 그러나 빈부 격차도 커졌다.", "advanced": "그러나는 문어체 역접 접속사로, 논설문이나 학술 글에서 주로 사용된다.", "master": "그러나와 하지만의 차이는 레지스터(격식도)의 차이이며, 의미상 차이는 거의 없다."}, "variations": {"formal": ["그러나 이 점은 재고해야 합니다."], "casual": ["하지만...", "근데..."], "short": ["그러나"]}, "dialogue": {"context": "발표에서 반론을 제시할 때", "dialogue": [{"speaker": "A", "text": "이 방법이 효율적입니다. 그러나 비용이 많이 듭니다.", "romanization": "i bangbeopi hyoyuljeogimnida. geureona biyongi mani deumnida.", "translation": "This method is efficient. However, it costs a lot."}, {"speaker": "B", "text": "그렇군요. 대안이 있을까요?", "romanization": "geureokgunyo. daeani isseulkkayo?", "translation": "I see. Are there alternatives?"}]}}, "en": {"word": "however / but (formal)", "explanation": "A formal conjunction introducing a contrasting idea. More literary than ''하지만'' and primarily used in written Korean, essays, and formal speeches.", "examples": {"beginner": "I tried. However, I failed.", "intermediate": "The economy grew. However, the wealth gap also widened.", "advanced": "''그러나'' is a written-register adversative conjunction used in essays and academic writing.", "master": "The difference between ''그러나'' and ''하지만'' is register (formality), not meaning."}, "variations": {"formal": ["However, this point needs reconsideration."], "casual": ["But...", "Though..."], "short": ["however"]}, "dialogue": {"context": "Presenting a counterpoint in a presentation", "dialogue": [{"speaker": "A", "text": "This method is efficient. However, it costs a lot.", "romanization": "", "translation": "이 방법이 효율적입니다. 그러나 비용이 많이 듭니다."}, {"speaker": "B", "text": "I see. Are there alternatives?", "romanization": "", "translation": "그렇군요. 대안이 있을까요?"}]}}}'),
  ('geureochiman', '그렇지만', 'geureochiman', 'conjunction', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "contrast", "formal"]', '{"ko": {"word": "그렇지만", "explanation": "앞의 내용을 인정하면서 반대되는 내용을 이어가는 접속사입니다. ''하지만''과 비슷하지만 좀 더 격식적인 느낌을 줍니다.", "examples": {"beginner": "어려워요. 그렇지만 재미있어요.", "intermediate": "시간이 부족해요. 그렇지만 끝까지 해볼게요.", "advanced": "그렇지만은 ''그렇다+지만''의 결합으로 양보의 의미가 강하다.", "master": "그렇지만은 하지만과 그러나의 중간 격식도를 가지며, 구어와 문어 모두에서 사용된다."}, "variations": {"formal": ["그렇지만 다른 관점에서 볼 필요가 있습니다."], "casual": ["그래도...", "하지만..."], "short": ["그렇지만"]}, "dialogue": {"context": "힘든 상황에서 격려할 때", "dialogue": [{"speaker": "A", "text": "이 일이 정말 힘들어요.", "romanization": "i iri jeongmal himdeureoyo.", "translation": "This work is really hard."}, {"speaker": "B", "text": "그렇지만 포기하면 안 돼요.", "romanization": "geureochiman pogihamyeon an dwaeyo.", "translation": "Nevertheless, you shouldn''t give up."}]}}, "en": {"word": "nevertheless / but still", "explanation": "A conjunction that acknowledges the preceding statement while introducing a contrasting point. Slightly more formal than ''하지만'' but less literary than ''그러나.'' Used in both spoken and written Korean.", "examples": {"beginner": "It''s difficult. Nevertheless, it''s fun.", "intermediate": "There isn''t enough time. But still, I''ll try my best.", "advanced": "''그렇지만'' combines ''그렇다'' + ''지만,'' carrying a concessive nuance.", "master": "''그렇지만'' occupies a middle register between ''하지만'' (casual) and ''그러나'' (formal)."}, "variations": {"formal": ["Nevertheless, we need to consider another perspective."], "casual": ["Still...", "But..."], "short": ["nevertheless"]}, "dialogue": {"context": "Encouraging someone in a tough situation", "dialogue": [{"speaker": "A", "text": "This work is really hard.", "romanization": "", "translation": "이 일이 정말 힘들어요."}, {"speaker": "B", "text": "Nevertheless, you shouldn''t give up.", "romanization": "", "translation": "그렇지만 포기하면 안 돼요."}]}}}'),
  ('geureomeuro', '그러므로', 'geureomeuro', 'conjunction', 'conjunctions', 'intermediate', 'uncommon', '["conjunctions", "grammar", "cause-effect", "formal", "writing"]', '{"ko": {"word": "그러므로", "explanation": "앞의 내용에 대한 논리적 결론을 이끄는 접속사입니다. ''그래서''보다 격식적이며 논설문, 학술 글에서 주로 사용합니다.", "examples": {"beginner": "늦었다. 그러므로 서둘러야 한다.", "intermediate": "증거가 충분하다. 그러므로 결론을 내릴 수 있다.", "advanced": "그러므로는 논리적 인과를 나타내는 문어체 접속사이다.", "master": "그러므로와 따라서는 유사하나, 그러므로가 논리적 필연성을 더 강하게 나타낸다."}, "variations": {"formal": ["그러므로 다음과 같이 결론짓겠습니다."], "casual": ["그래서...", "그러니까..."], "short": ["그러므로"]}, "dialogue": {"context": "논문 발표에서 결론을 말할 때", "dialogue": [{"speaker": "A", "text": "실험 결과가 가설을 지지합니다. 그러므로 이 이론은 유효합니다.", "romanization": "silheom gyeolgwaga gaseoreul jijihamnida. geureomeuro i ironeun yuhyohamnida.", "translation": "The experimental results support the hypothesis. Therefore, this theory is valid."}, {"speaker": "B", "text": "설득력 있는 결론이네요.", "romanization": "seoldeungnyeok inneun gyeollonieneyo.", "translation": "That''s a convincing conclusion."}]}}, "en": {"word": "therefore / thus", "explanation": "A formal conjunction introducing a logical conclusion. More formal than ''그래서'' and primarily used in academic writing, essays, and formal speeches. Emphasizes logical necessity.", "examples": {"beginner": "It''s late. Therefore, we must hurry.", "intermediate": "The evidence is sufficient. Therefore, we can draw a conclusion.", "advanced": "''그러므로'' is a written-register causal conjunction indicating logical consequence.", "master": "''그러므로'' and ''따라서'' are similar, but ''그러므로'' implies stronger logical necessity."}, "variations": {"formal": ["Therefore, I shall conclude as follows."], "casual": ["So...", "That''s why..."], "short": ["therefore"]}, "dialogue": {"context": "Presenting a conclusion in an academic paper", "dialogue": [{"speaker": "A", "text": "The experimental results support the hypothesis. Therefore, this theory is valid.", "romanization": "", "translation": "실험 결과가 가설을 지지합니다. 그러므로 이 이론은 유효합니다."}, {"speaker": "B", "text": "That''s a convincing conclusion.", "romanization": "", "translation": "설득력 있는 결론이네요."}]}}}'),
  ('ttaraseo', '따라서', 'ttaraseo', 'conjunction', 'conjunctions', 'intermediate', 'uncommon', '["conjunctions", "grammar", "cause-effect", "formal", "academic"]', '{"ko": {"word": "따라서", "explanation": "앞의 내용을 근거로 결론이나 결과를 이끄는 접속사입니다. ''그러므로''와 비슷하며 학술적, 공식적 맥락에서 자주 사용합니다.", "examples": {"beginner": "비가 온다. 따라서 우산이 필요하다.", "intermediate": "수요가 증가했다. 따라서 가격도 올랐다.", "advanced": "따라서는 논리적 귀결을 나타내는 문어체 접속사로, 보고서나 논문에서 빈번히 사용된다.", "master": "따라서는 ''따르다+아서''에서 문법화된 것으로, 원래 ''~에 따라''의 의미에서 접속사로 발전했다."}, "variations": {"formal": ["따라서 이번 분기 실적은 양호합니다."], "casual": ["그래서...", "그러니까..."], "short": ["따라서"]}, "dialogue": {"context": "회의에서 분석 결과를 보고할 때", "dialogue": [{"speaker": "A", "text": "매출이 20% 증가했습니다. 따라서 목표를 달성했습니다.", "romanization": "maechuri isip peoseonteu jeunggahaetsseumnida. ttaraseo mokpyoreul dalseonghaetsseumnida.", "translation": "Sales increased by 20%. Accordingly, we achieved our target."}, {"speaker": "B", "text": "좋은 소식이네요.", "romanization": "joeun sosigineyo.", "translation": "That''s good news."}]}}, "en": {"word": "accordingly / therefore", "explanation": "A formal conjunction drawing a conclusion based on prior information. Similar to ''그러므로'' and frequently used in academic, business, and official contexts such as reports and papers.", "examples": {"beginner": "It''s raining. Accordingly, an umbrella is needed.", "intermediate": "Demand increased. Accordingly, prices rose.", "advanced": "''따라서'' is a written-register conjunction for logical conclusions, common in reports and papers.", "master": "''따라서'' grammaticalized from ''따르다+아서,'' evolving from ''according to'' into a conjunction."}, "variations": {"formal": ["Accordingly, this quarter''s results are positive."], "casual": ["So...", "That means..."], "short": ["accordingly"]}, "dialogue": {"context": "Reporting analysis results at a meeting", "dialogue": [{"speaker": "A", "text": "Sales increased by 20%. Accordingly, we achieved our target.", "romanization": "", "translation": "매출이 20% 증가했습니다. 따라서 목표를 달성했습니다."}, {"speaker": "B", "text": "That''s good news.", "romanization": "", "translation": "좋은 소식이네요."}]}}}'),
  ('geuraedo', '그래도', 'geuraedo', 'conjunction', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "concession", "speaking"]', '{"ko": {"word": "그래도", "explanation": "앞의 상황을 인정하면서도 그것과 관계없이 뒤의 내용을 이어가는 접속사입니다. ''그럼에도 불구하고''의 구어적 표현입니다.", "examples": {"beginner": "힘들어요. 그래도 해야 해요.", "intermediate": "실패했어요. 그래도 다시 도전할 거예요.", "advanced": "그래도는 양보의 접속사로, 앞 상황에도 불구하고 뒤 내용이 유효함을 나타낸다.", "master": "그래도는 감정적 뉘앙스를 동반하며, 화자의 의지나 기대를 내포하는 경우가 많다."}, "variations": {"formal": ["그래도 희망은 있습니다."], "casual": ["그래도...", "그래두..."], "short": ["그래도"]}, "dialogue": {"context": "위로하면서", "dialogue": [{"speaker": "A", "text": "시험을 못 봤어.", "romanization": "siheomeul mot bwasseo.", "translation": "I did badly on the exam."}, {"speaker": "B", "text": "그래도 열심히 했잖아. 다음에 잘하면 돼.", "romanization": "geuraedo yeolsimhi haetjana. daeume jalhamyeon dwae.", "translation": "Still, you worked hard. You can do better next time."}]}}, "en": {"word": "still / even so", "explanation": "A conjunction acknowledging a situation while asserting that the following statement remains valid regardless. The conversational equivalent of ''그럼에도 불구하고'' (nevertheless). Often carries emotional nuance expressing the speaker''s determination or expectation.", "examples": {"beginner": "It''s hard. Still, I have to do it.", "intermediate": "I failed. Even so, I''ll try again.", "advanced": "''그래도'' is a concessive conjunction indicating the latter content holds despite the former.", "master": "''그래도'' often carries emotional nuance, implying the speaker''s willpower or expectation."}, "variations": {"formal": ["Even so, there is still hope."], "casual": ["Still...", "Even so..."], "short": ["still"]}, "dialogue": {"context": "Consoling someone", "dialogue": [{"speaker": "A", "text": "I did badly on the exam.", "romanization": "", "translation": "시험을 못 봤어."}, {"speaker": "B", "text": "Still, you worked hard. You can do better next time.", "romanization": "", "translation": "그래도 열심히 했잖아. 다음에 잘하면 돼."}]}}}'),
  ('gedaga', '게다가', 'gedaga', 'conjunction', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "addition", "emphasis"]', '{"ko": {"word": "게다가", "explanation": "앞의 내용에 더해 추가적인 정보를 강조하며 덧붙이는 접속사입니다. ''더군다나'', ''더구나''와 비슷합니다.", "examples": {"beginner": "비가 와요. 게다가 바람도 불어요.", "intermediate": "음식이 맛있어요. 게다가 가격도 싸요.", "advanced": "게다가는 첨가 접속사로, 앞 내용을 강화하는 추가 정보를 제시한다.", "master": "게다가는 긍정적·부정적 내용 모두에 사용되며, 감정의 누적 효과를 만든다."}, "variations": {"formal": ["게다가 추가적인 이점도 있습니다."], "casual": ["게다가...", "거기다가..."], "short": ["게다가"]}, "dialogue": {"context": "불평하면서", "dialogue": [{"speaker": "A", "text": "오늘 정말 힘들었어. 게다가 비까지 왔어.", "romanization": "oneul jeongmal himdeureosseo. gedaga bikkaji wasseo.", "translation": "Today was really tough. On top of that, it even rained."}, {"speaker": "B", "text": "정말 안 좋은 날이었네.", "romanization": "jeongmal an joeun narieonne.", "translation": "That was really a bad day."}]}}, "en": {"word": "moreover / on top of that", "explanation": "A conjunction adding and emphasizing additional information on top of what was already stated. Similar to ''더구나'' and ''더군다나.'' Works with both positive and negative contexts, creating a cumulative effect.", "examples": {"beginner": "It''s raining. On top of that, it''s windy.", "intermediate": "The food is delicious. Moreover, the price is low.", "advanced": "''게다가'' is an additive conjunction presenting reinforcing additional information.", "master": "''게다가'' works in both positive and negative contexts, creating a cumulative emotional effect."}, "variations": {"formal": ["Moreover, there are additional benefits."], "casual": ["On top of that...", "Plus..."], "short": ["moreover"]}, "dialogue": {"context": "Complaining about a bad day", "dialogue": [{"speaker": "A", "text": "Today was really tough. On top of that, it even rained.", "romanization": "", "translation": "오늘 정말 힘들었어. 게다가 비까지 왔어."}, {"speaker": "B", "text": "That was really a bad day.", "romanization": "", "translation": "정말 안 좋은 날이었네."}]}}}'),
  ('deoguna', '더구나', 'deoguna', 'conjunction', 'conjunctions', 'intermediate', 'uncommon', '["conjunctions", "grammar", "addition", "emphasis", "formal"]', '{"ko": {"word": "더구나", "explanation": "앞의 내용에 더하여 정도가 더 심한 사실을 덧붙이는 접속사입니다. ''게다가''보다 격식적이며 강조의 의미가 더 강합니다.", "examples": {"beginner": "추워요. 더구나 눈까지 와요.", "intermediate": "일이 많아요. 더구나 마감도 내일이에요.", "advanced": "더구나는 점층적 첨가를 나타내며, 앞 내용보다 더 심한 상황을 강조한다.", "master": "더구나와 하물며의 차이는 단순 첨가(더구나)와 논리적 유추(하물며)의 차이이다."}, "variations": {"formal": ["더구나 이번 사안은 긴급합니다."], "casual": ["게다가...", "거기다..."], "short": ["더구나"]}, "dialogue": {"context": "어려운 상황을 설명할 때", "dialogue": [{"speaker": "A", "text": "프로젝트가 지연되고 있습니다. 더구나 예산도 부족합니다.", "romanization": "peurojekteuga jiyeondoego itsseumnida. deoguna yesando bujokamnida.", "translation": "The project is delayed. Furthermore, the budget is insufficient."}, {"speaker": "B", "text": "대책을 세워야겠군요.", "romanization": "daechaekeul sewoyagetgunyo.", "translation": "We need to come up with a plan."}]}}, "en": {"word": "furthermore / what''s more", "explanation": "A formal conjunction adding a more extreme or significant fact to what was already stated. More formal and emphatic than ''게다가.'' Indicates an escalating situation.", "examples": {"beginner": "It''s cold. What''s more, it''s snowing.", "intermediate": "There''s a lot of work. Furthermore, the deadline is tomorrow.", "advanced": "''더구나'' indicates progressive addition, emphasizing a more severe situation.", "master": "The difference between ''더구나'' and ''하물며'' is simple addition vs. logical inference."}, "variations": {"formal": ["Furthermore, this matter is urgent."], "casual": ["On top of that...", "And also..."], "short": ["furthermore"]}, "dialogue": {"context": "Explaining a difficult situation", "dialogue": [{"speaker": "A", "text": "The project is delayed. Furthermore, the budget is insufficient.", "romanization": "", "translation": "프로젝트가 지연되고 있습니다. 더구나 예산도 부족합니다."}, {"speaker": "B", "text": "We need to come up with a plan.", "romanization": "", "translation": "대책을 세워야겠군요."}]}}}'),
  ('ppunman-anira', '뿐만 아니라', 'ppunman anira', 'conjunction', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "addition", "formal", "writing"]', '{"ko": {"word": "뿐만 아니라", "explanation": "앞의 내용에 그치지 않고 추가적인 내용이 있음을 나타내는 접속 표현입니다. ''~할 뿐만 아니라 ~도''의 형태로 자주 사용합니다.", "examples": {"beginner": "맛있을 뿐만 아니라 건강에도 좋아요.", "intermediate": "한국어뿐만 아니라 일본어도 할 수 있어요.", "advanced": "뿐만 아니라는 첨가·확장의 접속 표현으로, 범위를 넓히는 기능을 한다.", "master": "''뿐만 아니라''는 ''뿐+만+아니다+라''의 결합으로, 부정 형식이지만 긍정적 첨가를 나타낸다."}, "variations": {"formal": ["이 제품은 품질뿐만 아니라 디자인도 우수합니다."], "casual": ["그것만이 아니라...", "~도 있고..."], "short": ["뿐만 아니라"]}, "dialogue": {"context": "제품을 추천하면서", "dialogue": [{"speaker": "A", "text": "이 식당은 음식이 맛있을 뿐만 아니라 분위기도 좋아요.", "romanization": "i sikdangeun eumsigi masissul ppunman anira bunwigido joayo.", "translation": "This restaurant is not only delicious but also has a great atmosphere."}, {"speaker": "B", "text": "그래요? 한번 가 봐야겠네요.", "romanization": "geuraeyo? hanbeon ga bwayagenneyo.", "translation": "Really? I should try it sometime."}]}}, "en": {"word": "not only... but also", "explanation": "A conjunctive expression indicating that something goes beyond what was mentioned, adding more. Often used in the pattern ''A뿐만 아니라 B도'' (not only A but also B). Common in formal and written Korean.", "examples": {"beginner": "It''s not only delicious but also healthy.", "intermediate": "I can speak not only Korean but also Japanese.", "advanced": "''뿐만 아니라'' is an additive expression that expands the scope of the statement.", "master": "''뿐만 아니라'' combines ''뿐+만+아니다+라'' — a negative form expressing positive addition."}, "variations": {"formal": ["This product excels not only in quality but also in design."], "casual": ["Not just that...", "And also..."], "short": ["not only"]}, "dialogue": {"context": "Recommending a place", "dialogue": [{"speaker": "A", "text": "This restaurant is not only delicious but also has a great atmosphere.", "romanization": "", "translation": "이 식당은 음식이 맛있을 뿐만 아니라 분위기도 좋아요."}, {"speaker": "B", "text": "Really? I should try it sometime.", "romanization": "", "translation": "그래요? 한번 가 봐야겠네요."}]}}}'),
  ('ttohan', '또한', 'ttohan', 'conjunction', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "addition", "formal", "writing"]', '{"ko": {"word": "또한", "explanation": "앞의 내용에 추가적인 사항을 더할 때 사용하는 접속사입니다. ''또'', ''그리고''보다 격식적인 표현입니다.", "examples": {"beginner": "영어를 잘해요. 또한 중국어도 해요.", "intermediate": "건강에 좋습니다. 또한 맛도 훌륭합니다.", "advanced": "또한은 문어체 첨가 접속사로, 격식적인 글이나 발표에서 주로 사용된다.", "master": "또한과 아울러의 차이는 단순 첨가(또한)와 동시적 병행(아울러)의 뉘앙스 차이이다."}, "variations": {"formal": ["또한 다음 사항을 참고해 주시기 바랍니다."], "casual": ["그리고...", "또..."], "short": ["또한"]}, "dialogue": {"context": "보고서를 발표하면서", "dialogue": [{"speaker": "A", "text": "매출이 증가했습니다. 또한 고객 만족도도 높아졌습니다.", "romanization": "maechuri jeunggahaetsseumnida. ttohan gogaek manjokdodo nopajyeotsseumnida.", "translation": "Sales have increased. Also, customer satisfaction has improved."}, {"speaker": "B", "text": "훌륭한 성과네요.", "romanization": "hullyunghan seonggwaneyo.", "translation": "Those are excellent results."}]}}, "en": {"word": "also / in addition", "explanation": "A formal conjunction used to add supplementary information. More formal than ''또'' or ''그리고.'' Primarily used in written Korean, presentations, and formal speech.", "examples": {"beginner": "I speak English well. I also speak Chinese.", "intermediate": "It''s healthy. In addition, it tastes great.", "advanced": "''또한'' is a written-register additive conjunction for formal writing and presentations.", "master": "The difference between ''또한'' and ''아울러'' is simple addition vs. simultaneous parallel action."}, "variations": {"formal": ["In addition, please refer to the following."], "casual": ["And...", "Also..."], "short": ["also"]}, "dialogue": {"context": "Delivering a report", "dialogue": [{"speaker": "A", "text": "Sales have increased. Also, customer satisfaction has improved.", "romanization": "", "translation": "매출이 증가했습니다. 또한 고객 만족도도 높아졌습니다."}, {"speaker": "B", "text": "Those are excellent results.", "romanization": "", "translation": "훌륭한 성과네요."}]}}}'),
  ('jeuk', '즉', 'jeuk', 'conjunction', 'conjunctions', 'intermediate', 'uncommon', '["conjunctions", "grammar", "explanation", "formal", "academic"]', '{"ko": {"word": "즉", "explanation": "앞의 내용을 다른 말로 바꾸어 설명하거나 부연할 때 사용하는 접속사입니다. ''다시 말해서'', ''바꿔 말하면''과 같은 뜻입니다.", "examples": {"beginner": "일요일, 즉 내일 만나요.", "intermediate": "그는 의사, 즉 병원에서 일하는 사람이에요.", "advanced": "즉은 환언(換言)의 접속사로, 앞 내용을 재진술하거나 명확히 하는 기능을 한다.", "master": "즉과 곧의 차이는 문어체(즉)와 구어/문어 겸용(곧)의 차이이다."}, "variations": {"formal": ["즉, 이 결과는 다음을 의미합니다."], "casual": ["다시 말하면...", "쉽게 말하면..."], "short": ["즉"]}, "dialogue": {"context": "수업에서 개념을 설명할 때", "dialogue": [{"speaker": "A", "text": "광합성, 즉 식물이 빛으로 에너지를 만드는 과정입니다.", "romanization": "gwanghapseong, jeuk singmuri bicheuro eneojireu mandeuneu gwajeongimnida.", "translation": "Photosynthesis, in other words, the process by which plants make energy from light."}, {"speaker": "B", "text": "아, 그렇게 이해하면 되는군요.", "romanization": "a, geureoke ihaehamyeon doengunyo.", "translation": "Ah, I see, that''s how to understand it."}]}}, "en": {"word": "in other words / that is", "explanation": "A conjunction used to rephrase or clarify the preceding statement. Equivalent to ''in other words,'' ''that is,'' or ''i.e.'' Commonly used in academic and formal writing.", "examples": {"beginner": "Sunday, that is, tomorrow, let''s meet.", "intermediate": "He''s a doctor, that is, a person who works at a hospital.", "advanced": "''즉'' is a paraphrasing conjunction that restates or clarifies preceding content.", "master": "The difference between ''즉'' and ''곧'' is that ''즉'' is written-only while ''곧'' is used in both registers."}, "variations": {"formal": ["That is, this result means the following."], "casual": ["In other words...", "To put it simply..."], "short": ["i.e."]}, "dialogue": {"context": "Explaining a concept in class", "dialogue": [{"speaker": "A", "text": "Photosynthesis, in other words, the process by which plants make energy from light.", "romanization": "", "translation": "광합성, 즉 식물이 빛으로 에너지를 만드는 과정입니다."}, {"speaker": "B", "text": "Ah, I see, that''s how to understand it.", "romanization": "", "translation": "아, 그렇게 이해하면 되는군요."}]}}}'),
  ('yereul-deureo', '예를 들어', 'yereul deureo', 'conjunction', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "example", "academic"]', '{"ko": {"word": "예를 들어", "explanation": "앞의 내용에 대한 구체적인 예시를 제시할 때 사용하는 접속 표현입니다. ''예컨대'', ''가령''과 같은 뜻입니다.", "examples": {"beginner": "과일을 좋아해요. 예를 들어 사과, 바나나를 좋아해요.", "intermediate": "운동에는 여러 종류가 있어요. 예를 들어 수영, 달리기, 요가 등이 있어요.", "advanced": "예를 들어는 예시 제시의 접속 표현으로, 추상적 내용을 구체화하는 기능을 한다.", "master": "예를 들어, 예컨대, 가령은 모두 예시 접속어이나, 격식도와 사용 빈도에서 차이가 있다."}, "variations": {"formal": ["예를 들어, 다음과 같은 경우가 있습니다."], "casual": ["예를 들면...", "예를 들자면..."], "short": ["예를 들어"]}, "dialogue": {"context": "취미에 대해 이야기하면서", "dialogue": [{"speaker": "A", "text": "한국 음식을 좋아해요?", "romanization": "hanguk eumsigeul joahaeyo?", "translation": "Do you like Korean food?"}, {"speaker": "B", "text": "네, 좋아해요. 예를 들어 비빔밥이나 불고기를 자주 먹어요.", "romanization": "ne, joahaeyo. yereul deureo bibimbabina bulgogireul jaju meogeoyo.", "translation": "Yes, I do. For example, I often eat bibimbap or bulgogi."}]}}, "en": {"word": "for example / for instance", "explanation": "A conjunctive expression used to introduce specific examples. Equivalent to ''예컨대'' and ''가령.'' Used to make abstract statements more concrete with illustrations.", "examples": {"beginner": "I like fruits. For example, I like apples and bananas.", "intermediate": "There are many types of exercise. For example, swimming, running, yoga, etc.", "advanced": "''예를 들어'' is an example-introducing expression that concretizes abstract content.", "master": "''예를 들어,'' ''예컨대,'' and ''가령'' all introduce examples but differ in formality and frequency."}, "variations": {"formal": ["For example, there are the following cases."], "casual": ["Like...", "For instance..."], "short": ["e.g."]}, "dialogue": {"context": "Talking about hobbies", "dialogue": [{"speaker": "A", "text": "Do you like Korean food?", "romanization": "", "translation": "한국 음식을 좋아해요?"}, {"speaker": "B", "text": "Yes, I do. For example, I often eat bibimbap or bulgogi.", "romanization": "", "translation": "네, 좋아해요. 예를 들어 비빔밥이나 불고기를 자주 먹어요."}]}}}'),
  ('waenyahamyeon', '왜냐하면', 'waenyahamyeon', 'conjunction', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "cause-effect", "speaking", "reason"]', '{"ko": {"word": "왜냐하면", "explanation": "앞에서 말한 내용의 이유를 설명할 때 쓰는 접속사입니다. 주로 뒤에 ''-기 때문이다''와 함께 사용됩니다.", "examples": {"beginner": "왜냐하면 배가 고프니까요.", "intermediate": "못 갔어요. 왜냐하면 비가 왔기 때문이에요.", "advanced": "왜냐하면은 구어체에서 이유를 강조할 때 주로 사용된다.", "master": "격식체에서는 ''왜냐하면'' 대신 ''그 이유는''을 쓰는 것이 더 자연스럽다."}, "variations": {"formal": ["왜냐하면 그러한 사정이 있었기 때문입니다."], "casual": ["왜냐면...", "왜냐하면 말이야..."], "short": ["왜냐면"]}, "dialogue": {"context": "약속에 늦은 이유를 설명하면서", "dialogue": [{"speaker": "A", "text": "왜 늦었어?", "romanization": "wae neujeosseo?", "translation": "Why are you late?"}, {"speaker": "B", "text": "왜냐하면 버스를 놓쳤거든.", "romanization": "waenyahamyeon beoseureul nochyeotgeodeun.", "translation": "Because I missed the bus."}]}}, "en": {"word": "because", "explanation": "A conjunction used to explain the reason for a previously stated fact. Often paired with ''-기 때문이다'' at the end of the clause. Commonly used in spoken Korean.", "examples": {"beginner": "Because I''m hungry.", "intermediate": "I couldn''t go. Because it rained.", "advanced": "''왜냐하면'' is mainly used in spoken Korean to emphasize the reason.", "master": "In formal writing, ''그 이유는'' is preferred over ''왜냐하면''."}, "variations": {"formal": ["Because there were such circumstances."], "casual": ["Because...", "The thing is because..."], "short": ["''cause"]}, "dialogue": {"context": "Explaining why one is late to a meeting", "dialogue": [{"speaker": "A", "text": "Why are you late?", "romanization": "", "translation": "왜 늦었어?"}, {"speaker": "B", "text": "Because I missed the bus.", "romanization": "", "translation": "왜냐하면 버스를 놓쳤거든."}]}}}'),
  ('manyak', '만약', 'manyak', 'adverb', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "condition", "formal"]', '{"ko": {"word": "만약", "explanation": "어떤 일이 일어날 가능성을 가정하여 말할 때 쓰는 부사입니다. 뒤에 ''-면'', ''-다면'' 등의 조건 표현과 함께 씁니다.", "examples": {"beginner": "만약 비가 오면 집에 있을 거예요.", "intermediate": "만약 시간이 있다면 같이 갈까요?", "advanced": "만약은 가정법에서 조건절을 이끄는 부사로, ''-면''과 호응한다.", "master": "구어체에서는 ''만약''을 생략하고 ''-면''만으로 조건을 표현하기도 한다."}, "variations": {"formal": ["만약 그렇게 된다면 조치를 취하겠습니다."], "casual": ["만약에 내일 시간 되면...", "혹시 시간 되면..."], "short": ["만약에"]}, "dialogue": {"context": "주말 계획을 이야기하면서", "dialogue": [{"speaker": "A", "text": "주말에 뭐 할 거야?", "romanization": "jumale mwo hal geoya?", "translation": "What are you going to do on the weekend?"}, {"speaker": "B", "text": "만약 날씨가 좋으면 등산 갈 거야.", "romanization": "manyak nalssiga joeumyeon deungsan gal geoya.", "translation": "If the weather is nice, I''ll go hiking."}]}}, "en": {"word": "if / in case", "explanation": "An adverb used to introduce a hypothetical condition. It is paired with conditional endings like ''-면'' or ''-다면''. Equivalent to ''if'' or ''in case'' in English.", "examples": {"beginner": "If it rains, I will stay home.", "intermediate": "If you have time, shall we go together?", "advanced": "''만약'' is an adverb that introduces conditional clauses, paired with ''-면''.", "master": "In casual speech, ''만약'' is often omitted, with only ''-면'' used for the condition."}, "variations": {"formal": ["If that happens, we will take action."], "casual": ["If by chance you have time...", "In case tomorrow works..."], "short": ["if"]}, "dialogue": {"context": "Discussing weekend plans", "dialogue": [{"speaker": "A", "text": "What are you doing this weekend?", "romanization": "", "translation": "주말에 뭐 할 거야?"}, {"speaker": "B", "text": "If the weather is nice, I''ll go hiking.", "romanization": "", "translation": "만약 날씨가 좋으면 등산 갈 거야."}]}}}'),
  ('birok', '비록', 'birok', 'adverb', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "concession", "formal", "writing"]', '{"ko": {"word": "비록", "explanation": "어떤 사실을 인정하면서도 그에 반하는 내용을 말할 때 쓰는 부사입니다. ''-지만'', ''-더라도'' 등과 함께 사용합니다.", "examples": {"beginner": "비록 어렵지만 포기하지 않겠어요.", "intermediate": "비록 실패했지만 좋은 경험이었다.", "advanced": "비록은 양보의 뜻을 나타내며 ''-지만'', ''-더라도''와 호응한다.", "master": "비록과 ''비록...일지라도'' 구문은 문어체에서 빈번하게 사용된다."}, "variations": {"formal": ["비록 결과가 좋지 않았으나 과정은 의미 있었습니다."], "casual": ["비록 힘들었지만...", "그래도..."], "short": ["비록"]}, "dialogue": {"context": "시험 결과에 대해 이야기하면서", "dialogue": [{"speaker": "A", "text": "시험 결과가 안 좋았다며?", "romanization": "siheom gyeolgwaga an joatdamyeo?", "translation": "I heard your test results weren''t good?"}, {"speaker": "B", "text": "비록 떨어졌지만 많이 배웠어.", "romanization": "birok tteoreojyeotjiman mani baewosseo.", "translation": "Although I failed, I learned a lot."}]}}, "en": {"word": "although / even though", "explanation": "An adverb used to acknowledge a fact while introducing a contrasting result. Paired with endings like ''-지만'' or ''-더라도''. More common in writing and formal speech.", "examples": {"beginner": "Although it''s difficult, I won''t give up.", "intermediate": "Although I failed, it was a good experience.", "advanced": "''비록'' expresses concession and is paired with ''-지만'' or ''-더라도''.", "master": "The ''비록...일지라도'' construction is frequently used in literary Korean."}, "variations": {"formal": ["Although the result was not favorable, the process was meaningful."], "casual": ["Even though it was hard...", "Still..."], "short": ["although"]}, "dialogue": {"context": "Talking about test results", "dialogue": [{"speaker": "A", "text": "I heard your test results weren''t good?", "romanization": "", "translation": "시험 결과가 안 좋았다며?"}, {"speaker": "B", "text": "Although I failed, I learned a lot.", "romanization": "", "translation": "비록 떨어졌지만 많이 배웠어."}]}}}'),
  ('seollyeong', '설령', 'seollyeong', 'adverb', 'conjunctions', 'advanced', 'uncommon', '["conjunctions", "grammar", "concession", "formal", "literary"]', '{"ko": {"word": "설령", "explanation": "극단적인 가정을 할 때 쓰는 부사입니다. ''설사''와 비슷하며 ''-더라도'', ''-다 해도'' 등과 함께 씁니다. 문어체에서 주로 사용됩니다.", "examples": {"beginner": "설령 실패해도 괜찮아요.", "intermediate": "설령 그가 거짓말을 했더라도 용서해 줘야 한다.", "advanced": "설령은 극단적 양보를 나타내며 ''-더라도''와 호응하는 문어체 부사이다.", "master": "설령과 설사는 유의어이나, 설령이 더 강한 가정의 뉘앙스를 갖는다."}, "variations": {"formal": ["설령 그러한 상황이 발생하더라도 대비하겠습니다."], "casual": ["설령 그렇다 해도...", "아무리 그래도..."], "short": ["설령"]}, "dialogue": {"context": "결심을 밝히면서", "dialogue": [{"speaker": "A", "text": "정말 그 일을 시작할 거야?", "romanization": "jeongmal geu ireul sijakal geoya?", "translation": "Are you really going to start that?"}, {"speaker": "B", "text": "설령 어려움이 있더라도 해볼 거야.", "romanization": "seollyeong eoryeoumi itdeorado haebol geoya.", "translation": "Even if there are difficulties, I''ll give it a try."}]}}, "en": {"word": "even if", "explanation": "An adverb used to introduce an extreme hypothetical concession. Similar to ''설사''. Paired with ''-더라도'' or ''-다 해도''. Predominantly used in formal writing and literary contexts.", "examples": {"beginner": "Even if I fail, it''s okay.", "intermediate": "Even if he lied, we should forgive him.", "advanced": "''설령'' is a literary adverb expressing extreme concession, paired with ''-더라도''.", "master": "''설령'' and ''설사'' are synonymous, but ''설령'' carries a stronger hypothetical nuance."}, "variations": {"formal": ["Even if such a situation arises, we will be prepared."], "casual": ["Even if that''s the case...", "No matter what..."], "short": ["even if"]}, "dialogue": {"context": "Expressing determination", "dialogue": [{"speaker": "A", "text": "Are you really going to start that?", "romanization": "", "translation": "정말 그 일을 시작할 거야?"}, {"speaker": "B", "text": "Even if there are difficulties, I''ll give it a try.", "romanization": "", "translation": "설령 어려움이 있더라도 해볼 거야."}]}}}'),
  ('jiman', '-지만', 'jiman', 'particle', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "connective-ending", "contrast"]', '{"ko": {"word": "-지만", "explanation": "앞 절의 내용과 반대되거나 대조되는 내용을 이어줄 때 쓰는 연결 어미입니다. 동사, 형용사 어간 뒤에 붙습니다.", "examples": {"beginner": "맛있지만 비싸요.", "intermediate": "알고 있지만 실천하기 어렵다.", "advanced": "-지만은 역접의 연결 어미로, 서술어 어간에 직접 결합한다.", "master": "-지만과 -지마는 혼동하기 쉬우나, -지마는 금지 표현이므로 구별해야 한다."}, "variations": {"formal": ["죄송하지만 다시 말씀해 주시겠습니까?"], "casual": ["좋지만 좀...", "알겠지만..."], "short": ["-지만"]}, "dialogue": {"context": "음식 평가를 하면서", "dialogue": [{"speaker": "A", "text": "이 식당 어때?", "romanization": "i sikdang eottae?", "translation": "How''s this restaurant?"}, {"speaker": "B", "text": "음식은 맛있지만 좀 비싸.", "romanization": "eumsigeun masitjiman jom bissa.", "translation": "The food is delicious, but a bit expensive."}]}}, "en": {"word": "but / although", "explanation": "A connective ending attached to verb or adjective stems to introduce a contrasting clause. It is one of the most frequently used conjunctive endings in Korean.", "examples": {"beginner": "It''s delicious but expensive.", "intermediate": "I know, but it''s hard to put into practice.", "advanced": "''-지만'' is a contrastive connective ending that attaches directly to predicate stems.", "master": "''-지만'' and ''-지마'' are easily confused; ''-지마'' is a prohibitive expression."}, "variations": {"formal": ["I''m sorry, but could you say that again?"], "casual": ["It''s good, but...", "I get it, but..."], "short": ["but"]}, "dialogue": {"context": "Reviewing a restaurant", "dialogue": [{"speaker": "A", "text": "How''s this restaurant?", "romanization": "", "translation": "이 식당 어때?"}, {"speaker": "B", "text": "The food is delicious, but a bit expensive.", "romanization": "", "translation": "음식은 맛있지만 좀 비싸."}]}}}'),
  ('neunde', '-는데', 'neunde', 'particle', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "connective-ending", "background", "speaking"]', '{"ko": {"word": "-는데", "explanation": "배경 상황을 설명하거나 대조, 전환을 나타내는 연결 어미입니다. 구어체에서 매우 자주 사용되며 다양한 뜻을 가집니다.", "examples": {"beginner": "지금 밥 먹는데 나중에 전화할게.", "intermediate": "비가 오는데 우산이 없어요.", "advanced": "-는데는 배경, 대조, 전환 등 다기능 연결 어미로, 문맥에 따라 의미가 달라진다.", "master": "동사에는 ''-는데'', 형용사에는 ''-ㄴ데'', 과거에는 ''-았/었는데''가 결합한다."}, "variations": {"formal": ["말씀드리고 싶은 것이 있는데요."], "casual": ["있는데...", "그런데 말이야..."], "short": ["-는데"]}, "dialogue": {"context": "부탁을 하려고 할 때", "dialogue": [{"speaker": "A", "text": "지금 바빠?", "romanization": "jigeum bappa?", "translation": "Are you busy now?"}, {"speaker": "B", "text": "좀 바쁜데, 왜?", "romanization": "jom bappeunde, wae?", "translation": "I''m a bit busy, why?"}]}}, "en": {"word": "but / and / context", "explanation": "A multi-functional connective ending used to provide background, contrast, or transition. Extremely common in spoken Korean. Its meaning changes based on context.", "examples": {"beginner": "I''m eating right now, so I''ll call you later.", "intermediate": "It''s raining, but I don''t have an umbrella.", "advanced": "''-는데'' is a multi-functional connective ending for background, contrast, and transition.", "master": "Verbs take ''-는데'', adjectives take ''-ㄴ데'', and past tense uses ''-았/었는데''."}, "variations": {"formal": ["There is something I would like to mention."], "casual": ["The thing is...", "So, like..."], "short": ["but"]}, "dialogue": {"context": "About to ask a favor", "dialogue": [{"speaker": "A", "text": "Are you busy now?", "romanization": "", "translation": "지금 바빠?"}, {"speaker": "B", "text": "I''m a bit busy, why?", "romanization": "", "translation": "좀 바쁜데, 왜?"}]}}}'),
  ('aseo-eoseo', '-아서/-어서', 'aseo/eoseo', 'particle', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "connective-ending", "cause-effect"]', '{"ko": {"word": "-아서/-어서", "explanation": "원인이나 이유를 나타내거나 순서를 표현하는 연결 어미입니다. 양성 모음 뒤에는 ''-아서'', 음성 모음 뒤에는 ''-어서''가 붙습니다.", "examples": {"beginner": "배가 아파서 못 갔어요.", "intermediate": "늦어서 죄송합니다.", "advanced": "-아서/-어서는 원인·이유와 시간 순서를 모두 표현하는 연결 어미이다.", "master": "-아서/-어서는 명령문이나 청유문에 쓸 수 없고, 이 경우 -니까를 사용한다."}, "variations": {"formal": ["늦어서 대단히 죄송합니다."], "casual": ["아파서...", "바빠서 못 해..."], "short": ["-아서"]}, "dialogue": {"context": "결석 이유를 설명하면서", "dialogue": [{"speaker": "A", "text": "어제 왜 안 왔어?", "romanization": "eoje wae an wasseo?", "translation": "Why didn''t you come yesterday?"}, {"speaker": "B", "text": "감기에 걸려서 못 왔어.", "romanization": "gamgie geollyeoseo mot wasseo.", "translation": "I caught a cold, so I couldn''t come."}]}}, "en": {"word": "because / so", "explanation": "A connective ending expressing cause/reason or sequential order. ''-아서'' follows bright vowels (ㅏ, ㅗ) and ''-어서'' follows dark vowels. Cannot be used with imperative or suggestive sentences.", "examples": {"beginner": "I had a stomachache, so I couldn''t go.", "intermediate": "I''m sorry for being late.", "advanced": "''-아서/-어서'' expresses both cause/reason and sequential order.", "master": "''-아서/-어서'' cannot be used with commands or suggestions; use ''-니까'' instead."}, "variations": {"formal": ["I am terribly sorry for being late."], "casual": ["Because I''m sick...", "I''m busy so I can''t..."], "short": ["so"]}, "dialogue": {"context": "Explaining an absence", "dialogue": [{"speaker": "A", "text": "Why didn''t you come yesterday?", "romanization": "", "translation": "어제 왜 안 왔어?"}, {"speaker": "B", "text": "I caught a cold, so I couldn''t come.", "romanization": "", "translation": "감기에 걸려서 못 왔어."}]}}}'),
  ('nikka', '-니까', 'nikka', 'particle', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "connective-ending", "cause-effect", "speaking"]', '{"ko": {"word": "-니까", "explanation": "원인이나 이유를 나타내는 연결 어미입니다. ''-아서/-어서''와 달리 명령문, 청유문에도 사용할 수 있습니다. 구어체에서 자주 씁니다.", "examples": {"beginner": "추우니까 옷을 입으세요.", "intermediate": "시간이 없으니까 빨리 가자.", "advanced": "-니까는 이유의 연결 어미로, 명령·청유문에 사용 가능하다는 점에서 -아서와 다르다.", "master": "과거형에는 ''-았/었으니까''가 결합하며, 구어체에서 ''-니까''는 ''-니깐''으로 발음되기도 한다."}, "variations": {"formal": ["시간이 부족하니까 서두르시기 바랍니다."], "casual": ["추우니까 들어가자.", "알겠으니까 그만해."], "short": ["-니까"]}, "dialogue": {"context": "날씨에 대해 조언하면서", "dialogue": [{"speaker": "A", "text": "밖에 나갈 건데 뭐 입을까?", "romanization": "bakke nagal geonde mwo ireulkka?", "translation": "I''m going out, what should I wear?"}, {"speaker": "B", "text": "오늘 추우니까 따뜻하게 입어.", "romanization": "oneul chuunikka ttatteuthage ibeo.", "translation": "It''s cold today, so dress warmly."}]}}, "en": {"word": "because / since", "explanation": "A connective ending expressing cause or reason. Unlike ''-아서/-어서'', it can be used with imperative and suggestive sentences. Very common in spoken Korean.", "examples": {"beginner": "It''s cold, so put on your clothes.", "intermediate": "We don''t have time, so let''s hurry.", "advanced": "''-니까'' differs from ''-아서'' in that it can be used with commands and suggestions.", "master": "Past tense takes ''-았/었으니까''. In speech, ''-니까'' is sometimes pronounced ''-니깐''."}, "variations": {"formal": ["Since time is short, please hurry."], "casual": ["It''s cold so let''s go in.", "I get it so stop."], "short": ["since"]}, "dialogue": {"context": "Giving advice about the weather", "dialogue": [{"speaker": "A", "text": "I''m going out, what should I wear?", "romanization": "", "translation": "밖에 나갈 건데 뭐 입을까?"}, {"speaker": "B", "text": "It''s cold today, so dress warmly.", "romanization": "", "translation": "오늘 추우니까 따뜻하게 입어."}]}}}'),
  ('ryeogo', '-려고', 'ryeogo', 'particle', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "connective-ending", "purpose"]', '{"ko": {"word": "-려고", "explanation": "어떤 행동의 목적이나 의도를 나타내는 연결 어미입니다. ''-으려고''는 받침이 있는 동사 뒤에 사용됩니다.", "examples": {"beginner": "한국어를 배우려고 한국에 왔어요.", "intermediate": "건강해지려고 운동을 시작했어요.", "advanced": "-려고는 의도·목적을 나타내며, 주어가 같은 절만 연결할 수 있다.", "master": "-려고와 -러는 유의 표현이나, -러는 이동 동사와만 결합한다."}, "variations": {"formal": ["보고서를 작성하려고 자료를 조사하고 있습니다."], "casual": ["밥 먹으려고 나왔어.", "뭐 하려고?"], "short": ["-려고"]}, "dialogue": {"context": "한국에 온 이유를 묻는 상황", "dialogue": [{"speaker": "A", "text": "한국에 왜 왔어요?", "romanization": "hanguge wae wasseoyo?", "translation": "Why did you come to Korea?"}, {"speaker": "B", "text": "한국어를 배우려고 왔어요.", "romanization": "hangugeoreul baeuryeogo wasseoyo.", "translation": "I came to learn Korean."}]}}, "en": {"word": "in order to", "explanation": "A connective ending expressing the purpose or intention of an action. ''-으려고'' is used after stems ending in a consonant. The subjects of both clauses must be the same.", "examples": {"beginner": "I came to Korea to learn Korean.", "intermediate": "I started exercising to get healthy.", "advanced": "''-려고'' expresses intention/purpose and requires the same subject in both clauses.", "master": "''-려고'' and ''-러'' are similar, but ''-러'' only combines with verbs of movement."}, "variations": {"formal": ["I am researching materials in order to write a report."], "casual": ["I came out to eat.", "What are you trying to do?"], "short": ["to"]}, "dialogue": {"context": "Asking why someone came to Korea", "dialogue": [{"speaker": "A", "text": "Why did you come to Korea?", "romanization": "", "translation": "한국에 왜 왔어요?"}, {"speaker": "B", "text": "I came to learn Korean.", "romanization": "", "translation": "한국어를 배우려고 왔어요."}]}}}'),
  ('dorok', '-도록', 'dorok', 'particle', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "connective-ending", "purpose", "formal"]', '{"ko": {"word": "-도록", "explanation": "목적이나 정도, 기한을 나타내는 연결 어미입니다. ''~하게끔'', ''~할 때까지''의 뜻으로 사용됩니다.", "examples": {"beginner": "늦지 않도록 일찍 출발하세요.", "intermediate": "밤새도록 공부했어요.", "advanced": "-도록은 목적, 정도, 기한의 세 가지 의미를 가지는 연결 어미이다.", "master": "-도록과 -게의 차이: -도록은 목적성이 강하고, -게는 결과 상태를 강조한다."}, "variations": {"formal": ["실수가 없도록 철저히 준비하겠습니다."], "casual": ["늦지 않도록 해.", "알아듣도록 설명해 줘."], "short": ["-도록"]}, "dialogue": {"context": "시험 준비 조언을 하면서", "dialogue": [{"speaker": "A", "text": "시험 준비 어떻게 해야 해?", "romanization": "siheom junbi eotteoke haeya hae?", "translation": "How should I prepare for the exam?"}, {"speaker": "B", "text": "실수하지 않도록 꼼꼼히 공부해.", "romanization": "silsuhaji antorok kkomkkomhi gongbuhae.", "translation": "Study carefully so you don''t make mistakes."}]}}, "en": {"word": "so that / until", "explanation": "A connective ending expressing purpose, degree, or time limit. It can mean ''so that'', ''to the extent that'', or ''until''. More commonly used in formal contexts.", "examples": {"beginner": "Leave early so that you''re not late.", "intermediate": "I studied all night long.", "advanced": "''-도록'' has three meanings: purpose, degree, and time limit.", "master": "''-도록'' emphasizes purpose while ''-게'' emphasizes the resulting state."}, "variations": {"formal": ["We will prepare thoroughly so that there are no mistakes."], "casual": ["Make sure you''re not late.", "Explain it so I can understand."], "short": ["so that"]}, "dialogue": {"context": "Giving advice on exam preparation", "dialogue": [{"speaker": "A", "text": "How should I prepare for the exam?", "romanization": "", "translation": "시험 준비 어떻게 해야 해?"}, {"speaker": "B", "text": "Study carefully so you don''t make mistakes.", "romanization": "", "translation": "실수하지 않도록 꼼꼼히 공부해."}]}}}'),
  ('eulsurok', '-ㄹ수록', 'eulsurok', 'particle', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "connective-ending", "proportion"]', '{"ko": {"word": "-ㄹ수록", "explanation": "어떤 상태가 심해질수록 다른 결과도 함께 변하는 것을 나타내는 연결 어미입니다. ''~하면 할수록''의 형태로도 씁니다.", "examples": {"beginner": "갈수록 어려워요.", "intermediate": "한국어는 배우면 배울수록 재미있어요.", "advanced": "-ㄹ수록은 비례 관계를 나타내며 ''~면 ~ㄹ수록'' 구문으로 강조할 수 있다.", "master": "''-ㄹ수록''의 앞에 같은 동사를 반복하면(''하면 할수록'') 비례를 더 강조한다."}, "variations": {"formal": ["경험이 많을수록 판단력이 좋아집니다."], "casual": ["갈수록 힘들어...", "볼수록 예뻐."], "short": ["-ㄹ수록"]}, "dialogue": {"context": "한국어 학습에 대해 이야기하면서", "dialogue": [{"speaker": "A", "text": "한국어 공부 어때?", "romanization": "hangugeo gongbu eottae?", "translation": "How''s studying Korean?"}, {"speaker": "B", "text": "배우면 배울수록 재미있어.", "romanization": "baeumyeon baeulsurok jaemiisseo.", "translation": "The more I learn, the more interesting it gets."}]}}, "en": {"word": "the more...the more", "explanation": "A connective ending expressing a proportional relationship. It indicates that as one state intensifies, another changes accordingly. Can be emphasized with the pattern ''~면 ~ㄹ수록''.", "examples": {"beginner": "It gets harder as time goes on.", "intermediate": "The more I study Korean, the more interesting it is.", "advanced": "''-ㄹ수록'' expresses proportional relationships and can be emphasized with ''~면 ~ㄹ수록''.", "master": "Repeating the same verb before ''-ㄹ수록'' (as in ''하면 할수록'') strengthens the proportional emphasis."}, "variations": {"formal": ["The more experience one has, the better one''s judgment becomes."], "casual": ["It gets harder...", "The more I look, the prettier."], "short": ["the more"]}, "dialogue": {"context": "Talking about studying Korean", "dialogue": [{"speaker": "A", "text": "How''s studying Korean?", "romanization": "", "translation": "한국어 공부 어때?"}, {"speaker": "B", "text": "The more I learn, the more interesting it gets.", "romanization": "", "translation": "배우면 배울수록 재미있어."}]}}}'),
  ('jamaja', '-자마자', 'jamaja', 'particle', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "connective-ending", "time", "immediate"]', '{"ko": {"word": "-자마자", "explanation": "앞의 동작이 끝나는 즉시 뒤의 동작이 이어짐을 나타내는 연결 어미입니다. 시간적 간격이 거의 없음을 강조합니다.", "examples": {"beginner": "집에 오자마자 잠들었어요.", "intermediate": "소식을 듣자마자 달려왔어요.", "advanced": "-자마자는 두 행위의 즉각적 연속을 나타내며, 동사 어간에만 결합한다.", "master": "-자마자와 ''-는 대로''는 유사하나, -자마자가 더 즉각적인 뉘앙스를 갖는다."}, "variations": {"formal": ["회의가 끝나자마자 보고서를 제출하겠습니다."], "casual": ["오자마자 잤어.", "보자마자 알았어."], "short": ["-자마자"]}, "dialogue": {"context": "퇴근 후 일과를 이야기하면서", "dialogue": [{"speaker": "A", "text": "어제 퇴근하고 뭐 했어?", "romanization": "eoje toegeonhago mwo haesseo?", "translation": "What did you do after work yesterday?"}, {"speaker": "B", "text": "집에 오자마자 바로 잤어.", "romanization": "jibe ojamaja baro jasseo.", "translation": "I fell asleep as soon as I got home."}]}}, "en": {"word": "as soon as", "explanation": "A connective ending indicating that the second action occurs immediately after the first one finishes. Emphasizes there is almost no time gap. Only attaches to verb stems.", "examples": {"beginner": "I fell asleep as soon as I got home.", "intermediate": "I rushed over as soon as I heard the news.", "advanced": "''-자마자'' indicates immediate succession and only combines with verb stems.", "master": "''-자마자'' and ''-는 대로'' are similar, but ''-자마자'' has a more immediate nuance."}, "variations": {"formal": ["I will submit the report as soon as the meeting ends."], "casual": ["I slept right when I got there.", "I knew as soon as I saw it."], "short": ["as soon as"]}, "dialogue": {"context": "Talking about after-work routine", "dialogue": [{"speaker": "A", "text": "What did you do after work yesterday?", "romanization": "", "translation": "어제 퇴근하고 뭐 했어?"}, {"speaker": "B", "text": "I fell asleep as soon as I got home.", "romanization": "", "translation": "집에 오자마자 바로 잤어."}]}}}'),
  ('daga', '-다가', 'daga', 'particle', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "connective-ending", "time", "change"]', '{"ko": {"word": "-다가", "explanation": "진행 중인 동작이 중단되고 다른 동작으로 바뀌는 것을 나타내는 연결 어미입니다. 동작의 전환이나 변화를 표현합니다.", "examples": {"beginner": "공부하다가 잠들었어요.", "intermediate": "걷다가 넘어졌어요.", "advanced": "-다가는 행위의 중단·전환을 나타내며, 주어가 같아야 한다.", "master": "-다가를 반복하면(''-다가 -다가 하다'') 교체적 반복 행위를 표현할 수 있다."}, "variations": {"formal": ["보고서를 작성하다가 중요한 오류를 발견했습니다."], "casual": ["보다가 잠들었어.", "먹다가 그만뒀어."], "short": ["-다가"]}, "dialogue": {"context": "오늘 있었던 일을 이야기하면서", "dialogue": [{"speaker": "A", "text": "무릎에 왜 반창고 붙였어?", "romanization": "mureuppe wae banchanggo buchyeosseo?", "translation": "Why do you have a bandage on your knee?"}, {"speaker": "B", "text": "뛰다가 넘어졌어.", "romanization": "ttwi-daga neomeojyeosseo.", "translation": "I fell while running."}]}}, "en": {"word": "while / and then", "explanation": "A connective ending indicating that an action in progress is interrupted and switches to another action. Expresses transition or change in activity. The subject must be the same in both clauses.", "examples": {"beginner": "I fell asleep while studying.", "intermediate": "I tripped while walking.", "advanced": "''-다가'' indicates interruption or transition, requiring the same subject in both clauses.", "master": "Repeating ''-다가'' (''-다가 -다가 하다'') expresses alternating repeated actions."}, "variations": {"formal": ["While writing the report, I discovered an important error."], "casual": ["I fell asleep watching.", "I stopped eating midway."], "short": ["while"]}, "dialogue": {"context": "Talking about something that happened today", "dialogue": [{"speaker": "A", "text": "Why do you have a bandage on your knee?", "romanization": "", "translation": "무릎에 왜 반창고 붙였어?"}, {"speaker": "B", "text": "I fell while running.", "romanization": "", "translation": "뛰다가 넘어졌어."}]}}}'),
  ('deunji', '-든지', 'deunji', 'particle', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "connective-ending", "choice"]', '{"ko": {"word": "-든지", "explanation": "여러 가지 중 어느 것이든 상관없음을 나타내는 연결 어미입니다. 선택이나 무관함을 표현합니다.", "examples": {"beginner": "뭐든지 다 좋아해요.", "intermediate": "어디든지 갈 수 있어요.", "advanced": "-든지는 선택의 무관함을 나타내며, 의문사와 결합하면 ''아무~나''의 뜻이 된다.", "master": "-든지와 -던지를 혼동하지 않도록 주의해야 한다. -던지는 회상을 나타낸다."}, "variations": {"formal": ["무엇이든지 도움이 필요하시면 말씀하십시오."], "casual": ["뭐든지 괜찮아.", "언제든지 연락해."], "short": ["-든지"]}, "dialogue": {"context": "점심 메뉴를 정하면서", "dialogue": [{"speaker": "A", "text": "뭐 먹을래?", "romanization": "mwo meogeullae?", "translation": "What do you want to eat?"}, {"speaker": "B", "text": "나는 뭐든지 괜찮아.", "romanization": "naneun mwodeunji gwaenchana.", "translation": "Anything is fine with me."}]}}, "en": {"word": "whether / or", "explanation": "A connective ending indicating that it doesn''t matter which option is chosen. Expresses indifference to the choice. When combined with question words, it means ''any(thing/where/time)''.", "examples": {"beginner": "I like everything.", "intermediate": "I can go anywhere.", "advanced": "''-든지'' expresses indifference to choice. With question words, it means ''any-''.", "master": "Be careful not to confuse ''-든지'' with ''-던지'', which expresses recollection."}, "variations": {"formal": ["If you need any help whatsoever, please let me know."], "casual": ["Anything is fine.", "Contact me anytime."], "short": ["whatever"]}, "dialogue": {"context": "Deciding on lunch", "dialogue": [{"speaker": "A", "text": "What do you want to eat?", "romanization": "", "translation": "뭐 먹을래?"}, {"speaker": "B", "text": "Anything is fine with me.", "romanization": "", "translation": "나는 뭐든지 괜찮아."}]}}}'),
  ('geona', '-거나', 'geona', 'particle', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "connective-ending", "choice", "alternative"]', '{"ko": {"word": "-거나", "explanation": "둘 이상의 행동이나 상태 중 하나를 선택하는 것을 나타내는 연결 어미입니다. ''또는''과 비슷한 뜻입니다.", "examples": {"beginner": "주말에 영화를 보거나 쇼핑해요.", "intermediate": "궁금한 게 있으면 전화하거나 메일 보내세요.", "advanced": "-거나는 선택적 나열의 연결 어미로, 두 개 이상의 행위를 병렬한다.", "master": "-거나와 ''-든지''는 모두 선택을 나타내지만, -거나는 구체적 대안을, -든지는 무관함을 강조한다."}, "variations": {"formal": ["전화하시거나 이메일로 문의하시기 바랍니다."], "casual": ["자거나 쉬거나 해.", "먹거나 말거나."], "short": ["-거나"]}, "dialogue": {"context": "주말 계획을 이야기하면서", "dialogue": [{"speaker": "A", "text": "주말에 보통 뭐 해?", "romanization": "jumare botong mwo hae?", "translation": "What do you usually do on weekends?"}, {"speaker": "B", "text": "운동하거나 친구 만나요.", "romanization": "undongha-geona chingu mannayo.", "translation": "I exercise or meet friends."}]}}, "en": {"word": "or", "explanation": "A connective ending used to present alternatives or choices between two or more actions or states. Similar to ''or'' in English. Attaches to verb and adjective stems.", "examples": {"beginner": "On weekends, I watch movies or go shopping.", "intermediate": "If you have questions, call or send an email.", "advanced": "''-거나'' is an alternative-listing connective ending that parallels two or more actions.", "master": "''-거나'' and ''-든지'' both indicate choice, but ''-거나'' lists specific alternatives while ''-든지'' emphasizes indifference."}, "variations": {"formal": ["Please call or inquire via email."], "casual": ["Sleep or rest.", "Eat it or don''t."], "short": ["or"]}, "dialogue": {"context": "Talking about weekend plans", "dialogue": [{"speaker": "A", "text": "What do you usually do on weekends?", "romanization": "", "translation": "주말에 보통 뭐 해?"}, {"speaker": "B", "text": "I exercise or meet friends.", "romanization": "", "translation": "운동하거나 친구 만나요."}]}}}'),
  ('ndedo', '-ㄴ데도', 'ndedo', 'particle', 'conjunctions', 'advanced', 'common', '["conjunctions", "grammar", "connective-ending", "concession"]', '{"ko": {"word": "-ㄴ데도", "explanation": "앞의 상황에도 불구하고 뒤의 결과가 예상과 다를 때 쓰는 연결 어미입니다. ''-는데도 불구하고''의 줄임 형태입니다.", "examples": {"beginner": "많이 먹었는데도 배가 고파요.", "intermediate": "열심히 공부했는데도 시험에 떨어졌어요.", "advanced": "-ㄴ데도는 양보의 연결 어미로, 기대와 반대되는 결과를 이끈다.", "master": "동사는 ''-는데도'', 형용사는 ''-ㄴ데도'', 과거는 ''-았/었는데도''로 결합한다."}, "variations": {"formal": ["여러 차례 설명했는데도 이해하지 못하신 것 같습니다."], "casual": ["말했는데도 안 들어.", "했는데도 안 돼."], "short": ["-ㄴ데도"]}, "dialogue": {"context": "다이어트에 대해 이야기하면서", "dialogue": [{"speaker": "A", "text": "다이어트 잘 되고 있어?", "romanization": "daieoteu jal doego isseo?", "translation": "Is your diet going well?"}, {"speaker": "B", "text": "운동을 매일 하는데도 살이 안 빠져.", "romanization": "undongeul maeil haneundedo sari an ppajyeo.", "translation": "I exercise every day, but I''m not losing weight."}]}}, "en": {"word": "despite / even though", "explanation": "A connective ending expressing that the result is contrary to what is expected given the preceding situation. A shorter form of ''-는데도 불구하고''. Indicates concession.", "examples": {"beginner": "Even though I ate a lot, I''m still hungry.", "intermediate": "Despite studying hard, I failed the exam.", "advanced": "''-ㄴ데도'' is a concessive connective ending that introduces a result contrary to expectation.", "master": "Verbs take ''-는데도'', adjectives take ''-ㄴ데도'', and past tense uses ''-았/었는데도''."}, "variations": {"formal": ["Despite explaining multiple times, it seems you still don''t understand."], "casual": ["I told them but they don''t listen.", "I did it but it doesn''t work."], "short": ["despite"]}, "dialogue": {"context": "Talking about dieting", "dialogue": [{"speaker": "A", "text": "Is your diet going well?", "romanization": "", "translation": "다이어트 잘 되고 있어?"}, {"speaker": "B", "text": "I exercise every day, but I''m not losing weight.", "romanization": "", "translation": "운동을 매일 하는데도 살이 안 빠져."}]}}}'),
  ('deorado', '-더라도', 'deorado', 'particle', 'conjunctions', 'advanced', 'common', '["conjunctions", "grammar", "connective-ending", "concession", "hypothetical"]', '{"ko": {"word": "-더라도", "explanation": "가정적인 상황을 인정하면서도 그와 관계없이 뒤의 내용이 성립함을 나타내는 연결 어미입니다. ''-아도/-어도''보다 더 강한 양보를 표현합니다.", "examples": {"beginner": "힘들더라도 포기하지 마세요.", "intermediate": "비가 오더라도 축구를 할 거예요.", "advanced": "-더라도는 가정적 양보를 나타내며, -아도/-어도보다 강한 뉘앙스를 갖는다.", "master": "-더라도는 미실현 상황의 양보에 주로 쓰이며, -았/었더라도는 과거 반사실적 가정을 나타낸다."}, "variations": {"formal": ["어떤 어려움이 있더라도 반드시 완수하겠습니다."], "casual": ["힘들더라도 해 봐.", "싫더라도 참아."], "short": ["-더라도"]}, "dialogue": {"context": "힘든 상황에서 격려하면서", "dialogue": [{"speaker": "A", "text": "너무 힘들어서 그만두고 싶어.", "romanization": "neomu himdeureo-seo geumandugo sipeo.", "translation": "It''s so hard, I want to quit."}, {"speaker": "B", "text": "힘들더라도 조금만 더 버텨 봐.", "romanization": "himdeuldeorado jogeumman deo beottyeo bwa.", "translation": "Even if it''s hard, hang in there a little more."}]}}, "en": {"word": "even if", "explanation": "A connective ending indicating that the following clause holds true regardless of the hypothetical situation. Expresses stronger concession than ''-아도/-어도''. Often used for unrealized situations.", "examples": {"beginner": "Even if it''s hard, don''t give up.", "intermediate": "Even if it rains, I will play soccer.", "advanced": "''-더라도'' expresses hypothetical concession, stronger than ''-아도/-어도''.", "master": "''-더라도'' is mainly for unrealized situations; ''-았/었더라도'' expresses counterfactual past assumptions."}, "variations": {"formal": ["No matter what difficulties arise, I will complete it."], "casual": ["Even if it''s hard, try it.", "Even if you hate it, bear with it."], "short": ["even if"]}, "dialogue": {"context": "Encouraging someone in a difficult situation", "dialogue": [{"speaker": "A", "text": "It''s so hard, I want to quit.", "romanization": "", "translation": "너무 힘들어서 그만두고 싶어."}, {"speaker": "B", "text": "Even if it''s hard, hang in there a little more.", "romanization": "", "translation": "힘들더라도 조금만 더 버텨 봐."}]}}}'),
  ('hanpyeon', '한편', 'hanpyeon', 'conjunction', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "contrast", "formal", "writing"]', '{"ko": "한편", "en": "meanwhile; on the other hand"}'),
  ('banmyeone', '반면에', 'banmyeone', 'conjunction', 'conjunctions', 'intermediate', 'common', '["conjunctions", "grammar", "contrast", "formal", "comparison"]', '{"ko": "반면에", "en": "on the other hand"}'),
  ('daesine', '대신에', 'daesine', 'conjunction', 'conjunctions', 'beginner', 'common', '["conjunctions", "grammar", "alternative", "daily-life"]', '{"ko": "대신에", "en": "instead"}'),
  ('geu-e-banhae', '그에 반해', 'geu-e banhae', 'conjunction', 'conjunctions', 'advanced', 'uncommon', '["conjunctions", "grammar", "contrast", "formal", "academic"]', '{"ko": "그에 반해", "en": "in contrast"}'),
  ('gyeolguk', '결국', 'gyeolguk', 'adverb', 'conjunctions', 'intermediate', 'very-common', '["conjunctions", "grammar", "conclusion", "result"]', '{"ko": "결국", "en": "in the end; eventually"}'),
